INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Os contratos de integração vertical agroindustriais e a produção debiodiesel', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2008;1000836765', NULL, '', '', 'doutrina', 'Resumo:Trata do contrato de integração vertical agroindustrial, entendido como acordo firmado entre produtor agrícola e empresa de transformação industrial e que estabelece recíprocas obrigações de fornecimento de produtos e serviços segundo orientações e critérios técnicos convencionados com o objetivo de fortalecer a atividade empresarial agrária através da minização dos riscos. Explica que sua aplicação no âmbito da produção debiodieselpode ser uma forma de tornar este processo mais seguro e vantajoso para ambas as partes. Analisa ainda suas vantagens e desvantagens. | Assuntos: Biodiesel, produção, Brasil. Energia de biomassa, Brasil. Contrato agrário, Brasil. {Contrato agrário; Contrato agrícola}', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PRIVADO - 342::DIREITO CIVIL - 342.1::Direitos reais. Coisas ou bens - 342.12::Direitos reais segundo o objeto ao qual dizem respeito - 342.124::Direito Agrário. Direito Rural - 342.1247::Contratos agrários - 342.12478', 'Resumo:Trata do contrato de integração vertical agroindustrial, entendido como acordo firmado entre produtor agrícola e empresa de transformação industrial e que estabelece recíprocas obrigações de fornecimento de produtos e serviços segundo orientações e critérios técnicos convencionados com o objetivo de fortalecer a atividade empresarial agrária através da minização dos riscos. Explica que sua aplicação no âmbito da produção debiodieselpode ser uma forma de tornar este processo mais seguro e vantajoso para ambas as partes. Analisa ainda suas vantagens e desvantagens. | Assuntos: Biodiesel, produção, Brasil. Energia de biomassa, Brasil. Contrato agrário, Brasil. {Contrato agrário; Contrato agrícola}', '', 'Pereira, Marlene de Paula', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Doutrina___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
