INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Seguridad energética y medio ambiente', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:livro:2015;001101416', NULL, '', '', 'doutrina', 'Sumário:Seguridad energética : panorama general y apuestas defuturo-- Principales productores y consumidores energéticos -- La dependencia energética de la Unión Europea -- Evolución y políticas de la UE para «asegurar» su «inseguridad» energética -- Las energías alternativas a los hidrocarburos fósiles -- Seguridad medioambiental. | Assuntos: Consumidor. Dependência energética, Países da União Europeia. Energia, fontes. Petróleo comocombustível. Política energética. Proteção ambiental. {Proteção ambiental; Degradação ambiental, prevenção; Meio ambiente, proteção; Recursos naturais, proteção} Recursos naturais. Direito da energia.', '', 'LexML', 'transport_energy', 'Livro', 'Classificação: DIREITO PÚBLICO - 341::DIREITO ADMINISTRATIVO - 341.3::Domínio Público. Conceito. Domínio Eminente. Domínio Patrimonial - 341.34::Jazidas. Código de Minas - 341.344::Minérios nucleares. Energia atômica. Monopólio - 341.3443', 'Sumário:Seguridad energética : panorama general y apuestas defuturo-- Principales productores y consumidores energéticos -- La dependencia energética de la Unión Europea -- Evolución y políticas de la UE para «asegurar» su «inseguridad» energética -- Las energías alternativas a los hidrocarburos fósiles -- Seguridad medioambiental. | Assuntos: Consumidor. Dependência energética, Países da União Europeia. Energia, fontes. Petróleo comocombustível. Política energética. Proteção ambiental. {Proteção ambiental; Degradação ambiental, prevenção; Meio ambiente, proteção; Recursos naturais, proteção} Recursos naturais. Direito da energia.