INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Energiasrenováveis', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:livro:2018;001123075', NULL, '', '', 'doutrina', 'Sumário:Breves apontamentos sobre a geração elétrica e o sistema alemão -- Planejamento energético e o papel dasenergíasrenováveis: Regime especial de compensação. Espécies de fontes geradoras no sistema da EGG:Energiaeólica.Energiasolar.Energiahidráulica. Biomassa.Energiageotérmica. Operadores da rede elétrica -- Tópicos sobre a proteção ao meio ambiente: Aspectos gerais sobre a proteção ao ambiente em suas diversas frentes. Princípio da sustentabilidade. Gestão ambiental. O departamento do meio ambiente. Protocolo de Kyoto -- Regulação no setor elétrico alemão: Entidades do setor elétrico na Europa. Atores do sistema regulatório alemão. | Assuntos: Energiaelétrica, legislação, Alemanha.Energiaelétrica, regulação, Alemanha.Energiaelétrica, Alemanha.Energiaelétrica, Brasil.Energia, produção. Fonterenováveldeenergia. {Fonterenováveldeenergia; Fontes novas erenováveisdeenergia} Proteção ambiental. {Proteção ambiental; Degradação ambiental, prevenção; Meio ambiente, proteção; Recursos naturais, proteção} Recursos energéticos. {Recursos energéticos;Energia, fontes; Fonte energética} Regulação jurídica, Alemanha. Direito daenergia.', '', 'LexML', 'transport_energy', 'Livro', 'Classificação: DIREITO PÚBLICO - 341::DIREITO ADMINISTRATIVO - 341.3::Domínio Público. Conceito. Domínio Eminente. Domínio Patrimonial - 341.34::Jazidas. Código de Minas - 341.344::Minérios nucleares.Energiaatômica. Monopólio - 341.3443', 'Sumário:Breves apontamentos sobre a geração elétrica e o sistema alemão -- Planejamento energético e o papel dasenergíasrenováveis: Regime especial de compensação. Espécies de fontes geradoras no sistema da EGG:Energiaeólica.Energiasolar.Energiahidráulica. Biomassa.Energiageotérmica. Operadores da rede elétrica -- Tópicos sobre a proteção ao meio ambiente: Aspectos gerais sobre a proteção ao ambiente em suas diversas frentes. Princípio da sustentabilidade. Gestão ambiental. O departamento do meio ambiente. Protocolo de Kyoto -- Regulação no setor elétrico alemão: Entidades do setor elétrico na Europa. Atores do sistema regulatório alemão. | Assuntos: Energiaelétrica, legislação, Alemanha.Energiaelétrica, regulação, Alemanha.Energiaelétrica, Alemanha.Energiaelétrica, Brasil.Energia, produção. Fonterenováveldeenergia. {Fonterenováveldeenergia; Fontes novas erenováveisdeenergia} Proteção ambiental. {Proteção ambiental; Degradação ambiental, prevenção; Meio ambiente, proteção; Recursos naturais, proteção} Recursos energéticos. {Recursos energéticos;Energia, fontes; Fonte energética} Regulação jurídica, Alemanha. Direito daenergia.', '', 'Steindorfer, Fabriccio', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Doutrina___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Tributação sustentável para fontes deenergiasrenováveis', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2014;1001022304', NULL, '', '', 'doutrina', 'Resumo:Estudo comparado sobre o tratamento dado ao imposto e à fontes deenergiasrenováveisno direito da Polônia, República Tcheca, Eslováquia, Irlanda, França, na Polônia, na Alemanha, Itália, Reino Unido, na Austrália, no Canadá, nos Estados Unidos e Índia.Resumo:Fomenta o debate acerca da implementação de incentivos fiscais para ampliação da utilização de fontes deenergiasrenováveistendo como consequência a efetivação do direito fundamental ao meio ambiente saudável. Dessa forma, o direito tributário auxilia de maneira efetiva o direito ambiental. Apresentam-se as principais fontes deenergiasrenováveise a potencialidade brasileira para sua utilização. Descrevem-se alguns incentivos já existentes e demonstra-se a necessidade de se ter uma tributação sustentável diretamente relacionada àsenergiasrenováveis. Finaliza-se com algumas proposições que objetivam a maior utilização de fontes deenergiarenováveise conclui-se que a existência de uma tributação sustentável permitirá que a potencialidade brasileira relacionada às fontes deenergiasrenováveisaflore, por conseguinte, o Brasil dará um salto na proteção ambiental.Sumário:Energiasrenováveis- uma potencialidade brasileira: Alguns incentivos concedidos para utilização de fontes deenergiasrenováveis-- Tributação sustentável para fontes deenergiasrenováveis: Incentivos fiscais às fontes deenergiarenováveis. | Assuntos: Fonterenováveldeenergia, consumo, Brasil. {Fonterenováveldeenergia; Fontes novas erenováveisdeenergia} Incentivo fiscal, direito comparado. Políticas públicas, Brasil. Potencial energético, aspectos ambientais, Brasil. Fonterenováveldeenergia, natureza fiscal, Brasil. {Fonterenováveldeenergia; Fontes novas erenováveisdeenergia}', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PÚBLICO - 341::DIREITO ADMINISTRATIVO - 341.3::Domínio Público. Conceito. Domínio Eminente. Domínio Patrimonial - 341.34::Direito Ambiental - 341.347', 'Resumo:Estudo comparado sobre o tratamento dado ao imposto e à fontes deenergiasrenováveisno direito da Polônia, República Tcheca, Eslováquia, Irlanda, França, na Polônia, na Alemanha, Itália, Reino Unido, na Austrália, no Canadá, nos Estados Unidos e Índia.Resumo:Fomenta o debate acerca da implementação de incentivos fiscais para ampliação da utilização de fontes deenergiasrenováveistendo como consequência a efetivação do direito fundamental ao meio ambiente saudável. Dessa forma, o direito tributário auxilia de maneira efetiva o direito ambiental. Apresentam-se as principais fontes deenergiasrenováveise a potencialidade brasileira para sua utilização. Descrevem-se alguns incentivos já existentes e demonstra-se a necessidade de se ter uma tributação sustentável diretamente relacionada àsenergiasrenováveis. Finaliza-se com algumas proposições que objetivam a maior utilização de fontes deenergiarenováveise conclui-se que a existência de uma tributação sustentável permitirá que a potencialidade brasileira relacionada às fontes deenergiasrenováveisaflore, por conseguinte, o Brasil dará um salto na proteção ambiental.Sumário:Energiasrenováveis- uma potencialidade brasileira: Alguns incentivos concedidos para utilização de fontes deenergiasrenováveis-- Tributação sustentável para fontes deenergiasrenováveis: Incentivos fiscais às fontes deenergiarenováveis. | Assuntos: Fonterenováveldeenergia, consumo, Brasil. {Fonterenováveldeenergia; Fontes novas erenováveisdeenergia} Incentivo fiscal, direito comparado. Políticas públicas, Brasil. Potencial energético, aspectos ambientais, Brasil. Fonterenováveldeenergia, natureza fiscal, Brasil. {Fonterenováveldeenergia; Fontes novas erenováveisdeenergia}', '', 'Goron, Henrique Sampaio', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Doutrina___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Direito dasenergiasrenováveis', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:livro:2014;001012207', NULL, '', '', 'doutrina', 'Resumo:Estudo de direito comparado sobreenergiasrenováveisna Espanha, Alemanha, Itália, Reino Unido e Portugal.Resumo:Aborda o tema dasenergiasrenováveissob uma abordagem holística, embora centrada nos problemas jurídicos específicos. Está organizado em quatro partes fundamentais. Uma primeira na qual é dada especial ênfase à importância económica deste sector, às diversas fileiras que o compõem e à evolução da programação política nacional. Na segunda procura-se contextualizar a política do fomento dasenergiasrenováveisno direito europeu, incluindo uma análise do tema no quadro dos auxílios de Estado. A terceira parte apresenta um estudo-síntese sobre os regimes de organização e funcionamento da produção deenergiaa partir de fontesrenováveisem quatro países, nomeadamente Espanha, Alemanha, Itália e Reino Unido. Por último, na quarta parte, desenvolve-se a temática dasenergiasrenováveisem Portugal sob uma perspectiva de evolução temporal, que culmina com as perspectivas do que será a evolução do sector num futuro próximo. | Assuntos: Biomassa.Energiaeólica. {Energiaeólica;Energiados ventos; Força eólica} Etanol como combustível. Incentivo fiscal, aspectos ambientais. Política energética. Potencial energético, aspectos ambientais. Proteção ambiental. {Proteção ambiental; Degradação ambiental, prevenção; Meio ambiente, proteção; Recursos naturais, proteção} Fonterenováveldeenergia, direito comparado. {Fonterenováveldeenergia; Fontes novas erenováveisdeenergia}', '', 'LexML', 'transport_energy', 'Livro', 'Classificação: DIREITO PÚBLICO - 341::DIREITO ADMINISTRATIVO - 341.3::Domínio Público. Conceito. Domínio Eminente. Domínio Patrimonial - 341.34::Direito Ambiental - 341.347', 'Resumo:Estudo de direito comparado sobreenergiasrenováveisna Espanha, Alemanha, Itália, Reino Unido e Portugal.Resumo:Aborda o tema dasenergiasrenováveissob uma abordagem holística, embora centrada nos problemas jurídicos específicos. Está organizado em quatro partes fundamentais. Uma primeira na qual é dada especial ênfase à importância económica deste sector, às diversas fileiras que o compõem e à evolução da programação política nacional. Na segunda procura-se contextualizar a política do fomento dasenergiasrenováveisno direito europeu, incluindo uma análise do tema no quadro dos auxílios de Estado. A terceira parte apresenta um estudo-síntese sobre os regimes de organização e funcionamento da produção deenergiaa partir de fontesrenováveisem quatro países, nomeadamente Espanha, Alemanha, Itália e Reino Unido. Por último, na quarta parte, desenvolve-se a temática dasenergiasrenováveisem Portugal sob uma perspectiva de evolução temporal, que culmina com as perspectivas do que será a evolução do sector num futuro próximo. | Assuntos: Biomassa.Energiaeólica. {Energiaeólica;Energiados ventos; Força eólica} Etanol como combustível. Incentivo fiscal, aspectos ambientais. Política energética. Potencial energético, aspectos ambientais. Proteção ambiental. {Proteção ambiental; Degradação ambiental, prevenção; Meio ambiente, proteção; Recursos naturais, proteção} Fonterenováveldeenergia, direito comparado. {Fonterenováveldeenergia; Fontes novas erenováveisdeenergia}', '', 'Soares, Cláudia Dias', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Doutrina___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'A trajetória daenergiarenovávelno marco normativo europeu', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2019;1001206844', NULL, '', '', 'doutrina', 'Resumo:" Este artigo tem por objetivo analisar a trajetória das normativas da União Europeia (UE) para a implementação deenergiasrenováveis, mais especificamente de biocombustíveis, em seu território. Para o seu desenvolvimento, a metodologia utilizada foi a análise documental dos textos normativos que disciplinam a matéria, por meio de uma organização que segue o critério cronológico. Os resultados alcançados dão conta da evolução das discussões e da regulamentação sobre o tema, que resultou na Diretiva 28/2009, e demonstram a importância dada àsenergiasrenováveisespecialmente aos biocombustíveis, na Comunidade Europeia. Ademais, o percurso trilhado possibilita uma melhor compreensão das propostas que se encontram em fase de tramitação no Parlamento Europeu, e que devem ser encerradas até 2020. Por sua vez, a conclusão é no sentido de que o desafio de construção de um sistema de regulação do uso deenergiasrenováveisna UE permanece em aberto, devendo continuar a ser observado de perto."Sumário:Trajetória da normativa europeia para aenergiarenovável-- Diretiva 28/2009 relativa à promoção da utilização deenergiaproveniente de fontesrenováveis, alterações e novas propostas. | Assuntos: Biocombustível, Países da União Europeia. Fonterenováveldeenergia, Países da União Europeia. {Fonterenováveldeenergia; Fontes novas erenováveisdeenergia} Sustentabilidade ambiental, Países da União Europeia. Desenvolvimento sustentável, Países da União Europeia. {Desenvolvimento sustentável; Desenvolvimento auto-sustentado; Desenvolvimento sustentado}', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PÚBLICO - 341::DIREITO ADMINISTRATIVO - 341.3::Domínio Público. Conceito. Domínio Eminente. Domínio Patrimonial - 341.34::Direito Ambiental - 341.347', 'Resumo:" Este artigo tem por objetivo analisar a trajetória das normativas da União Europeia (UE) para a implementação deenergiasrenováveis, mais especificamente de biocombustíveis, em seu território. Para o seu desenvolvimento, a metodologia utilizada foi a análise documental dos textos normativos que disciplinam a matéria, por meio de uma organização que segue o critério cronológico. Os resultados alcançados dão conta da evolução das discussões e da regulamentação sobre o tema, que resultou na Diretiva 28/2009, e demonstram a importância dada àsenergiasrenováveisespecialmente aos biocombustíveis, na Comunidade Europeia. Ademais, o percurso trilhado possibilita uma melhor compreensão das propostas que se encontram em fase de tramitação no Parlamento Europeu, e que devem ser encerradas até 2020. Por sua vez, a conclusão é no sentido de que o desafio de construção de um sistema de regulação do uso deenergiasrenováveisna UE permanece em aberto, devendo continuar a ser observado de perto."Sumário:Trajetória da normativa europeia para aenergiarenovável-- Diretiva 28/2009 relativa à promoção da utilização deenergiaproveniente de fontesrenováveis, alterações e novas propostas. | Assuntos: Biocombustível, Países da União Europeia. Fonterenováveldeenergia, Países da União Europeia. {Fonterenováveldeenergia; Fontes novas erenováveisdeenergia} Sustentabilidade ambiental, Países da União Europeia. Desenvolvimento sustentável, Países da União Europeia. {Desenvolvimento sustentável; Desenvolvimento auto-sustentado; Desenvolvimento sustentado}', '', 'Trentini, Flávia', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Doutrina___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
