INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Custos de transação emenergiasrenováveise sua importância para o desenvolvimento sustentável', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2014;1001067285', NULL, '', '', 'doutrina', 'Resumo:Oferece uma visão multidisciplinar dos custos de transação emenergiasrenováveis, no contexto da Análise Econômica do Direito, sob a ótica do desenvolvimento e meio ambiente. Identifica as diversas formas deenergiarenovávele suas respectivas variantes com os fundamentos da sustentabilidade, a partir de onde se pode estabelecer a conexão entre uma pequena central hidrelétrica (como fonte deenergiarenovável) e o direito ao meio ambiente ecologicamente equilibrado. Estuda a ideia de governança, sendo fundamental a compreensão institucional da gestão sobre empreendimentos de geração deenergiasrenováveis. Analisa os instrumentos legais de uma boa administração pública a partir do enfoque empresarial, bem como os custos de transação a partir de possíveis incentivos fiscais. Levanta pontos de eficiência para o desenvolvimento setorial que, em conjunto com o dilema da necessidade de preservação ambiental, revelam a possibilidade de um caminho possível para a sustentabilidade energética a partir da Análise Econômica do Direito. | Assuntos: Análise econômica, aspectos jurídicos, Brasil. Conservação da natureza, Brasil. {Conservação da natureza; Conservação ambiental; Conservação do meio ambiente; Meio ambiente, conservação; Natureza, conservação; Preservação da natureza} Desenvolvimento sustentável, Brasil. {Desenvolvimento sustentável; Desenvolvimento auto-sustentado; Desenvolvimento sustentado} Fonterenováveldeenergia, Brasil. {Fonterenováveldeenergia; Fontes novas erenováveisdeenergia} Política energética, aspectos jurídicos, Brasil. Proteção ambiental, aspectos econômicos, Brasil. {Proteção ambiental; Degradação ambiental, prevenção; Meio ambiente, proteção; Recursos naturais, proteção}', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PÚBLICO - 341::DIREITO ADMINISTRATIVO - 341.3::Domínio Público. Conceito. Domínio Eminente. Domínio Patrimonial - 341.34::Direito Ambiental - 341.347', 'Resumo:Oferece uma visão multidisciplinar dos custos de transação emenergiasrenováveis, no contexto da Análise Econômica do Direito, sob a ótica do desenvolvimento e meio ambiente. Identifica as diversas formas deenergiarenovávele suas respectivas variantes com os fundamentos da sustentabilidade, a partir de onde se pode estabelecer a conexão entre uma pequena central hidrelétrica (como fonte deenergiarenovável) e o direito ao meio ambiente ecologicamente equilibrado. Estuda a ideia de governança, sendo fundamental a compreensão institucional da gestão sobre empreendimentos de geração deenergiasrenováveis. Analisa os instrumentos legais de uma boa administração pública a partir do enfoque empresarial, bem como os custos de transação a partir de possíveis incentivos fiscais. Levanta pontos de eficiência para o desenvolvimento setorial que, em conjunto com o dilema da necessidade de preservação ambiental, revelam a possibilidade de um caminho possível para a sustentabilidade energética a partir da Análise Econômica do Direito. | Assuntos: Análise econômica, aspectos jurídicos, Brasil. Conservação da natureza, Brasil. {Conservação da natureza; Conservação ambiental; Conservação do meio ambiente; Meio ambiente, conservação; Natureza, conservação; Preservação da natureza} Desenvolvimento sustentável, Brasil. {Desenvolvimento sustentável; Desenvolvimento auto-sustentado; Desenvolvimento sustentado} Fonterenováveldeenergia, Brasil. {Fonterenováveldeenergia; Fontes novas erenováveisdeenergia} Política energética, aspectos jurídicos, Brasil. Proteção ambiental, aspectos econômicos, Brasil. {Proteção ambiental; Degradação ambiental, prevenção; Meio ambiente, proteção; Recursos naturais, proteção}', '', 'Nascimento Neto, José Osório do', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Doutrina___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
