INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'A navegação decabotagemno Brasil', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2013;1001010435', NULL, '', '', 'doutrina', 'Resumo:Apresenta gráficos com a distribuição logística e a movimentação do tranporte de cargas por tipo de modal no Brasil e em outros países, vantagens e desvantagens da navegação decabotagem, quadro comparativo da capacidade do transporte de carga marítimo, ferroviário e rodoviário, aspectos legais do AFRMM e o que pode ser feito para ampliar o transporte de cabotagem.Sumário:A burocracia nacabotagem-- A questão dos combustíveis marítimos -- A instalação portuária e seus gargalos -- O Adicional de Frete para Renovação da Marinha Mercante - AFRMM -- As iniciativas pró-cabotagem-- Os números dacabotagem. | Assuntos: Navegação decabotagem, Brasil. {Navegação decabotagem;Cabotagem; Transporte decabotagem} Transporte de carga, Brasil. Transporte de carga. Navegação decabotagem. {Navegação decabotagem;Cabotagem; Transporte decabotagem}', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PRIVADO - 342::DIREITO COMERCIAL - 342.2::Direito Marítimo - 342.29::Questões diversas - 342.2901::Navegação em geral - 342.29011::Navegação de pequenacabotagem- 342.290113', 'Resumo:Apresenta gráficos com a distribuição logística e a movimentação do tranporte de cargas por tipo de modal no Brasil e em outros países, vantagens e desvantagens da navegação decabotagem, quadro comparativo da capacidade do transporte de carga marítimo, ferroviário e rodoviário, aspectos legais do AFRMM e o que pode ser feito para ampliar o transporte de cabotagem.Sumário:A burocracia nacabotagem-- A questão dos combustíveis marítimos -- A instalação portuária e seus gargalos -- O Adicional de Frete para Renovação da Marinha Mercante - AFRMM -- As iniciativas pró-cabotagem-- Os números dacabotagem. | Assuntos: Navegação decabotagem, Brasil. {Navegação decabotagem;Cabotagem; Transporte decabotagem} Transporte de carga, Brasil. Transporte de carga. Navegação decabotagem. {Navegação decabotagem;Cabotagem; Transporte decabotagem}', '', 'Serra, Fernando Antonio Correia', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Doutrina___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
