INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'O direito ao transporte misto de passageiros e cargas na navegação decabotagembrasileira', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2016;1001139583', NULL, '', '', 'doutrina', 'Resumo:Aborda o transporte de veículos Ro-Pax.Resumo:"O presente estudo propõe uma nova abordagem para o transporte de passageiros e cargas na navegação decabotagembrasileira, utilizando-se da metodologia do Direito para o seu conhecimento, adotando a análise das normas, dos fatos e dos fenômenos sociais, para se encontrar uma possível adequação do empreendimento com o ordenamento jurídico". | Assuntos: Transporte de carga, Brasil. Transporte de passageiros, Brasil. Navegação decabotagem, Brasil. {Navegação decabotagem;Cabotagem; Transporte decabotagem}', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PRIVADO - 342::DIREITO COMERCIAL - 342.2::Direito Marítimo - 342.29::Questões diversas - 342.2901::Navegação em geral - 342.29011::Navegação de pequenacabotagem- 342.290113', 'Resumo:Aborda o transporte de veículos Ro-Pax.Resumo:"O presente estudo propõe uma nova abordagem para o transporte de passageiros e cargas na navegação decabotagembrasileira, utilizando-se da metodologia do Direito para o seu conhecimento, adotando a análise das normas, dos fatos e dos fenômenos sociais, para se encontrar uma possível adequação do empreendimento com o ordenamento jurídico". | Assuntos: Transporte de carga, Brasil. Transporte de passageiros, Brasil. Navegação decabotagem, Brasil. {Navegação decabotagem;Cabotagem; Transporte decabotagem}', '', 'Lebre, Eduardo Antonio Temponi', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Doutrina___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Cabotagem, proteção à bandeira e livre concorrência', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2018;1001206415', NULL, '', '', 'doutrina', 'Resumo:"O presente trabalho objetiva analisar as peculiaridades do setor de navegação na modalidade decabotagem, bem como as políticas de regulação e proteção da bandeira na circulação de embarcações no Brasil, e realizar uma análise comparativa com as políticas internacionais. Para tanto, utilizou-se o estudo da legislação nacional e internacional sobre o tema, bem como de teoria da regulação."Sumário:A navegação decabotagemno Brasil -- Proteção à bandeira brasileira -- 3 Proteção à bandeira nacional decabotagemno direito internacional e comparado -- Regulação e o papel da Agência Nacional de Transportes Aquaviários - Antaq -- Proteção à bandeira brasileira e livre concorrência. | Assuntos: Bandeira nacional, Brasil. Bandeira de conveniência, Brasil. Navegação decabotagem, Brasil. {Navegação decabotagem;Cabotagem; Transporte decabotagem} Navegação marítima, Brasil. Livre concorrência, Brasil.', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PRIVADO - 342::DIREITO COMERCIAL - 342.2::Direito Marítimo - 342.29', 'Resumo:"O presente trabalho objetiva analisar as peculiaridades do setor de navegação na modalidade decabotagem, bem como as políticas de regulação e proteção da bandeira na circulação de embarcações no Brasil, e realizar uma análise comparativa com as políticas internacionais. Para tanto, utilizou-se o estudo da legislação nacional e internacional sobre o tema, bem como de teoria da regulação."Sumário:A navegação decabotagemno Brasil -- Proteção à bandeira brasileira -- 3 Proteção à bandeira nacional decabotagemno direito internacional e comparado -- Regulação e o papel da Agência Nacional de Transportes Aquaviários - Antaq -- Proteção à bandeira brasileira e livre concorrência. | Assuntos: Bandeira nacional, Brasil. Bandeira de conveniência, Brasil. Navegação decabotagem, Brasil. {Navegação decabotagem;Cabotagem; Transporte decabotagem} Navegação marítima, Brasil. Livre concorrência, Brasil.', '', 'Masuko, Ana Clarissa', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Doutrina___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
