INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Da taxa THC-2 e da insegurança trazida pelos poderes executivo e judiciário', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2017;1001131965', NULL, '', '', 'doutrina', 'Resumo:"O objetivo do presente artigo é expor, de maneira objetiva, os problemas gerados pela existência de decisões antagônicas proferidas pelos Poderes Executivo e Judiciário acerca da legalidade e legitimidade da cobrança da taxa portuária denominada THC-2. Referida taxa é cobrada pela prestação do serviço de segregação e entrega de contêineres por parte dos terminais portuários (também denominados operadores portuários) em face dos terminais retroportuários, responsáveis apenas pelo armazenamento de carga. Os materiais objetos da pesquisa consubstanciam-se nas decisões do Poder Executivo e Judiciário, bem como na legislação vigente e no contexto histórico da criação do referido serviço. Diante da análise crítica de todos esses materiais, chegou-se a duas conclusões importantes: (i) taxa THC-2 é legítima e legal, estando prevista pela legislação vigente e (ii) as decisões proferidas pelo Poder Judiciário apenas conseguiram gerar mais instabilidade às operações portuárias, haja vista a ausência de posição uníssona acerca da matéria".Sumário:Contextualização -- Conceito e origem da THC-2 -- Conflito de entendimentos e a insegurança jurídica. | Assuntos: Princípio da segurança jurídica, Brasil. Transportador marítimo, taxas, Brasil. Porto, taxas, Brasil. {Porto; Terminal portuário}', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PRIVADO - 342::DIREITO COMERCIAL - 342.2::Direito Marítimo - 342.29::Transporte marítimo e fluvial. Conhecimento - 342.295::Carregamentoe descarregamento. Estadia e sobre-estadia - 342.2955', 'Resumo:"O objetivo do presente artigo é expor, de maneira objetiva, os problemas gerados pela existência de decisões antagônicas proferidas pelos Poderes Executivo e Judiciário acerca da legalidade e legitimidade da cobrança da taxa portuária denominada THC-2. Referida taxa é cobrada pela prestação do serviço de segregação e entrega de contêineres por parte dos terminais portuários (também denominados operadores portuários) em face dos terminais retroportuários, responsáveis apenas pelo armazenamento de carga. Os materiais objetos da pesquisa consubstanciam-se nas decisões do Poder Executivo e Judiciário, bem como na legislação vigente e no contexto histórico da criação do referido serviço. Diante da análise crítica de todos esses materiais, chegou-se a duas conclusões importantes: (i) taxa THC-2 é legítima e legal, estando prevista pela legislação vigente e (ii) as decisões proferidas pelo Poder Judiciário apenas conseguiram gerar mais instabilidade às operações portuárias, haja vista a ausência de posição uníssona acerca da matéria".Sumário:Contextualização -- Conceito e origem da THC-2 -- Conflito de entendimentos e a insegurança jurídica. | Assuntos: Princípio da segurança jurídica, Brasil. Transportador marítimo, taxas, Brasil. Porto, taxas, Brasil. {Porto; Terminal portuário}', '', 'Vasconcelos, Ronaldo', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Doutrina___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'O regramento dos serviços de segregação e entrega de contêineres (SSE) e sua interpretação pelos tribunais', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2017;1001137922', NULL, '', '', 'doutrina', 'Resumo:"Este estudo aborda o regramento regulatório dos serviços de segregação e entrega (SSE), também conhecido como THC2, com análise crítica do conceito adotado e a evolução jurisprudencial sobre o tema. Concluímos pela legalidade da cobrança que vem sendo reconhecida pelos Tribunais pátrios".Sumário:Introdução : que é o serviço de segregação e entrega de contêineres -- Inadequação do termo "THC2" -- Fundamentos para cobrança do SSE -- Posição dos Tribunais: Posicionamentos contrários à cobrança. Recentes posicionamentos favoráveis à cobrança. | Assuntos: Administração portuária, Brasil. {Administração portuária; Porto, administração} Carga transporte, tarifa, jurisprudência. Desembarque de carga, tarifa, Brasil. Porto, tarifa, jurisprudência, Brasil. {Porto; Terminal portuário} Container, transporte, tarifa, Brasil.', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PRIVADO - 342::DIREITO COMERCIAL - 342.2::Direito Marítimo - 342.29::Transporte marítimo e fluvial. Conhecimento - 342.295::Carregamentoe descarregamento. Estadia e sobre-estadia - 342.2955', 'Resumo:"Este estudo aborda o regramento regulatório dos serviços de segregação e entrega (SSE), também conhecido como THC2, com análise crítica do conceito adotado e a evolução jurisprudencial sobre o tema. Concluímos pela legalidade da cobrança que vem sendo reconhecida pelos Tribunais pátrios".Sumário:Introdução : que é o serviço de segregação e entrega de contêineres -- Inadequação do termo "THC2" -- Fundamentos para cobrança do SSE -- Posição dos Tribunais: Posicionamentos contrários à cobrança. Recentes posicionamentos favoráveis à cobrança. | Assuntos: Administração portuária, Brasil. {Administração portuária; Porto, administração} Carga transporte, tarifa, jurisprudência. Desembarque de carga, tarifa, Brasil. Porto, tarifa, jurisprudência, Brasil. {Porto; Terminal portuário} Container, transporte, tarifa, Brasil.', '', 'Paula, Diego de', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Doutrina___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
