INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Os desafios regulatórios do pré-sal e os seus reflexos na atuação daANP', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2011;1001069168', NULL, '', '', 'doutrina', 'Resumo:Propõe a analise das restrições e possíveis conflitos de competência gerados na atuação daANPa partir da disciplina normativa direcionada ao petróleo e ao gás natural em decorrência das descobertas na camada pré-sal. | Assuntos: Gás natural, exploração, regulamentação, Brasil. {Gás natural; Gás de petróleo} Indústria petrolífera, Brasil. {Indústria petrolífera; Petróleo, indústria} Petróleo submarino, exploração, regulamentação, Brasil. Petróleo, legislação, Brasil. {Petróleo; Óleo cru} Agência reguladora, competência, Brasil.', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PÚBLICO - 341::DIREITO ADMINISTRATIVO - 341.3::Serviços Públicos - 341.32::Execução Indireta. Órgãos da Administração indireta - 341.322::Agências Reguladoras - 341.3221', 'Resumo:Propõe a analise das restrições e possíveis conflitos de competência gerados na atuação daANPa partir da disciplina normativa direcionada ao petróleo e ao gás natural em decorrência das descobertas na camada pré-sal. | Assuntos: Gás natural, exploração, regulamentação, Brasil. {Gás natural; Gás de petróleo} Indústria petrolífera, Brasil. {Indústria petrolífera; Petróleo, indústria} Petróleo submarino, exploração, regulamentação, Brasil. Petróleo, legislação, Brasil. {Petróleo; Óleo cru} Agência reguladora, competência, Brasil.', '', 'Siqueira, Mariana de', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Doutrina___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Sanções concorrenciais e discricionariedade daANP', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:livro:2019;001153097', NULL, '', '', 'doutrina', 'Sumário:Aplicação da Lei de penalidade pela Superintendência de Distribuição e Logística: políticas públicas e interesses públicos -- O estudo de três casos de flexibilização na aplicação da Lei de Penalidades pela Superintendência de Distribuição e Logística -- Instrumentos de flexibilização na aplicação de Lei de Penalidades pela Superintendência de Distribuição e Logística -- A flexibilização na aplicação da Lei de Penalidades e a exigência de análise técnica de avaliação de impacto regulatório da medida de revogação da autorização -- O abastecimento nacional de combustíveis líquidos vs. liberdade de concorrência: interesse público. | Assuntos: Combustível líquido, aspectos jurídicos, Brasil. Combustível líquido, regulação, Brasil. Concorrência, Brasil.', '', 'LexML', 'transport_energy', 'Livro', 'Classificação: DIREITO PÚBLICO - 341::DIREITO ADMINISTRATIVO - 341.3::Domínio Público. Conceito. Domínio Eminente. Domínio Patrimonial - 341.34::Jazidas. Código de Minas - 341.344::Petróleo. Monopólio - 341.3442', 'Sumário:Aplicação da Lei de penalidade pela Superintendência de Distribuição e Logística: políticas públicas e interesses públicos -- O estudo de três casos de flexibilização na aplicação da Lei de Penalidades pela Superintendência de Distribuição e Logística -- Instrumentos de flexibilização na aplicação de Lei de Penalidades pela Superintendência de Distribuição e Logística -- A flexibilização na aplicação da Lei de Penalidades e a exigência de análise técnica de avaliação de impacto regulatório da medida de revogação da autorização -- O abastecimento nacional de combustíveis líquidos vs. liberdade de concorrência: interesse público. | Assuntos: Combustível líquido, aspectos jurídicos, Brasil. Combustível líquido, regulação, Brasil. Concorrência, Brasil.', '', 'Gomes, Lucas Medeiros', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Doutrina___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'A sistemática de conteúdo local e a cooperação entre TCU eANP', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2021;1001208216', NULL, '', '', 'doutrina', 'Resumo:"O Tribunal de Contas da União realizou auditoria operacional para avaliar a Política de Conteúdo Local nas licitações do mercado de petróleo e gás, bem como as implicações e os impactos da ausência de regulamentação adequada sobre o tema dentro da Agência Nacional de Petróleo, Gás Natural e Biocombustíveis. Esse Tribunal fez recomendações e determinações à Agência e ao Ministério de Minas e Energia, e acabou por contribuir de forma efetiva para o aprimoramento regulatório da matéria. Investiga-se, no presente artigo, se é possível haver uma atuação coordenada de um agente regulador e seu controlador ou se, invariavelmente, pode-se pressupor certa dose de conflito entre eles."Sumário:Controle externo e regulação setorial: conflito de instituições?. A função regulatória daANP. O papel fiscalizatório do TCU. Relação entre regulador e seu controlador -- Estudo de caso: auditoria operacional do TCU sobre a sistemática de conteúdo local na indústria do petróleo e gás natural. | Assuntos: Petróleo, produção, Brasil. {Petróleo; Óleo cru} Políticas públicas, Brasil. Petróleo, exploração, Brasil. {Petróleo; Óleo cru} Controle externo, Brasil.', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PÚBLICO - 341::DIREITO ADMINISTRATIVO - 341.3', 'Resumo:"O Tribunal de Contas da União realizou auditoria operacional para avaliar a Política de Conteúdo Local nas licitações do mercado de petróleo e gás, bem como as implicações e os impactos da ausência de regulamentação adequada sobre o tema dentro da Agência Nacional de Petróleo, Gás Natural e Biocombustíveis. Esse Tribunal fez recomendações e determinações à Agência e ao Ministério de Minas e Energia, e acabou por contribuir de forma efetiva para o aprimoramento regulatório da matéria. Investiga-se, no presente artigo, se é possível haver uma atuação coordenada de um agente regulador e seu controlador ou se, invariavelmente, pode-se pressupor certa dose de conflito entre eles."Sumário:Controle externo e regulação setorial: conflito de instituições?. A função regulatória daANP. O papel fiscalizatório do TCU. Relação entre regulador e seu controlador -- Estudo de caso: auditoria operacional do TCU sobre a sistemática de conteúdo local na indústria do petróleo e gás natural. | Assuntos: Petróleo, produção, Brasil. {Petróleo; Óleo cru} Políticas públicas, Brasil. Petróleo, exploração, Brasil. {Petróleo; Óleo cru} Controle externo, Brasil.', '', 'Dantas, Bruno', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Doutrina___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
