INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Incentivosfiscaisinternacionais', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:livro:2010;000880210', NULL, '', '', 'doutrina', 'Sumário:A crise do welfare state e a figura do Estado regulador - a tributação como mecanismo regulatório econômico Ordem econômica e funcionamento regular do mercado - Estado e defesa da concorrência.A extrafiscalidade como mecanismo regulatóriao econômico - o uso da extrafiscalidade em todo o mundo. Efeitos da tributação sobre o processo econômico e as ajudas estatais (as teorias da neutralidade e da não-discriminação em matéria tributária) -- O fenômeno da concorrênciafiscalinternacional: A atração de capital financeiro e de investimento estrangeiro. Fomento à pesquisa e ao desenvolvimento (R&D - Research and devevopmente). Políticas econômicas e sociais em geral -- A regulação da concorrênciafiscalinternacional: OCDE - Organização de Cooperação para o Desenvolvimento Econômico. OMC - Organização Mundial do Comércio. União Europeia. Mercosul. Nafta. Breve comparativo entre os regimes de controle e as figuras examinadas. As espécies de contramedidas (medidas de defesa) para combater a concorrênciafiscalprejudicial - mecanismos unilaterais, bilaterais e multilaterais. Algumas considerações sobre os tratados internacionais em matéria tributária (a questão da dupla ou múltipla tributação da renda como fenômeno prejudicial e o problema da elisão e evasãofiscaisinternacionais). A posição crítica do controle internacional da concorrênciafiscal. O caso brasileiro : análise das medidas de fomento no sistema jurídico brasileiro e em face dos tratados internacionais - tratamento jurídico nacional e internacional. | Assuntos: Bitributação. {Bitributação; Dupla tributação} Concorrência internacional. Direito tributário. {Direito tributário; Direitofiscal} Tributação.Incentivofiscal.', '', 'LexML', 'transport_energy', 'Livro', 'Classificação: DIREITO PÚBLICO - 341::DIREITO ADMINISTRATIVO - 341.3::Direito Tributário - 341.39::Teoria. Fundamentos - 341.391::Incentivosfiscais- 341.39104', 'Sumário:A crise do welfare state e a figura do Estado regulador - a tributação como mecanismo regulatório econômico Ordem econômica e funcionamento regular do mercado - Estado e defesa da concorrência.A extrafiscalidade como mecanismo regulatóriao econômico - o uso da extrafiscalidade em todo o mundo. Efeitos da tributação sobre o processo econômico e as ajudas estatais (as teorias da neutralidade e da não-discriminação em matéria tributária) -- O fenômeno da concorrênciafiscalinternacional: A atração de capital financeiro e de investimento estrangeiro. Fomento à pesquisa e ao desenvolvimento (R&D - Research and devevopmente). Políticas econômicas e sociais em geral -- A regulação da concorrênciafiscalinternacional: OCDE - Organização de Cooperação para o Desenvolvimento Econômico. OMC - Organização Mundial do Comércio. União Europeia. Mercosul. Nafta. Breve comparativo entre os regimes de controle e as figuras examinadas. As espécies de contramedidas (medidas de defesa) para combater a concorrênciafiscalprejudicial - mecanismos unilaterais, bilaterais e multilaterais. Algumas considerações sobre os tratados internacionais em matéria tributária (a questão da dupla ou múltipla tributação da renda como fenômeno prejudicial e o problema da elisão e evasãofiscaisinternacionais). A posição crítica do controle internacional da concorrênciafiscal. O caso brasileiro : análise das medidas de fomento no sistema jurídico brasileiro e em face dos tratados internacionais - tratamento jurídico nacional e internacional. | Assuntos: Bitributação. {Bitributação; Dupla tributação} Concorrência internacional. Direito tributário. {Direito tributário; Direitofiscal} Tributação.Incentivofiscal.', '', 'Elali, André', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Doutrina___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
