INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Tributaçãoe desigualdade econômica', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:livro:2020;001176531', NULL, '', '', 'doutrina', 'Sumário:v. 1. Desigualdade econômica.Tributaçãoe desigualdade econômica: Desigualdade econômica e justiça tributária. Desigualdade econômica etributaçãoredistributiva -- v. 2. Iniquidades fiscais natributaçãodireta brasileira: Iniquidades fiscais natributaçãoda renda. Iniquidades fiscais natributaçãodo patrimônio. | Assuntos: Tributação, aspectos socioeconômicos, Brasil. Direito tributário, aspectos socioeconômicos, Brasil. {Direito tributário; Direito fiscal} Capacidade contributiva, aspectos socioeconômicos, Brasil. Desigualdade de renda,tributação, Brasil. Distribuição de renda, Brasil. {Distribuição de renda; Renda, distribuição} Obrigação tributária, aspectos socioeconômicos, Brasil. {Obrigação tributária; Obrigação (direito tributário); Obrigação fiscal} Política fiscal, aspectos socioeconômicos, Brasil. {Política fiscal; Política tributária} Justiça fiscal, Brasil.', '', 'LexML', 'transport_energy', 'Livro', 'Classificação: DIREITO PÚBLICO - 341::DIREITO ADMINISTRATIVO - 341.3::Direito Tributário - 341.39', 'Sumário:v. 1. Desigualdade econômica.Tributaçãoe desigualdade econômica: Desigualdade econômica e justiça tributária. Desigualdade econômica etributaçãoredistributiva -- v. 2. Iniquidades fiscais natributaçãodireta brasileira: Iniquidades fiscais natributaçãoda renda. Iniquidades fiscais natributaçãodo patrimônio. | Assuntos: Tributação, aspectos socioeconômicos, Brasil. Direito tributário, aspectos socioeconômicos, Brasil. {Direito tributário; Direito fiscal} Capacidade contributiva, aspectos socioeconômicos, Brasil. Desigualdade de renda,tributação, Brasil. Distribuição de renda, Brasil. {Distribuição de renda; Renda, distribuição} Obrigação tributária, aspectos socioeconômicos, Brasil. {Obrigação tributária; Obrigação (direito tributário); Obrigação fiscal} Política fiscal, aspectos socioeconômicos, Brasil. {Política fiscal; Política tributária} Justiça fiscal, Brasil.', '', 'Rebouças, Marcus Vinicius Parente', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Doutrina___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Tributaçãoimplícita', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:livro:2010;000896508', NULL, '', '', 'doutrina', 'Resumo:Apresenta os principais conceitos e fundamentos datributaçãoimplícita e testa empiricamente a existência datributaçãoimplícita decorrente da isenção introduzida pela MP n. 281/2006, que exonerou o imposto de renda dos rendimentos produzidos por títulos públicos federais adquiridos por investidores estrangeiros a partir de 16 de fevereiro de 2006. | Assuntos: Impostos, Brasil. {Impostos; Impostos (direito tributário)}Tributação, Brasil.', '', 'LexML', 'transport_energy', 'Livro', 'Classificação: DIREITO PÚBLICO - 341::DIREITO ADMINISTRATIVO - 341.3::Direito Tributário - 341.39::Impostos - 341.396', 'Resumo:Apresenta os principais conceitos e fundamentos datributaçãoimplícita e testa empiricamente a existência datributaçãoimplícita decorrente da isenção introduzida pela MP n. 281/2006, que exonerou o imposto de renda dos rendimentos produzidos por títulos públicos federais adquiridos por investidores estrangeiros a partir de 16 de fevereiro de 2006. | Assuntos: Impostos, Brasil. {Impostos; Impostos (direito tributário)}Tributação, Brasil.', '', 'Wasserman, Claudio', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Doutrina___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Tributaçãoextrafiscal', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2021;3001117886', NULL, '', '', 'doutrina', 'Resumo:Apresenta um estudo sobre o Imposto sobre Circulação de Mercadorias e Serviços\U+00a0\- ICMS, evidenciando o seu aspecto extrafiscal, pautado no mecanismo denominado seletividade em razão da essencialidade. Tal instituto teve sua ideia original instituída a partir da vigência da Constituição Federal 1967, sendo tão somente aplicado no âmbito do Imposto Sobre Produtos Industrializados\U+00a0\ - IPI. Contudo, apesar do longo tempo de vigência do dispositivo, muito se discute na doutrina acerca da obrigatoriedade ou facultatividade da adoção deste critério pelo legislador infraconstitucional, fato este que acarreta em diversas distorções quando datributaçãode produtos essenciais para a vida humana, como a energia elétrica. Analisa a situação atual deste instituto, bem como as medidas necessárias à correção desta disparidade, especialmente no que se refere ao papel poder judiciárioSumário:O panorama do ICMS na Constituição federal de 1988: Breves considerações sobre o perfil constitucional do ICMS. A extrafiscalidade como elemento característico dos tributos. O mecanismo extrafiscal do ICMS: a seletividade em razão da essencialidade. -- Seletividade e essencialidade no manuseio do ICMS: A obrigatoriedade da adoção do critério no âmbito infraconstitucional. Atributaçãoda energia elétrica como exemplo de desvirtuação da seletividade. O papel do poder judiciário no controle da seletividade. | Assuntos: Energia elétrica, impostos, jurisprudência, Brasil.Tributação, Brasil. Impostos, base de cálculo, Brasil. {Impostos; Impostos (direito tributário)} Energia elétrica, impostos, jurisprudência, Brasil.Tributação, Brasil. Impostos, base de cálculo, Brasil. {Impostos; Impostos (direito tributário)} Energia elétrica, impostos, jurisprudência, Brasil.Tributação, Brasil. Impostos, base de cálculo, Brasil. {Impostos; Impostos (direito tributário)}', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PÚBLICO - 341::DIREITO ADMINISTRATIVO - 341.3::Direito Tributário - 341.39::Impostos - 341.396', 'Resumo:Apresenta um estudo sobre o Imposto sobre Circulação de Mercadorias e Serviços\U+00a0\- ICMS, evidenciando o seu aspecto extrafiscal, pautado no mecanismo denominado seletividade em razão da essencialidade. Tal instituto teve sua ideia original instituída a partir da vigência da Constituição Federal 1967, sendo tão somente aplicado no âmbito do Imposto Sobre Produtos Industrializados\U+00a0\ - IPI. Contudo, apesar do longo tempo de vigência do dispositivo, muito se discute na doutrina acerca da obrigatoriedade ou facultatividade da adoção deste critério pelo legislador infraconstitucional, fato este que acarreta em diversas distorções quando datributaçãode produtos essenciais para a vida humana, como a energia elétrica. Analisa a situação atual deste instituto, bem como as medidas necessárias à correção desta disparidade, especialmente no que se refere ao papel poder judiciárioSumário:O panorama do ICMS na Constituição federal de 1988: Breves considerações sobre o perfil constitucional do ICMS. A extrafiscalidade como elemento característico dos tributos. O mecanismo extrafiscal do ICMS: a seletividade em razão da essencialidade. -- Seletividade e essencialidade no manuseio do ICMS: A obrigatoriedade da adoção do critério no âmbito infraconstitucional. Atributaçãoda energia elétrica como exemplo de desvirtuação da seletividade. O papel do poder judiciário no controle da seletividade. | Assuntos: Energia elétrica, impostos, jurisprudência, Brasil.Tributação, Brasil. Impostos, base de cálculo, Brasil. {Impostos; Impostos (direito tributário)} Energia elétrica, impostos, jurisprudência, Brasil.Tributação, Brasil. Impostos, base de cálculo, Brasil. {Impostos; Impostos (direito tributário)} Energia elétrica, impostos, jurisprudência, Brasil.Tributação, Brasil. Impostos, base de cálculo, Brasil. {Impostos; Impostos (direito tributário)}', '', 'Maia, Thiago Nobre', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Doutrina___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Tributaçãoambiental e sustentabilidade', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:livro:2020;001176528', NULL, '', '', 'doutrina', 'Sumário:O quadro datributaçãoambiental: Funções datributaçãoe instrumentos econômico-tributários. A proteção ambiental pela via tributária. Os tributos e benefícios fiscais ambientais no ordenamento jurídico brasileiro -- Análise datributaçãoambiental em face da noção de sustentabilidade: Da sustentabilidade fiscal, ecológica e social. Atributaçãoambiental no setor dos transportes em face do desenvolvimento sustentável. | Assuntos: Tributação, aspectos jurídicos, doutrinas e controvérsias. Proteção ambiental, aspectos econômicos,tributação. {Proteção ambiental; Degradação ambiental, prevenção; Meio ambiente, proteção; Recursos naturais, proteção} Proteção ambiental, impostos, Brasil. {Proteção ambiental; Degradação ambiental, prevenção; Meio ambiente, proteção; Recursos naturais, proteção} Incentivo fiscal, Brasil. Proteção ambiental, impostos. {Proteção ambiental; Degradação ambiental, prevenção; Meio ambiente, proteção; Recursos naturais, proteção} Sustentabilidade ambiental, aspectos constitucionais, Brasil. Transporte, modernização, efeito ambiental, Brasil. Combustível, efeito ambiental, natureza fiscal, Brasil. {Combustível; Carburante}Tributação, aspectos constitucionais, legislação, Brasil.', '', 'LexML', 'transport_energy', 'Livro', 'Classificação: DIREITO PÚBLICO - 341::DIREITO ADMINISTRATIVO - 341.3::Direito Tributário - 341.39', 'Sumário:O quadro datributaçãoambiental: Funções datributaçãoe instrumentos econômico-tributários. A proteção ambiental pela via tributária. Os tributos e benefícios fiscais ambientais no ordenamento 