INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Emissãode CAT por perda auditiva', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2007;1000788311', NULL, '', '', 'doutrina', 'Resumo:Apresenta relatório dos indicadores de desempenho do PPCA e fluxograma para indicação deemissãode CAT.Resumo:Faz uma abordagem epidemiológica sobre a perda auditiva neurossensorial por exposição continuada a níveis elevados de pressão sonora, as situações em que essa perda poderá ser considerada acidente do trabalho e enumera as situações em que a Comunicação de acidente de trabalho - CAT deverá ser emitida. Sua abordagem se baseia nas conclusões da 3ª Conferência Nacional de SST. | Assuntos: Deficiência auditiva, diagnóstico, Brasil. {Deficiência auditiva; Distúrbio da audição} Doença profissional, diagnóstico, Brasil. {Doença profissional; Doença do trabalho; Doença ocupacional} Doença profissional, legislação, Brasil. {Doença profissional; Doença do trabalho; Doença ocupacional} Acidente do trabalho, diagnóstico, Brasil. {Acidente do trabalho; Trabalho, acidente} Nexo de causalidade, Brasil. Condições de trabalho, Brasil. Audição, diagnóstico, Brasil. Benefício previdenciário, Brasil.', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PÚBLICO - 341::DIREITO PREVIDENCIÁRIO. SEGURIDADE SOCIAL - 341.6', 'Resumo:Apresenta relatório dos indicadores de desempenho do PPCA e fluxograma para indicação deemissãode CAT.Resumo:Faz uma abordagem epidemiológica sobre a perda auditiva neurossensorial por exposição continuada a níveis elevados de pressão sonora, as situações em que essa perda poderá ser considerada acidente do trabalho e enumera as situações em que a Comunicação de acidente de trabalho - CAT deverá ser emitida. Sua abordagem se baseia nas conclusões da 3ª Conferência Nacional de SST. | Assuntos: Deficiência auditiva, diagnóstico, Brasil. {Deficiência auditiva; Distúrbio da audição} Doença profissional, diagnóstico, Brasil. {Doença profissional; Doença do trabalho; Doença ocupacional} Doença profissional, legislação, Brasil. {Doença profissional; Doença do trabalho; Doença ocupacional} Acidente do trabalho, diagnóstico, Brasil. {Acidente do trabalho; Trabalho, acidente} Nexo de causalidade, Brasil. Condições de trabalho, Brasil. Audição, diagnóstico, Brasil. Benefício previdenciário, Brasil.', '', 'Kwitko, Airton', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Doutrina___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
