INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'O compliance como instrumento concretizador dasustentabilidade', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2019;1001207400', NULL, '', '', 'doutrina', 'Resumo:"Asustentabilidadetoma relevo a partir da necessidade de conciliação de valores caros à sociedade contemporânea, quais sejam, desenvolvimento econômico, preservação ambiental e diminuição das desigualdades sociais. Esses são os três pilares do desenvolvimento sustentável, reconhecidos pelos organismos internacionais. A permear o tripé econômico, ambiental e social, encontra-se a questão ética, pressuposto essencial para a implementação dasustentabilidade. A partir da delimitação da contemporânea conceituação do direito ao desenvolvimento e sua correlação com asustentabilidadee suas implicações éticas, mormente no setor empresarial, busca-se, no presente artigo, estabelecer a necessária conexão entresustentabilidadee compliance. Asustentabilidadeencontra sua efetivação na ética empresarial. Apresenta-se o compliance como instrumento importante para a concretização desta ética e, consequentemente, para implementação de um desenvolvimento que se possa caracterizar como sustentável. Concluiu-se que asustentabilidadesomente será efetivada na junção e equilíbrio entre economia (mercado), ética e Direito. A elaboração do artigo utilizou-se do método lógico-dedutivo, baseando-se em pesquisa bibliográfica, fundamentada nos problemas destacados e nos seus desdobramentos."Sumário:Direito ao desenvolvimento,sustentabilidadee ética empresarial -- Considerações acerca do compliance. Ética empresarial, compliance esustentabilidade. | Assuntos: Compliance, aspectos ambientais. Empresa, aspectos ambientais. Governança corporativa, aspectos ambientais.Sustentabilidadeambiental. Ética empresarial, aspectos ambientais.', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PÚBLICO - 341::DIREITO ADMINISTRATIVO - 341.3::Domínio Público. Conceito. Domínio Eminente. Domínio Patrimonial - 341.34::Direito Ambiental - 341.347', 'Resumo:"Asustentabilidadetoma relevo a partir da necessidade de conciliação de valores caros à sociedade contemporânea, quais sejam, desenvolvimento econômico, preservação ambiental e diminuição das desigualdades sociais. Esses são os três pilares do desenvolvimento sustentável, reconhecidos pelos organismos internacionais. A permear o tripé econômico, ambiental e social, encontra-se a questão ética, pressuposto essencial para a implementação dasustentabilidade. A partir da delimitação da contemporânea conceituação do direito ao desenvolvimento e sua correlação com asustentabilidadee suas implicações éticas, mormente no setor empresarial, busca-se, no presente artigo, estabelecer a necessária conexão entresustentabilidadee compliance. Asustentabilidadeencontra sua efetivação na ética empresarial. Apresenta-se o compliance como instrumento importante para a concretização desta ética e, consequentemente, para implementação de um desenvolvimento que se possa caracterizar como sustentável. Concluiu-se que asustentabilidadesomente será efetivada na junção e equilíbrio entre economia (mercado), ética e Direito. A elaboração do artigo utilizou-se do método lógico-dedutivo, baseando-se em pesquisa bibliográfica, fundamentada nos problemas destacados e nos seus desdobramentos."Sumário:Direito ao desenvolvimento,sustentabilidadee ética empresarial -- Considerações acerca do compliance. Ética empresarial, compliance esustentabilidade. | Assuntos: Compliance, aspectos ambientais. Empresa, aspectos ambientais. Governança corporativa, aspectos ambientais.Sustentabilidadeambiental. Ética empresarial, aspectos ambientais.', '', 'Medeiros Neto, Elias Marques de', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Doutrina___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
