INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Desenvolvimento sustentável e estudo deimpactoambiental', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:livro:2017;001107617', NULL, '', '', 'doutrina', 'Sumário:Desenvolvimento e o meio ambiente: Da criseambiental. História e evolução do desenvolvimento sustentável. O desenvolvimento sustentável no Brasil -- Proteção jurídica do meio ambiente: O meio ambiente na Constituição Federal de 1988. Conceitosambientaise suas classificações. Princípios norteadores da proteçãoambiental. Tutela penal do meio ambiente : Lei de crimesambientais(nº 9.605/98). Responsabilidade por danos socioambientais. Instituições de proteção -- Estudo deimpactoambientale o desenvolvimento sustentável: Concepção deimpactoambientale os princípios orientadores. Oimpactoambientale a interpretação dos mecanismos e ações de tutela do meio ambiente no direito internacional. A necessidade do estudo deimpactoambientalpara o desenvolvimento sustentável do estdo brasileiro. Análise do EIA/RIMA do projeto de ntegração do rio são francisco com bacias hidrográficas do nordeste brasileiro. | Assuntos: Crimeambiental, Brasil. Direitoambiental, Brasil. {Direitoambiental; Direito ecológico}Impactoambiental, Brasil. Desenvolvimento sustentável, Brasil. {Desenvolvimento sustentável; Desenvolvimento auto-sustentado; Desenvolvimento sustentado}', '', 'LexML', 'transport_energy', 'Livro', 'Classificação: DIREITO PÚBLICO - 341::DIREITO ADMINISTRATIVO - 341.3::Domínio Público. Conceito. Domínio Eminente. Domínio Patrimonial - 341.34::DireitoAmbiental- 341.347', 'Sumário:Desenvolvimento e o meio ambiente: Da criseambiental. História e evolução do desenvolvimento sustentável. O desenvolvimento sustentável no Brasil -- Proteção jurídica do meio ambiente: O meio ambiente na Constituição Federal de 1988. Conceitosambientaise suas classificações. Princípios norteadores da proteçãoambiental. Tutela penal do meio ambiente : Lei de crimesambientais(nº 9.605/98). Responsabilidade por danos socioambientais. Instituições de proteção -- Estudo deimpactoambientale o desenvolvimento sustentável: Concepção deimpactoambientale os princípios orientadores. Oimpactoambientale a interpretação dos mecanismos e ações de tutela do meio ambiente no direito internacional. A necessidade do estudo deimpactoambientalpara o desenvolvimento sustentável do estdo brasileiro. Análise do EIA/RIMA do projeto de ntegração do rio são francisco com bacias hidrográficas do nordeste brasileiro. | Assuntos: Crimeambiental, Brasil. Direitoambiental, Brasil. {Direitoambiental; Direito ecológico}Impactoambiental, Brasil. Desenvolvimento sustentável, Brasil. {Desenvolvimento sustentável; Desenvolvimento auto-sustentado; Desenvolvimento sustentado}', '', 'Jatobá, Augusto César Maurício de Oliveira', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Doutrina___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
