INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Avaliação deimpactoambiental', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2020;1001209524', NULL, '', '', 'doutrina', 'Resumo:"O presente artigo tem como objetivo demonstrar a existência de falhas e vícios que possam obstar a efetividade da avaliação deimpactoambiental, em face do licenciamento brasileiro. Na busca de argumentos, será utilizado um viés doutrinário, especialmente em Luís Enrique Sanchez e Marina Motta Benevides Gadelha. A metodologia utilizada baseou-se na pesquisa bibliográfica com raciocínio crítico-dedutivo. Um dos apontamentos percebidos no artigo são as consequências negativas e diretas dessas falhas e vícios na efetividade da AIA, com repercussão no equilíbrio da equação permeada pelo desenvolvimento, o meio ambiente e as normas de regências desses segmentos."Sumário:Considerações gerais sobre a avaliação deimpactoambiental, sua origem e seu estabelecimento como instrumento de gestãoambiental-- A introdução da avaliação deimpactoambientalno contexto normativo brasileiro -- Obstáculos à efetividade da avaliação deimpactoambientalno âmbito dos processos de licenciamento brasileiro. | Assuntos: Políticaambiental. {Políticaambiental; Ecologia, política; Meio ambiente, política; Política do meio ambiente}Impactoambiental, avaliação. Desenvolvimento sustentável. {Desenvolvimento sustentável; Desenvolvimento auto-sustentado; Desenvolvimento sustentado} Educaçãoambiental. {Educaçãoambiental; Meio ambiente, ensino; Proteçãoambiental, ensino} Gestãoambiental.', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PÚBLICO - 341::DIREITO ADMINISTRATIVO - 341.3::Domínio Público. Conceito. Domínio Eminente. Domínio Patrimonial - 341.34::DireitoAmbiental- 341.347', 'Resumo:"O presente artigo tem como objetivo demonstrar a existência de falhas e vícios que possam obstar a efetividade da avaliação deimpactoambiental, em face do licenciamento brasileiro. Na busca de argumentos, será utilizado um viés doutrinário, especialmente em Luís Enrique Sanchez e Marina Motta Benevides Gadelha. A metodologia utilizada baseou-se na pesquisa bibliográfica com raciocínio crítico-dedutivo. Um dos apontamentos percebidos no artigo são as consequências negativas e diretas dessas falhas e vícios na efetividade da AIA, com repercussão no equilíbrio da equação permeada pelo desenvolvimento, o meio ambiente e as normas de regências desses segmentos."Sumário:Considerações gerais sobre a avaliação deimpactoambiental, sua origem e seu estabelecimento como instrumento de gestãoambiental-- A introdução da avaliação deimpactoambientalno contexto normativo brasileiro -- Obstáculos à efetividade da avaliação deimpactoambientalno âmbito dos processos de licenciamento brasileiro. | Assuntos: Políticaambiental. {Políticaambiental; Ecologia, política; Meio ambiente, política; Política do meio ambiente}Impactoambiental, avaliação. Desenvolvimento sustentável. {Desenvolvimento sustentável; Desenvolvimento auto-sustentado; Desenvolvimento sustentado} Educaçãoambiental. {Educaçãoambiental; Meio ambiente, ensino; Proteçãoambiental, ensino} Gestãoambiental.', '', 'Ribeiro, José Claudio Junqueira', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Doutrina___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
