INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Auditoriaambientalde acompanhamento na implantação de avaliações deimpactoestratégicoambientale incremento de resultados', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2017;1001115777', NULL, '', '', 'doutrina', 'Resumo:"As auditoriasambientaisconstituem tema ainda não popularizado no DireitoAmbiental, em especial porque são mais frequentemente associadas apenas à prevenção de passivosambientaissob a ótica do Direito Empresarial ou em caráter preventivo interno. Propõe-se que essas auditorias podem permitir maior controle, combinadas a outro instrumento também pouco conhecido, a Avaliação deImpactoEstratégico (AIA). Uma das razões aqui debatidas propõe programa mais estruturado de avaliação, favorecendo encadeamento e praticidade de suas ações e aumento de eficiência, para disseminação de seu uso. Preliminarmente, estabelece diferenças conceituais comuns entre as avaliações disponíveis, desenvolve a relação entre versão mais ampla das possibilidades das auditorias e o fortalecimento da avaliação deimpactoestratégico. Publicizar a discussão, esclarecer visões desses instrumentos e estabelecer relações são os objetivos precípuos deste artigo, além de discutir, acessoriamente, crises anteriores que justificam e convidam a refletir sobre a validade da proposta". | Assuntos: Auditoria.Impactoambiental, avaliação, aspectos jurídicos.', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PÚBLICO - 341::DIREITO ADMINISTRATIVO - 341.3::Domínio Público. Conceito. Domínio Eminente. Domínio Patrimonial - 341.34::DireitoAmbiental- 341.347', 'Resumo:"As auditoriasambientaisconstituem tema ainda não popularizado no DireitoAmbiental, em especial porque são mais frequentemente associadas apenas à prevenção de passivosambientaissob a ótica do Direito Empresarial ou em caráter preventivo interno. Propõe-se que essas auditorias podem permitir maior controle, combinadas a outro instrumento também pouco conhecido, a Avaliação deImpactoEstratégico (AIA). Uma das razões aqui debatidas propõe programa mais estruturado de avaliação, favorecendo encadeamento e praticidade de suas ações e aumento de eficiência, para disseminação de seu uso. Preliminarmente, estabelece diferenças conceituais comuns entre as avaliações disponíveis, desenvolve a relação entre versão mais ampla das possibilidades das auditorias e o fortalecimento da avaliação deimpactoestratégico. Publicizar a discussão, esclarecer visões desses instrumentos e estabelecer relações são os objetivos precípuos deste artigo, além de discutir, acessoriamente, crises anteriores que justificam e convidam a refletir sobre a validade da proposta". | Assuntos: Auditoria.Impactoambiental, avaliação, aspectos jurídicos.', '', 'Pontes, Ana Carolina Amaral de', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Doutrina___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
