INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Accidenteslaborales de tráfico', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:livro:2015;001050033', NULL, '', '', 'doutrina', 'Sumário:El accidente de tráfico como prototípico accidente de trabajo: La protección del accidente laboral y su influencia en el accidente de tráfico. Las modalidades del accidente laboral de tráfico -- El difícil diálogo de las normas de tráfico con las normas de seguridad social -- Elementos configuradores del accidente laboral de tráfico: Los elementos del accidente de trabajo y su conexión con el accidente de tráfico -- El accidente laboral de tráfico "propio": Incumplimientos del trabajador y responsabilidad de la empresa. Análisis de circunstancia particulares: Conducción bajo la influencia de bebidas alcohólicas. Conducción bajo la influencia de sustancias estupefacientes. Sobrevelocidad -- El accidente laboral de tráfico "in itinere" -- El accidente como consecuencia del desempeño de cargos de carácter sindical -- El accidente laboral de tráfico en misión -- El accidente de tráfico en actos de salvamento o análogos -- La imprudencia temeraria en losaccidenteslaborales de tráfico. | Assuntos: Acidentedo trabalho, Espanha. {Acidentedo trabalho; Trabalho,acidente}Acidentein itinere, Espanha. {Acidentein itinere;Acidentede trajeto;Acidenteno itinerário;Acidenteno percurso para o trabalho}Acidentede trânsito, Espanha. {Acidentede trânsito;Acidentede automóvel;Acidentede tráfego; Automóvel,acidente; Tráfego,acidente; Trânsito,acidente}', '', 'LexML', 'transport_energy', 'Livro', 'Classificação: DIREITO PRIVADO - 342::DIREITO DO TRABALHO - 342.6::Acidentesdo Trabalho - 342.61', 'Sumário:El accidente de tráfico como prototípico accidente de trabajo: La protección del accidente laboral y su influencia en el accidente de tráfico. Las modalidades del accidente laboral de tráfico -- El difícil diálogo de las normas de tráfico con las normas de seguridad social -- Elementos configuradores del accidente laboral de tráfico: Los elementos del accidente de trabajo y su conexión con el accidente de tráfico -- El accidente laboral de tráfico "propio": Incumplimientos del trabajador y responsabilidad de la empresa. Análisis de circunstancia particulares: Conducción bajo la influencia de bebidas alcohólicas. Conducción bajo la influencia de sustancias estupefacientes. Sobrevelocidad -- El accidente laboral de tráfico "in itinere" -- El accidente como consecuencia del desempeño de cargos de carácter sindical -- El accidente laboral de tráfico en misión -- El accidente de tráfico en actos de salvamento o análogos -- La imprudencia temeraria en losaccidenteslaborales de tráfico. | Assuntos: Acidentedo trabalho, Espanha. {Acidentedo trabalho; Trabalho,acidente}Acidentein itinere, Espanha. {Acidentein itinere;Acidentede trajeto;Acidenteno itinerário;Acidenteno percurso para o trabalho}Acidentede trânsito, Espanha. {Acidentede trânsito;Acidentede automóvel;Acidentede tráfego; Automóvel,acidente; Tráfego,acidente; Trânsito,acidente}', '', 'Arias Domínguez, Ángel', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Doutrina___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
