INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Algumas questões sobre a recente decisão do STJ na arbitragem Petrobras v.ANP', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2018;1001124660', NULL, '', '', 'doutrina', 'Sumário:O caso : quais são os fatos? -- O julgamento no STJ : quem votou como? -- Análise das questões jurídicas debatidas : pontos positivos e pontos negativos: Reconhecimento da natureza jurisdicional da arbitragem : arbitragem é jurisdição. Visão ampla a respeito da arbitrabilidade objetiva : disputas decorrentes de contrato de concessão para exploração de petróleo e gás natural são arbitráveis. Valorização do princípio da competência-competência, mas só em certa medida. Ausência de enfrentamento do inciso VII do art. 485 do Código de Processo Civil : silêncio ensurdecedor. | Assuntos: Cláusula compromissória, Brasil. Concessão comercial, Brasil. Conflito de competência, Brasil. Gás natural, exploração, Brasil. {Gás natural; Gás de petróleo} Juízo arbitral, Brasil. Petróleo, exploração, Brasil. {Petróleo; Óleo cru} Poder judiciário, competência, Brasil. Arbitragem, decisão judicial, Brasil.', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PÚBLICO - 341::DIREITO PROCESSUAL - 341.4::Direito Processual Civil - 341.46::Processos particulares - 341.461::Processo diante de árbitros. Arbitragem - 341.4618', 'Sumário:O caso : quais são os fatos? -- O julgamento no STJ : quem votou como? -- Análise das questões jurídicas debatidas : pontos positivos e pontos negativos: Reconhecimento da natureza jurisdicional da arbitragem : arbitragem é jurisdição. Visão ampla a respeito da arbitrabilidade objetiva : disputas decorrentes de contrato de concessão para exploração de petróleo e gás natural são arbitráveis. Valorização do princípio da competência-competência, mas só em certa medida. Ausência de enfrentamento do inciso VII do art. 485 do Código de Processo Civil : silêncio ensurdecedor. | Assuntos: Cláusula compromissória, Brasil. Concessão comercial, Brasil. Conflito de competência, Brasil. Gás natural, exploração, Brasil. {Gás natural; Gás de petróleo} Juízo arbitral, Brasil. Petróleo, exploração, Brasil. {Petróleo; Óleo cru} Poder judiciário, competência, Brasil. Arbitragem, decisão judicial, Brasil.', '', 'Monteiro, André Luís', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Doutrina___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
