INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Políticadepatentes em saúde humana', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:livro:2001;000612898', NULL, '', '', 'doutrina', 'Resumo:Reúne artigos de especialistas sobre a nova Lei da Propriedade Industrial Brasileira no que tange à prática de patentes em medicamentos. Demonstra as falhas da legislação brasileira específica e sugere alternativas para seu aperfeiçoamento. Apresenta também uma perspectiva internacional sobre o tema, citando acordos e tratados. Aprecia questões polêmicas e atuais: patentes de produtos de origem biológica,preçosna indústria farmacêutica, licença compulsória, direito da concorrência, exaustão internacional de patentes e a questão dos medicamentos genéricos.Sumário:PolíticaPública Setorial e de Propriedade Intelectual / Márcio Iorio Aranha --PolíticadePatentes em Face da Pesquisa em Saúde Humana: desafios e perspectivas no Brasil / Simone H. C. Scholze -- Patentes de Produtos de Origem Biológica / Ela Wiecko Volkmer de Castilho --Preçosna Indústria Farmacêutica: abuso e salvaguardas em propriedade industrial. A Questão Brasileira Atual / A. L. Figueira Barbosa -- Licenças Compulsórias e Legislação Brasileira sobre Patentes / Lucas Rocha Furtado -- Algumas Considerações sobre o Sistema de Patentes e a Saúde Humana / Maria Margarida R. Mittelbach --PolíticadePatentes e o Direito da Concorrência / Celso Fernandes Campilongo -- Exaustão Internacional de Patentes e Questões Afins / Antonio Fonseca -- Posfácio - Recente Questão das Patentes e dos Medicamentos Genéricos no Brasil / Alessandro Lordêllo e Luiz Felipe Moreira Lima. | Assuntos: Políticadesaúde, coletânea, Brasil. {Políticadesaúde; Saúde,,política; Saúde,,políticaspúblicas;Políticamédica} Patente, Brasil. Patente, legislação, Brasil. Propriedade industrial, Brasil. {Propriedade industrial; Marca de fábrica, registro; Registro da marca} Propriedade intelectual. {Propriedade intelectual; Propriedade imaterial} Indústria farmacêutica. Concorrência. Medicamento, Brasil. {Medicamento; Droga lícita; Remédio} Saúde, Brasil. Pesquisa médica, Brasil. {Pesquisa médica; Medicina, pesquisa; Saúde, pesquisa}', '', 'LexML', 'transport_energy', 'Livro', '', 'Resumo:Reúne artigos de especialistas sobre a nova Lei da Propriedade Industrial Brasileira no que tange à prática de patentes em medicamentos. Demonstra as falhas da legislação brasileira específica e sugere alternativas para seu aperfeiçoamento. Apresenta também uma perspectiva internacional sobre o tema, citando acordos e tratados. Aprecia questões polêmicas e atuais: patentes de produtos de origem biológica,preçosna indústria farmacêutica, licença compulsória, direito da concorrência, exaustão internacional de patentes e a questão dos medicamentos genéricos.Sumário:PolíticaPública Setorial e de Propriedade Intelectual / Márcio Iorio Aranha --PolíticadePatentes em Face da Pesquisa em Saúde Humana: desafios e perspectivas no Brasil / Simone H. C. Scholze -- Patentes de Produtos de Origem Biológica / Ela Wiecko Volkmer de Castilho --Preçosna Indústria Farmacêutica: abuso e salvaguardas em propriedade industrial. A Questão Brasileira Atual / A. L. Figueira Barbosa -- Licenças Compulsórias e Legislação Brasileira sobre Patentes / Lucas Rocha Furtado -- Algumas Considerações sobre o Sistema de Patentes e a Saúde Humana / Maria Margarida R. Mittelbach --PolíticadePatentes e o Direito da Concorrência / Celso Fernandes Campilongo -- Exaustão Internacional de Patentes e Questões Afins / Antonio Fonseca -- Posfácio - Recente Questão das Patentes e dos Medicamentos Genéricos no Brasil / Alessandro Lordêllo e Luiz Felipe Moreira Lima. | Assuntos: Políticadesaúde, coletânea, Brasil. {Políticadesaúde; Saúde,,políti