INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Financiamentos', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2017;1001115902', NULL, '', '', 'doutrina', 'Resumo:"O presente trabalho desenvolver-se-á pautado na premissa de que as instituições financeiras devem implementar de forma substancial suas Políticas de Responsabilidade Socioambiental, devendo, por ocasião da análise dos projetos de concessão definanciamento, bem como durante a execução dos contratos definanciamentosjá firmados, não se limitar à análise contábil e formal, mas sim realizar uma análise substancial das variáveis econômica, social e ambiental envolvidas, de forma a determinar, dentro de uma faixa estreita de riscos aceitáveis pelo poder público e pela coletividade, quais riscos ambientais serão tolerados durante o desenvolvimento do empreendimento objeto dofinanciamento, como forma de cumprir com o dever constitucional de proteção do equilíbrio ambiental e, assim, evitar sua responsabilização civil pelos eventuais danos ambientais causados pelo empreendimento financiado". | Assuntos: Responsabilidade socioambiental, Brasil.Financiamento, Brasil.', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PRIVADO - 342::DIREITO COMERCIAL - 342.2::Instituições comerciais. Mercado de capitais - 342.23::Direito bancário - 342.234', 'Resumo:"O presente trabalho desenvolver-se-á pautado na premissa de que as instituições financeiras devem implementar de forma substancial suas Políticas de Responsabilidade Socioambiental, devendo, por ocasião da análise dos projetos de concessão definanciamento, bem como durante a execução dos contratos definanciamentosjá firmados, não se limitar à análise contábil e formal, mas sim realizar uma análise substancial das variáveis econômica, social e ambiental envolvidas, de forma a determinar, dentro de uma faixa estreita de riscos aceitáveis pelo poder público e pela coletividade, quais riscos ambientais serão tolerados durante o desenvolvimento do empreendimento objeto dofinanciamento, como forma de cumprir com o dever constitucional de proteção do equilíbrio ambiental e, assim, evitar sua responsabilização civil pelos eventuais danos ambientais causados pelo empreendimento financiado". | Assuntos: Responsabilidade socioambiental, Brasil.Financiamento, Brasil.', '', 'Messias, Ewerton Ricardo', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Doutrina___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Anais do Seminário aspectos jurídicos e econômicos do sistema definanciamentoimobiliário', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:livro:1999;000582051', NULL, '', '', 'doutrina', 'Sumário:Atividade imobiliária / Arthur Parkinson -- Elementos fundamentais da alienação fiduciária do bem imóvel / Mehlim Namem Chalub-- A Lei 9514 como instrumento de direito econômico e do direito do desenvolvimento / Arnoldo Wald, Enrique Ricardo Lewandowski -- Aplicação de recursos no mercado imobiliário: a experiência européia / Diogo Leite de Campos. A experiência americana / Peter Messitte, Robert F. Mc.Donough -- A importância do equilíbrio econômico-financeiro nos contratos definanciamentoimobiliário / Sérgio Cutolo dos Santos, Sérgio Darcy da Silva Alves -- Alienação fiduciária de bens imóveis - aspectos de direito material / José Carlos Moreira Alves -- Sistema definanciamentoimobiliário - aspectos processuais e constitucionais / Ilmar do Nascimento Galvão -- Sistema definanciamentoimobiliário - interpretação sistemática da Lei 9514/97 com o Código de Defesa do Consumidor / Alvaro Villaça de Azevedo -- Rescisão na promessa da compra e venda imobiliária / Mailson da Nóbrega -- A dimensão do desafio da habitação e o SFI / Emílio H. Carazzai Sobrinho -- Mercado americano de Mortgages / Raul Leite Luna -- O judiciário e o social / Marcio Fernandes. | Assuntos: Compra e venda, Brasil. {Compra e venda; Compra e venda (direito civil); Venda (direito civil)} Direito imobiliário, Brasil. {Direito imobiliário; Direito predial; Direito sobre bens imóveis}Financiamentohabitacional, Brasil. {Financiamentohabitacional; Casa própria,financiamento; Habitação,financiamento; Imóvel residencial,f