INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'As finanças doBNDES', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2009;1000895053', NULL, '', '', 'doutrina', 'Resumo:"Este artigo analisa a evolução das finanças doBNDESna atual década e discute suas perspectivas ao longo dos próximos anos. Mostra-se que os resultados doBNDEStêm sido associados ao retorno da renda variável e que os recursos líquidos do FAT estão escasseando. O artigo discute as incertezas associadas à continuidade do financiamento por parte do Tesouro na próxima década e conclui que, se oBNDESquiser continuar sua expansão, terá de se engajar em um intenso programa de novas captações, na década de 2010." | Assuntos: Desenvolvimento econômico, Brasil. Financiamento, Brasil. Banco nacional, finanças, Brasil.', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PÚBLICO - 341::DIREITO ADMINISTRATIVO - 341.3::Direito Financeiro - 341.38', 'Resumo:"Este artigo analisa a evolução das finanças doBNDESna atual década e discute suas perspectivas ao longo dos próximos anos. Mostra-se que os resultados doBNDEStêm sido associados ao retorno da renda variável e que os recursos líquidos do FAT estão escasseando. O artigo discute as incertezas associadas à continuidade do financiamento por parte do Tesouro na próxima década e conclui que, se oBNDESquiser continuar sua expansão, terá de se engajar em um intenso programa de novas captações, na década de 2010." | Assuntos: Desenvolvimento econômico, Brasil. Financiamento, Brasil. Banco nacional, finanças, Brasil.', '', 'Giambiagi, Fabio', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Doutrina___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-1