INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Propostas legislativas de novomarcoregulatóriodo pré-sal', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2010;1000888537', NULL, '', '', 'doutrina', 'Resumo:Analisa a constitucionalidade dos projetos de lei de iniciativa do Presidente da República, que pretendem instituir ummarcoregulatóriopara contratos de exploração do monopólio do petróleo. | Assuntos: Petróleo submarino, exploração, aspectos constitucionais, Brasil. Petróleo submarino, exploração, projeto de lei, Brasil.', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PÚBLICO - 341::DIREITO CONSTITUCIONAL - 341.2', 'Resumo:Analisa a constitucionalidade dos projetos de lei de iniciativa do Presidente da República, que pretendem instituir ummarcoregulatóriopara contratos de exploração do monopólio do petróleo. | Assuntos: Petróleo submarino, exploração, aspectos constitucionais, Brasil. Petróleo submarino, exploração, projeto de lei, Brasil.', '', 'Souto,MarcosJuruena Villela, 1963', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Doutrina___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'A Pré-Sal Petróleo S.A. e o novomarcoregulatóriobrasileiro', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2013;1001067735', NULL, '', '', 'doutrina', 'Resumo:Estuda a empresa estatal Pré-Sal Petróleo S.A. (PPSA) no contexto do pré-sal a fim de compreender as funções regulatórias desempenhadas pela empresa na exploração e produção de petróleo e gás natural, assim como estabelecer o ambiente de atuação da PPSA dentro do novomarcoregulatório. São examinadas as características gerais do novomarcoregulatórioelaborado para a região do pré-sal e realiza estudo em específico sobre o papel a ser desempenhado pela PPSA no âmbito do pré-sal. Conclui com críticas e sugestões sobre a atuação da nova empresa estatal no contexto domarcoregulatórioestabelecido em face do pré-sal, de modo a garantir maior eficiência regulatória ao setor.Sumário:O pré-sal -- Breves considerações sobre o novomarcoregulatório: A cessão onerosa e capitalização da Petrobrás. Contratos de partilha de produção. Fundo social -- A criação da nova empresa estatal - a PPSA. | Assuntos: Empresa de petróleo, criação, Brasil. Petróleo submarino, exploração, Brasil. Petróleo, regulação, Brasil. {Petróleo; Óleo cru}', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PÚBLICO - 341::DIREITO ADMINISTRATIVO - 341.3::Domínio Público. Conceito. Domínio Eminente. Domínio Patrimonial - 341.34::Jazidas. Código de Minas - 341.344::Petróleo. Monopólio - 341.3442', 'Resumo:Estuda a empresa estatal Pré-Sal Petróleo S.A. (PPSA) no contexto do pré-sal a fim de compreender as funções regulatórias desempenhadas pela empresa na exploração e produção de petróleo e gás natural, assim como estabelecer o ambiente de atuação da PPSA dentro do novomarcoregulatório. São examinadas as características gerais do novomarcoregulatórioelaborado para a região do pré-sal e realiza estudo em específico sobre o papel a ser desempenhado pela PPSA no âmbito do pré-sal. Conclui com críticas e sugestões sobre a atuação da nova empresa estatal no contexto domarcoregulatórioestabelecido em face do pré-sal, de modo a garantir maior eficiência regulatória ao setor.Sumário:O pré-sal -- Breves considerações sobre o novomarcoregulatório: A cessão onerosa e capitalização da Petrobrás. Contratos de partilha de produção. Fundo social -- A criação da nova empresa estatal - a PPSA. | Assuntos: Empresa de petróleo, criação, Brasil. Petróleo submarino, exploração, Brasil. Petróleo, regulação, Brasil. {Petróleo; Óleo cru}', '', 'Bulhões, Daniel Bruno Damasceno', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Doutrina___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
