INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Infraestrutura jurídica da ciência, tecnologia einovaçãonos países em desenvolvimento', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:livro:2020;001186263', NULL, '', '', 'doutrina', 'Sumário:v.3. Patentes farmacêuticas, regulação de preços e acesso a medicamentos : o caso do Sofosbuvir no Brasil / Marcos Vinício Chein Feres, Leonardo da Silva Sant''Anna, Alan Rossi Silva -- Uma análise comparativa entre o conteúdo da estratégia nacional de ciência, tecnologia einovação2012-2015 e 2016-2022 / Ana Luiza Santos Sena -- Aspectos regulatórios dasinovaçõestecnológicas no Brasil / Ana Maria Roncaglia --Inovaçãotecnológica e as doenças negligenciadas : um estudo de caso exploratório sobre o arquivamento dos pedidos de patentes relacionados à esquistossomose / Marcos Vinício Chein Feres, Anderson Resende Morais, Alan Silva Rossi -- BNDES e desenvolvimento : o financiamento da infraestrutura no Brasil / Beatriz Momente Miquelin, Isabella Cristina Serra Negra Lofrano, Luiz Roque Miranda Cardia -- Lei n° 13.879, de 03 de outubro de 2019 : desafios tecnológicos e inovativos para as empresas brasileiras de telecomunicações diante da internet das coisas / Demetrius Ferreira Chacur -- A biopirataria na Amazônia brasileira : estudo do caso do perfume Chanel n° 205 / Lauana Guedes Carvalho, Diogo de Calasans Melo Andrade, Dimas Pereira Duarte Júnior -- O Brasil na quarta revolução industrial : abismos tecnológicos e desafios para a superação do subdesenvolvimento no século XXI / Gabriela Souto Maior Baccarin -- O modelo da tripla hélice e o financiamento público dainovaçãono Brasil / Matheus Amorim de Oliveira Andrade, Matheus Rodrigues Oliveira -- O impacto do processo desindustrializaçã