INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'O conceito detecnologia', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:livro:2005;000753374', NULL, '', '', 'doutrina', 'Sumário:Análise de algumas noções fundamentais -- Em face da "era tecnológica" -- O homem e a máquina -- A técnica -- Atecnologia-- O conceito de razão técnica -- As antecipações da "razão técnica" -- O conceito de tecno-estrutura -- Desenvolvimento e categorias da razão técnica -- Questões datecnologiaatual -- Temas propostos pela cibernética -- Natureza e tipos dos sistemas cibernéticos -- Problemas gerais da informação -- Lógica e informação -- O caráter social da cibernética -- O processo histórico e o caráter da inteligência -- A cibernética e o destino do homem --tecnologiae problemas da existência -- As perspectivas datecnologia--Tecnologia, escatologia e classes sociais. | Assuntos: Tecnologia, filosofia. {Tecnologia; Ciências aplicadas}Tecnologia, aspectos sociais. {Tecnologia; Ciências aplicadas} Mecanização. Máquina. {Máquina; Maquinaria} Razão. Cibernética, aspectos sociais. Informação. Lógica. {Lógica; Argumentação; Dedução (lógica); Dialética (lógica); Lógica dedutiva} Escatologia.', '', 'LexML', 'transport_energy', 'Livro', 'Classificação: DIREITO - 340', 'Sumário:Análise de algumas noções fundamentais -- Em face da "era tecnológica" -- O homem e a máquina -- A técnica -- Atecnologia-- O conceito de razão técnica -- As antecipações da "razão técnica" -- O conceito de tecno-estrutura -- Desenvolvimento e categorias da razão técnica -- Questões datecnologiaatual -- Temas propostos pela cibernética -- Natureza e tipos dos sistemas cibernéticos -- Problemas gerais da informação -- Lógica e informação -- O caráter social da cibernética -- O processo histórico e o caráter da inteligência -- A cibernética e o destino do homem --tecnologiae problemas da existência -- As perspectivas datecnologia--Tecnologia, escatologia e classes sociais. | Assuntos: Tecnologia, filosofia. {Tecnologia; Ciências aplicadas}Tecnologia, aspectos sociais. {Tecnologia; Ciências aplicadas} Mecanização. Máquina. {Máquina; Maquinaria} Razão. Cibernética, aspectos sociais. Informação. Lógica. {Lógica; Argumentação; Dedução (lógica); Dialética (lógica); Lógica dedutiva} Escatologia.', '', 'Pinto, Álvaro Vieira', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Doutrina___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Gestão de ciência etecnologiapara a força terrestre', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2003;1000703574', NULL, '', '', 'doutrina', 'Resumo:Analisa a demanda da Força Terrestre por ciência etecnologia(C&T) e, para atender à gestão setorial, apresenta uma proposta de inclusão do tema na formação do oficial, particularmente nos cursos de Altos Estudos Militares. Destaca a importância de assuntos como a Gerência de Projetos, a Gestão de C&T propriamente dita, a Engenharia de Sistemas militares aplicada ao Projeto e ao preparo da Força Terrestre, e aborda aspectos da aquisição e do desenvolvimento de materiais de emprego militar - MEM, da transferência detecnologias, da gestão detecnologiada informação e da pesquisa operacional.Sumário:A demanda da força terrestre por ciência etecnologia-- Projeto sistemático de força terrestre -- Alguns temas centrais para a gestão da ciência etecnologiada força terrestre -- Gestão do processo de engenharia de sistemas -- Gestão da aquisição e desenvolvimento de material de emprego militar -- Gestão de transferência detecnologia-- Gestao datecnologiada informação -- Pesquisa operacional aplicada aos assuntos de defesa -- Inserção da ciência etecnologiana capacitação do oficial de estado-maior. | Assuntos: Estratégia militar, Brasil. Exército, Brasil. Engenharia militar, Brasil.Tecnologiamilitar, Brasil. Forças armadas, Brasil. Transferência detecnologia, Brasil. {Transferência detecnologia;Tecnologia, transferência}', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PÚBLICO - 341::DIREITO CONSTITUCIONAL - 341.2::Segurança nacional - 341.26', 'Resumo:Analisa a demanda da Força Terrestre por ciência etecnologia(C&T) e, para atender à gestão setorial, apresenta uma proposta de inclusão do tema na formação do oficial, particularmente nos cursos de Altos Estudos Militares. Destaca a importância de assuntos como a Gerência de Projetos, a Gestão de C&T propriamente dita, a Engenharia de Sistemas militares aplicada ao Projeto e ao preparo da Força Terrestre, e aborda aspectos da aquisição e do desenvolvimento de materiais de emprego militar - MEM, da transferência detecnologias, da gestão detecnologiada informação e da pesquisa operacional.Sumário:A demanda da força terrestre por ciência etecnologia-- Projeto sistemático de força terrestre -- Alguns temas centrais para a gestão da ciência etecnologiada força terrestre -- Gestão do processo de engenharia de sistemas -- Gestão da aquisição e desenvolvimento de material de emprego militar -- Gestão de transferência detecnologia-- Gestao datecnologiada informação -- Pesquisa operacional aplicada aos assuntos de defesa -- Inserção da ciência etecnologiana capacitação do oficial de estado-maior. | Assuntos: Estratégia militar, Brasil. Exército, Brasil. Engenharia militar, Brasil.Tecnologiamilitar, Brasil. Forças armadas, Brasil. Transferência detecnologia, Brasil. {Transferência detecnologia;Tecnologia, transferência}', '', 'De Sordi, Antônio Cesar Castro', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Doutrina___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
