INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Startups', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2020;1001188548', NULL, '', '', 'doutrina', 'Sumário:O conceito de empresário -- O princípio da autonomia patrimonial da pessoa jurídica -- Classificação das sociedades empresárias. O que importa para os empreendedores de umastartup-- Formatos societários maiores das startups: empresário individual e microempreendedor individual; empresa individual de responsabilidade limitada - EIRELI; sociedade limitada; sociedade anônima, sociedade em conta de participação como veículo de investimento. | Assuntos: Start up, aspectos jurídicos, Brasil. Sociedade comercial, legislação, Brasil. {Sociedade comercial; Corporação comercial; Sociedade mercantil} Desconsideração da personalidade jurídica, Brasil. {Desconsideração da personalidade jurídica; Desconsideração da pessoa jurídica; Desestimação da personalidade jurídica; Disregard doctrine} Sócio, responsabilidade, Brasil. Sociedade por cotas de responsabilidade limitada, Brasil. {Sociedade por cotas de responsabilidade limitada; Sociedade de responsabilidade limitada; Sociedade limitada; Sociedade por quotas} Sociedade anônima, Brasil. {Sociedade anônima; Companhias; Sociedade por ações} Empresa individual de responsabilidade limitada Eireli, Brasil.', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PRIVADO - 342::DIREITO COMERCIAL - 342.2::Sociedades comerciais - 342.22', 'Sumário:O conceito de empresário -- O princípio da autonomia patrimonial da pessoa jurídica -- Classificação das sociedades empresárias. O que importa para os empreendedores de umastartup-- Formatos societários maiores das startups: empresário individual e microempreendedor individual; empresa individual de responsabilidade limitada - EIRELI; sociedade limitada; sociedade anônima, sociedade em conta de participação como veículo de investimento. | Assuntos: Start up, aspectos jurídicos, Brasil. Sociedade comercial, legislação, Brasil. {Sociedade comercial; Corporação comercial; Sociedade mercantil} Desconsideração da personalidade jurídica, Brasil. {Desconsideração da personalidade jurídica; Desconsideração da pessoa jurídica; Desestimação da personalidade jurídica; Disregard doctrine} Sócio, responsabilidade, Brasil. Sociedade por cotas de responsabilidade limitada, Brasil. {Sociedade por cotas de responsabilidade limitada; Sociedade de responsabilidade limitada; Sociedade limitada; Sociedade por quotas} Sociedade anônima, Brasil. {Sociedade anônima; Companhias; Sociedade por ações} Empresa individual de responsabilidade limitada Eireli, Brasil.', '', 'Zirpoli, Rodrigo Domingos', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Doutrina___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Inova Simples aplicado ao modelo de remuneração da universidade pública por incubação de startups', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2020;1001184029', NULL, '', '', 'doutrina', 'Resumo:"O presente trabalho dedica-se a responder se o Inova Simples, instituído pela Lei Complementar nº 167/2019, consiste em tratamento tributário diferenciado e em mecanismo de apoio à incubação de startups por universidade pública. Nele se analisam os argumentos utilizados pela Receita Federal do Brasil para impedi-las de optar pelo regime tributário correspondente ao Simples Nacional apenas pelo fato de sócios de startups em incubação terem constituído usufruto sobre suas quotas em favor da universidade pública incubadora. Também se analisam os contornos do Inova Simples e a conformação da incubação destartuppor universidade pública remunerada pelo usufruto de quotas. Conclui-se que o regime jurídico do Inova Simples veda expressamente às startups a opção pelo Simples Nacional, não traz tratamento fiscal diferenciado às startups incubadas por entes públicos, nem soluciona a incongruente interpretação da Receita Federal que equipara o usufruto de quotas à participação societária, impedindo-as de optar pelo Simples Nacional. Para que se ofereça benefício fiscal relevante para o empreendedor dedicar-se a desenvolver empresas de caráter inovador, sugere-se que o Comitê Gestor do Simples Nacional module a regulamentação do Inova Simples de modo a permitir que não incidam tributos por período determinado sobre a comercialização experimental de produtos e serviços inovadores."Sumário:Astartupincubada e a remuneração da universidade pública mediante usufruto sobre quotas -- A remuneração pela incubação mediante usufruto de quotas e o impedimento de incubada por universidade pública optar pelo Simples Nacional -- Inova Simples: a conformação de regime tributário menos benéfico e a manutenção do problema para remunerar a universidade pública pela incubação. | Assuntos: Direito comercial, Minas Gerais. {Direito comercial; Comércio (direito comercial); Comércio (direito); Direito mercantil} Empreendedorismo, Minas Gerais. {Empreendedorismo; Empreendedor} Incubadora de empresas, Minas Gerais. Microempresa, Minas Gerais. Start up, financiamento, Minas Gerais.', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PRIVADO - 342::DIREITO COMERCIAL - 342.2', 'Resumo:"O presente trabalho dedica-se a responder se o Inova Simples, instituído pela Lei Complementar nº 167/2019, consiste em tratamento tributário diferenciado e em mecanismo de apoio à incubação de startups por universidade pública. Nele se analisam os argumentos utilizados pela Receita Federal do Brasil para impedi-las de optar pelo regime tributário correspondente ao Simples Nacional apenas pelo fato de sócios de startups em incubação terem constituído usufruto sobre suas quotas em favor da universidade pública incubadora. Também se analisam os contornos do Inova Simples e a conformação da incubação destartuppor universidade pública remunerada pelo usufruto de quotas. Conclui-se que o regime jurídico do Inova Simples veda expressamente às startups a opção pelo Simples Nacional, não traz tratamento fiscal diferenciado às startups incubadas por entes públicos, nem soluciona a incongruente interpretação da Receita Federal que equipara o usufruto de quotas à participação societária, impedindo-as de optar pelo Simples Nacional. Para que se ofereça benefício fiscal relevante para o empreendedor dedicar-se a desenvolver empresas de caráter inovador, sugere-se que o Comitê Gestor do Simples Nacional module a regulamentação do Inova Simples de modo a permitir que não incidam tributos por período determinado sobre a comercialização experimental de produtos e serviços inovadores."Sumário:Astartupincubada e a remuneração da universidade pública mediante usufruto sobre quotas -- A remuneração pela incubação mediante usufruto de quotas e o impedimento de incubada por universidade pública optar pelo Simples Nacional -- Inova Simples: a conformação de regime tributário menos benéfico e a manutenção do problema para remunerar a universidade pública pela incubação. | Assuntos: Direito comercial, Minas Gerais. {Direito comercial; Comércio (direito comercial); Comércio (direito); Direito mercantil} Empreendedorismo, Minas Gerais. {Empreendedorismo; Empreendedor} Incubadora de empresas, Minas Gerais. Microempresa, Minas Gerais. Start up, financiamento, Minas Gerais.', '', 'Neves, Rubia Carneiro', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Doutrina___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Contratos relacionais e vesting empresarial nos instrumentos de parceria para startups de base tecnológica', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2021;1001194792', NULL, '', '', 'doutrina', 'Resumo:"Investiga a indagação sobre qual é a importância de se compreender os novos direitos contratuais, como o vesting empresarial, à luz da teoria dos contratos relacionais. O termo vesting é extraído do inglês e se traduz como o "ato de vestir", que simbolicamente apresenta uma das inovações contratuais mais interessantes relacionadas ao direito dos contratos e ao direito empresarial. Este modelo de parceria tem se tornado cada vez mais comum, no Brasil, em relação às startups em bootstrapping (baixo ou nenhum investimento), justamente em virtude de seu formato, que permite àstartupum processo crescente de maturação e desenvolvimento de suas atividades. O fomento ao empreendedorismo propicia o surgimento de novas ideias, cuja implementação, dado o avanço contínuo da tecnologia, ocorre cada vez mais pela internet para a criação de modelos de negócio que rompem com os arquétipos usuais. Nessa linha, aferi em que medida o fomento ao empreendedorismo está atrelado à necessidade de mitigação de riscos e ao contingenciamento de custos, e à alavancagem da empresa, nesse cenário, a partir da consolidação dos Cliffs como condições resolutivas, que definem o modelo definido como "vesting invertido". Analisa a casuística concernente à aplicação do vesting empresarial ao estudo das startups e da disciplina dos contratos em contraponto à análise histórica e comparativa do modelo tradicional de constituição das sociedades empresárias."Sumário:Startups de base tecnológica e seu papel no fomento ao empreendedorismo -- Vesting empresarial e contratos relacionais. | Assuntos: Contrato, Brasil. Start up, Brasil. Start up, doutrinas e controvérsias, Brasil. Princípio da segurança jurídica, Brasil. Empreendedorismo, Brasil. {Empreendedorismo; Empreendedor} Participação societária, Brasil. Redução de risco, Brasil. Contingenciamento, Brasil. Tomada de decisão, Brasil. Escalabilidade, Brasil. Marco regulatório, Brasil. Terceirização, Brasil. Propriedade intelectual, proteção, Brasil. {Propriedade intelectual; Propriedade imaterial}', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PRIVADO - 342::DIREITO CIVIL - 342.1', 'Resumo:"Investiga a indagação sobre qual é a importância de se compreender os novos direitos contratuais, como o vesting empresarial, à luz da teoria dos contratos relacionais. O termo vesting é extraído do inglês e se traduz como o "ato de vestir", que simbolicamente apresenta uma das inovações contratuais mais interessantes relacionadas ao direito dos contratos e ao direito empresarial. Este modelo de parceria tem se tornado cada vez mais comum, no Brasil, em relação às startups em bootstrapping (baixo ou nenhum investimento), justamente em virtude de seu formato, que permite àstartupum processo crescente de maturação e desenvolvimento de suas atividades. O fomento ao empreendedorismo propicia o surgimento de novas ideias, cuja implementação, dado o avanço contínuo da tecnologia, ocorre cada vez mais pela internet para a criação de modelos de negócio que rompem com os arquétipos usuais. Nessa linha, aferi em que medida o fomento ao empreendedorismo está atrelado à necessidade de mitigação de riscos e ao contingenciamento de custos, e à alavancagem da empresa, nesse cenário, a partir da consolidação dos Cliffs como condições resolutivas, que definem o modelo definido como "vesting invertido". Analisa a casuística concernente à aplicação do vesting empresarial ao estudo das startups e da disciplina dos contratos em contraponto à análise histórica e comparativa do modelo tradicional de constituição das sociedades empresárias."Sumário:Startups de base tecnológica e seu papel no fomento ao empreendedorismo -- Vesting empresarial e contratos relacionais. | Assuntos: Contrato, Brasil. Start up, Brasil. Start up, doutrinas e controvérsias, Brasil. Princípio da segurança jurídica, Brasil. Empreendedorismo, Brasil. {Empreendedorismo; Empreendedor} Participação societária, Brasil. Redução de risco, Brasil. Contingenciamento, Brasil. Tomada de decisão, Brasil. Escalabilidade, Brasil. Marco regulatório, Brasil. Terceirização, Brasil. Propriedade intelectual, proteção, Brasil. {Propriedade intelectual; Propriedade imaterial}', '', 'Faleiros Júnior, José Luiz de Moura', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Doutrina___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Origem e o papel das aceleradoras eincubadorasde startups no sistema inovativo brasileiro', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2021;1001208639', NULL, '', '', 'doutrina', 'Sumário:Inovação : conceito e embasamento legal: conceito de inovação e a hélice tríplice; a legislação brasileira como instrumento fomentador da inovação -- Startups como expoente do movimento inventivo: startups : conceituação; startups : estágios de evolução -- Incubação e aceleração de startups: Incubação de startups: conceito e origem; evolução da incubação no Brasil : legislação e números. Aceleração de startups: conceito e origem; evolução da aceleração no Brasil : legislação e números. | Assuntos: Start up, Brasil. Start up, legislação, Brasil. Start up. Inovação tecnológica, legislação, Brasil. Inovação tecnológica.Incubadorade empresas, Brasil.Incubadorade empresas.', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO - 340', 'Sumário:Inovação : conceito e embasamento legal: conceito de inovação e a hélice tríplice; a legislação brasileira como instrumento fomentador da inovação -- Startups como expoente do movimento inventivo: startups : conceituação; startups : estágios de evolução -- Incubação e aceleração de startups: Incubação de startups: conceito e origem; evolução da incubação no Brasil : legislação e números. Aceleração de startups: conceito e origem; evolução da aceleração no Brasil : legislação e números. | Assuntos: Start up, Brasil. Start up, legislação, Brasil. Start up. Inovação tecnológica, legislação, Brasil. Inovação tecnológica.Incubadorade empresas, Brasil.Incubadorade empresas.', '', 'Mendes, Hugo Cavalcanti Vaz', '', ''