INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Asincubadorasde empresas e seus aspectos jurídicos', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2015;1001061436', NULL, '', '', 'doutrina', 'Assuntos: Cooperação, tecnologia, Brasil. Empreendedorismo, Brasil. {Empreendedorismo; Empreendedor} Pequena empresa, aspectos jurídicos, Brasil. {Pequena empresa; Empresa de pequeno porte; Empresa pequena; EPP} Políticas públicas, Brasil. Pequena empresa, inovação tecnológica, Brasil. {Pequena empresa; Empresa de pequeno porte; Empresa pequena; EPP}', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PRIVADO - 342::DIREITO COMERCIAL - 342.2::Sociedades comerciais - 342.22', 'Assuntos: Cooperação, tecnologia, Brasil. Empreendedorismo, Brasil. {Empreendedorismo; Empreendedor} Pequena empresa, aspectos jurídicos, Brasil. {Pequena empresa; Empresa de pequeno porte; Empresa pequena; EPP} Políticas públicas, Brasil. Pequena empresa, inovação tecnológica, Brasil. {Pequena empresa; Empresa de pequeno porte; Empresa pequena; EPP}', '', 'Andrade, Caio Martins de', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Doutrina___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Inova Simples aplicado ao modelo de remuneração da universidade pública por incubação de startups', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2020;1001184029', NULL, '', '', 'doutrina', 'Resumo:"O presente trabalho dedica-se a responder se o Inova Simples, instituído pela Lei Complementar nº 167/2019, consiste em tratamento tributário diferenciado e em mecanismo de apoio à incubação de startups por universidade pública. Nele se analisam os argumentos utilizados pela Receita Federal do Brasil para impedi-las de optar pelo regime tributário correspondente ao Simples Nacional apenas pelo fato de sócios de startups em incubação terem constituído usufruto sobre suas quotas em favor da universidade públicaincubadora. Também se analisam os contornos do Inova Simples e a conformação da incubação de startup por universidade pública remunerada pelo usufruto de quotas. Conclui-se que o regime jurídico do Inova Simples veda expressamente às startups a opção pelo Simples Nacional, não traz tratamento fiscal diferenciado às startups incubadas por entes públicos, nem soluciona a incongruente interpretação da Receita Federal que equipara o usufruto de quotas à participação societária, impedindo-as de optar pelo Simples Nacional. Para que se ofereça benefício fiscal relevante para o empreendedor dedicar-se a desenvolver empresas de caráter inovador, sugere-se que o Comitê Gestor do Simples Nacional module a regulamentação do Inova Simples de modo a permitir que não incidam tributos por período determinado sobre a comercialização experimental de produtos e serviços inovadores."Sumário:A startup incubada e a remuneração da universidade pública mediante usufruto sobre quotas -- A remuneração pela incubação mediante usufruto de quotas e o impedimento de incubada por universidade pública optar pelo Simples Nacional -- Inova Simples: a conformação de regime tributário menos benéfico e a manutenção do problema para remunerar a universidade pública pela incubação. | Assuntos: Direito comercial, Minas Gerais. {Direito comercial; Comércio (direito comercial); Comércio (direito); Direito mercantil} Empreendedorismo, Minas Gerais. {Empreendedorismo; Empreendedor}Incubadorade empresas, Minas Gerais. Microempresa, Minas Gerais. Start up, financiamento, Minas Gerais.', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PRIVADO - 342::DIREITO COMERCIAL - 342.2', 'Resumo:"O presente trabalho dedica-se a responder se o Inova Simples, instituído pela Lei Complementar nº 167/2019, consiste em tratamento tributário diferenciado e em mecanismo de apoio à incubação de startups por universidade pública. Nele se analisam os argumentos utilizados pela Receita Federal do Brasil para impedi-las de optar pelo regime tributário correspondente ao Simples Nacional apenas pelo fato de sócios de startups em incubação terem constituído usufruto sobre suas quotas em favor da universidade públicaincubadora. Também se analisam os contornos do Inova Simples e a conformação da incubação de startup por universidade pública remunerada pelo usufruto de quotas. Conclui-se que o regime jurídico do Inova Simples veda expressamente às startups a opção pelo Simples Nacional, não traz tratamento fiscal diferenciado às startups incubadas por entes públicos, nem soluciona a incongruente interpretação da Receita Federal que equipara o usufruto de quotas à participação societária, impedindo-as de optar pelo Simples Nacional. Para que se ofereça benefício fiscal relevante para o empreendedor dedicar-se a desenvolver empresas de caráter inovador, sugere-se que o Comitê Gestor do Simples Nacional module a regulamentação do Inova Simples de modo a permitir que não incidam tributos por período determinado sobre a comercialização experimental de produtos e serviços inovadores."Sumário:A startup incubada e a remuneração da universidade pública mediante usufruto sobre quotas -- A remuneração pela incubação mediante usufruto de quotas e o impedimento de incubada por universidade pública optar pelo Simples Nacional -- Inova Simples: a conformação de regime tributário menos benéfico e a manutenção do problema para remunerar a universidade pública pela incubação. | Assuntos: Direito comercial, Minas Gerais. {Direito comercial; Comércio (direito comercial); Comércio (direito); Direito mercantil} Empreendedorismo, Minas Gerais. {Empreendedorismo; Empreendedor}Incubadorade empresas, Minas Gerais. Microempresa, Minas Gerais. Start up, financiamento, Minas Gerais.', '', 'Neves, Rubia Carneiro', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Doutrina___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
