INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Pharmaceuticalpatentprotection and world trade law', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:livro:2018;001138491', NULL, '', '', 'doutrina', 'Resumo:Estudo de direito comparado sobre: aplicação do TRIPS no África do Sul, Brasil, China, India e Quênia.Sumário:pt. 1. Evolution of intellectual propery laws, and the introduction of IP protection in the multilateral trading system: A jurisprudential enquiry into the justification of international IP rights protection, with particular reference to pharmaceutical patents. Intellectual propery in the multilateral trading system : forum shifting, TRIPS agreement, Doha Declaration and TRIPS flexibilities. Underminig TRIPS flexibilities : FTAs, RTAs, EPAs, TRIPS-plus and stoppage in transit -- pt. 2. TRIPS and developing countries : implementation, knowledge economy and IP policymaking: Brazil : ambitious missions and early TRIPS implementation. China: the uneasy transition. India : the transition from process to productpatent. South Africa : against all odds. Kenya : can generics still reach the needy -- pt. 3. TRIPS at what cost? TRIPS agreement and the future of access to affordable. | Assuntos: Comércio internacional. {Comércio internacional; Comércio mundial; Negócio internacional} Direito à saúde. Indústria farmacêutica, aspectos jurídicos. Medicamento, patente. {Medicamento; Droga lícita; Remédio} Propriedade industrial. {Propriedade industrial; Marca de fábrica, registro; Registro da marca} Propriedade intelectual, direito comparado. {Propriedade intelectual; Propriedade imaterial} Propriedade intelectual, tratado. {Propriedade intelectual; Propriedade imaterial} Propriedade intelectual. {Propriedade intelectual; Propriedade imaterial} Patente.', '', 'LexML', 'transport_energy', 'Livro', 'Classificação: DIREITO PRIVADO - 342::DIREITO COMERCIAL - 342.2::Direitos Intelectuais. Propriedade industrial, comercial, científica e de programas de computador - 342.27::Patentes de invenção - 342.271', 'Resumo:Estudo de direito comparado sobre: aplicação do TRIPS no África do Sul, Brasil, China, India e Quênia.Sumário:pt. 1. Evolution of intellectual propery laws, and the introduction of IP protection in the multilateral trading system: A jurisprudential enquiry into the justification of international IP rights protection, with particular reference to pharmaceutical patents. Intellectual propery in the multilateral trading system : forum shifting, TRIPS agreement, Doha Declaration and TRIPS flexibilities. Underminig TRIPS flexibilities : FTAs, RTAs, EPAs, TRIPS-plus and stoppage in transit -- pt. 2. TRIPS and developing countries : implementation, knowledge economy and IP policymaking: Brazil : ambitious missions and early TRIPS implementation. China: the uneasy transition. India : the transition from process to productpatent. South Africa : against all odds. Kenya : can generics still reach the needy -- pt. 3. TRIPS at what cost? TRIPS agreement and the future of access to affordable. | Assuntos: Comércio internacional. {Comércio internacional; Comércio mundial; Negócio internacional} Direito à saúde. Indústria farmacêutica, aspectos jurídicos. Medicamento, patente. {Medicamento; Droga lícita; Remédio} Propriedade industrial. {Propriedade industrial; Marca de fábrica, registro; Registro da marca} Propriedade intelectual, direito comparado. {Propriedade intelectual; Propriedade imaterial} Propriedade intelectual, tratado. {Propriedade intelectual; Propriedade imaterial} Propriedade intelectual. {Propriedade intelectual; Propriedade imaterial} Patente.', '', 'Sundaram, Jae', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Doutrina___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
