INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Anais do I Congresso Internacional daPropriedadeIntelectual. --', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:livro:2003;000712993', NULL, '', '', 'doutrina', 'Resumo:Trata de questões depropriedadeintelectual, direito autoral, marcas e patentes e seus vínculos e avanços cibernéticos sob o ângulo jurídico, artístico e empresarial, com base no direito civil e penal.Sumário:La propriedadintelectualen la América Latina (un enfoque desde el derecho de autor y los derechos conexos / Carlos A. Vilalba -- A gestão coletiva e as relações de reciprocidade entre os países da América Latina e entre estes e a comunidade européia, EUA e Japão / Delia Lipszye -- A evolução do direito internacional e o regimento jurídico brasileiro nas novas tecnologias na área do direito de autor e conexo (parte 2): o direito de autor sobre as obras musicais na era digital / José Carlos Costa Netto -- O interesseintelectualcoletivo e sua harmonização com apropriedadeintelectual/ João Carlos de Camargo Eboli -- O que épropriedadeintelectual? / Newton Silveira -- New technology and the protection of intellectual property under U.S. law/ Lawrence Piersol -- Direito de autor e conexos nas obras audiovisuais e questões atuais no campo das TVS (abertas e por assinatura) e internet / Sérgio Famá D''Antino -- Crimes contra apropriedadeintelectual/ Bruno Jorge Hammes -- Pirataria de obrasintelectuaisno Brasil e no mundo / João Carlos Müller Chaves -- A relevância da prova pericial na área dapropriedadeintelectual: casos concretos / Maria Luiza de Freitas Valle Egea -- O papel do juiz nos Estados Unidos nos processos envolvendopropriedadeintelectual/ Peter J. Messite. | Assuntos: Propriedadeintelectual, congre