INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Propriedadeintelectuale desenvolvimento', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:livro:2005;000746897', NULL, '', '', 'doutrina', 'Resumo:Discute apropriedadeintelectual. Analisa possibilidades de políticas públicas pelos países adaptadores de tecnologia ou excluídos da produção tecnológica, tendo em vista os tratados em vigor, tais como Trips, PCT(Tratado de Cooperação em Matéria de Patentes) e as normas nacionais.Sumário:O divisor global de inovação / Jeffrey Sachs -- Aperfeiçoando a eficiência econômica e a eqüidade pela criação de leis depropriedadeintelectual/ Carlos M. Correa -- Revolução tecnológica, globalização e Direito das patentes / Bernard Remiche -- Trips e a experiência brasileira / Denis Borges Barbosa -- Políticas públicas parapropriedadeintelectualno Brasil / Marcelo Dias Varella -- O parágrafo 6 da Declaração de Doha, o Acordo Trips e os Países em desenvolvimento / Daya Shanker -- O impacto das patentes farmacêuticas em países em desenvolvimento e as perspectivas para o Brasil / Maria Fernanda Gonçalves Macedo e Eloan dos Santos Pinheiro -- Política de patentes em biotecnologia: posicionamento brasileiro / Maria Edelvacy Pinto Marinho -- Desenvolvimento tecnológico, pesquisa pública epropriedadeintelectual. Análise da miríade de normas institucionais / Marcelo Dias Varella; Ana Flávia Barros Plaatiau e Rafael T. Schleicher -- Indicações geográficas e arranjos produtivos locais / Marcelo Dias Varella e Ana Flávia Granja e Barros. | Assuntos: Propriedadeintelectual. {Propriedadeintelectual;Propriedadeimaterial}Propriedadeintelectual, coletânea, Brasil. {Propriedadeintelectual;Propriedadeimaterial} Patente, Brasil. Biotecnologia, Brasil. {Biotecnologia; Tecnologia biológica}', '', 'LexML', 'transport_energy', 'Livro', 'Classificação: DIREITO PRIVADO - 342::DIREITO COMERCIAL - 342.2::DireitosIntelectuais.Propriedadeindustrial, comercial, científica e de programas de computador - 342.27', 'Resumo:Discute apropriedadeintelectual. Analisa possibilidades de políticas públicas pelos países adaptadores de tecnologia ou excluídos da produção tecnológica, tendo em vista os tratados em vigor, tais como Trips, PCT(Tratado de Cooperação em Matéria de Patentes) e as normas nacionais.Sumário:O divisor global de inovação / Jeffrey Sachs -- Aperfeiçoando a eficiência econômica e a eqüidade pela criação de leis depropriedadeintelectual/ Carlos M. Correa -- Revolução tecnológica, globalização e Direito das patentes / Bernard Remiche -- Trips e a experiência brasileira / Denis Borges Barbosa -- Políticas públicas parapropriedadeintelectualno Brasil / Marcelo Dias Varella -- O parágrafo 6 da Declaração de Doha, o Acordo Trips e os Países em desenvolvimento / Daya Shanker -- O impacto das patentes farmacêuticas em países em desenvolvimento e as perspectivas para o Brasil / Maria Fernanda Gonçalves Macedo e Eloan dos Santos Pinheiro -- Política de patentes em biotecnologia: posicionamento brasileiro / Maria Edelvacy Pinto Marinho -- Desenvolvimento tecnológico, pesquisa pública epropriedadeintelectual. Análise da miríade de normas institucionais / Marcelo Dias Varella; Ana Flávia Barros Plaatiau e Rafael T. Schleicher -- Indicações geográficas e arranjos produtivos locais / Marcelo Dias Varella e Ana Flávia Granja e Barros. | Assuntos: Propriedadeintelectual. {Propriedadeintelectual;Propriedadeimaterial}Propriedadeintelectual, coletânea, Brasil. {Propriedadeintelectual;Propriedadeimaterial} Patente, Brasil. Biotecnologia, Brasil. {Biotecnologia; Tecnologia biológica}', '', '', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Doutrina___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Tributação datransferênciadetecnologia', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:livro:2001;000592005', NULL, '', '', 'doutrina', 'Sumário:Direito Tributário Internacional --Transferênciadetecnologiae sua tributação -- As convenções bilaterais para prevenir a bitributação assinadas pelo Brasil e a tributação datransferenciadetecnologia-- O Mercosul e a tributação datransferênciadetecnologia-- Atualização segundo a nova Lei de Marcas e Patentes: Lei nº 9279, de 14.05.1996 -- PMF nº 436, de 30.12.1958, com modificações posteriores -- Lista de tratados internacionais para prevenir a bitributação celebrados pelo Brasil (em ordem cronológica) e relação da legislação tributária pertinente -- Alíquotas máximas aplicáveis a pagamentos ao exterior segundo os tratados promulgados no Brasil (em ordem alfabética) -- Relação de atos infralegais do fisco brasileiro a respeito de acordos para prevenir a bitributação -- Texto do art. 12 (em inglês) da CM-OCDE 1963, 1977 e 1992, da CM-ONU e da CM-EUA -- Texto do artigo que trata de royalties e dos itens relevantes do protocolo nas convenções promulgadas no Brasil (em ordem alfabética) -- Gráfico de gastos com importaçãodetecnologiapelo Brasil. | Assuntos: Bitributação, Brasil. {Bitributação; Dupla tributação} Royalties, Brasil.Transferênciadetecnologia, impostos, Brasil. {Transferênciadetecnologia;Tecnologia,transferência}Transferênciadetecnologia, legislação, Brasil. {Transferênciadetecnologia;Tecnologia,transferência}Transferênciadetecnologia, regulamentação, Brasil. {Transferênciadetecnologia;Tecnologia,transferência}Transferênciadetecnologia, tratado. {Transferênciadetecnologia;Tecnologia,transferência} Direito tributário intern