INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Direito administrativo einovação', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2017;1001115216', NULL, '', '', 'doutrina', 'Sumário:O que pode ser ainovaçãono direito administrativo brasileiro. Três requisitos de cautela -- A Lei de direito administrativo: ponte experimental imperfeita -- A doutrina de direito administrativo : entre o centralismo e a proposta -- A jurisprudência de direito administrativo : laboratório ou museu?. | Assuntos: Direito administrativo,inovação, Brasil.', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PÚBLICO - 341::DIREITO ADMINISTRATIVO - 341.3', 'Sumário:O que pode ser ainovaçãono direito administrativo brasileiro. Três requisitos de cautela -- A Lei de direito administrativo: ponte experimental imperfeita -- A doutrina de direito administrativo : entre o centralismo e a proposta -- A jurisprudência de direito administrativo : laboratório ou museu?. | Assuntos: Direito administrativo,inovação, Brasil.', '', 'Mendonça, José Vicente Santos de', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Doutrina___Rodovi\u00e1rio.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Contratos relacionais e vesting empresarial nos instrumentos de parceria para startups de base tecnológica', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2021;1001194792', NULL, '', '', 'doutrina', 'Resumo:"Investiga a indagação sobre qual é a importância de se compreender os novos direitos contratuais, como o vesting empresarial, à luz da teoria dos contratos relacionais. O termo vesting é extraído do inglês e se traduz como o "ato de vestir", que simbolicamente apresenta uma das inovações contratuais mais interessantes relacionadas ao direito dos contratos e ao direito empresarial. Este modelo de parceria tem se tornado cada vez mais comum, no Brasil, em relação às startups em bootstrapping (baixo ou nenhum investimento), justamente em virtude de seu formato, que permite àstartupum processo crescente de maturação e desenvolvimento de suas atividades. O fomento ao empreendedorismo propicia o surgimento de novas ideias, cuja implementação, dado o avanço contínuo da tecnologia, ocorre cada vez mais pela internet para a criação de modelos de negócio que rompem com os arquétipos usuais. Nessa linha, aferi em que medida o fomento ao empreendedorismo está atrelado à necessidade de mitigação de riscos e ao contingenciamento de custos, e à alavancagem da empresa, nesse cenário, a partir da consolidação dos Cliffs como condições resolutivas, que definem o modelo definido como "vesting invertido". Analisa a casuística concernente à aplicação do vesting empresarial ao estudo das startups e da disciplina dos contratos em contraponto à análise histórica e comparativa do modelo tradicional de constituição das sociedades empresárias."Sumário:Startups de base tecnológica e seu papel no fomento ao empreendedorismo -- Vesting empresarial e contratos relacionais. | Assuntos: Contrato, Brasil. Start up, Brasil. Start up, doutrinas e controvérsias, Brasil. Princípio da segurança jurídica, Brasil. Empreendedorismo, Brasil. {Empreendedorismo; Empreendedor} Participação societária, Brasil. Redução de risco, Brasil. Contingenciamento, Brasil. Tomada de decisão, Brasil. Escalabilidade, Brasil. Marco regulatório, Brasil. Terceirização, Brasil. Propriedade intelectual, proteção, Brasil. {Propriedade intelectual; Propriedade imaterial}', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PRIVADO - 342::DIREITO CIVIL - 342.1', 'Resumo:"Investiga a indagação sobre qual é a importância de se compreender os novos direitos contratuais, como o vesting empresarial, à luz da teoria dos contratos relacionais. O termo vesting é extraído do inglês e se traduz como o "ato de vestir", que simbolicamente apresenta uma das inovações contratuais mais interessantes relacionadas ao direito dos contratos e ao direito empresarial. Este modelo de parceria tem se tornado cada vez mais comum, no Brasil, em relação às startups em bootstrapping (baixo ou nenhum investimento), justamente em virtude de seu formato, que permite àstartupum processo crescente de maturação e desenvolvimento de suas atividades. O fomento ao empreendedorismo propicia o surgimento de novas ideias, cuja implementação, dado o avanço contínuo da tecnologia, ocorre cada vez mais pela internet para a criação de modelos de negócio que rompem com os arquétipos usuais. Nessa linha, aferi em que medida o fomento ao empreendedorismo está atrelado à necessidade de mitigação de riscos e ao contingenciamento de custos, e à alavancagem da empresa, nesse cenário, a partir da consolidação dos Cliffs como condições resolutivas, que definem o modelo definido como "vesting invertido". Analisa a casuística concernente à aplicação do vesting empresarial ao estudo das startups e da disciplina dos contratos em contraponto à análise histórica e comparativa do modelo tradicional de constituição das sociedades empresárias."Sumário:Startups de base tecnológica e seu papel no fomento ao empreendedorismo -- Vesting empresarial e contratos relacionais. | Assuntos: Contrato, Brasil. Start up, Brasil. Start up, doutrinas e controvérsias, Brasil. Princípio da segurança jurídica, Brasil. Empreendedorismo, Brasil. {Empreendedorismo; Empreendedor} Participação societária, Brasil. Redução de risco, Brasil. Contingenciamento, Brasil. Tomada de decisão, Brasil. Escalabilidade, Brasil. Marco regulatório, Brasil. Terceirização, Brasil. Propriedade intelectual, proteção, Brasil. {Propriedade intelectual; Propriedade imaterial}', '', 'Faleiros Júnior, José Luiz de Moura', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Doutrina___Rodovi\u00e1rio.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
