INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'O ICMS nas operações interestaduais comgásliquefeito de petróleo derivado dogásnatural', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2005;2000830170', NULL, '', '', 'doutrina', 'Sumário:A imprescindível distinção entre petróleo egásnatural-- O regime de tributação pelo ICMS das operações interestaduais com petróleo e derivados : O entendimento eminentemente doutrinário : plena e integral desoneração do ICMS. A imunidade na lei Kandir : o critério da destinação. A imunidade sob a ótica do STF -- O regime de tributação pelo ICMS das operações interestaduais com GLP derivado de GV : A correta exegese dos termo "consumidor final", "destinatário contribuinte" e "destinatário não contribuinte". Outras questões que demandam esclarecimento. As alíquotas -- A ADIn 3.103 e o GLP derivado de GN : A EC 33/2001 e a nova sistemática do ICMS a ser implementada : a monofasia. A tese do autos da ADIN : estaria tudo certo se não fosse por um pequeno, porém decisivo detalhe! Algumas considerações de fundo acerca da ADIn 3.103. | Assuntos: Gásnatural, impostos, Brasil. {Gásnatural;Gásde petróleo} Petróleo, impostos, Brasil. {Petróleo; Óleo cru}Gásliquefeito de petróleo GLP, impostos, Brasil. {Gásliquefeito de petróleo (GLP);Gásde cozinha}Gásnatural, impostos, Brasil. {Gásnatural;Gásde petróleo} Petróleo, impostos, Brasil. {Petróleo; Óleo cru}Gásliquefeito de petróleo GLP, impostos, Brasil. {Gásliquefeito de petróleo (GLP);Gásde cozinha}', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PÚBLICO - 341::DIREITO ADMINISTRATIVO - 341.3::Direito Tributário - 341.39', 'Sumário:A imprescindível distinção entre petróleo egásnatural-- O regime de tributação pelo ICMS das operações interestaduais com petróleo e derivados : O entendimento eminentemente doutrinário : plena e integral desoneração do ICMS. A imunidade na lei Kandir : o critério da destinação. A imunidade sob a ótica do STF -- O regime de tributação pelo ICMS das operações interestaduais com GLP derivado de GV : A correta exegese dos termo "consumidor final", "destinatário contribuinte" e "destinatário não contribuinte". Outras questões que demandam esclarecimento. As alíquotas -- A ADIn 3.103 e o GLP derivado de GN : A EC 33/2001 e a nova sistemática do ICMS a ser implementada : a monofasia. A tese do autos da ADIN : estaria tudo certo se não fosse por um pequeno, porém decisivo detalhe! Algumas considerações de fundo acerca da ADIn 3.103. | Assuntos: Gásnatural, impostos, Brasil. {Gásnatural;Gásde petróleo} Petróleo, impostos, Brasil. {Petróleo; Óleo cru}Gásliquefeito de petróleo GLP, impostos, Brasil. {Gásliquefeito de petróleo (GLP);Gásde cozinha}Gásnatural, impostos, Brasil. {Gásnatural;Gásde petróleo} Petróleo, impostos, Brasil. {Petróleo; Óleo cru}Gásliquefeito de petróleo GLP, impostos, Brasil. {Gásliquefeito de petróleo (GLP);Gásde cozinha}', '', 'Maia, Américo Nobre de Mariz', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
