INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Aspectos econômicos e jurídicos das cláusulas de ship-or-pay e take-or-paynos contratos de transporte e fornecimento degásnatural', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2006;1000780974', NULL, '', '', 'doutrina', 'Resumo:Trata da natureza jurídica dos contratos de tranporte e fornecimento degáscom claúsula de ship-or-pay e take-or-pay. A primeira claúsula permite ao transportador a obtenção do retorno de seus investimentos em infra-estrutura de transporte; já a segunda visa a obtenção da remuneração por suas despesas de exploração, desenvolvimento e produção dogásnatural.Sumário:Panorama do modelo do setor degásnaturalno Brasil -- Características do setor degásnaturale a relevância das claúsulas de take-or-pay e ship-or pay -- Natureza jurídica imposta pelas claúsulas de ship-or-pay e take-or-pay aos contratos de transporte e de fornecimento degásnatural-- Algumas consequências de sua natureza jurídica. | Assuntos: Contrato de transporte, aspectos econômicos, Brasil. {Contrato de transporte; Direito de transporte; Transporte (direito civil); Transporte (direito comercial)}Gásnatural, transporte, Brasil. {Gásnatural;Gásde petróleo}Gásnatural, compra e venda, Brasil. {Gásnatural;Gásde petróleo} Transportador, Brasil. Contrato de transporte, rescisão, Brasil. {Contrato de transporte; Direito de transporte; Transporte (direito civil); Transporte (direito comercial)} Transporte, Brasil. Direito comercial, Brasil. {Direito comercial; Comércio (direito comercial); Comércio (direito); Direito mercantil}', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PRIVADO - 342::DIREITO COMERCIAL - 342.2::Transporte. Comunicação - 342.263', 'Resumo:Trata da natureza jurídica dos contratos de tranporte e fornecimento degáscom claúsula de ship-or-pay e take-or-pay. A primeira claúsula permite ao transportador a obtenção do retorno de seus investimentos em infra-estrutura de transporte; já a segunda visa a obtenção da remuneração por suas despesas de exploração, desenvolvimento e produção dogásnatural.Sumário:Panorama do modelo do setor degásnaturalno Brasil -- Características do setor degásnaturale a relevância das claúsulas de take-or-pay e ship-or pay -- Natureza jurídica imposta pelas claúsulas de ship-or-pay e take-or-pay aos contratos de transporte e de fornecimento degásnatural-- Algumas consequências de sua natureza jurídica. | Assuntos: Contrato de transporte, aspectos econômicos, Brasil. {Contrato de transporte; Direito de transporte; Transporte (direito civil); Transporte (direito comercial)}Gásnatural, transporte, Brasil. {Gásnatural;Gásde petróleo}Gásnatural, compra e venda, Brasil. {Gásnatural;Gásde petróleo} Transportador, Brasil. Contrato de transporte, rescisão, Brasil. {Contrato de transporte; Direito de transporte; Transporte (direito civil); Transporte (direito comercial)} Transporte, Brasil. Direito comercial, Brasil. {Direito comercial; Comércio (direito comercial); Comércio (direito); Direito mercantil}', '', 'Baleroni, Rafael Baptista', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
