INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:tribunal.superior.trabalho;turma.7:acordao;airr:2008-12-10;242340-2003-18-2-40', 'Acórdão do processo Nº AIRR - 242340-37.2003.5.02.0018', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.7:acordao;airr:2008-12-10;242340-2003-18-2-40', '2008-12-10', '', '', 'outro', 'AGRAVO DE INSTRUMENTO - RECURSO DE REVISTA - NEGATIVA DE PRESTAÇÃO JURISDICIONAL - NÃO-CARACTERIZAÇÃO -ADICIONAL DE PERICULOSIDADE - ESTADO GASOSO DOHIDROGÊNIO- AUSÊNCIA DE PREVISÃO NA NR 16 DA PORTARIA 3.214/78 - ACÓRDÃO REGIONAL QUE ASSENTA O ENQUADRAMENTO DA SITUAÇÃO FÁTICA NA NORMA. 1. A preliminar de nulidade da decisão, por negativa de prestação jurisdicional, em sede de recurso de revista, só pode ser argüida com base em violência aos arts. 832 da CLT, 458 do CPC ou 93, IX, da Constituição Federal, como estipula a Orientação Jurisprudencial 115 da SBDI-1 do TST.  2. Na hipótese, a Corte ¿a quo¿ consignou expressamente que a hipótese fática, consistente na manobra de substância inflamável (hidrogênio) para abastecimento realizada pelo Autor, estava plenamente enquadrada na NR 16 da Portaria 3.214/78. 3. Portanto, houve a completa entrega da prestação jurisdicional, não se verificando violação dos dispositivos constitucional e legais supramencionados. 4. Ademais, a alegação de que ohidrogêniomanipulado estava em estado gasoso, e não liqüefeito, e que, por essa razão, não estava inserida dentre as atividades consideradas perigosas na mencionada NR não aproveita a Reclamada, pois a situação fática assentada pelo Regional vai em sentido oposto, consignando que o caso concreto amoldava-se perfeitamente à norma.  Agravo de instrumento desprovido.', '', 'LexML', 'transport_energy', '', '', 'AGRAVO DE INSTRUMENTO - RECURSO DE REVISTA - NEGATIVA DE PRESTAÇÃO JURISDICIONAL - NÃO-CARACTERIZAÇÃO -ADICIONAL DE PERICULOSIDADE - ESTADO GASOSO DOHIDROGÊNIO- AUSÊNCIA DE PREVISÃO NA NR 16 DA PORTARIA 3.214/78 - ACÓRDÃO REGIONAL QUE ASSENTA O ENQUADRAMENTO DA SITUAÇÃO FÁTICA NA NORMA. 1. A preliminar de nulidade da decisão, por negativa de prestação jurisdicional, em sede de recurso de revista, só pode ser argüida com base em violência aos arts. 832 da CLT, 458 do CPC ou 93, IX, da Constituição Federal, como estipula a Orientação Jurisprudencial 115 da SBDI-1 do TST.  2. Na hipótese, a Corte ¿a quo¿ consignou expressamente que a hipótese fática, consistente na manobra de substância inflamável (hidrogênio) para abastecimento realizada pelo Autor, estava plenamente enquadrada na NR 16 da Portaria 3.214/78. 3. Portanto, houve a completa entrega da prestação jurisdicional, não se verificando violação dos dispositivos constitucional e legais supramencionados. 4. Ademais, a alegação de que ohidrogêniomanipulado estava em estado gasoso, e não liqüefeito, e que, por essa razão, não estava inserida dentre as atividades consideradas perigosas na mencionada NR não aproveita a Reclamada, pois a situação fática assentada pelo Regional vai em sentido oposto, consignando que o caso concreto amoldava-se perfeitamente à norma.  Agravo de instrumento desprovido.', '', 'Tribunal Superior do Trabalho. 7ª Turma', 'Federal', 'Tribunal', '{"search_term": "", "urn_type": "other", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:camara.deputados:projeto.lei;pl:2023-11-28;5751', 'PL 5751/2023', 'https://www.lexml.gov.br/urn/urn:lex:br:camara.deputados:projeto.lei;pl:2023-11-28;5751', '2023-11-28', '', '', 'outro', 'Institui o marco legal dohidrogêniode baixa emissão de carbono, dispõe sobre a Política Nacional doHidrogêniode Baixa Emissão de Carbono, seus princípios, objetivos, conceitos, governança e instrumentos, altera a Lei nº 9.427, de 26 de dezembro de 1996, a Lei nº 9.478, de 6 de agosto de 1997, a Lei nº 9.991, de 24 de julho de 2000, a Lei nº 10.438, de 26 de abril de 2002, a Lei nº 10.848, de 15 de março de 2004, Lei nº 11.508, de 20 de julho de 2007, a Lei nº 14.182, de 12 de junho de 2021, e dá outras providências.', '', 'LexML', 'transport_energy', '', '', 'Institui o marco legal dohidrogêniode baixa emissão de carbono, dispõe sobre a Política Nacional doHidrogêniode Baixa Emissão de Carbono, seus princípios, objetivos, conceitos, governança e instrumentos, altera a Lei nº 9.427, de 26 de dezembro de 1996, a Lei nº 9.478, de 6 de agosto de 1997, a Lei nº 9.991, de 24 de julho de 2000, a Lei nº 10.438, de 26 de abril de 2002, a Lei nº 10.848, de 15 de março de 2004, Lei nº 11.508, de 20 de julho de 2007, a Lei nº 14.182, de 12 de junho de 2021, e dá outras providências.', '', 'Câmara dos Deputados', 'Federal', 'Outros', '{"search_term": "", "urn_type": "other", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
