INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Seguridad energética y medio ambiente', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:livro:2015;001101416', NULL, '', '', 'doutrina', 'Sumário:Seguridad energética : panorama general y apuestas defuturo-- Principales productores y consumidores energéticos -- La dependencia energética de la Unión Europea -- Evolución y políticas de la UE para «asegurar» su «inseguridad» energética -- Las energías alternativas a los hidrocarburos fósiles -- Seguridad medioambiental. | Assuntos: Consumidor. Dependência energética, Países da União Europeia. Energia, fontes. Petróleo comocombustível. Política energética. Proteção ambiental. {Proteção ambiental; Degradação ambiental, prevenção; Meio ambiente, proteção; Recursos naturais, proteção} Recursos naturais. Direito da energia.', '', 'LexML', 'transport_energy', 'Livro', 'Classificação: DIREITO PÚBLICO - 341::DIREITO ADMINISTRATIVO - 341.3::Domínio Público. Conceito. Domínio Eminente. Domínio Patrimonial - 341.34::Jazidas. Código de Minas - 341.344::Minérios nucleares. Energia atômica. Monopólio - 341.3443', 'Sumário:Seguridad energética : panorama general y apuestas defuturo-- Principales productores y consumidores energéticos -- La dependencia energética de la Unión Europea -- Evolución y políticas de la UE para «asegurar» su «inseguridad» energética -- Las energías alternativas a los hidrocarburos fósiles -- Seguridad medioambiental. | Assuntos: Consumidor. Dependência energética, Países da União Europeia. Energia, fontes. Petróleo comocombustível. Política energética. Proteção ambiental. {Proteção ambiental; Degradação ambiental, prevenção; Meio ambiente, proteção; Recursos naturais, proteção} Recursos naturais. Direito da energia.', '', 'Morán Blanco, Sagrario', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Direito das energias renováveis', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:livro:2014;001012207', NULL, '', '', 'doutrina', 'Resumo:Estudo de direito comparado sobre energias renováveis na Espanha, Alemanha, Itália, Reino Unido e Portugal.Resumo:Aborda o tema das energias renováveis sob uma abordagem holística, embora centrada nos problemas jurídicos específicos. Está organizado em quatro partes fundamentais. Uma primeira na qual é dada especial ênfase à importância económica deste sector, às diversas fileiras que o compõem e à evolução da programação política nacional. Na segunda procura-se contextualizar a política do fomento das energias renováveis no direito europeu, incluindo uma análise do tema no quadro dos auxílios de Estado. A terceira parte apresenta um estudo-síntese sobre os regimes de organização e funcionamento da produção de energia a partir de fontes renováveis em quatro países, nomeadamente Espanha, Alemanha, Itália e Reino Unido. Por último, na quarta parte, desenvolve-se a temática das energias renováveis em Portugal sob uma perspectiva de evolução temporal, que culmina com as perspectivas do que será a evolução do sector numfuturopróximo. | Assuntos: Biomassa. Energia eólica. {Energia eólica; Energia dos ventos; Força eólica} Etanol comocombustível. Incentivo fiscal, aspectos ambientais. Política energética. Potencial energético, aspectos ambientais. Proteção ambiental. {Proteção ambiental; Degradação ambiental, prevenção; Meio ambiente, proteção; Recursos naturais, proteção} Fonte renovável de energia, direito comparado. {Fonte renovável de energia; Fontes novas e renováveis de energia}', '', 'LexML', 'transport_energy', 'Livro', 'Classificação: DIREITO PÚBLICO - 341::DIREITO ADMINISTRATIVO - 341.3::Domínio Público. Conceito. Domínio Eminente. Domínio Patrimonial - 341.34::Direito Ambiental - 341.347', 'Resumo:Estudo de direito comparado sobre energias renováveis na Espanha, Alemanha, Itália, Reino Unido e Portugal.Resumo:Aborda o tema das energias renováveis sob uma abordagem holística, embora centrada nos problemas jurídicos específicos. Está organizado em quatro partes fundamentais. Uma primeira na qual é dada especial ênfase à importância económica deste sector, às diversas fileiras que o compõem e à evolução da programação política nacional. Na segunda procura-se contextualizar a política do fomento das energias renováveis no direito europeu, incluindo uma análise do tema no quadro dos auxílios de Estado. A terceira parte apresenta um estudo-síntese sobre os regimes de organização e funcionamento da produção de energia a partir de fontes renováveis em quatro países, nomeadamente Espanha, Alemanha, Itália e Reino Unido. Por último, na quarta parte, desenvolve-se a temática das energias renováveis em Portugal sob uma perspectiva de evolução temporal, que culmina com as perspectivas do que será a evolução do sector numfuturopróximo. | Assuntos: Biomassa. Energia eólica. {Energia eólica; Energia dos ventos; Força eólica} Etanol comocombustível. Incentivo fiscal, aspectos ambientais. Política energética. Potencial energético, aspectos ambientais. Proteção ambiental. {Proteção ambiental; Degradação ambiental, prevenção; Meio ambiente, proteção; Recursos naturais, proteção} Fonte renovável de energia, direito comparado. {Fonte renovável de energia; Fontes novas e renováveis de energia}', '', 'Soares, Cláudia Dias', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br;distrito.federal:tribunal.justica.distrito.federal.territorios;turma.civel.2:acordao:2012-03-14;572877', 'Acórdão nº 572877 do Processo nº20050110255336apc', 'https://www.lexml.gov.br/urn/urn:lex:br;distrito.federal:tribunal.justica.distrito.federal.territorios;turma.civel.2:acordao:2012-03-14;572877', '2012-03-14', 'DF', '', 'jurisprudencia', 'APELAÇÃO CÍVEL. SENTENÇA ULTRA PETITA. NÃO OCORRÊNCIA. CERCEAMENTO DO DIREITO DE DEFESA NÃO CONFIGURADO. PRELIMINARES DE ILEGITIMIDADE PASSIVA AD CAUSAM E FALTA DE INTERESSE DE AGIR AFASTADAS. PRESCRIÇÃO. INOCORRÊNCIA. APLICAÇÃO DO ART. 27 DO CDC. RESPONSABILIDADE CIVIL. RELAÇÃO DE CONSUMO POR EQUIPARAÇÃO. VAZAMENTO DECOMBUSTÍVEL. RESPONSABILIDADE OBJETIVA. DANO MORAL CONFIGURADO. OBRIGAÇÃO DE FAZER. LIMITAÇÃO.
APESAR DE O JULGAMENTO ULTRA PETITA NÃO DAR ENSEJO À NULIDADE, CABENDO TÃO SOMENTE À INSTÂNCIA REVISORA DECOTAR O QUE EXCEDEU DO PEDIDO, NÃO SE VISLUMBRA SUA OCORRÊNCIA, IN CASU.
TRATANDO-SE DE RELAÇÃO DE CONSUMO POR EQUIPARAÇÃO, SENDO A HIPÓTESE REGIDA PELO CÓDIGO DE DEFESA DO CONSUMIDOR, APLICA-SE A TEORIA DA APARÊNCIA A FIM DE RESPONSABILIZAR, DE MODO SOLIDÁRIO, TODAS AS EMPRESAS ENVOLVIDAS, PODENDO, O CONSUMIDOR, DEMANDAR EM FACE DE QUALQUER UMA DELAS OU AMBAS.
IRREFUTÁVEL O INTERESSE PROCESSUAL, ESTE APOIADO NA NECESSIDADE DA INTERVENÇÃO JUDICIAL E NA UTILIDADE DO PROCESSO PARA A OBTENÇÃO DO DIREITO QUE SE ALEGA POSSUIR.
ÀS PRETENSÕES RELATIVAS À RESPONSABILIDADE PELO FATO DO PRODUTO OU SERVIÇO, ISTO É, PELOS VÍCIOS OU DEFEITOS DE SEGURANÇA NELE HAVIDOS, APLICA-SE O PRAZO PRESCRICIONAL PREVISTO NO ART. 27 DO CDC.
PARA ELIDIR A RESPONSABILIDADE OBJETIVA DAS RÉS SOBRE O DEFEITO NA PRESTAÇÃO DO SERVIÇO, O QUAL OCASIONOU VAZAMENTO DECOMBUSTÍVELE, CONSEQUENTEMENTE, DANOS À POPULAÇÃO QUE VIVIA AO REDOR DO POSTO DE GASOLINA, O FORNECEDOR DO PRODUTO OU SERVIÇO DEVE COMPROVAR A AUSÊNCIA DE DEFEITO OU A CULPA EXCLUSIVA DA VÍTIMA OU DE TERCEIRO, NOS TERMOS DO §3.º DO ART. 14 DO CDC, O QUE NÃO OCORREU.
A EXPOSIÇÃO AOS COMPONENTES QUÍMICOS DOCOMBUSTÍVELGEROU ANGÚSTIA DECORRENTE DA INCERTEZA QUANTO AOFUTURO. ESSE FATO, ALIADO AO SOFRIDO PELO QUAL PADECERAM AS VÍTIMAS DO ACIDENTE, CONFIGURA DANO MORAL.
A DOUTRINA E A JURISPRUDÊNCIA PÁTRIAS TÊM CONSAGRADO A DUPLA FUNÇÃO NA COMPENSAÇÃO PECUNIÁRIA DO DANO MORAL: COMPENSATÓRIA E PENALIZANTE, VALENDO RESSALTAR QUE O VALOR ARBITRADO DEVE GUARDAR PERTINÊNCIA COM A FORÇA ECONÔMICO-FINANCEIRA DAS PARTES E A INTENSIDADE DO DANO SOFRIDO. | Assuntos: PROCEDÊNCIA, INDENIZAÇÃO, DANO MATERIAL, DANO MORAL, DEFEITO, PRODUTO, OBJETO, RESPONSABILIDADE OBJETIVA, VENDEDOR, FORNECEDOR, RESPONSABILIDADE SOLIDÁRIA, PRESTAÇÃO DE SERVIÇO, CORREÇÃO, VÍCIO OCULTO, VICIO DE QUALIDADE, DEFESA DO CONSUMIDOR.', '', 'LexML', 'transport_energy', 'Acórdão', '', 'APELAÇÃO CÍVEL. SENTENÇA ULTRA PETITA. NÃO OCORRÊNCIA. CERCEAMENTO DO DIREITO DE DEFESA NÃO CONFIGURADO. PRELIMINARES DE ILEGITIMIDADE PASSIVA AD CAUSAM E FALTA DE INTERESSE DE AGIR AFASTADAS. PRESCRIÇÃO. INOCORRÊNCIA. APLICAÇÃO DO ART. 27 DO CDC. RESPONSABILIDADE CIVIL. RELAÇÃO DE CONSUMO POR EQUIPARAÇÃO. VAZAMENTO DECOMBUSTÍVEL. RESPONSABILIDADE OBJETIVA. DANO MORAL CONFIGURADO. OBRIGAÇÃO DE FAZER. LIMITAÇÃO.
APESAR DE O JULGAMENTO ULTRA PETITA NÃO DAR ENSEJO À NULIDADE, CABENDO TÃO SOMENTE À INSTÂNCIA REVISORA DECOTAR O QUE EXCEDEU DO PEDIDO, NÃO SE VISLUMBRA SUA OCORRÊNCIA, IN CASU.
TRATANDO-SE DE RELAÇÃO DE CONSUMO POR EQUIPARAÇÃO, SENDO A HIPÓTESE REGIDA PELO CÓDIGO DE DEFESA DO CONSUMIDOR, APLICA-SE A TEORIA DA APARÊNCIA A FIM DE RESPONSABILIZAR, DE MODO SOLIDÁRIO, TODAS AS EMPRESAS ENVOLVIDAS, PODENDO, O CONSUMIDOR, DEMANDAR EM FACE DE QUALQUER UMA DELAS OU AMBAS.
