INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.8:acordao:2019-06-19;0012082-69.2016.5.03.0042', 'Acórdão PJe TRT 3ª / Oitava Turma / 2019-06-19', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.8:acordao:2019-06-19;0012082-69.2016.5.03.0042', '2019-06-19', '', '3ª Região - Minas Gerais', 'jurisprudencia', 'COMBUSTÍVEL. POSSIBILIDADE DE PENHORA. Nos termo do art. 789 do CPC, "O devedor responde com todos os seus bens presentes efuturospara o cumprimento de suas obrigações, salvo as restrições estabelecidas em lei." Assim, considerando a inadimplência do devedor e levando-se em conta que ocombustívelpor ele comercializado trata-se de bem fungível, não inserido nas hipóteses de impenhorabilidade previstas no art. 833 do CPC, é plenamente cabível sua penhora. | Assuntos: PENHORA - CABIMENTO', '', 'LexML', 'transport_energy', 'Acórdão', '', 'COMBUSTÍVEL. POSSIBILIDADE DE PENHORA. Nos termo do art. 789 do CPC, "O devedor responde com todos os seus bens presentes efuturospara o cumprimento de suas obrigações, salvo as restrições estabelecidas em lei." Assim, considerando a inadimplência do devedor e levando-se em conta que ocombustívelpor ele comercializado trata-se de bem fungível, não inserido nas hipóteses de impenhorabilidade previstas no art. 833 do CPC, é plenamente cabível sua penhora. | Assuntos: PENHORA - CABIMENTO', '', 'Tribunal Regional do Trabalho. 8ª Turma', '', 'Tribunal', '{"search_term": "", "urn_type": "jurisprudence", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
