INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:congresso.nacional:medida.provisoria;mpv:2018-05-27;833', 'MPV 833/2018', 'https://www.lexml.gov.br/urn/urn:lex:br:congresso.nacional:medida.provisoria;mpv:2018-05-27;833', '2018-05-27', '', '', 'lei', 'Altera a Lei nº 13.103, de 2 de março de 2015, para prever que, em todo o território nacional, os veículos detransportedecargasque circularem vazios nas vias terrestres federais, estaduais, distritais e municipais ficarão isentos da cobrança de pedágio sobre os eixos que mantiverem suspensos.

NOVA EMENTA: Altera a Lei nº 13.103, de 2 de março de 2015, para prever isenção, em todo o território nacional, da cobrança de pedágio sobre eixos suspensos de veículos detransportedecargasque circularem vazios nas vias terrestres federais, estaduais, distritais e municipais.', '', 'LexML', 'transport_energy', 'Medida Provisória', '', 'Altera a Lei nº 13.103, de 2 de março de 2015, para prever que, em todo o território nacional, os veículos detransportedecargasque circularem vazios nas vias terrestres federais, estaduais, distritais e municipais ficarão isentos da cobrança de pedágio sobre os eixos que mantiverem suspensos.

NOVA EMENTA: Altera a Lei nº 13.103, de 2 de março de 2015, para prever isenção, em todo o território nacional, da cobrança de pedágio sobre eixos suspensos de veículos detransportedecargasque circularem vazios nas vias terrestres federais, estaduais, distritais e municipais.', '', 'Congresso Nacional', 'Federal', 'Legislativo Federal', '{"search_term": "", "urn_type": "legislation", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
