INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:congresso.nacional:medida.provisoria;mpv:2019-05-03;882', 'MPV 882/2019', 'https://www.lexml.gov.br/urn/urn:lex:br:congresso.nacional:medida.provisoria;mpv:2019-05-03;882', '2019-05-03', '', '', 'lei', 'Altera a Lei nº 9.503, de 23 de setembro de 1997- Código de Trânsito Brasileiro; a Lei nº 10.233, de 5 de junho de 2001, que dispõe sobre a reestruturação dostransportesaquaviárioe terrestre e cria o Conselho Nacional de Integração de Políticas deTransporte, a Agência Nacional deTransportesTerrestres, a Agência Nacional deTransportesAquaviáriose o Departamento Nacional de Infraestrutura deTransportes, a Lei nº 12.815, de 5 de junho de 2013, que dispõe sobre a exploração direta e indireta pela União de portos e instalações portuárias e sobre as atividades desempenhadas pelos operadores portuários, e a Lei nº 13.334, de 13 de setembro de 2016, que cria o Programa de Parcerias de Investimentos - PPI, e dá outras providências.', '', 'LexML', 'transport_energy', 'Medida Provisória', '', 'Altera a Lei nº 9.503, de 23 de setembro de 1997- Código de Trânsito Brasileiro; a Lei nº 10.233, de 5 de junho de 2001, que dispõe sobre a reestruturação dostransportesaquaviárioe terrestre e cria o Conselho Nacional de Integração de Políticas deTransporte, a Agência Nacional deTransportesTerrestres, a Agência Nacional deTransportesAquaviáriose o Departamento Nacional de Infraestrutura deTransportes, a Lei nº 12.815, de 5 de junho de 2013, que dispõe sobre a exploração direta e indireta pela União de portos e instalações portuárias e sobre as atividades desempenhadas pelos operadores portuários, e a Lei nº 13.334, de 13 de setembro de 2016, que cria o Programa de Parcerias de Investimentos - PPI, e dá outras providências.', '', 'Congresso Nacional', 'Federal', 'Legislativo Federal', '{"search_term": "", "urn_type": "legislation", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
