INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'A Regulação dotransporteaquaviário', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:livro:2005;000730444', NULL, '', '', 'doutrina', 'Resumo:Analisa a Lei n. 10.233 de 05 de de junho de 2001, decorrente do Projeto de Lei n. 1615 de 1999, especificamente no que concerne à Agência Nacional deTransportesAquaviários.Sumário:Visão histórica dotransporteaquaviáriono Brasil. Construção naval. Política detransportesmarítimos. Quadros da legislação da estrutura dos órgãos da Marinha Mercante -- A Constituição de 1988 e a reforma do Estado com a criação da agências reguladoras -- Projeto de Lei n. 1615/99 e tópicos específicos da Lei n. 10.233/2001 - Aspecto orgânico e atribuições da mesma quanto à outorga para prestação de serviços detransportesaquaviários. Questão das chamadas "Empresas de Papel". As primeiras normas editadas pela ANTAQ -- Regulação segundo a moderna metodologia do Direito e a insuficiência do positivismo jurídico em face das modernas teorias dos princípios jurídicos da Ciência do Direito. | Assuntos: Transportemarítimo, Brasil.Transportemarítimo, regulação, Brasil. Indústria naval, Brasil. {Indústria naval; Indústria de construção naval}Transportede carga, Brasil. Frete, Brasil. Agência reguladora, Brasil. Prestação de serviços, Brasil. Livre concorrência, Brasil.', '', 'LexML', 'transport_energy', 'Livro', 'Classificação: DIREITO PRIVADO - 342::DIREITO COMERCIAL - 342.2::Direito Marítimo - 342.29::Navios de comércio - 342.291', 'Resumo:Analisa a Lei n. 10.233 de 05 de de junho de 2001, decorrente do Projeto de Lei n. 1615 de 1999, especificamente no que concerne à Agência Nacional deTransportesAquaviários.Sumário:Visão histórica dotransporteaquaviáriono Brasil. Construção naval. Política detransportesmarítimos. Quadros da legislação da estrutura dos órgãos da Marinha Mercante -- A Constituição de 1988 e a reforma do Estado com a criação da agências reguladoras -- Projeto de Lei n. 1615/99 e tópicos específicos da Lei n. 10.233/2001 - Aspecto orgânico e atribuições da mesma quanto à outorga para prestação de serviços detransportesaquaviários. Questão das chamadas "Empresas de Papel". As primeiras normas editadas pela ANTAQ -- Regulação segundo a moderna metodologia do Direito e a insuficiência do positivismo jurídico em face das modernas teorias dos princípios jurídicos da Ciência do Direito. | Assuntos: Transportemarítimo, Brasil.Transportemarítimo, regulação, Brasil. Indústria naval, Brasil. {Indústria naval; Indústria de construção naval}Transportede carga, Brasil. Frete, Brasil. Agência reguladora, Brasil. Prestação de serviços, Brasil. Livre concorrência, Brasil.', '', 'Biolchini, Monique Calmon de Almeida', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
