INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Logísticasustentável', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:livro:2018;001162981', NULL, '', '', 'doutrina', 'Sumário:Sustentabilidade: o desafio contemporâneo dos gestores delogística-- Entendendo os impactos socioambientais das atividades primárias dalogística-- Avaliando os impactos socioambientais das atividades primárias dalogística-- Redesenhando a cadeia de suprimento sob a ótica da sustentabilidade ambiental -- Privilegiando modos de transporte ambientalmente sustentáveis -- Desenvolvendo veículos e equipamentos de movimentação ambientalmente sustentáveis -- Desenvolvendo sistemas de manutenção de estoque e processamento de pedidos ambientalmente sustentáveis -- Aprimorando a utilização dos veículos e suas rotas -- Renovando a frota e aprimorando a eficiência energética na utilização de veículos rodoviários -- Potencializando a aplicação da tecnologia da informação para a sustentabilidade ambiental dalogística-- Programa de sustentabilidade ambiental emlogística-- Aplicando boas práticas para a sustentabilidade emlogística-- Evoluindo continuamente. | Assuntos: Logísticareversa. Gestão de projetos, aspectos ambientais. Administração de material. Sustentabilidade, transporte. Tecnologia ambiental, transporte. Impacto ambiental. Desenvolvimento sustentável. {Desenvolvimento sustentável; Desenvolvimento auto-sustentado; Desenvolvimento sustentado}', '', 'LexML', 'transport_energy', 'Livro', 'Classificação: DIREITO PÚBLICO - 341::DIREITO ADMINISTRATIVO - 341.3::Domínio Público. Conceito. Domínio Eminente. Domínio Patrimonial - 341.34::Direito Ambiental - 341.347', 'Sumário:Sustentabilidade: o desafio contemporâneo dos gestores delogística-- Entendendo os impactos socioambientais das atividades primárias dalogística-- Avaliando os impactos socioambientais das atividades primárias dalogística-- Redesenhando a cadeia de suprimento sob a ótica da sustentabilidade ambiental -- Privilegiando modos de transporte ambientalmente sustentáveis -- Desenvolvendo veículos e equipamentos de movimentação ambientalmente sustentáveis -- Desenvolvendo sistemas de manutenção de estoque e processamento de pedidos ambientalmente sustentáveis -- Aprimorando a utilização dos veículos e suas rotas -- Renovando a frota e aprimorando a eficiência energética na utilização de veículos rodoviários -- Potencializando a aplicação da tecnologia da informação para a sustentabilidade ambiental dalogística-- Programa de sustentabilidade ambiental emlogística-- Aplicando boas práticas para a sustentabilidade emlogística-- Evoluindo continuamente. | Assuntos: Logísticareversa. Gestão de projetos, aspectos ambientais. Administração de material. Sustentabilidade, transporte. Tecnologia ambiental, transporte. Impacto ambiental. Desenvolvimento sustentável. {Desenvolvimento sustentável; Desenvolvimento auto-sustentado; Desenvolvimento sustentado}', '', 'D''Agosto, Márcio de Almeida', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Logísticaintegrada e estratégia', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2002;1000699725', NULL, '', '', 'doutrina', 'Resumo:"...trata da atividadelogísticanos meios acadêmico, empresarial e militar. Apresenta um resumo do assuntoLogísticaIntegrada e Estratégia e uma revisão bibliográfica sumária do temaLogísticaMilitar Brasileira, em forma de sinopse. Os vínculos identificados entre as duas abordagens são destacados no desenvolvimento do artigo e um possicionamento conclusivo é realizado ao seu final. Alogísticaé destacada como atividade operacional e estratégica, sempre atenta para integrar conceitos e procedimentos visando à busca da vantagem competitiva no mercado ou vantagem operacional nas ações militares".Sumário:Formação do conceito delogística-- A consolidação da atividade e do conceito delogística-- Alogísticae a vantagem competitiva --Logísticae estratégia -- Modelos e estruturação estratégicalogística-- Política estratégia e doutrina militares do Brasil -- Forças Armadas --Logísticaoperacional no exército brasileiro. | Assuntos: Ciência militar. {Ciência militar; Arte e ciência militar} Estratégia militar.Logística.', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PÚBLICO - 341::DIREITO CONSTITUCIONAL - 341.2::Segurança nacional - 341.26', 'Resumo:"...trata da atividadelogísticanos meios acadêmico, empresarial e militar. Apresenta um resumo do assuntoLogísticaIntegrada e Estratégia e uma revisão bibliográfica sumária do temaLogísticaMilitar Brasileira, em forma de sinopse. Os vínculos identificados entre as duas abordagens são destacados no desenvolvimento do artigo e um possicionamento conclusivo é realizado ao seu final. Alogísticaé destacada como atividade operacional e estratégica, sempre atenta para integrar conceitos e procedimentos visando à busca da vantagem competitiva no mercado ou vantagem operacional nas ações militares".Sumário:Formação do conceito delogística-- A consolidação da atividade e do conceito delogística-- Alogísticae a vantagem competitiva --Logísticae estratégia -- Modelos e estruturação estratégicalogística-- Política estratégia e doutrina militares do Brasil -- Forças Armadas --Logísticaoperacional no exército brasileiro. | Assuntos: Ciência militar. {Ciência militar; Arte e ciência militar} Estratégia militar.Logística.', '', 'Silva, Carlos Alberto Vicente da', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
