INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'A gestão moderna e alogísticaorganizacional', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2003;1000703576', NULL, '', '', 'doutrina', 'Resumo:Apresenta o processo de implantação do modelo de gestão moderna nas organizações militares de suprimento, analisando, de forma didática, os critérios que compõem o instrumento de auto-avaliação, fundamental para que sejam alcançados os resultados da gestão pela qualidade, e mostra o quanto se pode fazer, apesar dos poucos recursos disponíveis, para se garantir o bom desempenho dalogísticaorganizacional.Sumário:O processo de implantação do modelo de gestão -- O instrumento de auto-avaliação -- a gestão moderna e seus resultados -- | Assuntos: Logística, Brasil. Exército, Brasil. Organização militar, Brasil. Planejamento militar, Brasil.', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PÚBLICO - 341::DIREITO CONSTITUCIONAL - 341.2::Segurança nacional - 341.26', 'Resumo:Apresenta o processo de implantação do modelo de gestão moderna nas organizações militares de suprimento, analisando, de forma didática, os critérios que compõem o instrumento de auto-avaliação, fundamental para que sejam alcançados os resultados da gestão pela qualidade, e mostra o quanto se pode fazer, apesar dos poucos recursos disponíveis, para se garantir o bom desempenho dalogísticaorganizacional.Sumário:O processo de implantação do modelo de gestão -- O instrumento de auto-avaliação -- a gestão moderna e seus resultados -- | Assuntos: Logística, Brasil. Exército, Brasil. Organização militar, Brasil. Planejamento militar, Brasil.', '', 'Figueiredo, Ricardo Marques', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
