INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Alogísticado agronegócio, regulação e os contratos pertinentes', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2015;1001096425', NULL, '', '', 'doutrina', 'Resumo:Trata alogísticado agronegócio, o papel do Estado na respectiva regulação e alguns contratos pertinentes, tais como armazenagem, transporte e seguro. Identifica os principais problemas que os operadores desse segmento enfrentam diariamente no país, em especial nos segmentos de transporte, armazenagem, portos e custos em geral. Conclui com um embasamento - teórico e prático - para as futuras discussões voltadas à melhoria dalogísticado agronegócio no Brasil. | Assuntos: Agronegócio, Brasil. {Agronegócio; Agribusiness}Logística, Brasil. Contrato, regulamentação, Brasil.', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PRIVADO - 342::DIREITO CIVIL - 342.1::Obrigações. Contratos. Convenções - 342.14::Contratos e convenções em geral - 342.144', 'Resumo:Trata alogísticado agronegócio, o papel do Estado na respectiva regulação e alguns contratos pertinentes, tais como armazenagem, transporte e seguro. Identifica os principais problemas que os operadores desse segmento enfrentam diariamente no país, em especial nos segmentos de transporte, armazenagem, portos e custos em geral. Conclui com um embasamento - teórico e prático - para as futuras discussões voltadas à melhoria dalogísticado agronegócio no Brasil. | Assuntos: Agronegócio, Brasil. {Agronegócio; Agribusiness}Logística, Brasil. Contrato, regulamentação, Brasil.', '', 'Dib, Adriano Abrão', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
