INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:congresso.nacional:medida.provisoria;mpv:2024;1255', '[ Medida Provisória nº 1255/2024 ]', 'https://www.lexml.gov.br/urn/urn:lex:br:congresso.nacional:medida.provisoria;mpv:2024;1255', NULL, '', '', 'lei', 'Altera a Lei nº 9.478, de 6 de agosto de 1997, e a Lei nº 14.871, de 28 de maio de 2024, para autorizar a concessão de quotas diferenciadas de depreciação acelerada para navios-tanque novos produzidos no Brasil destinados ao ativo imobilizado e empregados exclusivamente em atividade decabotagemde petróleo e seus derivados.', '', 'LexML', 'transport_energy', 'Medida Provisória', '', 'Altera a Lei nº 9.478, de 6 de agosto de 1997, e a Lei nº 14.871, de 28 de maio de 2024, para autorizar a concessão de quotas diferenciadas de depreciação acelerada para navios-tanque novos produzidos no Brasil destinados ao ativo imobilizado e empregados exclusivamente em atividade decabotagemde petróleo e seus derivados.', '', 'Congresso Nacional', 'Federal', 'Legislativo Federal', '{"search_term": "", "urn_type": "legislation", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
