INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:congresso.nacional:projeto.lei;pln:2023;26', '[ Projeto de Lei do Congresso Nacional nº 26/2023 : Lei nº 14.710 de 25/10/2023 ]', 'https://www.lexml.gov.br/urn/urn:lex:br:congresso.nacional:projeto.lei;pln:2023;26', NULL, '', '', 'outro', 'Abre ao Orçamento Fiscal da União, em favor do Ministério da Defesa, crédito suplementar no valor de R$ 39.700.000,00, para reforço de dotações constantes da Lei Orçamentária vigente.', '', 'LexML', 'transport_energy', '', '', 'Abre ao Orçamento Fiscal da União, em favor do Ministério da Defesa, crédito suplementar no valor de R$ 39.700.000,00, para reforço de dotações constantes da Lei Orçamentária vigente.', '', 'Congresso Nacional', 'Federal', 'Legislativo Federal', '{"search_term": "", "urn_type": "other", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Regulação jurídica dasrodoviasconcedidas', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:livro:2004;000687170', NULL, '', '', 'doutrina', 'Resumo:Estuda o modelo das concessões derodoviae as polêmicas envolvidas no tema, muitas das quais somente se encerram no Judiciário. Trata darodoviaenquanto bem público e da sua gestão, buscando-se demonstrar a legitimidade da opção pela concessão. Aborda a regulação darodoviae destaca os principais mecanismos legais para viabilizar a prestação de um serviço público adequado. Examina os direitos e obrigações do concedente, do concessionário e do usuário. Estuda, ainda, os aspectos jurídicos da remuneração do concessionário e as questões atinentes ao equilíbrio econômico-financeiro da relação contratual.Sumário:Asrodoviase sua gestão: A CIDE como mecanismo financiador -- Atividade regulatória nasrodovias-- A relação trilateral no contrato de concessão derodovia-- Aspectos jurídicos da remuneração nas concessões derodovias: O pedágio. As receitas alternativas, complementares, acessórias ou de projetos associados. O equilíbrio econômico-financeiro do contrato de concessão derodovias. | Assuntos: Concessão de serviços públicos, Brasil. {Concessão de serviços públicos; Concessão (direito administrativo); Concessão administrativa; Concessão de serviço público; Serviços públicos concedidos} Contrato administrativo, Brasil. {Contrato administrativo; Contrato de direito público; Contrato público} Direito rodoviário, Brasil. Pedágio, Brasil.Rodovia, financiamento, Brasil. {Rodovia; Autoestrada; Estrada de rodagem}Rodovia, regulação, Brasil. {Rodovia; Autoestrada; Estrada de rodagem}Rodovia, aspectos jurídicos, Brasil. {Rodovia; Autoestrada; Estrada de rodagem}', '', 'LexML', 'transport_energy', 'Livro', 'Classificação: DIREITO PÚBLICO - 341::DIREITO ADMINISTRATIVO - 341.3::Poder de Polícia  - 341.37::Regulamentação do Tráfego e Trânsito. Código de Trânsito - 341.376', 'Resumo:Estuda o modelo das concessões derodoviae as polêmicas envolvidas no tema, muitas das quais somente se encerram no Judiciário. Trata darodoviaenquanto bem público e da sua gestão, buscando-se demonstrar a legitimidade da opção pela concessão. Aborda a regulação darodoviae destaca os principais mecanismos legais para viabilizar a prestação de um serviço público adequado. Examina os direitos e obrigações do concedente, do concessionário e do usuário. Estuda, ainda, os aspectos jurídicos da remuneração do concessionário e as questões atinentes ao equilíbrio econômico-financeiro da relação contratual.Sumário:Asrodoviase sua gestão: A CIDE como mecanismo financiador -- Atividade regulatória nasrodovias-- A relação trilateral no contrato de concessão derodovia-- Aspectos jurídicos da remuneração nas concessões derodovias: O pedágio. As receitas alternativas, complementares, acessórias ou de projetos associados. O equilíbrio econômico-financeiro do contrato de concessão derodovias. | Assuntos: Concessão de serviços públicos, Brasil. {Concessão de serviços públicos; Concessão (direito administrativo); Concessão administrativa; Concessão de serviço público; Serviços públicos concedidos} Contrato administrativo, Brasil. {Contrato administrativo; Contrato de direito público; Contrato público} Direito rodoviário, Brasil. Pedágio, Brasil.Rodovia, financiamento, Brasil. {Rodovia; Autoestrada; Estrada de rodagem}Rodovia, regulação, Brasil. {Rodovia; Autoestrada; Estrada de rodagem}Rodovia, aspectos jurídicos, Brasil. {Rodovia; Autoestrada; Estrada de rodagem}', '', 'Garcia, Flávio Amaral', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
