INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:camara.deputados:projeto.lei;pl:2024-04-09;1149', 'PL 1149/2024', 'https://www.lexml.gov.br/urn/urn:lex:br:camara.deputados:projeto.lei;pl:2024-04-09;1149', '2024-04-09', '', '', 'outro', 'Estabelece a dedução integral das importâncias aplicadas nas atividades de instalação de pontos de recarga deveículoselétricos ouhíbridosem cada período de apuração na determinação do lucro real e da base de cálculo da Contribuição Social sobre o Lucro Líquido – CSLL,  a dedução do montante da conta de energia elétrica que seja atribuível ao consumo dosveículoselétricos ouhíbridosrecarregados nos postos até o limite de um por cento do imposto sobre a renda devido, inclusive adicional, e da contribuição social sobre o lucro devida em cada período de apuração, e a autorização da concessão de linhas de crédito favorecidas para a instalação dos postos de recarga deveículoselétricos ouhíbridos.', '', 'LexML', 'transport_energy', '', '', 'Estabelece a dedução integral das importâncias aplicadas nas atividades de instalação de pontos de recarga deveículoselétricos ouhíbridosem cada período de apuração na determinação do lucro real e da base de cálculo da Contribuição Social sobre o Lucro Líquido – CSLL,  a dedução do montante da conta de energia elétrica que seja atribuível ao consumo dosveículoselétricos ouhíbridosrecarregados nos postos até o limite de um por cento do imposto sobre a renda devido, inclusive adicional, e da contribuição social sobre o lucro devida em cada período de apuração, e a autorização da concessão de linhas de crédito favorecidas para a instalação dos postos de recarga deveículoselétricos ouhíbridos.', '', 'Câmara dos Deputados', 'Federal', 'Outros', '{"search_term": "", "urn_type": "other", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
