INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:camara.deputados:projeto.lei.complementar;plp:2023-07-25;158', 'PLP 158/2023', 'https://www.lexml.gov.br/urn/urn:lex:br:camara.deputados:projeto.lei.complementar;plp:2023-07-25;158', '2023-07-25', '', '', 'outro', 'Estabelece normas gerais em matéria de legislação tributária nos termos do art. 146, III, alínea “a” da Constituição para dispor que o Imposto sobre Circulação de Mercadorias e sobre Serviços de Transporte Interestadual, Intermunicipal e de Comunicações (ICMS) e o Imposto sobre a Propriedade deVeículosAutomotores (IPVA) previstos, respectivamente, nos incisos II e III do art. 155 da Constituição, não incidem sobre as operações comveículoselétricos leves e levíssimos a bateria (BEV),veículoselétricos a célula de combustível (FCEV),veículosda modalidadehíbridacom combustível fóssil (HEV) e plugin (PHEV) ou a propriedade dessesveículos; que essa não-incidência alcança os serviços correlatos de instalação e uso de eletropostos e pontos de carregamento dessesveículose as taxas em função da alienação, transferência, registro e licenciamento da propriedade dessesveículos; que essesveículospoderão transitar pelas faixas regulamentadas como de circulação exclusiva paraveículosde transporte público e que a União, os Estados e o Distrito Federal concederão linhas de crédito prioritárias para fomentar e subsidiar a aquisição dessesveículos; a produção, capacitação, e importação de equipamentos para produção de peças e componentes
destinados à cadeia produtiva dessesveículose a instalação de redes de postos ou pontos de carregamento para eles.', '', 'LexML', 'transport_energy', '', '', 'Estabelece normas gerais em matéria de legislação tributária nos termos do art. 146, III, alínea “a” da Constituição para dispor que o Imposto sobre Circulação de Mercadorias e sobre Serviços de Transporte Interestadual, Intermunicipal e de Comunicações (ICMS) e o Imposto sobre a Propriedade deVeículosAutomotores (IPVA) previstos, respectivamente, nos incisos II e III do art. 155 da Constituição, não incidem sobre as operações comveículoselétricos leves e levíssimos a bateria (BEV),veículoselétricos a célula de combustível (FCEV),veículosda modalidadehíbridacom combustível fóssil (HEV) e plugin (PHEV) ou a propriedade dessesveículos; que essa não-incidência alcança os serviços correlatos de instalação e uso de eletropostos e pontos de carregamento dessesveículose as taxas em função da alienação, transferência, registro e licenciamento da propriedade dessesveículos; que essesveículospoderão transitar pelas faixas regulamentadas como de circulação exclusiva paraveículosde transporte público e que a União, os Estados e o Distrito Federal concederão linhas de crédito prioritárias para fomentar e subsidiar a aquisição dessesveículos; a produção, capacitação, e importação de equipamentos para produção de peças e componentes
destinados à cadeia produtiva dessesveículose a instalação de redes de postos ou pontos de carregamento para eles.', '', 'Câmara dos Deputados', 'Federal', 'Outros', '{"search_term": "", "urn_type": "other", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br;distrito.federal:tribunal.justica.distrito.federal.territorios;turma.civel.4:acordao:2010-12-15;474070', 'Acórdão nº 474070 do Processo nº20090210048838apc', 'https://www.lexml.gov.br/urn/urn:lex:br;distrito.federal:tribunal.justica.distrito.federal.territorios;turma.civel.4:acordao:2010-12-15;474070', '2010-12-15', 'DF', '', 'jurisprudencia', 'CIVIL E PROCESSUAL CIVIL. ARRENDAMENTO MERCANTIL. RESCISÃO DO CONTRATO A PEDIDO DO ARRENDATÁRIO. POSSIBILIDADE. RESTITUIÇÃO DO VRG PAGO ANTECIPADAMENTE. 
1. O ARRENDAMENTO MERCANTIL É UM CONTRATOHÍBRIDOQUE REÚNE ELEMENTOS DA LOCAÇÃO E DA COMPRA E VENDA. NESSA MODALIDADE CONTRATUAL, A INSTITUIÇÃO FINANCEIRA ALUGA UM BEM PARA O ARRENDATÁRIO, POR DETERMINADO PERÍODO DE TEMPO, MEDIANTE O PAGAMENTO DE PRESTAÇÕES PERIÓDICAS, SURGINDO PARA O ARRENDATÁRIO, AO FINAL DO PERÍODO DO ALUGUEL, TRÊS OPÇÕES: RENOVAR O ALUGUEL DO BEM, DEVOLVER O BEM AO ARRENDANTE OU COMPRÁ-LO, PAGANDO UMA QUANTIA PREVIAMENTE ESTIPULADA, O VALOR RESIDUAL GARANTIDO.
2. O PAGAMENTO ANTECIPADO DO VRG NÃO DESNATURA O CONTRATO DE LEASING E NÃO SIGNIFICA QUE O ARRENDATÁRIO OPTOU PELA COMPRA DO BEM, DEVENDO LHE SER RESTITUÍDO CASO NÃO QUEIRA PERMANECER COM OVEÍCULOAO FINAL DO PERÍODO DE ALUGUEL. 
3. SE O CONTRATO DE ARRENDAMENTO MERCANTIL FOI RESOLVIDO ANTES DE SEU CUMPRIMENTO, AS PARTES DEVEM RETORNAR AO ESTADO ANTERIOR, DE MODO QUE A POSSE DOVEÍCULODEVE SER RESTITUÍDA AO ARRENDANTE E O VALOR DO VRG PAGO ANTECIPADAMENTE DEVOLVIDO A ARRENDATÁRIO, SOB PENA DE ENRIQUECIMENTO ILÍCITO DO PRIMEIRO, POIS ESSA QUANTIA SÓ É DEVIDA EM CASO DE COMPRA DO BEM.
4. A DEVOLUÇÃO DO VALOR PAGO ANTECIPADAMENTE A TÍTULO DE VRG É UMA DECORRÊNCIA NATURAL DA RESOLUÇÃO DO CONTRATO E DA REINTEGRAÇÃO DOVEÍCULONA POSSE DO AUTOR, PORQUE O ORDENAMENTO VEDA O ENRIQUECIMENTO SEM CAUSA, PODENDO SER DETERMINADA ATÉ MESMO DE OFÍCIO.
5. O VALOR DO VRG PAGO ANTECIPADAMENTE DEVE SER INTEGRALMENTE RESTITUÍDO AO ARRENDATÁRIO.
6. APELO IMPROVIDO. | Assuntos: PROCEDÊNCIA, AÇÃO DE REINTEGRAÇÃO DE POSSE,VEÍCULOAUTOMOTOR, AUTOR, DEVOLUÇÃO, (VRG), RESCISÃO, CONTRATO, ARRENDAMENTO MERCANTIL, INOCORRÊNCIA, USO, ARRENDATÁRIO, OPÇÃO, COMPRA E VENDA, PREVISÃO LEGAL.', '', 'LexML', 'transport_energy', 'Acórdão', '', 'CIVIL E PROCESSUAL CIVIL. ARRENDAMENTO MERCANTIL. RESCISÃO DO CONTRATO A PEDIDO DO ARRENDATÁRIO. POSSIBILIDADE. RESTITUIÇÃO DO VRG PAGO ANTECIPADAMENTE. 
