INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br;justica.trabalho;regiao.16:tribunal.regional.trabalho;turma.1:acordao:2011-03-02;0247900-75.2009.5.16.0012', 'ACORDÃO TRT 16ª / 1ª Turma / RO 0247900-75.2009.5.16.0012', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.16:tribunal.regional.trabalho;turma.1:acordao:2011-03-02;0247900-75.2009.5.16.0012', '2011-03-02', '', '16ª Região - Maranhão', 'jurisprudencia', 'AUXILIAR DE CONDUTORAUTÔNOMODEVEÍCULO. LEI Nº 6.094/74. RELAÇÃO DE EMPREGO. INEXISTÊNCIA. Constatando-se que o reclamado, na qualidade de motorista-proprietário de um únicoveículode praça (van), dividia a jornada com o reclamante e considerando-se a prestação de serviços do obreiro sem qualquer subordinação, mas em regime de colaboração, entendo presentes os elementos tipificadores da hipótese prevista na legislação especial (Lei n. 6.094/74), não havendo como reconhecer o liame empregatício, nos moldes do art. 3º da CLT, como postulado. Recurso conhecido, mas não provido. | Assuntos: AUTÔNOMO,AUXILIAR,CONDUTOR,EMPREGO,INEXISTÊNCIA,LEI,RELAÇÃO,VEÍCULO', '', 'LexML', 'transport_energy', 'Acórdão', '', 'AUXILIAR DE CONDUTORAUTÔNOMODEVEÍCULO. LEI Nº 6.094/74. RELAÇÃO DE EMPREGO. INEXISTÊNCIA. Constatando-se que o reclamado, na qualidade de motorista-proprietário de um únicoveículode praça (van), dividia a jornada com o reclamante e considerando-se a prestação de serviços do obreiro sem qualquer subordinação, mas em regime de colaboração, entendo presentes os elementos tipificadores da hipótese prevista na legislação especial (Lei n. 6.094/74), não havendo como reconhecer o liame empregatício, nos moldes do art. 3º da CLT, como postulado. Recurso conhecido, mas não provido. | Assuntos: AUTÔNOMO,AUXILIAR,CONDUTOR,EMPREGO,INEXISTÊNCIA,LEI,RELAÇÃO,VEÍCULO', '', 'Tribunal Regional do Trabalho. 1ª Turma', '', 'Tribunal', '{"search_term": "", "urn_type": "jurisprudence", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br;justica.trabalho;regiao.13:tribunal.regional.trabalho;tribunal.pleno:acordao:2011-07-19;126966', 'ACÓRDÃO TRT 13ª REGIÃO / NÚCLEO DE JURISPRUDÊNCIA - ACÓRDÃO N. 126966', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.13:tribunal.regional.trabalho;tribunal.pleno:acordao:2011-07-19;126966', '2011-07-19', '', '13ª Região - Paraíba', 'jurisprudencia', 'E M E N T A: MOTORISTA DECAMINHÃO. TRABALHO EM EXPOSIÇÃO A SISTEMAELÉTRICOENERGIZADO. ADICIONAL DE PERICULOSIDADE. DEFERIMENTO. O motorista decaminhãode empresa que presta serviços terceirizados para concessionária de energiaelétricae que, em face disso, por vezes, é instado a operar munck em área exposta a sistemaelétricoenergizado, faz jus à adicional de insalubridade. Exegese da Súmula nº 361 do TST.', '', 'LexML', 'transport_energy', 'Acórdão', '', 'E M E N T A: MOTORISTA DECAMINHÃO. TRABALHO EM EXPOSIÇÃO A SISTEMAELÉTRICOENERGIZADO. ADICIONAL DE PERICULOSIDADE. DEFERIMENTO. O motorista decaminhãode empresa que presta serviços terceirizados para concessionária de energiaelétricae que, em face disso, por vezes, é instado a operar munck em área exposta a sistemaelétricoenergizado, faz jus à adicional de insalubridade. Exegese da Súmula nº 361 do TST.', '', 'Tribunal Regional do Trabalho. Tribunal Pleno', '', 'Tribunal', '{"search_term": "", "urn_type": "jurisprudence", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
