INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:tribunal.superior.trabalho;turma.1:acordao;rr:2023-10-04;546-2017-66-23-0', 'Acórdão do processo Nº RR - 546-94.2017.5.23.0066', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.1:acordao;rr:2023-10-04;546-2017-66-23-0', '2023-10-04', '', '', 'outro', 'I - AGRAVO DOS RECLAMANTES. AGRAVO DE INSTRUMENTO EM RECURSO DE REVISTA. ACIDENTE DE TRABALHO COM ÓBITO. MOTORISTA DECAMINHÃOGRANELEIRO. CHOQUEELÉTRICO. CONTATO DO TUBO DE DESCARREGAMENTO COM FIAÇÃOELÉTRICASEM ISOLAMENTO, NA SEDE DE TERCEIRA EMPRESA. HIPÓTESE EM QUE O TRT CONCLUI PELA CULPA EXCLUSIVA DO TRABALHADOR, A DESPEITO DE REGISTRAR QUE A PERÍCIA REALIZADA PELO MPT CONSTATOU "A AUSÊNCIA DA PROVA ACERCA DA CAPACITAÇÃO DA VÍTIMA PARA OPERAR OS EQUIPAMENTOS". CULPA CONCORRENTE CARACTERIZADA. TRANSCENDÊNCIA DA CAUSA RECONHECIDA. Ante as razões apresentadas pela agravante, afasta-se o óbice oposto na decisão agravada. Agravo conhecido e provido. II - AGRAVO DE INSTRUMENTO EM RECURSO DE REVISTA DOS RECLAMANTES. ACIDENTE DE TRABALHO COM ÓBITO. MOTORISTA DECAMINHÃOGRANELEIRO. CHOQUEELÉTRICO. CONTATO DO TUBO DE DESCARREGAMENTO COM FIAÇÃOELÉTRICASEM ISOLAMENTO, NA SEDE DE TERCEIRA EMPRESA. HIPÓTESE EM QUE O TRT CONCLUI PELA CULPA EXCLUSIVA DO TRABALHADOR, A DESPEITO DE REGISTRAR QUE A PERÍCIA REALIZADA PELO MPT CONSTATOU "A AUSÊNCIA DA PROVA ACERCA DA CAPACITAÇÃO DA VÍTIMA PARA OPERAR OS EQUIPAMENTOS". CULPA CONCORRENTE CARACTERIZADA. Aparente violação dos artigos 186 e 927 do Código Civil, a ensejar o provimento do agravo de instrumento. Agravo de instrumento conhecido e provido. III - RECURSO DE REVISTA DOS RECLAMANTES. ACIDENTE DE TRABALHO COM ÓBITO. MOTORISTA DECAMINHÃOGRANELEIRO. CHOQUEELÉTRICO. CONTATO DO TUBO DE DESCARREGAMENTO COM FIAÇÃOELÉTRICASEM ISOLAMENTO, NA SEDE DE TERCEIRA EMPRESA. HIPÓTESE EM QUE O TRT CONCLUI PELA CULPA EXCLUSIVA DO TRABALHADOR, A DESPEITO DE REGISTRAR QUE A PERÍCIA REALIZADA PELO MPT CONSTATOU "A AUSÊNCIA DA PROVA ACERCA DA CAPACITAÇÃO DA VÍTIMA PARA OPERAR OS EQUIPAMENTOS". CULPA CONCORRENTE CARACTERIZADA. Ainda que delineada a conduta negligente do de cujus -  que "não teve a atenção e o cuidado necessário para evitar que o tubo de descarregamento docaminhãopor ele conduzido tocasse na redeelétrica" - não há como se entender que o acidente ocorreu por fato exclusivo da vítima, mas sim, que caracterizada a culpa concorrente da empresa -  negligente em capacitar o trabalhador para operar com segurança os equipamentos.  Recurso de revista conhecido e provido.', '', 'LexML', 'transport_energy', '', '', 'I - AGRAVO DOS RECLAMANTES. AGRAVO DE INSTRUMENTO EM RECURSO DE REVISTA. ACIDENTE DE TRABALHO COM ÓBITO. MOTORISTA DECAMINHÃOGRANELEIRO. CHOQUEELÉTRICO. CONTATO DO TUBO DE DESCARREGAMENTO COM FIAÇÃOELÉTRICASEM ISOLAMENTO, NA SEDE DE TERCEIRA EMPRESA. HIPÓTESE EM QUE O TRT CONCLUI PELA CULPA EXCLUSIVA DO TRABALHADOR, A DESPEITO DE REGISTRAR QUE A PERÍCIA REALIZADA PELO MPT CONSTATOU "A AUSÊNCIA DA PROVA ACERCA DA CAPACITAÇÃO DA VÍTIMA PARA OPERAR OS EQUIPAMENTOS". CULPA CONCORRENTE CARACTERIZADA. TRANSCENDÊNCIA DA CAUSA RECONHECIDA. Ante as razões apresentadas pela agravante, afasta-se o óbice oposto na decisão agravada. Agravo conhecido e provido. II - AGRAVO DE INSTRUMENTO EM RECURSO DE REVISTA DOS RECLAMANTES. ACIDENTE DE TRABALHO COM ÓBITO. MOTORISTA DECAMINHÃOGRANELEIRO. CHOQUEELÉTRICO. CONTATO DO TUBO DE DESCARREGAMENTO COM FIAÇÃOELÉTRICASEM ISOLAMENTO, NA SEDE DE TERCEIRA EMPRESA. HIPÓTESE EM QUE O TRT CONCLUI PELA CULPA EXCLUSIVA DO TRABALHADOR, A DESPEITO DE REGISTRAR QUE A PERÍCIA REALIZADA PELO MPT CONSTATOU "A AUSÊNCIA DA PROVA ACERCA DA CAPACITAÇÃO DA VÍTIMA PARA OPERAR OS EQUIPAMENTOS". CULPA CONCORRENTE CARACTERIZADA. Aparente violação dos artigos 186 e 927 do Código Civil, a ensejar o provimento do agravo de instrumento. Agravo de instrumento conhecido e provido. III - RECURSO DE REVISTA DOS RECLAMANTES. ACIDENTE DE TRABALHO COM ÓBITO. MOTORISTA DECAMINHÃOGRANELEIRO. CHOQUEELÉTRICO. CONTATO DO TUBO DE DESCARREGAMENTO COM FIAÇÃOELÉTRICASEM ISOLAMENTO, NA SEDE DE TERCEIRA EMPRESA. HIPÓTESE EM QUE O TRT CONCLUI PELA CULPA EXCLUSIVA DO TRABALHADOR, A DESPEITO DE REGISTRAR QUE A PERÍCIA REALIZADA PELO MPT CONSTATOU "A AUSÊNCIA DA PROVA ACERCA DA CAPACITAÇÃO DA VÍTIMA PARA OPERAR OS EQUIPAMENTOS". CULPA CONCORRENTE CARACTERIZADA. Ainda que delineada a conduta negligente do de cujus -  que "não teve a atenção e o cuidado necessário para evitar que o tubo de descarregamento docaminhãopor ele conduzido tocasse na redeelétrica" - não há como se entender que o acidente ocorreu por fato exclusivo da vítima, mas sim, que caracterizada a culpa concorrente da empresa -  negligente em capacitar o trabalhador para operar com segurança os equipamentos.  Recurso de revista conhecido e provido.', '', 'Tribunal Superior do Trabalho. 1ª Turma', 'Federal', 'Tribunal', '{"search_term": "", "urn_type": "other", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:tribunal.superior.trabalho;turma.5:acordao;rr:2007-09-26;14700-2003-103-3-0', 'Acórdão do processo Nº RR - 14700-52.2003.5.03.0103', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.5:acordao;rr:2007-09-26;14700-2003-103-3-0', '2007-09-26', '', '', 'outro', 'ADICIONAL DE PERICULOSIDADE. SISTEMAELÉTRICODE POTÊNCIA.CAMINHÃO¿MUCK¿. EXPOSIÇÃO A RISCO PRÓXIMO A TENSÃO DE 3.800V. Empregado que operacaminhãomuck equipado com cesto aéreo expõe-se a eletricidade ante o risco de queda de cabo eletrificado sobre ocaminhãoenquanto opera o braço levantador por ocasião de substituição de lâmpadas de iluminação pública. Acórdão regional em harmonia com a jurisprudência desta Corte concentrada na Orientação Jurisprudencial 324 da SBDI-1. Recurso de Revista de que não se conhece.', '', 'LexML', 'transport_energy', '', '', 'ADICIONAL DE PERICULOSIDADE. SISTEMAELÉTRICODE POTÊNCIA.CAMINHÃO¿MUCK¿. EXPOSIÇÃO A RISCO PRÓXIMO A TENSÃO DE 3.800V. Empregado que operacaminhãomuck equipado com cesto aéreo expõe-se a eletricidade ante o risco de queda de cabo eletrificado sobre ocaminhãoenquanto opera o braço levantador por ocasião de substituição de lâmpadas de iluminação pública. Acórdão regional em harmonia com a jurisprudência desta Corte concentrada na Orientação Jurisprudencial 324 da SBDI-1. Recurso de Revista de que não se conhece.', '', 'Tribunal Superior do Trabalho. 5ª Turma', 'Federal', 'Tribunal', '{"search_term": "", "urn_type": "other", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br;distrito.federal:tribunal.justica.distrito.federal.territorios;turma.civel.1:acordao:2012-10-24;632327', 'Acórdão nº 632327 do Processo nº20110110752552apc', 'https://www.lexml.gov.br/urn/urn:lex:br;distrito.federal:tribunal.justica.distrito.federal.territorios;turma.civel.1:acordao:2012-10-24;632327', '2012-10-24', 'DF', '', 'jurisprudencia', 'APELAÇÃO CÍVEL. RESPONSABILIDADE CIVIL. AÇÃO DE REPARAÇÃO DE DANOS MATERIAIS. ACIDENTE DE VEÍCULO. DERRUBADA DE POSTES DE ENERGIAELÉTRICA. PREJUÍZOS PARA O CONDOMÍNIO. PRELIMINAR DE ILEGITIMIDADE PASSIVA. RESPONSABILIDADE SOLIDÁRIA. ARTIGO 932, INCISO III, DO CÓDIGO CIVIL. ÔNUS DA PROVA. VALOR DA CONDENAÇÃO. NOTA FISCAL. CORREÇÃO MONETÁRIA. JUROS LEGAIS DE MORA. SENTENÇA MANTIDA.
1. NOS TERMOS DO ARTIGO 932, INCISO III, DO CÓDIGO CIVIL, "SÃO TAMBÉM RESPONSÁVEIS PELA REPARAÇÃO CIVIL: (...) O EMPREGADOR OU COMITENTE, POR SEUS EMPREGADOS, SERVIÇAIS E PREPOSTOS, NO EXERCÍCIO DO TRABALHO QUE LHES COMPETIR, OU EM RAZÃO DELE".
2. CONSTATADA A PERTINÊNCIA SUBJETIVA DA RELAÇÃO DE DIREITO MATERIAL ENTRE AS PARTES, REJEITA-SE A PRELIMINAR DE ILEGITIMIDADE PASSIVA.
3. PARA QUE SEJA CARACTERIZADA A RESPONSABILIDADE CIVIL POR ATO ILÍCITO SE FAZ NECESSÁRIA A PRESENÇA DO DANO, DA CONDUTA E DO NEXO DE CAUSALIDADE ENTRE A CONDUTA E O DANO, CONFORME DISPÕE O ARTIGO 927 DO CÓDIGO CIVIL.
4. NÃO LOGRANDO ÊXITO OS RÉUS/RECORRENTES EM DEMONSTRAR QUE A CULPA DO AUTOR FOI EXCLUSIVA OU CONCORRENTE COM A DELES, NÃO HÁ QUE SE FALAR EM IMPROCEDÊNCIA DOS PEDIDOS DO AUTOR (ARTIGO 333, INCISO II, DO CÓDIGO DE PROCESSO CIVIL).
5. NÃO APRESENTADAS RAZÕES PARA DESCONSTITUIR A IDONEIDADE DA NOTA FISCAL COLACIONADA, O VALOR NELA CONSTANTE SERVE COMO FUNDAMENTO PARA CONDENAÇÃO EM DECORRÊNCIA DE DANOS MATERIAIS.
6. EM RELAÇÃO AO DANO MATERIAL, A CORREÇÃO MONETÁRIA E OS JUROS DE MORA DEVEM INCIDIR A PARTIR DO EVENTO DANOSO, CONFORME DISPÕE OS ENUNCIADOS 43 E 54 DA SÚMULA DO STJ.
7. A INCIDÊNCIA DE CORREÇÃO MONETÁRIA A PARTIR DA SENTENÇA TEM LUGAR APENAS PARA O DANO MORAL (ENUNCIADO 362 DA SÚMULA DO STJ).
8. RECURSO CONHECIDO, REJEITADA A PRELIMINAR DE ILEGITIMIDADE PASSIVA E, NO MÉRITO, NEGADO PROVIMENTO. | Assuntos: CONFIRMAÇÃO, INDENIZAÇÃO, DANO MATERIAL, CONDOMÍNIO, AÇÃO, RESSARCIMENTO DE DANOS, DECORRÊNCIA, COLISÃO,CAMINHÃO, INOCORRÊNCIA, PROVA, CULPA EXCLUSIVA, CONCORRENTE, AUTOR. IMPROCEDÊNCIA, REDUÇÃO, VALOR, CONDENAÇÃO, EXISTÊNCIA, NOTA FISCAL, COMPROVAÇÃO, PRESTAÇÃO DE SERVIÇO, REPARAÇÃO, PREJUÍZO, INOCORRÊNCIA, APRESENTAÇÃO, RÉU, DIVERSIDADE, ORÇAMENTO, DEMONSTRAÇÃO, ABUSIVIDADE, VALOR, OBSERVÂNCIA, JURISPRUDÊNCIA, TJDFT. CONFIRMAÇÃO, TERMO INICIAL, INCIDÊNCIA, JUROS, CORREÇÃO MONETÁRIA, DATA, FATO.', '', 'LexML', 'transport_energy', 'Acórdão', '', 'APELAÇÃO CÍVEL. RESPONSABILIDADE CIVIL. AÇÃO DE REPARAÇÃO DE DANOS MATERIAIS. ACIDENTE DE VEÍCULO. DERRUBADA DE POSTES DE ENERGIAELÉTRICA. PREJUÍZOS PARA O CONDOMÍNIO. PRELIMINAR DE ILEGITIMIDADE PASSIVA. RESPONSABILIDADE SOLIDÁRIA. ARTIGO 932, INCISO III, DO CÓDIGO CIVIL. ÔNUS DA PROVA. VALOR DA CONDENAÇÃO. NOTA FISCAL. CORREÇÃO MONETÁRIA. JUROS LEGAIS DE MORA. SENTENÇA MANTIDA.
