INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:tribunal.superior.trabalho;turma.7:acordao;rr:2022-02-23;1003291-2013-467-2-0', 'Acórdão do processo Nº RR - 1003291-15.2013.5.02.0467', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.7:acordao;rr:2022-02-23;1003291-2013-467-2-0', '2022-02-23', '', '', 'outro', 'AGRAVO DE INSTRUMENTO EM RECURSO DE REVISTA. LEI Nº 13.015/2014. CPC/2015. INSTRUÇÃO NORMATIVA Nº 40 DO TST. ADICIONAL DE PERICULOSIDADE. MOTORISTA DEÔNIBUSELÉTRICO(TRÓLEBUS). ORIENTAÇÃO JURISPRUDENCIAL Nº 324 DA SBDI-1 DESTA CORTE SUPERIOR. Agravo de instrumento provido para determinar o processamento do recurso de revista, em face de haver sido demonstrada possível contrariedade à Orientação Jurisprudencial nº 324 da SBDI-1 do TST. RECURSO DE REVISTA. LEI Nº 13.015/2014. CPC/2015. INSTRUÇÃO NORMATIVA Nº 40 DO TST. ADICIONAL DE PERICULOSIDADE. MOTORISTA DEÔNIBUSELÉTRICO(TRÓLEBUS). ORIENTAÇÃO JURISPRUDENCIAL Nº 324 DA SBDI-1 DESTA CORTE SUPERIOR. O empregado que exerce suas atividades em contato habitual com sistema de geração de energiaelétricaencontra-se exposto a condições perigosas, de acordo com o item 4 do Anexo do Decreto nº 93.412/86, que regulamenta a Lei nº 7.369/95 e faz jus ao pagamento de adicional de periculosidade, sendo irrelevante o fato de o trabalho ter sido exercido ou não em sistemaelétricode potência; basta a caracterização do labor em área de risco, de forma intermitente e habitual, consoante legislação supra citada. Consta do acórdão regional que "o reclamante era motorista deônibuselétrico(trólebus), tendo que efetuar reengates na redeelétricae restart doônibusjunto à caixa de força". Estabelecida pelo Tribunal Regional a premissa fática de que o autor se expunha a condições de risco, conclui-se que a decisão recorrida possivelmente contraria a Orientação Jurisprudencial nº 324 da SBDI-I desta Corte. Recurso de revista conhecido e provido.', '', 'LexML', 'transport_energy', '', '', 'AGRAVO DE INSTRUMENTO EM RECURSO DE REVISTA. LEI Nº 13.015/2014. CPC/2015. INSTRUÇÃO NORMATIVA Nº 40 DO TST. ADICIONAL DE PERICULOSIDADE. MOTORISTA DEÔNIBUSELÉTRICO(TRÓLEBUS). ORIENTAÇÃO JURISPRUDENCIAL Nº 324 DA SBDI-1 DESTA CORTE SUPERIOR. Agravo de instrumento provido para determinar o processamento do recurso de revista, em face de haver sido demonstrada possível contrariedade à Orientação Jurisprudencial nº 324 da SBDI-1 do TST. RECURSO DE REVISTA. LEI Nº 13.015/2014. CPC/2015. INSTRUÇÃO NORMATIVA Nº 40 DO TST. ADICIONAL DE PERICULOSIDADE. MOTORISTA DEÔNIBUSELÉTRICO(TRÓLEBUS). ORIENTAÇÃO JURISPRUDENCIAL Nº 324 DA SBDI-1 DESTA CORTE SUPERIOR. O empregado que exerce suas atividades em contato habitual com sistema de geração de energiaelétricaencontra-se exposto a condições perigosas, de acordo com o item 4 do Anexo do Decreto nº 93.412/86, que regulamenta a Lei nº 7.369/95 e faz jus ao pagamento de adicional de periculosidade, sendo irrelevante o fato de o trabalho ter sido exercido ou não em sistemaelétricode potência; basta a caracterização do labor em área de risco, de forma intermitente e habitual, consoante legislação supra citada. Consta do acórdão regional que "o reclamante era motorista deônibuselétrico(trólebus), tendo que efetuar reengates na redeelétricae restart doônibusjunto à caixa de força". Estabelecida pelo Tribunal Regional a premissa fática de que o autor se expunha a condições de risco, conclui-se que a decisão recorrida possivelmente contraria a Orientação Jurisprudencial nº 324 da SBDI-I desta Corte. Recurso de revista conhecido e provido.', '', 'Tribunal Superior do Trabalho. 7ª Turma', 'Federal', 'Tribunal', '{"search_term": "", "urn_type": "other", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br;sao.paulo;hortolandia:municipal:lei:2024-07-25;4328', 'Lei n° 4328,  de 25 de julho de 2024', 'https://www.lexml.gov.br/urn/urn:lex:br;sao.paulo;hortolandia:municipal:lei:2024-07-25;4328', '2024-07-25', 'SP', 'Hortolândia', 'lei', 'Autoriza o Poder Executivo a contratar operação de crédito com a Caixa Econômica Federal, com a garantia da União e dá outras providências. | Assuntos: Caixa Econômica Federal, PAC, aceleração crescimento, renovação e Eletrificação Parcial da Frota de Transporte Público Municipal,ônibuselétricos', '', 'LexML', 'transport_energy', 'Lei', '', 'Autoriza o Poder Executivo a contratar operação de crédito com a Caixa Econômica Federal, com a garantia da União e dá outras providências. | Assuntos: Caixa Econômica Federal, PAC, aceleração crescimento, renovação e Eletrificação Parcial da Frota de Transporte Público Municipal,ônibuselétricos', '', 'Municipal', '', 'Outros', '{"search_term": "", "urn_type": "legislation", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.3:acordao:2004-03-10;00278-2003-044-03-00-6', 'Acórdão TRT 3ª / Terceira Turma / 2004-03-10', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.3:acordao:2004-03-10;00278-2003-044-03-00-6', '2004-03-10', '', '3ª Região - Minas Gerais', 'jurisprudencia', 'ADICIONAL DE PERICULOSIDADE.  DESCARACTERIZAÇÃO. O perito informa  que o A.  era eletricista de autos,  fazendo manutençãoelétricadosônibusda frota da empresa,  incluindo montagens,  limpadores  de pára-brisa,  baterias,  lubrificação, testes,  etc.  E também,  eletricista  industrial  e  predial,  com montagem  e  manutenção  corretiva  e  preventiva de  máquinas,  equipamentos,  motores  e  instalações,  de  alta e baixa tensão,  ajustando,  reparando  ou  substituindo peças, fazendo testes em máquinas e motores, reparos  e   substituições  de  lâmpadas,   tomadas,   fios,   painéis   e  interruptores.  Trabalhava,  como é óbvio,  então,  no sistema de  energia fornecido pela Cemig,  que,  na empresa Ré,  era de 220v.  Havendo, inclusive, fotos das prosaicas bancadas onde o labor era  desenvolvido.  Após  tecer  considerações  teóricas sobre  sistemaelétricode  potência  e  áreas  de risco,  o  perito  amplia  tais  conceitos  praticamente  ao infinito,  ao concluir que qualquer  pessoa  que  atue  mesmo  na  ponta final do consumo de energia,  que  são  as  residências  e escritórios,  acha-se em contato com uma  fase  do  chamado SEP. Conclusão acatada pelo d. Juízo.  O que,  no entanto,  não vejo como sendo a vontade do legislador,  nem a "mens legis",  que se dirige ao risco acentuado dos que são  obrigados,  por  força  das exigências profissionais,  a  viverem  cercados pelo risco de atuarem no contato direto com a energia em  seu grau mais exposto e menos domesticado.  Não alcançando os que  vivem  nos  imóveis onde ela já chega minimizada e  mais  domada,  através  de  sistemas  seguros  -  não  completamente,  o  que  é  inviável,  mas  o  suficiente para propiciar  uma  convivência  e  utilização diária dentro dos limites e normas gerais de segurança  pelos  usuários  e  técnicos  de  instalações  domésticas  e   de  eletrodomésticos.  Para mim, esse é o caso presente.  Afasto a caracterização de periculosidade. | Assuntos: ADICIONAL DE PERICULOSIDADE - ENERGIAELÉTRICA', '', 'LexML', 'transport_energy', 'Acórdão', '', 'ADICIONAL DE PERICULOSIDADE.  DESCARACTERIZAÇÃO. O perito informa  que o A.  era eletricista de autos,  fazendo manutençãoelétricadosônibusda frota da empresa,  incluindo montagens,  limpadores  de pára-brisa,  baterias,  lubrificação, testes,  etc.  E também,  eletricista  industrial  e  predial,  com montagem  e  manutenção  corretiva  e  preventiva de  máquinas,  equipamentos,  motores  e  instalações,  de  alta e baixa tensão,  ajustando,  reparando  ou  substituindo peças, fazendo testes em máquinas e motores, reparos  e   substituições  de  lâmpadas,   tomadas,   fios,   painéis   e  interruptores.  Trabalhava,  como é óbvio,  então,  no sistema de  energia fornecido pela Cemig,  que,  na empresa Ré,  era de 220v.  Havendo, inclusive, fotos das prosaicas bancadas onde o labor era  desenvolvido.  Após  tecer  considerações  teóricas sobre  sistemaelétricode  potência  e  áreas  de risco,  o  perito  amplia  tais  conceitos  praticamente  ao infinito,  ao concluir que qualquer  pessoa  que  atue  mesmo  na  ponta final do consumo de energia,  que  são  as  residências  e escritórios,  acha-se em contato com uma  fase  do  chamado SEP. Conclusão acatada pelo d. Juízo.  O que,  no entanto,  não vejo como sendo a vontade do legislador,  nem a "mens legis",  que se dirige ao risco acentuado dos que são  obrigados,  por  força  das exigências profissionais,  a  viverem  cercados pelo risco de atuarem no contato direto com a energia em  seu grau mais exposto e menos domesticado.  Não alcançando os que  vivem  nos  imóveis onde ela já chega minimizada e  mais  domada,  através  de  sistemas  seguros  -  não  completamente,  o  que  é  inviável,  mas  o  suficiente para propiciar  uma  convivência  e  utilização diária dentro dos limites e normas gerais de segurança  pelos  usuários  e  técnicos  de  instalações  domésticas  e   de  eletrodomésticos.  Para mim, esse é o caso presente.  Afasto a caracterização de periculosidade. | Assuntos: ADICIONAL DE PERICULOSIDADE - ENERGIAELÉTRICA', '', 'Tribunal Regional do Trabalho. 3ª Turma', '', 'Tribunal', '{"search_term": "", "urn_type": "jurisprudence", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
