INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br;santa.catarina:estadual:lei:2000-01-17;11347', 'Lei nº 11.347, de 17 de janeiro de 2000', 'https://www.lexml.gov.br/urn/urn:lex:br;santa.catarina:estadual:lei:2000-01-17;11347', '2000-01-17', 'Santa Catarina', '', 'lei', 'Dispõe sobre a coleta, o recolhimento e o destino final de resíduos sólidos potencialmente perigosos que menciona, e adota outras providências.
As pilhas,bateriase lâmpadas, identificadas no art. 3º desta Lei, após seu uso ou esgotamento energético, são consideradas resíduos potencialmente perigosos à saúde e ao meio ambiente, devendo a sua coleta, seu recolhimento e seu destino final, observar o estabelecido nesta Lei. | Assuntos: baterias', '', 'LexML', 'transport_energy', 'Lei', '', 'Dispõe sobre a coleta, o recolhimento e o destino final de resíduos sólidos potencialmente perigosos que menciona, e adota outras providências.
As pilhas,bateriase lâmpadas, identificadas no art. 3º desta Lei, após seu uso ou esgotamento energético, são consideradas resíduos potencialmente perigosos à saúde e ao meio ambiente, devendo a sua coleta, seu recolhimento e seu destino final, observar o estabelecido nesta Lei. | Assuntos: baterias', '', 'Estadual', '', 'Outros', '{"search_term": "", "urn_type": "legislation", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
