INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:federal:decreto:1994-05-30;seq-sf-6', 'Decreto  de 30/05/1994 ( seq-sf: 6 )', 'https://www.lexml.gov.br/urn/urn:lex:br:federal:decreto:1994-05-30;seq-sf-6', '1994-05-30', '', '', 'lei', 'DECLARA DE UTILIDADE PUBLICA, PARA FINS DE DESAPROPRIAÇÃO, EM FAVOR DA ELETROPAULO - ELETRICIDADE DE SÃO PAULO S.A., A AREA DE TERRA QUE MENCIONA. | Assuntos: DECLARAÇÃO ,  UTILIDADE PUBLICA ,  DESAPROPRIAÇÃO ,  TERRENO ,  ELETRICIDADE DE SÃO PAULO S/A (ELETROPAULO) ,  DESTINAÇÃO ,  INSTALAÇÃO ,  ESTAÇÃO ,  RADIO ,TELEMETRIA,  MUNICIPIO ,  ITAPECERICA DA SERRA (SP) ,  ESTADO DE SÃO PAULO (SP) .', '', 'LexML', 'transport_energy', 'Decreto', '', 'DECLARA DE UTILIDADE PUBLICA, PARA FINS DE DESAPROPRIAÇÃO, EM FAVOR DA ELETROPAULO - ELETRICIDADE DE SÃO PAULO S.A., A AREA DE TERRA QUE MENCIONA. | Assuntos: DECLARAÇÃO ,  UTILIDADE PUBLICA ,  DESAPROPRIAÇÃO ,  TERRENO ,  ELETRICIDADE DE SÃO PAULO S/A (ELETROPAULO) ,  DESTINAÇÃO ,  INSTALAÇÃO ,  ESTAÇÃO ,  RADIO ,TELEMETRIA,  MUNICIPIO ,  ITAPECERICA DA SERRA (SP) ,  ESTADO DE SÃO PAULO (SP) .', '', 'Federal', 'Federal', 'Outros', '{"search_term": "", "urn_type": "legislation", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:camara.deputados:projeto.lei;pl:2013-10-01;6468', 'PL 6468/2013', 'https://www.lexml.gov.br/urn/urn:lex:br:camara.deputados:projeto.lei;pl:2013-10-01;6468', '2013-10-01', '', '', 'outro', 'Dispõe sobre a regulamentação das atividades de Gestão de Riscos Logísticos e Securitários, compreendendo o Gerenciamento de Riscos em Operações Logísticas e Securitárias, Tecnologia de Rastreamento, Monitoramento,Telemetriae Sistemas Eletrônicos de Prevenção a Perdas Patrimoniais.', '', 'LexML', 'transport_energy', '', '', 'Dispõe sobre a regulamentação das atividades de Gestão de Riscos Logísticos e Securitários, compreendendo o Gerenciamento de Riscos em Operações Logísticas e Securitárias, Tecnologia de Rastreamento, Monitoramento,Telemetriae Sistemas Eletrônicos de Prevenção a Perdas Patrimoniais.', '', 'Câmara dos Deputados', 'Federal', 'Outros', '{"search_term": "", "urn_type": "other", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Sprinklers em museus', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2020;1001202861', NULL, '', '', 'doutrina', 'Resumo:Apresenta gráfico e tabela sobre:telemetriade pressão do Bairro da Graça, registrada no dia 07/04/2019; comparativo entre as pressões e a vazões ofertadas pela rede pública e demandadas pelo sistema de SPK. | Assuntos: Prevenção de incêndio, Brasil. {Prevenção de incêndio; Incêndio, medida de segurança; Incêndio, prevenção} Museu, Salvador BA. {Museu; Galerias e museus}', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PRIVADO - 342::DIREITO DO TRABALHO - 342.6::Acidentes do Trabalho - 342.61::Medidas preventivas dos acidentes de trabalho. Higiene e segurança do trabalho - 342.617', 'Resumo:Apresenta gráfico e tabela sobre:telemetriade pressão do Bairro da Graça, registrada no dia 07/04/2019; comparativo entre as pressões e a vazões ofertadas pela rede pública e demandadas pelo sistema de SPK. | Assuntos: Prevenção de incêndio, Brasil. {Prevenção de incêndio; Incêndio, medida de segurança; Incêndio, prevenção} Museu, Salvador BA. {Museu; Galerias e museus}', '', 'Almonfrey, Sávio', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:tribunal.superior.trabalho;turma.1:acordao;airr:2011-11-09;45300-2009-203-4-0', 'Acórdão do processo Nº AIRR - 45300-10.2009.5.04.0203', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.1:acordao;airr:2011-11-09;45300-2009-203-4-0', '2011-11-09', '', '', 'outro', 'RESPONSABILIDADE SOLIDÁRIA OU SUBSIDIÁRIA. CONTRATO DE EMPREITADA. DONO DA OBRA. IMPOSSIBILIDADE. CONSTRUÇÃO CIVIL. EXECUÇÃO DE SERVIÇOS DE ENCANADOR NA OBRA DE REFORMA E INSTALAÇÃO COMPLEMENTAR DETELEMETRIANOS TANQUES DO TERMINAL DE CANOAS. 1. Nos termos da nova redação conferida pelo Tribunal Pleno desta Corte superior à Orientação Jurisprudencial n.º 191 da SBDI-I, "Diante da inexistência de previsão legal específica, o contrato de empreitada de construção civil entre o dono da obra e o empreiteiro não enseja responsabilidade solidária ou subsidiária nas obrigações trabalhistas contraídas pelo empreiteiro, salvo sendo o dono da obra uma empresa construtora ou incorporadora". 2. Constatando-se que o egrégio Tribunal Regional consignou expressamente que o obreiro laborou nos "serviços de encanador, em obra contratada pela 2ª ré, Petrobras Distribuidora S.A., de reforma e instalação complementar detelemetrianos tanques do terminal de Canoas- TENOAS", conclui-se que a segunda reclamada atuou como verdadeira dona da obra, visto que os serviços desenvolvidos pelo obreiro em seu favor inserem-se no conceito técnico de construção civil. 3. Agravo de instrumento não provido. RESPONSABILIDADE CIVIL. DANO MORAL. INDENIZAÇÃO. MAJORAÇÃO. RECURSO DE REVISTA. AUSÊNCIA DE FUNDAMENTAÇÃO. Não cuidando a parte de dar a seu inconformismo o devido enquadramento legal, mediante a alegação de afronta a dispositivos de lei ou da Constituição da República ou de contrariedade a súmula deste Tribunal Superior ou, ainda, transcrevendo paradigmas à hipótese dos autos, resulta manifesta a impossibilidade de conhecimento do recurso de revista por ausência de fundamentação. Agravo de instrumento não provido.', '', 'LexML', 'transport_energy', '', '', 'RESPONSABILIDADE SOLIDÁRIA OU SUBSIDIÁRIA. CONTRATO DE EMPREITADA. DONO DA OBRA. IMPOSSIBILIDADE. CONSTRUÇÃO CIVIL. EXECUÇÃO DE SERVIÇOS DE ENCANADOR NA OBRA DE REFORMA E INSTALAÇÃO COMPLEMENTAR DETELEMETRIANOS TANQUES DO TERMINAL DE CANOAS. 1. Nos termos da nova redação conferida pelo Tribunal Pleno desta Corte superior à Orientação Jurisprudencial n.º 191 da SBDI-I, "Diante da inexistência de previsão legal específica, o contrato de empreitada de construção civil entre o dono da obra e o empreiteiro não enseja responsabilidade solidária ou subsidiária nas obrigações trabalhistas contraídas pelo empreiteiro, salvo sendo o dono da obra uma empresa construtora ou incorporadora". 2. Constatando-se que o egrégio Tribunal Regional consignou expressamente que o obreiro laborou nos "serviços de encanador, em obra contratada pela 2ª ré, Petrobras Distribuidora S.A., de reforma e instalação complementar detelemetrianos tanques do terminal de Canoas- TENOAS", conclui-se que a segunda reclamada atuou como verdadeira dona da obra, visto que os serviços desenvolvidos pelo obreiro em seu favor inserem-se no conceito técnico de construção civil. 3. Agravo de instrumento não provido. RESPONSABILIDADE CIVIL. DANO MORAL. INDENIZAÇÃO. MAJORAÇÃO. RECURSO DE REVISTA. AUSÊNCIA DE FUNDAMENTAÇÃO. Não cuidando a parte de dar a seu inconformismo o devido enquadramento legal, mediante a alegação de afronta a dispositivos de lei ou da Constituição da República ou de contrariedade a súmula deste Tribunal Superior ou, ainda, transcrevendo paradigmas à hipótese dos autos, resulta manifesta a impossibilidade de conhecimento do recurso de revista por ausência de fundamentação. Agravo de instrumento não provido.', '', 'Tribunal Superior do Trabalho. 1ª Turma', 'Federal', 'Tribunal', '{"search_term": "", "urn_type": "other", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.1:acordao:2012-07-02;0001431-73.2011.5.03.0067', 'Acórdão TRT 3ª / Primeira Turma / 2012-07-02', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.1:acordao:2012-07-02;0001431-73.2011.5.03.0067', '2012-07-02', '', '3ª Região - Minas Gerais', 'jurisprudencia', 'EMENTA: ENQUADRAMENTO SINDICAL DE EMPREGADO. Em regra, o enquadramento sindical do empregado é determinado pela atividade preponderante da empresa, de forma que, desenvolvendo a empregadora atividade de prestação de serviços de telecomunicações etelemetria, não lhe será aplicável norma coletiva celebrada pelo Sindicato das Empresas de Asseio e Conservação do Estado de Minas Gerais.', '', 'LexML', 'transport_energy', 'Acórdão', '', 'EMENTA: ENQUADRAMENTO SINDICAL DE EMPREGADO. Em regra, o enquadramento sindical do empregado é determinado pela atividade preponderante da empresa, de forma que, desenvolvendo a empregadora atividade de prestação de serviços de telecomunicações etelemetria, não lhe será aplicável norma coletiva celebrada pelo Sindicato das Empresas de Asseio e Conservação do Estado de Minas Gerais.', '', 'Tribunal Regional do Trabalho. 1ª Turma', '', 'Tribunal', '{"search_term": "", "urn_type": "jurisprudence", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.9:acordao:2011-08-10;0000803-62.2010.5.03.0021', 'Acórdão TRT 3ª / Nona Turma / 2011-08-10', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.9:acordao:2011-08-10;0000803-62.2010.5.03.0021', '2011-08-10', '', '3ª Região - Minas Gerais', 'jurisprudencia', 'EMENTA: TERCEIRIZAÇÃO - SERVIÇOS DE TELEFONIA - ATIVIDADE-FIM - ILICITUDE. Contrariamente às alegações contidas na contestação da recorrente, onde alega a existência de um contrato comercial de revenda de mercadorias, ela própria juntou aos autos o "contrato de prestação de serviços", que outorga à 1ª reclamada a condição de agente autorizado, remunerada à base de comissão por cada contrato por ela firmado, relativamente à ativação de novas linhas telefônicas por novos clientes, inclusive clientes corporativos, com potencial superior a 100 (cem) linhas de telefonia móvel (cláusula 4.1), associações cooperativas (cláusula 7) e órgãos públicos (cláusulas 7.2 e 7.3), serviços detelemetriae rastreamento (cláusula 8.1), serviços de linhas específicas de planos de dados (cláusula 8.2) e módulos de dados individuais (cláusula 8.3), com reserva de mercado para a recorrente em relação aos processos licitatórios para serviços de telecomunicações (cláusula 7.3.1). Os serviços definidos nas cláusulas do contrato de prestação de serviços celebrado entre as reclamadas se amoldam à definição de serviços de telecomunicações ditada pelo artigo 60 da Lei nº 9.472, de 1997. O artigo 94 da mesma lei só autoriza a terceirização da atividade-meio na área das telecomunicações, não autorizando a terceirização da atividade-fim, na forma da interpretação ditada pela Súmula nº 331, item III, do TST. | Assuntos: TERCEIRIZAÇÃO - SERVIÇO DE TELECOMUNICAÇÃO', '', 'LexML', 'transport_energy', 'Acórdão', '', 'EMENTA: TERCEIRIZAÇÃO - SERVIÇOS DE TELEFONIA - ATIVIDADE-FIM - ILICITUDE. Contrariamente às alegações contidas na contestação da recorrente, onde alega a existência de um contrato comercial de revenda de mercadorias, ela própria juntou aos autos o "contrato de prestação de serviços", que outorga à 1ª reclamada a condição de agente autorizado, remunerada à base de comissão por cada contrato por ela firmado, relativamente à ativação de novas linhas telefônicas por novos clientes, inclusive clientes corporativos, com potencial superior a 100 (cem) linhas de telefonia móvel (cláusula 4.1), associações cooperativas (cláusula 7) e órgãos públicos (cláusulas 7.2 e 7.3), serviços detelemetriae rastreamento (cláusula 8.1), serviços de linhas específicas de planos de dados (cláusula 8.2) e módulos de dados individuais (cláusula 8.3), com reserva de mercado para a recorrente em relação aos processos licitatórios para serviços de telecomunicações (cláusula 7.3.1). Os serviços definidos nas cláusulas do contrato de prestação de serviços celebrado entre as reclamadas se amoldam à definição de serviços de telecomunicações ditada pelo artigo 60 da Lei nº 9.472, de 1997. O artigo 94 da mesma lei só autoriza a terceirização da atividade-meio na área das telecomunicações, não autorizando a terceirização da atividade-fim, na forma da interpretação ditada pela Súmula nº 331, item III, do TST. | Assuntos: TERCEIRIZAÇÃO - SERVIÇO DE TELECOMUNICAÇÃO', '', 'Tribunal Regional do Trabalho. 9ª Turma', '', 'Tribunal', '{"search_term": "", "urn_type": "jurisprudence", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:tribunal.superior.trabalho;turma.3:acordao;ag:2023-12-13;1000616-2022-63-2-0', 'Acórdão do processo Nº Ag-AIRR - 1000616-15.2022.5.02.0063', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.3:acordao;ag:2023-12-13;1000616-2022-63-2-0', '2023-12-13', '', '', 'outro', 'AGRAVO. AGRAVO DE INSTRUMENTO EM RECURSO DE REVISTA.   1) PRESCRIÇÃO QUINQUENAL TOTAL. AJUIZAMENTO DE AÇÃO APÓS 5 ANOS DO PROTESTO INTERRUPTIVO. 2) BANCÁRIA. EXERCÍCIO DA FUNÇÃO DE CONFIANÇA DE QUE TRATA O ARTIGO 224, § 2º, DA CLT. COMPROVAÇÃO DA FIDÚCIA ESPECIAL. HORAS EXTRAS INDEVIDAS. 3) TRABALHO AOS DOMINGOS NÃO COMPROVADO. HORAS EXTRAS INDEVIDAS. Não merece provimento o agravo, pois não desconstitui os fundamentos da decisão monocrática pela qual foi negado provimento ao agravo de instrumento, fundada na aplicação dos entendimentos de que: a) em relação ao protesto interruptivo do prazo prescricional, adotou-se o entendimento de que a prescrição quinquenal deve ser contada do primeiro ato de interrupção, ou seja, da propositura da primeira ação trabalhista; b) quanto à caracterização do cargo de confiança, foi constatado pela Corte a quo que "a reclamante fazia análise de qualidade etelemetriade caixa eletrônico, fazia tratamento de ocorrências abertas pelos clientes no SAC, ouvidoria e órgão externos como Bacen e Procon, dando retorno para os clientes, tinha alçada para devolução de valores, não havia necessidade do superior validar as atividades desenvolvidas, bem como possuía certificação CPA10, pelo que se verifica que se tratam de responsabilidades e poderes estes que não são inerentes às atividades do bancário comum", aplicando-se o óbice da Súmula nº 126 do TST; e c) no que tange ao trabalho aos domingos, a decisão regional, examinando o quadro fático dos autos, concluiu que "a reclamante não indicou a existência de nenhum domingo trabalhado não quitado ou não compensado, de maneira que não há que se falar em pagamento de adicional de 100% para horas extras trabalhadas em domingos", aplicando-se o óbice da Súmula nº 126 do TST. Agravo desprovido.', '', 'LexML', 'transport_energy', '', '', 'AGRAVO. AGRAVO DE INSTRUMENTO EM RECURSO DE REVISTA.   1) PRESCRIÇÃO QUINQUENAL TOTAL. AJUIZAMENTO DE AÇÃO APÓS 5 ANOS DO PROTESTO INTERRUPTIVO. 2) BANCÁRIA. EXERCÍCIO DA FUNÇÃO DE CONFIANÇA DE QUE TRATA O ARTIGO 224, § 2º, DA CLT. COMPROVAÇÃO DA FIDÚCIA ESPECIAL. HORAS EXTRAS INDEVIDAS. 3) TRABALHO AOS DOMINGOS NÃO COMPROVADO. HORAS EXTRAS INDEVIDAS. Não merece provimento o agravo, pois não desconstitui os fundamentos da decisão monocrática pela qual foi negado provimento ao agravo de instrumento, fundada na aplicação dos entendimentos de que: a) em relação ao protesto interruptivo do prazo prescricional, adotou-se o entendimento de que a prescrição quinquenal deve ser contada do primeiro ato de interrupção, ou seja, da propositura da primeira ação trabalhista; b) quanto à caracterização do cargo de confiança, foi constatado pela Corte a quo que "a reclamante fazia análise de qualidade etelemetriade caixa eletrônico, fazia tratamento de ocorrências abertas pelos clientes no SAC, ouvidoria e órgão externos como Bacen e Procon, dando retorno para os clientes, tinha alçada para devolução de valores, não havia necessidade do superior validar as atividades desenvolvidas, bem como possuía certificação CPA10, pelo que se verifica que se tratam de responsabilidades e poderes estes que não são inerentes às atividades do bancário comum", aplicando-se o óbice da Súmula nº 126 do TST; e c) no que tange ao trabalho aos domingos, a decisão regional, examinando o quadro fático dos autos, concluiu que "a reclamante não indicou a existência de nenhum domingo trabalhado não quitado ou não compensado, de maneira que não há que se falar em pagamento de adicional de 100% para horas extras trabalhadas em domingos", aplicando-se o óbice da Súmula nº 126 do TST. Agravo desprovido.', '', 'Tribunal Superior do Trabalho. 3ª Turma', 'Federal', 'Tribunal', '{"search_term": "", "urn_type": "other", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:tribunal.superior.trabalho;turma.7:acordao;airr:2016-10-05;1196-2010-6-5-0', 'Acórdão do processo Nº AIRR - 1196-75.2010.5.05.0006', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.7:acordao;airr:2016-10-05;1196-2010-6-5-0', '2016-10-05', '', '', 'outro', 'AGRAVO DE INSTRUMENTO EM RECURSO DE REVISTA. NÃO REGIDO PELA LEI 13.015/2014. 1. HORAS EXTRAS. TRABALHO EXTERNO. O Tribunal Regional, com base no conjunto fático-probatório dos autos, concluiu que o Reclamante, embora realizasse trabalho externo, tinha a jornada de trabalho controlada pela Reclamada, pois o caminhão era equipado com sistema de monitoramento que possibilitava "o envio e recebimento de mensagens, localização dos veículos através de mapas digitalizados, envio de comandos e recebimento de alertas do veículo,telemetria, relatórios gerenciais e diversas outras funcionalidades que permitem ao cliente o completo gerenciamento da sua frota". Anotou, mais, que "se houvesse desvio de rota, o sistema o detectaria, sendo comunicado o motorista para retornar à rota", acrescentando que "o sistema era capaz até de desligar o veículo, e que o motorista não conseguiria fazê-lo antes de determinado horário". Consignou, também, com amparo na prova testemunhal, que o motorista era obrigado a fazer o registro das paradas curtas. Destacou, assim, que a jornada de trabalho do Autor era passível de controle pela Demandada. Nesse contexto, não prospera a alegação de violação do artigo 62, I, da CLT. A exceção nele prevista não depende apenas do exercício de trabalho externo, mas também da impossibilidade de controle de horário pelo empregador. Tendo o julgador solucionado o caso com fundamento nos fatos e nas provas efetivamente produzidas nos autos, conforme lhe permite o artigo 131 do CPC/73, e provado o fato constitutivo do direito às horas extras, não há falar em violação dos artigos 818 da CLT e 333, I, do CPC. Cumpre notar que para se chegar a conclusão diversa, tal como pretende a Reclamada, necessário seria o revolvimento dos fatos e provas dos autos, o que é vedado nesta fase recursal, a teor da Súmula 126 do TST. Arestos paradigmas amparados em premissas fáticas diversas e oriundos do próprio Regional prolator do acórdão não se prestam para o processamento da revista por divergência jurisprudencial. 2. JORNADA DE TRABALHO. INOBSERVÂNCIA DO ARTIGO 896 DA CLT. Hipótese em que a Reclamada, em seu agravo de instrumento, restringe-se a apontar que o seu recurso de revista merece ser processado, porquanto entende que restou comprovado pela prova testemunhal que o horário de trabalho do Reclamante era diverso daquele apontado na petição inicial. Ocorre que a Demandada não ampara o agravo de instrumento nas hipóteses descritas nas alíneas "a", "b" e "c" do art. 896 da CLT, circunstância que inviabiliza o processamento do recurso de revista. 3. MULTA DO ARTIGO 538, PARÁGRAFO ÚNICO, DO CPC/73. Confirmado que o acórdão embargado não continha nenhum dos vícios previstos nos artigos 897-A da CLT ou 535 do CPC/73, com o devido exame de todos os elementos suscitados nos embargos declaratórios opostos pela Reclamada, mostra-se cabível a aplicação da multa prevista no artigo 538, parágrafo único, do CPC/73. Agravo de instrumento não provido.', '', 'LexML', 'transport_energy', '', '', 'AGRAVO DE INSTRUMENTO EM RECURSO DE REVISTA. NÃO REGIDO PELA LEI 13.015/2014. 1. HORAS EXTRAS. TRABALHO EXTERNO. O Tribunal Regional, com base no conjunto fático-probatório dos autos, concluiu que o Reclamante, embora realizasse trabalho externo, tinha a jornada de trabalho controlada pela Reclamada, pois o caminhão era equipado com sistema de monitoramento que possibilitava "o envio e recebimento de mensagens, localização dos veículos através de mapas digitalizados, envio de comandos e recebimento de alertas do veículo,telemetria, relatórios gerenciais e diversas outras funcionalidades que permitem ao cliente o completo gerenciamento da sua frota". Anotou, mais, que "se houvesse desvio de rota, o sistema o detectaria, sendo comunicado o motorista para retornar à rota", acrescentando que "o sistema era capaz até de desligar o veículo, e que o motorista não conseguiria fazê-lo antes de determinado horário". Consignou, também, com amparo na prova testemunhal, que o motorista era obrigado a fazer o registro das paradas curtas. Destacou, assim, que a jornada de trabalho do Autor era passível de controle pela Demandada. Nesse contexto, não prospera a alegação de violação do artigo 62, I, da CLT. A exceção nele prevista não depende apenas do exercício de trabalho externo, mas também da impossibilidade de controle de horário pelo empregador. Tendo o julgador solucionado o caso com fundamento nos fatos e nas provas efetivamente produzidas nos autos, conforme lhe permite o artigo 131 do CPC/73, e provado o fato constitutivo do direito às horas extras, não há falar em violação dos artigos 818 da CLT e 333, I, do CPC. Cumpre notar que para se chegar a conclusão diversa, tal como pretende a Reclamada, necessário seria o revolvimento dos fatos e provas dos autos, o que é vedado nesta fase recursal, a teor da Súmula 126 do TST. Arestos paradigmas amparados em premissas fáticas diversas e oriundos do próprio Regional prolator do acórdão não se prestam para o processamento da revista por divergência jurisprudencial. 2. JORNADA DE TRABALHO. INOBSERVÂNCIA DO ARTIGO 896 DA CLT. Hipótese em que a Reclamada, em seu agravo de instrumento, restringe-se a apontar que o seu recurso de revista merece ser processado, porquanto entende que restou comprovado pela prova testemunhal que o horário de trabalho do Reclamante era diverso daquele apontado na petição inicial. Ocorre que a Demandada não ampara o agravo de instrumento nas hipóteses descritas nas alíneas "a", "b" e "c" do art. 896 da CLT, circunstância que inviabiliza o processamento do recurso de revista. 3. MULTA DO ARTIGO 538, PARÁGRAFO ÚNICO, DO CPC/73. Confirmado que o acórdão embargado não continha nenhum dos vícios previstos nos artigos 897-A da CLT ou 535 do CPC/73, com o devido exame de todos os elementos suscitados nos embargos declaratórios opostos pela Reclamada, mostra-se cabível a aplicação da multa prevista no artigo 538, parágrafo único, do CPC/73. Agravo de instrumento não provido.', '', 'Tribunal Superior do Trabalho. 7ª Turma', 'Federal', 'Tribunal', '{"search_term": "", "urn_type": "other", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:tribunal.superior.trabalho;turma.8:acordao;airr:2021-08-25;1007-2017-101-10-0', 'Acórdão do processo Nº AIRR - 1007-21.2017.5.10.0101', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.8:acordao;airr:2021-08-25;1007-2017-101-10-0', '2021-08-25', '', '', 'outro', 'AGRAVO DE INSTRUMENTO EM RECURSO DE REVISTA. 1. REMUNERAÇÃO VARIÁVEL. PRÊMIO POR CUMPRIMENTO DE META. O Tribunal Regional consignou que a reclamada limitou-se a apresentar defesa genérica, sem trazer documentos quanto aos critérios de cálculo da remuneração variável bem como às metas alcançadas pelo trabalhador ao longo do contrato, de modo a possibilitar a averiguação do acerto no pagamento da referida verba. Nesse contexto, concluir que a comissão foi paga corretamente, como pretende a recorrente, encontra óbice na Súmula nº 126 do TST, porquanto demandaria revolvimento de fatos e provas, procedimento vedado nesta instância recursal. 2. HORAS EXTRAS. O Tribunal Regional, com base na prova produzida nos autos, consignou que, em que pese a previsão de trabalho externo no contrato de trabalho, o cenário laboral descrito pela testemunha deixa entrever a possibilidade de controle de jornada pela empresa, seja por meio das reuniões diárias, matutinas e vespertinas realizadas em horários estabelecidos, seja mediante atelemetria, sistema através do qual a empresa acompanha o trajeto dos vendedores, aspectos incompatíveis com o regime excepcional previsto no art. 62, I, da CLT. Nesse contexto, insuscetível de reexame nesta instância recursal, a teor da Súmula nº 126 do TST, não é possível concluir que havia desempenho de serviço externo incompatível com o controle de jornada. 3. EQUIPARAÇÃO SALARIAL. INDICAÇÃO DO TRECHO DA DECISÃO RECORRIDA QUE CONSUBSTANCIA O PREQUESTIONAMENTO DA CONTROVÉRSIA OBJETO DO RECURSO DE REVISTA. ARTIGO 896, § 1º-A, I, DA CLT. ARGUIÇÃO DE OFÍCIO. Nos termos do artigo 896, § 1º-A, I, da CLT, incluído pela Lei nº 13.015/2014, é ônus da parte, sob pena de não conhecimento, "indicar o trecho da decisão recorrida que consubstancia o prequestionamento da controvérsia objeto do recurso de revista". No caso, não há falar em observância do requisito previsto no artigo 896, § 1º-A, I, da CLT, porque se verifica que a parte recorrente, nas razões do seu recurso de revista, não transcreveu o trecho pertinente da decisão atacada que consubstancia o prequestionamento da matéria recorrida no tocante à responsabilidade subsidiária. Agravo de instrumento conhecido e não provido.', '', 'LexML', 'transport_energy', '', '', 'AGRAVO DE INSTRUMENTO EM RECURSO DE REVISTA. 1. REMUNERAÇÃO VARIÁVEL. PRÊMIO POR CUMPRIMENTO DE META. O Tribunal Regional consignou que a reclamada limitou-se a apresentar defesa genérica, sem trazer documentos quanto aos critérios de cálculo da remuneração variável bem como às metas alcançadas pelo trabalhador ao longo do contrato, de modo a possibilitar a averiguação do acerto no pagamento da referida verba. Nesse contexto, concluir que a comissão foi paga corretamente, como pretende a recorrente, encontra óbice na Súmula nº 126 do TST, porquanto demandaria revolvimento de fatos e provas, procedimento vedado nesta instância recursal. 2. HORAS EXTRAS. O Tribunal Regional, com base na prova produzida nos autos, consignou que, em que pese a previsão de trabalho externo no contrato de trabalho, o cenário laboral descrito pela testemunha deixa entrever a possibilidade de controle de jornada pela empresa, seja por meio das reuniões diárias, matutinas e vespertinas realizadas em horários estabelecidos, seja mediante atelemetria, sistema através do qual a empresa acompanha o trajeto dos vendedores, aspectos incompatíveis com o regime excepcional previsto no art. 62, I, da CLT. Nesse contexto, insuscetível de reexame nesta instância recursal, a teor da Súmula nº 126 do TST, não é possível concluir que havia desempenho de serviço externo incompatível com o controle de jornada. 3. EQUIPARAÇÃO SALARIAL. INDICAÇÃO DO TRECHO DA DECISÃO RECORRIDA QUE CONSUBSTANCIA O PREQUESTIONAMENTO DA CONTROVÉRSIA OBJETO DO RECURSO DE REVISTA. ARTIGO 896, § 1º-A, I, DA CLT. ARGUIÇÃO DE OFÍCIO. Nos termos do artigo 896, § 1º-A, I, da CLT, incluído pela Lei nº 13.015/2014, é ônus da parte, sob pena de não conhecimento, "indicar o trecho da decisão recorrida que consubstancia o prequestionamento da controvérsia objeto do recurso de revista". No caso, não há falar em observância do requisito previsto no artigo 896, § 1º-A, I, da CLT, porque se verifica que a parte recorrente, nas razões do seu recurso de revista, não transcreveu o trecho pertinente da decisão atacada que consubstancia o prequestionamento da matéria recorrida no tocante à responsabilidade subsidiária. Agravo de instrumento conhecido e não provido.', '', 'Tribunal Superior do Trabalho. 8ª Turma', 'Federal', 'Tribunal', '{"search_term": "", "urn_type": "other", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.1:acordao:2023-12-15;0010386-24.2021.5.03.0009', 'Acórdão PJe TRT 3ª / Primeira Turma / 2023-12-15', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.1:acordao:2023-12-15;0010386-24.2021.5.03.0009', '2023-12-15', '', '3ª Região - Minas Gerais', 'jurisprudencia', 'INDENIZAÇÃO POR DANOS MORAIS. ASSÉDIO MORAL. CONDUTA ABUSIVA DO EMPREGADOR. RECOMENDAÇÃO 123 DO CNJ. CONVENÇÕES Nº 111, 155, 187 DA OIT RATIFICADAS PELO BRASIL. O assédio moral pressupõe uma prática de perseguição constante à vítima, de forma que lhe cause um sentimento de desqualificação, incapacidade e despreparo frente ao trabalho. Cria-se, no ambiente de trabalho, um terror psicológico capaz de incutir no empregado uma sensação de descrédito de si próprio, levando-o ao isolamento e ao comprometimento de sua saúde física e mental. O tratamento abusivo dispensado pela parte empregadora torna o ambiente de trabalho inapto para propiciar o desenvolvimento das atividades laborais de modo saudável, sendo que é papel do empregador estimular um ambiente de trabalho pautado pela saúde laboral, pelo bem-estar, pela harmonia, pela dignidade e pela cidadania. Nesse sentido, o procedimento empresarial acerca da divulgação da lista detelemetria/direção econômica e exposição dos rankings em mural e grupos de whatsapp é inaceitável, pois submete a pessoa trabalhadora a situações constrangedoras e gera um desequilíbrio no meio ambiente de trabalho, que se torna contaminado diante do assédio moral direcionado à parte autora, deixando se ser hígido e saudável, o que vulnera os art. 7º, XXII; 200, VIII e 225 da CF/88, bem como as Convenções 155 e 187 (Status de Convenção fundamental. Declaração de 1998 da OIT/2022 - core obligation). Nesse sentido, conforme declina o art. 3º, "e", da Convenção 155, a saúde no ambiente de trabalho envolve não apenas afecção de doenças, mas os elementos físicos e mentais que afetam a saúde e estão diretamente relacionados com a segurança e a higiene no trabalho. Outrossim, configura uma violação psicológica da pessoa trabalhadora, o que contraria a Convenção 190 da OIT (art. 8º da CLT), que determina a eliminação da violência e do assédio no mundo do trabalho (art. 5º). Da mesma forma, observa-se afronta à NR 17 (6.13), que veda a utilização de métodos que causem assédio moral, medo ou constrangimento. Tal situação é inadmissível, porque a relação de trabalho deve proporcionar bem-estar ao indivíduo, em acepção próxima ao conceito de dignidade humana, principalmente no ambiente de trabalho. A dignidade da pessoa humana é o fundamento de todas as democracias modernas, inclusive a brasileira (art. 1º, III, da CF/88) e como tal deve ser constantemente enaltecida pelo Poder Judiciário. | Assuntos: ASSÉDIO MORAL - INDENIZAÇÃO', '', 'LexML', 'transport_energy', 'Acórdão', '', 'INDENIZAÇÃO POR DANOS MORAIS. ASSÉDIO MORAL. CONDUTA ABUSIVA DO EMPREGADOR. RECOMENDAÇÃO 123 DO CNJ. CONVENÇÕES Nº 111, 155, 187 DA OIT RATIFICADAS PELO BRASIL. O assédio moral pressupõe uma prática de perseguição constante à vítima, de forma que lhe cause um sentimento de desqualificação, incapacidade e despreparo frente ao trabalho. Cria-se, no ambiente de trabalho, um terror psicológico capaz de incutir no empregado uma sensação de descrédito de si próprio, levando-o ao isolamento e ao comprometimento de sua saúde física e mental. O tratamento abusivo dispensado pela parte empregadora torna o ambiente de trabalho inapto para propiciar o desenvolvimento das atividades laborais de modo saudável, sendo que é papel do empregador estimular um ambiente de trabalho pautado pela saúde laboral, pelo bem-estar, pela harmonia, pela dignidade e pela cidadania. Nesse sentido, o procedimento empresarial acerca da divulgação da lista detelemetria/direção econômica e exposição dos rankings em mural e grupos de whatsapp é inaceitável, pois submete a pessoa trabalhadora a situações constrangedoras e gera um desequilíbrio no meio ambiente de trabalho, que se torna contaminado diante do assédio moral direcionado à parte autora, deixando se ser hígido e saudável, o que vulnera os art. 7º, XXII; 200, VIII e 225 da CF/88, bem como as Convenções 155 e 187 (Status de Convenção fundamental. Declaração de 1998 da OIT/2022 - core obligation). Nesse sentido, conforme declina o art. 3º, "e", da Convenção 155, a saúde no ambiente de trabalho envolve não apenas afecção de doenças, mas os elementos físicos e mentais que afetam a saúde e estão diretamente relacionados com a segurança e a higiene no trabalho. Outrossim, configura uma violação psicológica da pessoa trabalhadora, o que contraria a Convenção 190 da OIT (art. 8º da CLT), que determina a eliminação da violência e do assédio no mundo do trabalho (art. 5º). Da mesma forma, observa-se afronta à NR 17 (6.13), que veda a utilização de métodos que causem assédio moral, medo ou constrangimento. Tal situação é inadmissível, porque a relação de trabalho deve proporcionar bem-estar ao indivíduo, em acepção próxima ao conceito de dignidade humana, principalmente no ambiente de trabalho. A dignidade da pessoa humana é o fundamento de todas as democracias modernas, inclusive a brasileira (art. 1º, III, da CF/88) e como tal deve ser constantemente enaltecida pelo Poder Judiciário. | Assuntos: ASSÉDIO MORAL - INDENIZAÇÃO', '', 'Tribunal Regional do Trabalho. 1ª Turma', '', 'Tribunal', '{"search_term": "", "urn_type": "jurisprudence", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
