INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:tribunal.superior.trabalho;turma.2:acordao;rr:2018-03-20;190-2014-222-5-0', 'Acórdão do processo Nº RR - 190-25.2014.5.05.0222', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.2:acordao;rr:2018-03-20;190-2014-222-5-0', '2018-03-20', '', '', 'outro', 'I - AGRAVO. AGRAVO DE INSTRUMENTO. RECURSO DE REVISTA. HORAS EXTRAS. TRABALHO EXTERNO. EXISTÊNCIA DE TACÓGRAFO ERASTREAMENTO. Observo possível violação ao art. 62, I, da CLT. Dou provimento para analisar o agravo de instrumento. II - AGRAVO DE INSTRUMENTO. HORAS EXTRAS. TRABALHO EXTERNO. EXISTÊNCIA DE TACÓGRAFO ERASTREAMENTO. Observo possível violação ao art. 62, I, da CLT. Agravo de instrumento conhecido e provido. III - RECURSO DE REVISTA. HORAS EXTRAS. TRABALHO EXTERNO. EXISTÊNCIA DE TACÓGRAFO ERASTREAMENTO. Na hipótese, o TRT esclarece que havia tacógrafo erastreamentopor satélite. Para configuração da hipótese do art. 62, I, da CLT não se exige a simples constatação de exercício de atividade externa, mas, sim, daquela que, por sua natureza, seja incompatível com a fixação ou possibilidade de controle direto ou indireto da jornada de trabalho. Do exame do acórdão regional, infere-se a possibilidade de controle da jornada do empregado, pois o veículo utilizado pelo autor era equipado com dispositivo derastreamentovia satélite. A jurisprudência desta Corte Superior firmou entendimento de que o sistema de monitoramento erastreamentoviabiliza o controle de jornada do empregado. Precedentes. Recurso de revista conhecido e provido.', '', 'LexML', 'transport_energy', '', '', 'I - AGRAVO. AGRAVO DE INSTRUMENTO. RECURSO DE REVISTA. HORAS EXTRAS. TRABALHO EXTERNO. EXISTÊNCIA DE TACÓGRAFO ERASTREAMENTO. Observo possível violação ao art. 62, I, da CLT. Dou provimento para analisar o agravo de instrumento. II - AGRAVO DE INSTRUMENTO. HORAS EXTRAS. TRABALHO EXTERNO. EXISTÊNCIA DE TACÓGRAFO ERASTREAMENTO. Observo possível violação ao art. 62, I, da CLT. Agravo de instrumento conhecido e provido. III - RECURSO DE REVISTA. HORAS EXTRAS. TRABALHO EXTERNO. EXISTÊNCIA DE TACÓGRAFO ERASTREAMENTO. Na hipótese, o TRT esclarece que havia tacógrafo erastreamentopor satélite. Para configuração da hipótese do art. 62, I, da CLT não se exige a simples constatação de exercício de atividade externa, mas, sim, daquela que, por sua natureza, seja incompatível com a fixação ou possibilidade de controle direto ou indireto da jornada de trabalho. Do exame do acórdão regional, infere-se a possibilidade de controle da jornada do empregado, pois o veículo utilizado pelo autor era equipado com dispositivo derastreamentovia satélite. A jurisprudência desta Corte Superior firmou entendimento de que o sistema de monitoramento erastreamentoviabiliza o controle de jornada do empregado. Precedentes. Recurso de revista conhecido e provido.', '', 'Tribunal Superior do Trabalho. 2ª Turma', 'Federal', 'Tribunal', '{"search_term": "", "urn_type": "other", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
