INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Algumas questões sobre a recente decisão do STJ na arbitragem Petrobras v.ANP', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2018;1001124660', NULL, '', '', 'doutrina', 'Sumário:O caso : quais são os fatos? -- O julgamento no STJ : quem votou como? -- Análise das questões jurídicas debatidas : pontos positivos e pontos negativos: Reconhecimento da natureza jurisdicional da arbitragem : arbitragem é jurisdição. Visão ampla a respeito da arbitrabilidade objetiva : disputas decorrentes de contrato de concessão para exploração de petróleo e gás natural são arbitráveis. Valorização do princípio da competência-competência, mas só em certa medida. Ausência de enfrentamento do inciso VII do art. 485 do Código de Processo Civil : silêncio ensurdecedor. | Assuntos: Cláusula compromissória, Brasil. Concessão comercial, Brasil. Conflito de competência, Brasil. Gás natural, exploração, Brasil. {Gás natural; Gás de petróleo} Juízo arbitral, Brasil. Petróleo, exploração, Brasil. {Petróleo; Óleo cru} Poder judiciário, competência, Brasil. Arbitragem, decisão judicial, Brasil.', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PÚBLICO - 341::DIREITO PROCESSUAL - 341.4::Direito Processual Civil - 341.46::Processos particulares - 341.461::Processo diante de árbitros. Arbitragem - 341.4618', 'Sumário:O caso : quais são os fatos? -- O julgamento no STJ : quem votou como? -- Análise das questões jurídicas debatidas : pontos positivos e pontos negativos: Reconhecimento da natureza jurisdicional da arbitragem : arbitragem é jurisdição. Visão ampla a respeito da arbitrabilidade objetiva : disputas decorrentes de contrato de concessão para exploração de petróleo e gás natural são arbitráveis. Valorização do princípio da competência-competência, mas só em certa medida. Ausência de enfrentamento do inciso VII do art. 485 do Código de Processo Civil : silêncio ensurdecedor. | Assuntos: Cláusula compromissória, Brasil. Concessão comercial, Brasil. Conflito de competência, Brasil. Gás natural, exploração, Brasil. {Gás natural; Gás de petróleo} Juízo arbitral, Brasil. Petróleo, exploração, Brasil. {Petróleo; Óleo cru} Poder judiciário, competência, Brasil. Arbitragem, decisão judicial, Brasil.', '', 'Monteiro, André Luís', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br;santa.catarina:estadual:lei:2011-11-21;15622', 'LEI Nº 15.622, de 21 de novembro de 2011', 'https://www.lexml.gov.br/urn/urn:lex:br;santa.catarina:estadual:lei:2011-11-21;15622', '2011-11-21', 'Santa Catarina', '', 'lei', 'Art. 1º Fica o Poder Executivo autorizado a ceder à Agência Nacional do Petróleo, Gás Natural e Biocombustíveis -ANP, pelo prazo de 5 (cinco) anos, o uso gratuito de parte do imóvel com área de 11,14 m² (onze metros e quatorze decímetros quadrados), no Município de Florianópolis, onde funciona o Comando do Corpo de Bombeiros Militar de Santa Catarina, escriturado no livro de notas sob o nº 114, fls. 26 verso a 28 e cadastrado sob o nº 01576 no Sistema de Gestão Patrimonial da Secretaria de Estado da Administração. | Assuntos: ANP', '', 'LexML', 'transport_energy', 'Lei', '', 'Art. 1º Fica o Poder Executivo autorizado a ceder à Agência Nacional do Petróleo, Gás Natural e Biocombustíveis -ANP, pelo prazo de 5 (cinco) anos, o uso gratuito de parte do imóvel com área de 11,14 m² (onze metros e quatorze decímetros quadrados), no Município de Florianópolis, onde funciona o Comando do Corpo de Bombeiros Militar de Santa Catarina, escriturado no livro de notas sob o nº 114, fls. 26 verso a 28 e cadastrado sob o nº 01576 no Sistema de Gestão Patrimonial da Secretaria de Estado da Administração. | Assuntos: ANP', '', 'Estadual', '', 'Outros', '{"search_term": "", "urn_type": "legislation", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
