INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:agencia.nacional.energia.eletrica:resolucao.normativa:2010-04-23;399', 'RESOLUÇÃO NORMATIVA nº 399, de 23/04/2010', 'https://www.lexml.gov.br/urn/urn:lex:br:agencia.nacional.energia.eletrica:resolucao.normativa:2010-04-23;399', '2010-04-23', '', '', 'outro', 'Regulamenta a contratação do uso do sistema de transmissão, CUST, em caráter permanente, flexível e temporário, as formas de cálculo dos encargos correspondentes; altera a redação dos artigos 3º, 4º, 14, 15 e 18 da ResoluçãoANEEL281 de 01.10.1999, do artigo 5º da ResoluçãoANEEL371 de 29.12.1999, dos artigos 2º e 4º da ResoluçãoANEEL117 de 03.12.2004, do artigo 5º da ResoluçãoANEEL067 de 08.06.2004 e do artigo 14 da Resolução NormativaANEEL166 de 10.10.2005, que passam a vigorar conforme descrito nos artigos 26, 27, 28, 29 e 30 desta Resolução; e revoga o parágrafo 1º do artigo 15 da ResoluçãoANEEL281 de 01.10.1999 e a ResoluçãoANEEL715 de 28.12.2001. | Assuntos: Regulamentação. Contratação. {Contrato de Uso do Sistema de Transmissão, CUST}. {Caráter Permanente, Caráter Definitivo}. {Caráter Provisório, Caráter Temporário}. Cálculo. {Despesa, Encargo, Gasto}. {MUST, Montante de Uso do Sistema de Transmissão}. {(ONS), Operador Nacional do Sistema Elétrico}. {Tarifa, Adicional Tarifário}. Rede Básica. {Transmissão, Transmissão Elétrica}. Energia Elétrica. {TUST, Tarifa de Uso do Sistema de Transmissão}. {(ANEEL), Agência Nacional de Energia Elétrica}. {(CCEE), Câmara de Comercialização de Energia Elétrica}. Importação. Exportação. {Alteração, Modificação}. Revogação. Resolução. Legislação Básica | {Operador Nacional do Sistema Elétrico, ONS}. {ANEEL, Agência Nacional da Energia Elétrica}. {Câmara de Comercialização de Energia Elétri