INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'O processo punitivo daAneelprevisto nas Resoluções Normativas nºs 63/2004 e 846/2019 e as necessárias interações com o CPC/2015, a nova LINDB e a MP da liberdade econômica', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2020;2001160962', NULL, '', '', 'doutrina', 'Sumário:Do rito estabelecido pela RN 63/2004 para instauração e julgamento dos processos punitivos daAneel-- Da necessária aplicação supletiva e subsidiária do CPC/2015 aos processos punitivos daAneel: Artigo 15 do CPC/2015. Artigo 373, § 1º, do CPC/2015. Artigo 489, § 1º, do CPC/2015. Artigo 926 do CPC/2015 -- Da inafastável incidência dos preceitos da LINDB nos processos punitivos daAneel: Artigo 20, parágrafo único, da LINDB. Artigo 22, §§ 1º, 2º e 3º, da LINDB. Artigos 26 e 27 da LINDB. Artigo 30 da LINDB -- Do impacto da MP 881/2019 nos processos punitivos daAneel: Artigo 2º, II, c/c artigo 3º, V, da MP 881/2019. Artigo 4º, VIII, da MP 881/2019. | Assuntos: Agência reguladora, Brasil. Energia elétrica, Brasil. Medida provisória, Brasil. Punição, Brasil. Liberdade de comércio, Brasil. {Liberdade de comércio; Liberdade comercial} Agência reguladora, Brasil. Energia elétrica, Brasil. Medida provisória, Brasil. Punição, Brasil. Liberdade de comércio, Brasil. {Liberdade de comércio; Liberdade comercial}', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PÚBLICO - 341::DIREITO CONSTITUCIONAL - 341.2::Direitos Fundamentais. Direitos primordiais. Garantias asseguradas aos cidadãos e associações. Direitos do homem. Liberdades fundamentais. Direitos políticos - 341.27::Liberdade do comércio, da indústria e do trabalho. Liberdade das profissões - 341.2734', 'Sumário:Do rito estabelecido pela RN 63/2004 para instauração e julgamento dos processos punitivos daAneel-- Da necessária aplicação supletiva e subsidiária do CPC/2015 aos processos punitivos daAneel: Artigo 15 do CPC/2015. Artigo 373, § 1º, do CPC/2015. Artigo 489, § 1º, do CPC/2015. Artigo 926 do CPC/2015 -- Da inafastável incidência dos preceitos da LINDB nos processos punitivos daAneel: Artigo 20, parágrafo único, da LINDB. Artigo 22, §§ 1º, 2º e 3º, da LINDB. Artigos 26 e 27 da LINDB. Artigo 30 da LINDB -- Do impacto da MP 881/2019 nos processos punitivos daAneel: Artigo 2º, II, c/c artigo 3º, V, da MP 881/2019. Artigo 4º, VIII, da MP 881/2019. | Assuntos: Agência reguladora, Brasil. Energia elétrica, Brasil. Medida provisória, Brasil. Punição, Brasil. Liberdade de comércio, Brasil. {Liberdade de comércio; Liberdade comercial} Agência reguladora, Brasil. Energia elétrica, Brasil. Medida provisória, Brasil. Punição, Brasil. Liberdade de comércio, Brasil. {Liberdade de comércio; Liberdade comercial}', '', 'Araújo, Aldem Johnston Barbosa', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
