INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br;distrito.federal:tribunal.justica.distrito.federal.territorios;turma.civel.6:acordao:2007-05-02;272127', 'Acórdão nº 272127 do Processo nº20050111192602apc', 'https://www.lexml.gov.br/urn/urn:lex:br;distrito.federal:tribunal.justica.distrito.federal.territorios;turma.civel.6:acordao:2007-05-02;272127', '2007-05-02', 'DF', '', 'jurisprudencia', 'DIREITO PROCESSUAL CIVIL. PRELIMINAR DE CERCEAMENTO DE DEFESA REJEITADA. ARTIGOS 130, 131 E 330, INCISO I DO CÓDIGO DE PROCESSO CIVIL. INFRAÇÕES DE TRÂNSITO. PORTARIA Nº 1/98 DODENATRAN. OBSERVÂNCIA PELO DER/DF.
NOS TERMOS DOS ARTIGOS 130 E 131, DO CÓDIGO DE PROCESSO CIVIL, AS PROVAS SE PRESTAM A FORMAR A CONVICÇÃO DO JULGADOR, A QUEM CABE DETERMINÁ-LAS SE NECESSÁRIAS, OU INDEFERI-LAS, SE DESPICIENDAS. 
O ARTIGO 330, INCISO I, DO CPC, PRECEITUA QUE, QUANDO O FEITO ENCONTRA-SE EM CONDIÇÕES DE JULGAMENTO ANTECIPADO, SEM NECESSIDADE DE COLHEITA DE NOVAS PROVAS, A PROLAÇÃO DA SENTENÇA SEQUER É UMA FACULDADE, MAS UMA OBRIGAÇÃO, À VISTA DOS PRINCÍPIOS DA ECONOMIA E CELERIDADE PROCESSUAIS.
ESTANDO OS AUTOS DE INFRAÇÃO EM CONSONÂNCIA COM O DISPOSTO NA PORTARIA Nº 1/98 DODENATRAN, O NÃO PROVIMENTO DO RECURSO É MEDIDA QUE SE IMPÕE.
APELAÇÃO NÃO PROVIDA. | Assuntos: IMPROCEDÊNCIA, DECLARAÇÃO, NULIDADE, MULTA DE TRÂNSITO, OBSERVÂNCIA, REGULARIDADE, AUTO DE INFRAÇÃO, ATENDIMENTO, REQUISITOS, PREVISÃO, PORTARIA,DENATRAN.', '', 'LexML', 'transport_energy', 'Acórdão', '', 'DIREITO PROCESSUAL CIVIL. PRELIMINAR DE CERCEAMENTO DE DEFESA REJEITADA. ARTIGOS 130, 131 E 330, INCISO I DO CÓDIGO DE PROCESSO CIVIL. INFRAÇÕES DE TRÂNSITO. PORTARIA Nº 1/98 DODENATRAN. OBSERVÂNCIA PELO DER/DF.
NOS TERMOS DOS ARTIGOS 130 E 131, DO CÓDIGO DE PROCESSO CIVIL, AS PROVAS SE PRESTAM A FORMAR A CONVICÇÃO DO JULGADOR, A QUEM CABE DETERMINÁ-LAS SE NECESSÁRIAS, OU INDEFERI-LAS, SE DESPICIENDAS. 
O ARTIGO 330, INCISO I, DO CPC, PRECEITUA QUE, QUANDO O FEITO ENCONTRA-SE EM CONDIÇÕES DE JULGAMENTO ANTECIPADO, SEM NECESSIDADE DE COLHEITA DE NOVAS PROVAS, A PROLAÇÃO DA SENTENÇA SEQUER É UMA FACULDADE, MAS UMA OBRIGAÇÃO, À VISTA DOS PRINCÍPIOS DA ECONOMIA E CELERIDADE PROCESSUAIS.
ESTANDO OS AUTOS DE INFRAÇÃO EM CONSONÂNCIA COM O DISPOSTO NA PORTARIA Nº 1/98 DODENATRAN, O NÃO PROVIMENTO DO RECURSO É MEDIDA QUE SE IMPÕE.
APELAÇÃO NÃO PROVIDA. | Assuntos: IMPROCEDÊNCIA, DECLARAÇÃO, NULIDADE, MULTA DE TRÂNSITO, OBSERVÂNCIA, REGULARIDADE, AUTO DE INFRAÇÃO, ATENDIMENTO, REQUISITOS, PREVISÃO, PORTARIA,DENATRAN.', '', 'Tribunal de Justiça do Distrito Federal e dos Territórios. 6ª Turma Cível', 'Distrital', 'Tribunal', '{"search_term": "", "urn_type": "jurisprudence", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
