INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:senado.federal:projeto.lei;pl:2020;4121', '[ Projeto de Lei nº 4121/2020 - Iniciadora ]', 'https://www.lexml.gov.br/urn/urn:lex:br:senado.federal:projeto.lei;pl:2020;4121', NULL, '', '', 'outro', 'Altera a Lei no 12.305, de 2 de agosto de 2010, que institui a Política Nacional de Resíduos Sólidos, com o objetivo de dispor sobre a logística reversa de veículos automotores, e a Lei nº 13.755, de 10 de dezembro de 2018, que estabelece requisitos obrigatórios para a comercialização de veículos no Brasil e institui o ProgramaRota2030– Mobilidade e Logística, para criar requisitos referentes à reciclagem de veículos automotores.', '', 'LexML', 'transport_energy', '', '', 'Altera a Lei no 12.305, de 2 de agosto de 2010, que institui a Política Nacional de Resíduos Sólidos, com o objetivo de dispor sobre a logística reversa de veículos automotores, e a Lei nº 13.755, de 10 de dezembro de 2018, que estabelece requisitos obrigatórios para a comercialização de veículos no Brasil e institui o ProgramaRota2030– Mobilidade e Logística, para criar requisitos referentes à reciclagem de veículos automotores.', '', 'Senado Federal', 'Federal', 'Outros', '{"search_term": "", "urn_type": "other", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
