INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Direito das energias renováveis no Brasil', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2019;1001207741', NULL, '', '', 'doutrina', 'Resumo:"As energias renováveis representam aspectos estratégicos e nucleares para um modelo energético mais sustentável, especialmente para contribuir com os propósitos do Acordo de Paris. Aprovado em 2015 por 195 países, referido acordo internacional tem como objetivo central fortalecer a resposta global à ameaça da mudança do clima e de reforçar a capacidade dos países para lidar com os impactos decorrentes dessas mudanças e, consequentemente, o propósito de reduzir emissões de gases de efeito estufa (GEE). Para isso os governos se envolveram na construção de seus próprios compromissos, seguindo o que consideram viável a partir dos seus cenários econômico, social e ambiental. Nesse contexto global, o presente artigo tem como objetivo, por meio do levantamento e revisão bibliográfica, análise de conteúdo de legislações, políticas públicas, traçar um panorama sobre o estado atual da discussão sobre energias renováveis no Brasil, que também contribuam para que o país atenda suas metas de redução de emissões de gases efeito estufa (GEEs). Da legislação energética brasileira com essas características, será destacada a Lei Federal n. 13.576, de 26 de dezembro de 2017, que instituiu a Política Nacional de Biocombustíveis (RenovaBio), e que terá os seus principais aspectos e potencialidades abordados."Sumário:Aquecimento global, mudanças climáticas e a questão energética -- Contexto brasileiro. As emissões de GEE no setor de energia. O Acordo de Paris e a iNDC -- Direito das energias renováveis no Brasil. Legislação e política pública energética voltada para os biocombustíveis:RenovaBio. Projeções: benefícios e riscos doRenovaBio. | Assuntos: Biocombustível, impostos, redução, legislação, Brasil. Carga tributária, redução, aspectos ambientais, Brasil. {Carga tributária; Carga fiscal} Combustível fóssil, consumo, redução, aspectos jurídicos, Brasil. Incentivo fiscal, aspectos ambientais, Brasil. Biocombustível, impostos, redução, doutrinas e controvérsias, Brasil.', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PÚBLICO - 341::DIREITO ADMINISTRATIVO - 341.3::Domínio Público. Conceito. Domínio Eminente. Domínio Patrimonial - 341.34::Direito Ambiental - 341.347', 'Resumo:"As energias renováveis representam aspectos estratégicos e nucleares para um modelo energético mais sustentável, especialmente para contribuir com os propósitos do Acordo de Paris. Aprovado em 2015 por 195 países, referido acordo internacional tem como objetivo central fortalecer a resposta global à ameaça da mudança do clima e de reforçar a capacidade dos países para lidar com os impactos decorrentes dessas mudanças e, consequentemente, o propósito de reduzir emissões de gases de efeito estufa (GEE). Para isso os governos se envolveram na construção de seus próprios compromissos, seguindo o que consideram viável a partir dos seus cenários econômico, social e ambiental. Nesse contexto global, o presente artigo tem como objetivo, por meio do levantamento e revisão bibliográfica, análise de conteúdo de legislações, políticas públicas, traçar um panorama sobre o estado atual da discussão sobre energias renováveis no Brasil, que também contribuam para que o país atenda suas metas de redução de emissões de gases efeito estufa (GEEs). Da legislação energética brasileira com essas características, será destacada a Lei Federal n. 13.576, de 26 de dezembro de 2017, que instituiu a Política Nacional de Biocombustíveis (RenovaBio), e que terá os seus principais aspectos e potencialidades abordados."Sumário:Aquecimento global, mudanças climáticas e a questão energética -- Contexto brasileiro. As emissões de GEE no setor de energia. O Acordo de Paris e a iNDC -- Direito das energias renováveis no Brasil. Legislação e política pública energética voltada para os biocombustíveis:RenovaBio. Projeções: benefícios e riscos doRenovaBio. | Assuntos: Biocombustível, impostos, redução, legislação, Brasil. Carga tributária, redução, aspectos ambientais, Brasil. {Carga tributária; Carga fiscal} Combustível fóssil, consumo, redução, aspectos jurídicos, Brasil. Incentivo fiscal, aspectos ambientais, Brasil. Biocombustível, impostos, redução, doutrinas e controvérsias, Brasil.', '', 'Freiria, Rafael Costa', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:federal:decreto:2019-06-27;9888', 'Decreto nº 9.888, de 27 de Junho de 2019', 'https://www.lexml.gov.br/urn/urn:lex:br:federal:decreto:2019-06-27;9888', '2019-06-27', '', '', 'lei', 'Dispõe sobre a definição das metas compulsórias anuais de redução de emissões de gases causadores do efeito estufa para a comercialização de combustíveis de que trata a Lei nº 13.576, de 26 de dezembro de 2017, e institui o Comitê da Política Nacional de Biocombustíveis - ComitêRenovaBio. | Assuntos: REGULAMENTAÇÃO ,  POLITICA NACIONAL ,  Biocombustível ,  DEFINIÇÃO ,  CRITERIOS ,  ANO ,  REDUÇÃO ,  EMISSÃO ,  GAS ,  EFEITO ESTUFA ,  COMERCIO ,  COMBUSTIVEL ,  CRIAÇÃO ,  ORGÃO PUBLICO ,  COMITE NACIONAL ,  COMPETENCIA ,  COMPOSIÇÃO ,  FUNCIONAMENTO .', '', 'LexML', 'transport_energy', 'Decreto', '', 'Dispõe sobre a definição das metas compulsórias anuais de redução de emissões de gases causadores do efeito estufa para a comercialização de combustíveis de que trata a Lei nº 13.576, de 26 de dezembro de 2017, e institui o Comitê da Política Nacional de Biocombustíveis - ComitêRenovaBio. | Assuntos: REGULAMENTAÇÃO ,  POLITICA NACIONAL ,  Biocombustível ,  DEFINIÇÃO ,  CRITERIOS ,  ANO ,  REDUÇÃO ,  EMISSÃO ,  GAS ,  EFEITO ESTUFA ,  COMERCIO ,  COMBUSTIVEL ,  CRIAÇÃO ,  ORGÃO PUBLICO ,  COMITE NACIONAL ,  COMPETENCIA ,  COMPOSIÇÃO ,  FUNCIONAMENTO .', '', 'Federal', 'Federal', 'Outros', '{"search_term": "", "urn_type": "legislation", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:federal:decreto:2023-04-25;11499', 'Decreto nº 11.499, de 25 de Abril de 2023', 'https://www.lexml.gov.br/urn/urn:lex:br:federal:decreto:2023-04-25;11499', '2023-04-25', '', '', 'lei', 'Altera o Decreto nº 9.888, de 27 de junho de 2019, para dispor sobre a alteração da composição do Comitê da Política Nacional de Biocombustíveis - ComitêRenovaBioe redefinir a data para comprovação de atendimento à meta individual por cada distribuidor de combustíveis. | Assuntos: ALTERAÇÃO ,  DECRETO FEDERAL ,  COMPOSIÇÃO ,  COMITE ,  POLITICA NACIONAL ,  Biocombustível ,  PRAZO ,  COMPROVAÇÃO ,  ATENDIMENTO ,  ALCANCE ,  OBJETIVO ,  DISTRIBUIDOR ,  COMBUSTIVEL .', '', 'LexML', 'transport_energy', 'Decreto', '', 'Altera o Decreto nº 9.888, de 27 de junho de 2019, para dispor sobre a alteração da composição do Comitê da Política Nacional de Biocombustíveis - ComitêRenovaBioe redefinir a data para comprovação de atendimento à meta individual por cada distribuidor de combustíveis. | Assuntos: ALTERAÇÃO ,  DECRETO FEDERAL ,  COMPOSIÇÃO ,  COMITE ,  POLITICA NACIONAL ,  Biocombustível ,  PRAZO ,  COMPROVAÇÃO ,  ATENDIMENTO ,  ALCANCE ,  OBJETIVO ,  DISTRIBUIDOR ,  COMBUSTIVEL .', '', 'Federal', 'Federal', 'Outros', '{"search_term": "", "urn_type": "legislation", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:senado.federal:projeto.lei;pl:2020;3149', '[ Projeto de Lei nº 3149/2020 ]', 'https://www.lexml.gov.br/urn/urn:lex:br:camara.deputados:projeto.lei;pl:2020-06-05;3149', '2020-06-05', '', '', 'outro', 'Altera a Lei nº 13.576, de 26 de dezembro de 2017, que dispõe sobre a Política Nacional de Biocombustíveis (RenovaBio), para nela incluir os produtores independentes de matéria-prima destinada à produção de biocombustível; e altera a Lei nº 9.478, de 6 de agosto de 1997.', '', 'LexML', 'transport_energy', '', '', 'Altera a Lei nº 13.576, de 26 de dezembro de 2017, que dispõe sobre a Política Nacional de Biocombustíveis (RenovaBio), para nela incluir os produtores independentes de matéria-prima destinada à produção de biocombustível; e altera a Lei nº 9.478, de 6 de agosto de 1997.', '', 'Senado Federal', 'Federal', 'Outros', '{"search_term": "", "urn_type": "other", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
