INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:tribunal.superior.eleitoral;plenario:acordao;ro:1982-09-28;ro-5309', 'Acórdão RO de 28/09/1982 (Processo RO nº 5309)', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.eleitoral;plenario:acordao;ro:1982-09-28;ro-5309', '1982-09-28', '', '', 'outro', 'RECURSO ORDINARIO. DIRIGENTES DE EMPRESAS BENEFICIADAS PELOPROALCOOL. INELEGIBILIDADE DA LETRA "H" NAO CONFIGURADA. PRECLUSAO. 1) SE O FATO ALEGADO PELO RECORRENTE PREEXISTIA AO PEDIDO DE REGISTRO DO CANDIDATO, NAO HA MOTIVO SUPERVENIENTE QUE JUSTIFIQUE O RECURSO POR PARTE DE QUEM NAO IMPUGNOU O REGISTRO. A ALEGACAO DE CONHECIMENTO SUPERVENIENTE DO IMPEDIMENTO NAO AFASTA A PRECLUSAO. 2) OS INCENTIVOS DOPROALCOOLQUE BENEFICIAM, COM CARATER DE GENERALIDADE, TODAS AS EMPRESAS DO RAMO, COMO RECONHECE O PROPRIO RECORRENTE, NAO JUSTIFICAM A INELEGIBILIDADE DA LETRA "H", COMO O TSE JA RECONHECEU NO CASO ANALOGO DA SUDENE.', '', 'LexML', 'transport_energy', '', '', 'RECURSO ORDINARIO. DIRIGENTES DE EMPRESAS BENEFICIADAS PELOPROALCOOL. INELEGIBILIDADE DA LETRA "H" NAO CONFIGURADA. PRECLUSAO. 1) SE O FATO ALEGADO PELO RECORRENTE PREEXISTIA AO PEDIDO DE REGISTRO DO CANDIDATO, NAO HA MOTIVO SUPERVENIENTE QUE JUSTIFIQUE O RECURSO POR PARTE DE QUEM NAO IMPUGNOU O REGISTRO. A ALEGACAO DE CONHECIMENTO SUPERVENIENTE DO IMPEDIMENTO NAO AFASTA A PRECLUSAO. 2) OS INCENTIVOS DOPROALCOOLQUE BENEFICIAM, COM CARATER DE GENERALIDADE, TODAS AS EMPRESAS DO RAMO, COMO RECONHECE O PROPRIO RECORRENTE, NAO JUSTIFICAM A INELEGIBILIDADE DA LETRA "H", COMO O TSE JA RECONHECEU NO CASO ANALOGO DA SUDENE.', '', 'Tribunal Superior Eleitoral. Plenário', 'Federal', 'Tribunal', '{"search_term": "", "urn_type": "other", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
