INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:congresso.nacional:medida.provisoria;mpv:2022-02-15;1100', 'MPV 1100/2022', 'https://www.lexml.gov.br/urn/urn:lex:br:congresso.nacional:medida.provisoria;mpv:2022-02-15;1100', '2022-02-15', '', '', 'lei', 'Altera a Lei nº 9.478, de 6 de agosto de 1997, e a Lei nº 9.718, de 27 de novembro de 1998, para promover ajustes na cobrança da Contribuição para os Programas de Integração Social e de Formação do Patrimônio do Servidor Público -PIS/Pasep e da Contribuição para o Financiamento da Seguridade Social - Cofins incidentes sobre a cadeia de produção e de comercialização de etanol hidratado combustível

NOVA EMENTA: Altera as Leis nºs 9.478, de 6 de agosto de 1997, e 9.718, de 27 de novembro de 1998, para promover ajustes na cobrança da Contribuição para os Programas de Integração Social e de Formação do Patrimônio do Servidor Público (Contribuição para oPIS/Pasep) e da Contribuição para o Financiamento da Seguridade Social (Cofins) incidentes sobre a cadeia de produção e de comercialização de etanol hidratado combustível; e revoga a Medida Provisória nº 1.069, de 13 de setembro de 2021.', '', 'LexML', 'transport_energy', 'Medida Provisória', '', 'Altera a Lei nº 9.478, de 6 de agosto de 1997, e a Lei nº 9.718, de 27 de novembro de 1998, para promover ajustes na cobrança da Contribuição para os Programas de Integração Social e de Formação do Patrimônio do Servidor Público -PIS/Pasep e da Contribuição para o Financiamento da Seguridade Social - Cofins incidentes sobre a cadeia de produção e de comercialização de etanol hidratado combustível

NOVA EMENTA: Altera as Leis nºs 9.478, de 6 de agosto de 1997, e 9.718, de 27 de novembro de 1998, para promover ajustes na cobrança da Contribuição para os Programas de Integração Social e de Formação do Patrimônio do Servidor Público (Contribuição para oPIS/Pasep) e da Contribuição para o Financiamento da Seguridade Social (Cofins) incidentes sobre a cadeia de produção e de comercialização de etanol hidratado combustível; e revoga a Medida Provisória nº 1.069, de 13 de setembro de 2021.', '', 'Congresso Nacional', 'Federal', 'Legislativo Federal', '{"search_term": "", "urn_type": "legislation", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:congresso.nacional:projeto.lei;pln:2023;27', '[ Projeto de Lei do Congresso Nacional nº 27/2023 : Lei nº 14.771 de 22/12/2023 ]', 'https://www.lexml.gov.br/urn/urn:lex:br:congresso.nacional:projeto.lei;pln:2023;27', NULL, '', '', 'outro', 'Abre ao Orçamento Fiscal da União, em favor do Ministério da Educação e de Encargos Financeiros da União, crédito especial no valor de R$ 185.200.000,00, para os fins que especifica (alteração proposta pela Mensagem Presidencial nº 672/2023).', '', 'LexML', 'transport_energy', '', '', 'Abre ao Orçamento Fiscal da União, em favor do Ministério da Educação e de Encargos Financeiros da União, crédito especial no valor de R$ 185.200.000,00, para os fins que especifica (alteração proposta pela Mensagem Presidencial nº 672/2023).', '', 'Congresso Nacional', 'Federal', 'Legislativo Federal', '{"search_term": "", "urn_type": "other", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:congresso.nacional:medida.provisoria;mpv:2017-12-27;813', 'MPV 813/2017', 'https://www.lexml.gov.br/urn/urn:lex:br:congresso.nacional:medida.provisoria;mpv:2017-12-27;813', '2017-12-27', '', '', 'lei', 'Altera a Lei Complementar nº 26, de 11 de setembro de 1975, para dispor sobre a possibilidade de movimentação da conta do Programa de Integração Social -PISe do Programa de Formação do Patrimônio do Servidor Público - PASEP.', '', 'LexML', 'transport_energy', 'Medida Provisória', '', 'Altera a Lei Complementar nº 26, de 11 de setembro de 1975, para dispor sobre a possibilidade de movimentação da conta do Programa de Integração Social -PISe do Programa de Formação do Patrimônio do Servidor Público - PASEP.', '', 'Congresso Nacional', 'Federal', 'Legislativo Federal', '{"search_term": "", "urn_type": "legislation", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:congresso.nacional:medida.provisoria;mpv:2021-03-01;1034', 'MPV 1034/2021', 'https://www.lexml.gov.br/urn/urn:lex:br:congresso.nacional:medida.provisoria;mpv:2021-03-01;1034', '2021-03-01', '', '', 'lei', 'Altera a Lei nº 7.689, de 15 de dezembro de 1988, para majorar a alíquota da Contribuição Social sobre o Lucro Líquido devida pelas pessoas jurídicas do setor financeiro, a Lei nº 8.989, de 24 de fevereiro de 1995, para modificar a concessão da isenção relativa ao Imposto sobre Produtos Industrializados incidente na aquisição de automóveis por pessoa com deficiência, revoga a tributação especial relativa à nafta e a outros produtos destinados a centrais petroquímicas, e institui crédito presumido da Contribuição para os Programas de Integração Social e de Formação do Patrimônio do Servidor Público e da Contribuição Social para o Financiamento da Seguridade Social para produtos destinados ao uso em hospitais, clínicas, consultórios médicos e campanhas de vacinação.

NOVA EMENTA: Altera a Lei nº 7.689, de 15 de dezembro de 1988, para majorar a alíquota da Contribuição Social sobre o Lucro Líquido devida pelas pessoas jurídicas do setor financeiro, a Lei nº 8.989, de 24 de fevereiro de 1995, para modificar a concessão da isenção relativa ao Imposto sobre Produtos Industrializados incidente na aquisição de automóveis por pessoa com deficiência, as Leis nºs 10.865, de 30 de abril de 2004, 11.196, de 21 de novembro de 2005, 13.756, de 12 de dezembro de 2018, e 9.613, de 3 de março de 1998, e o Decreto-Lei nº 288, de 28 de fevereiro de 1967; e revoga a tributação especial relativa à nafta e a outros produtos destinados a centrais petroquímicas.', '', 'LexML', 'transport_energy', 'Medida Provisória', '', 'Altera a Lei nº 7.689, de 15 de dezembro de 1988, para majorar a alíquota da Contribuição Social sobre o Lucro Líquido devida pelas pessoas jurídicas do setor financeiro, a Lei nº 8.989, de 24 de fevereiro de 1995, para modificar a concessão da isenção relativa ao Imposto sobre Produtos Industrializados incidente na aquisição de automóveis por pessoa com deficiência, revoga a tributação especial relativa à nafta e a outros produtos destinados a centrais petroquímicas, e institui crédito presumido da Contribuição para os Programas de Integração Social e de Formação do Patrimônio do Servidor Público e da Contribuição Social para o Financiamento da Seguridade Social para produtos destinados ao uso em hospitais, clínicas, consultórios médicos e campanhas de vacinação.

NOVA EMENTA: Altera a Lei nº 7.689, de 15 de dezembro de 1988, para majorar a alíquota da Contribuição Social sobre o Lucro Líquido devida pelas pessoas jurídicas do setor financeiro, a Lei nº 8.989, de 24 de fevereiro de 1995, para modificar a concessão da isenção relativa ao Imposto sobre Produtos Industrializados incidente na aquisição de automóveis por pessoa com deficiência, as Leis nºs 10.865, de 30 de abril de 2004, 11.196, de 21 de novembro de 2005, 13.756, de 12 de dezembro de 2018, e 9.613, de 3 de março de 1998, e o Decreto-Lei nº 288, de 28 de fevereiro de 1967; e revoga a tributação especial relativa à nafta e a outros produtos destinados a centrais petroquímicas.', '', 'Congresso Nacional', 'Federal', 'Legislativo Federal', '{"search_term": "", "urn_type": "legislation", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:congresso.nacional:medida.provisoria;mpv:2022-12-21;1147', 'MPV 1147/2022', 'https://www.lexml.gov.br/urn/urn:lex:br:congresso.nacional:medida.provisoria;mpv:2022-12-21;1147', '2022-12-21', '', '', 'lei', 'Altera a Lei nº 14.148, de 3 de maio de 2021, que instituiu o Programa Emergencial de Retomada do Setor de Eventos - Perse, e reduz a zero por cento as alíquotas da Contribuição para o Programa de Integração Social e o Programa de Formação do Patrimônio do Servidor Público -PIS/Pasep e da Contribuição para o Financiamento da Seguridade Social - Cofins incidentes sobre as receitas decorrentes da atividade de transporte aéreo regular de passageiros. 

NOVA EMENTA: Altera a Lei nº 14.148, de 3 de maio de 2021, que instituiu o Programa Emergencial de Retomada do Setor de Eventos (Perse); reduz a 0% (zero por cento) as alíquotas da Contribuição para os Programas de Integração Social e de Formação do Patrimônio do Servidor Público (Contribuição para oPIS/Pasep) e da Contribuição para o Financiamento da Seguridade Social (Cofins) incidentes sobre as receitas decorrentes da atividade de transporte aéreo regular de passageiros; reduz as alíquotas da Contribuição para oPIS/Pasep e da Cofins incidentes sobre operações realizadas com óleo diesel, biodiesel, gás liquefeito de petróleo, álcool, querosene de aviação, gás natural veicular e gasolina; altera as Leis nºs 10.637, de 30 de dezembro de 2002, e 10.833, de 29 de dezembro de 2003, para excluir o Imposto sobre Operações relativas à Circulação de Mercadorias e sobre Prestações de Serviços de Transporte Interestadual e Intermunicipal e de Comunicação (ICMS) da base de cálculo dos créditos da Contribuição para oPIS/Pasep e da Cofins, e as Leis nºs 13.483, de 21 de setembro de 2017, e 13.576, de 26 de dezembro de 2017, e os Decretos-Lei nºs 9.853, de 13 de setembro de 1946, e 8.621, de 10 de janeiro de 1946; revoga dispositivos das Medidas Provisórias nºs 1.157, de 1º de janeiro de 2023, 1.159, de 12 de janeiro de 2023, e 1.163, de 28 de fevereiro de 2023; e dá outras providências.', '', 'LexML', 'transport_energy', 'Medida Provisória', '', 'Altera a Lei nº 14.148, de 3 de maio de 2021, que instituiu o Programa Emergencial de Retomada do Setor de Eventos - Perse, e reduz a zero por cento as alíquotas da Contribuição para o Programa de Integração Social e o Programa de Formação do Patrimônio do Servidor Público -PIS/Pasep e da Contribuição para o Financiamento da Seguridade Social - Cofins incidentes sobre as receitas decorrentes da atividade de transporte aéreo regular de passageiros. 

NOVA EMENTA: Altera a Lei nº 14.148, de 3 de maio de 2021, que instituiu o Programa Emergencial de Retomada do Setor de Eventos (Perse); reduz a 0% (zero por cento) as alíquotas da Contribuição para os Programas de Integração Social e de Formação do Patrimônio do Servidor Público (Contribuição para oPIS/Pasep) e da Contribuição para o Financiamento da Seguridade Social (Cofins) incidentes sobre as receitas decorrentes da atividade de transporte aéreo regular de passageiros; reduz as alíquotas da Contribuição para oPIS/Pasep e da Cofins incidentes sobre operações realizadas com óleo diesel, biodiesel, gás liquefeito de petróleo, álcool, querosene de aviação, gás natural veicular e gasolina; altera as Leis nºs 10.637, de 30 de dezembro de 2002, e 10.833, de 29 de dezembro de 2003, para excluir o Imposto sobre Operações relativas à Circulação de Mercadorias e sobre Prestações de Serviços de Transporte Interestadual e Intermunicipal e de Comunicação (ICMS) da base de cálculo dos créditos da Contribuição para oPIS/Pasep e da Cofins, e as Leis nºs 13.483, de 21 de setembro de 2017, e 13.576, de 26 de dezembro de 2017, e os Decretos-Lei nºs 9.853, de 13 de setembro de 1946, e 8.621, de 10 de janeiro de 1946; revoga dispositivos das Medidas Provisórias nºs 1.157, de 1º de janeiro de 2023, 1.159, de 12 de janeiro de 2023, e 1.163, de 28 de fevereiro de 2023; e dá outras providências.', '', 'Congresso Nacional', 'Federal', 'Legislativo Federal', '{"search_term": "", "urn_type": "legislation", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
