INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Impactoambiental', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:livro:2005;000718315', NULL, '', '', 'doutrina', 'Resumo:Analisa a proteçãoambientalà luz dos princípios constitucionais e o desenvolvimento de políticas específicas. Apresenta os procedimentos necessários à elaboração de estudos deimpactoambiental: diretrizes, atividades técnicas, relatório, participação do público eimpactode vizinhança. Comenta a discricionariedade e o poder de polícia da Administração Pública.Sumário:A proteção do meio ambiente -- A política do meio ambiente no Brasil: uma visão global -- O poder de polícia e o direitoambiental-- O estudo deimpactoambientale sua importância institucional -- A discricionariedade administrativa e o estudo deimpactoambiental-- O estudo deimpactoambientale o meio ambiente do trabalho -- O estudo deimpactoambientale o patrimônio genético -- O estudo deimpactoambientalem face da atividade impactante do meio ambiente cultural -- A efetividade do estudo deimpactoambiental: Portugal. Brasil. | Assuntos: Impactoambiental, aspectos jurídicos, Brasil.Impactoambiental, jurisprudência, Brasil.Impactoambiental, direito comparado, Brasil, Portugal. Direitoambiental, Brasil. {Direitoambiental; Direito ecológico} Proteçãoambiental, aspectos constitucionais, Brasil. {Proteçãoambiental; Degradaçãoambiental, prevenção; Meio ambiente, proteção; Recursos naturais, proteção} Meio ambiente, proteção, Brasil. Políticaambiental, Brasil. {Políticaambiental; Ecologia, política; Meio ambiente, política; Política do meio ambiente} Constituição, Brasil, 1988. {Constituição; Carta constitucional; Lei maior; Magna carta}', '', 'LexML', 'transport_energy', 'Livro', 'Classificação: DIREITO 