INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'O tratamento jurídico dosimpactostransfronteiriços pelo direito internacionalambiental', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2012;1000938126', NULL, '', '', 'doutrina', 'Sumário:Os principais instrumentos internacionais relativos ao tratamento dosimpactosambientaistransfronteiriços -- Osimpactosambientaistransfronteiriços e a legislação adotada pela União Europeia e pelo Mercosul. | Assuntos: Degradaçãoambiental. {Degradaçãoambiental; Danos no ambiente; Degradação ecológica; Deterioração do ambiente} Desastreambiental. Direito internacional público. {Direito internacional público; Direito das gentes; Direito público internacional}Impactoambiental, legislação, Países da União Europeia.Impactoambiental, legislação, Países do Mercosul.Impactoambiental, tratado. Direitoambiental, tratado. {Direitoambiental; Direito ecológico}', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PÚBLICO - 341::DIREITO ADMINISTRATIVO - 341.3::Domínio Público. Conceito. Domínio Eminente. Domínio Patrimonial - 341.34::DireitoAmbiental- 341.347', 'Sumário:Os principais instrumentos internacionais relativos ao tratamento dosimpactosambientaistransfronteiriços -- Osimpactosambientaistransfronteiriços e a legislação adotada pela União Europeia e pelo Mercosul. | Assuntos: Degradaçãoambiental. {Degradaçãoambiental; Danos no ambiente; Degradação ecológica; Deterioração do ambiente} Desastreambiental. Direito internacional público. {Direito internacional público; Direito das gentes; Direito público internacional}Impactoambiental, legislação, Países da União Europeia.Impactoambiental, legislação, Países do Mercosul.Impactoambiental, tratado. Direitoambi