INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:federal:decreto:1948-01-06;24313', 'Decreto nº 24.313, de 6 de Janeiro de 1948', 'https://www.lexml.gov.br/urn/urn:lex:br:federal:decreto:1948-01-06;24313', '1948-01-06', '', '', 'lei', 'Faz pública a adesão, por parte do Govêrno da Espanha, em nome das colônias espanholas, aos seguintes atos: ConvençãodeParis, de 20 de Março de 1883, para a proteção da propriedade industrial;AcôrdodeMadrid, de 14 de Abril de 1891, relativo às falsas indicações de procedência de mercadorias;AcôrdodeMadrid de 14 de Abril de 1891, relativo ao registro internacional das marcas de fábrica ou de comércio; eAcôrdoda Haia, de 6 de Novembro de 1925, referente ao depósito internacional de desenhos ou modelos industriais. | Assuntos: DIVULGAÇÃO ,  ADESÃO ,ACORDOINTERNACIONAL ,  CONVENÇÃO ,  PROTEÇÃO ,  PROPRIEDADE INDUSTRIAL ,  PAIS ESTRANGEIRO ,  ESPANHA .', '', 'LexML', 'transport_energy', 'Decreto', '', 'Faz pública a adesão, por parte do Govêrno da Espanha, em nome das colônias espanholas, aos seguintes atos: ConvençãodeParis, de 20 de Março de 1883, para a proteção da propriedade industrial;AcôrdodeMadrid, de 14 de Abril de 1891, relativo às falsas indicações de procedência de mercadorias;AcôrdodeMadrid de 14 de Abril de 1891, relativo ao registro internacional das marcas de fábrica ou de comércio; eAcôrdoda Haia, de 6 de Novembro de 1925, referente ao depósito internacional de desenhos ou modelos industriais. | Assuntos: DIVULGAÇÃO ,  ADESÃO ,ACORDOINTERNACIONAL ,  CONVENÇÃO ,  PROTEÇÃO ,  PROPRIEDADE INDUSTRIAL ,  PAIS ESTRANGEIRO ,  ESPANHA .', '', 'Federal', 'Federal', 'Outros', '{"search_term": "", "urn_type": "legislation", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-0