INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br;distrito.federal:tribunal.justica.distrito.federal.territorios;turma.civel.2:acordao:2008-10-03;330120', 'Acórdão nº 330120 do Processo nº20060110545845apc', 'https://www.lexml.gov.br/urn/urn:lex:br;distrito.federal:tribunal.justica.distrito.federal.territorios;turma.civel.2:acordao:2008-10-03;330120', '2008-10-03', 'DF', '', 'jurisprudencia', 'DIREITO PROCESSUAL CIVIL. AÇÃO DE COBRANÇA. CHEQUE. FALECIMENTO DO EMITENTE. LEGITIMIDADE PASSIVA. ESPÓLIO.  GRATUIDADE JUDICIÁRIA. LEI Nº 1.060/50.   
1. ATÉ O ENCERRAMENTO DEFINITIVO DOINVENTÁRIO, COM O TRÂNSITO EM JULGADO DA SENTENÇA DE PARTILHA, A AÇÃO DE COBRANÇA DE CHEQUE EMITIDO PELO DE CUJUS DEVE SER AJUIZADA EM DESFAVOR DO ESPÓLIO. 
2. A LEI Nº 1.060/50 DISPÕE QUE A CONDENAÇÃO NOS ÔNUS DA SUCUMBÊNCIA FICARÁ SOBRESTADA ATÉ, E SE, EM CINCO ANOS, A PARTE CONTRÁRIA PROVAR A CESSAÇÃO DO ESTADO DE MISERABILIDADE DO APELANTE.
3. APELO IMPROVIDO. SENTENÇA MANTIDA. | Assuntos: CONFIRMAÇÃO, EXTINÇÃO DO PROCESSO, DECORRÊNCIA, ILEGITIMIDADE PASSIVA, HERDEIRA, AÇÃO DE COBRANÇA, CHEQUE,EMISSÃO,DECUJUS, EXISTÊNCIA, ESPÓLIO, INOCORRÊNCIA, TRÂNSITO EM JULGADO,INVENTÁRIO.', '', 'LexML', 'transport_energy', 'Acórdão', '', 'DIREITO PROCESSUAL CIVIL. AÇÃO DE COBRANÇA. CHEQUE. FALECIMENTO DO EMITENTE. LEGITIMIDADE PASSIVA. ESPÓLIO.  GRATUIDADE JUDICIÁRIA. LEI Nº 1.060/50.   
1. ATÉ O ENCERRAMENTO DEFINITIVO DOINVENTÁRIO, COM O TRÂNSITO EM JULGADO DA SENTENÇA DE PARTILHA, A AÇÃO DE COBRANÇA DE CHEQUE EMITIDO PELO DE CUJUS DEVE SER AJUIZADA EM DESFAVOR DO ESPÓLIO. 
2. A LEI Nº 1.060/50 DISPÕE QUE A CONDENAÇÃO NOS ÔNUS DA SUCUMBÊNCIA FICARÁ SOBRESTADA ATÉ, E SE, EM CINCO ANOS, A PARTE CONTRÁRIA PROVAR A CESSAÇÃO DO ESTADO DE MISERABILIDADE DO APELANTE.
3. APELO IMPROVIDO. SENTENÇA MANTIDA. | Assuntos: CONFIRMAÇÃO, EXTINÇÃO DO PROCESSO, DECORRÊNCIA, ILEGITIMIDADE PASSIVA, HERDEIRA, AÇÃO DE COBRANÇA, CHEQUE,EMISSÃO,DECUJUS, EXISTÊNCIA, ESPÓLIO, INOCORRÊNCIA, TRÂNSITO EM JULGADO,INVENTÁRIO.', '', 'Tribunal de Justiça do Distrito Federal e dos Territórios. 2ª Turma Cível', 'Distrital', 'Tribunal', '{"search_term": "", "urn_type": "jurisprudence", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:senado.federal:projeto.lei;pl:2023;2229', '[ Projeto de Lei nº 2229/2023 ]', 'https://www.lexml.gov.br/urn/urn:lex:br:senado.federal:projeto.lei;pl:2023;2229', NULL, '', '', 'outro', 'Regulamenta o Mercado Brasileiro de ReduçãodeEmissões– MBRE, com base na Política Nacional sobre Mudança do Clima – PNMC (Lei nº 12.187, de 29 de dezembro de 2009); institui a Política de Redução dasEmissõesde Gases de Efeito Estufa Provenientes do Desmatamento e da Degradação Florestal, da Conservação dos Estoques de Carbono Florestal, do Manejo Sustentável de Florestas e do Aumento de Estoques de Carbono Florestal (REDD+); altera o Decreto-Lei nº 2.848, de 7 de dezembro de 1940, para tipificar a conduta de fraude no registro,emissãoou distribuição de certificados representativos de crédito de carbono; e as Leis nºs 11.284, de 2 de março de 2006, para assegurar o direito de comercializar créditos de carbono de atividades silviculturais; 12.187, para prever que o Mercado Brasileiro de ReduçãodeEmissõesserá operacionalizado no âmbito do Sistema Nacional de Registro deInventáriodeEmissõesde Gases de Efeito Estufa (SNRI-GEE); e 12.651, de 25 de maio de 2012, para definir certificado representativo de crédito de carbono; e dá outras providências.', '', 'LexML', 'transport_energy', '', '', 'Regulamenta o Mercado Brasileiro de ReduçãodeEmissões– MBRE, com base na Política Nacional sobre Mudança do Clima – PNMC (Lei nº 12.187, de 29 de dezembro de 2009); institui a Política de Redução dasEmissõesde Gases de Efeito Estufa Provenientes do Desmatamento e da Degradação Florestal, da Conservação dos Estoques de Carbono Florestal, do Manejo Sustentável de Florestas e do Aumento de Estoques de Carbono Florestal (REDD+); altera o Decreto-Lei nº 2.848, de 7 de dezembro de 1940, para tipificar a conduta de fraude no registro,emissãoou distribuição de certificados representativos de crédito de carbono; e as Leis nºs 11.284, de 2 de março de 2006, para assegurar o direito de comercializar créditos de carbono de atividades silviculturais; 12.187, para prever que o Mercado Brasileiro de ReduçãodeEmissõesserá operacionalizado no âmbito do Sistema Nacional de Registro deInventáriodeEmissõesde Gases de Efeito Estufa (SNRI-GEE); e 12.651, de 25 de maio de 2012, para definir certificado representativo de crédito de carbono; e dá outras providências.', '', 'Senado Federal', 'Federal', 'Outros', '{"search_term": "", "urn_type": "other", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:superior.tribunal.justica;turma.2:acordao;resp:2017-08-17;1673140-1652484', 'REsp 1673140 / SC', 'https://www.lexml.gov.br/urn/urn:lex:br:superior.tribunal.justica;turma.2:acordao;resp:2017-08-17;1673140-1652484', '2017-08-17', '', '', 'outro', 'PROCESSUAL  CIVIL  E  TRIBUTÁRIO.  VIOLAÇÃO  DO  ART.  1.022 DO CPC.
DEFICIÊNCIA  NA  FUNDAMENTAÇÃO.  SÚMULA  284/STF.  DEMANDA EXECUTIVA
AFORADA  CONTRA DEVEDOR FALECIDO. ILEGITIMIDADE DE PARTE.INVENTÁRIOCONCLUÍDO.   RESPONSABILIDADE  SUBSIDIÁRIA  DOS  HERDEIROS.  RECURSO
ESPECIAL PARCIALMENTE CONHECIDO E, NESTA PARTE, NÃO PROVIDO.
1.  Não  se  conhece do Recurso Especial em relação à ofensa ao art.
1.022  do  CPC quando a parte não aponta, de forma clara, o vício em
que teria incorrido o acórdão impugnado. Aplicação, por analogia, da
Súmula 284/STF.
2.   Aforada  demanda  executiva  contra  devedor  já  falecido,  há
ilegitimidade ad causam passiva.
3.  Encerrado  oinventáriodebens  com  que faleceu o de cujus,
remanesce  a  responsabilidade  tributária  pessoal  dos  herdeiros,
segundo o quinhão herdado (CTN, art. 131, II).
4.  Não  se  podendo  demandar o de cujus e nem o espólio, porque já
efetuada  a  partilha  de  bens,  a  demanda fiscal deve ser aforada
contra os herdeiros.
5.  Recurso  Especial  parcialmente  conhecido  e,  nessa parte, não
provido.
Decisão
Vistos,  relatados  e discutidos os autos em que são partes as acima
indicadas,  acordam  os  Ministros  da  Segunda  Turma  do  Superior
Tribunal  de  Justiça: ""A Turma, por unanimidade, conheceu em parte
do  recurso e, nessa parte, negou-lhe provimento, nos termos do voto
do(a) Sr(a). Ministro(a)-Relator(a)."
Os  Srs.  Ministros  Og  Fernandes, Mauro Campbell Marques, Assusete
Magalhães (Presidente) e Francisco Falcão votaram com o Sr. Ministro
Relator." | Assuntos: Aplica-se a Súmula 83 do STJ aos recursos especiais interpostos
pela   alínea  "a"  do  permissivo  constitucional,  de  acordo  com
entendimento desta Corte Superior.
     "Colho  várias  consequências  dessas  observações  da Corte de
origem,  a saber: (a) a notória ilegitimidade ''ad causam'' passiva do
''de  cujus''  e  do espólio; (b) a inidoneidade da certidão de dívida
ativa  que lastreou a execução fiscal contra pessoa já falecida; (c)
a  necessidadedeemissãode nova CDA, a qual deve ser precedida da
prática  de  atos administrativos no seio da Procuradoria da Fazenda
Nacional,  com  vista  a  subsidiar  o  aforamento  de  nova demanda
executiva, nos termos do art. 2º, § § 5º e 6º, da Lei n. 6.830/1980;
(d)  a  impossibilidade  de  substituição da CDA no seio da execução
fiscal, em face do óbice previsto na Súmula 392/STJ".
     "Clara,  portanto,  a  individualização  das  responsabilidades
tributárias  no  tempo.  Remanesce a obrigatoriedade de os herdeiros
arcarem com a paga da exação, limitada ao quinhão de cada qual".', '', 'LexML', 'transport_energy', '', '', 'PROCESSUAL  CIVIL  E  TRIBUTÁRIO.  VIOLAÇÃO  DO  ART.  1.022 DO CPC.
DEFICIÊNCIA  NA  FUNDAMENTAÇÃO.  SÚMULA  284/STF.  DEMANDA EXECUTIVA
AFORADA  CONTRA DEVEDOR FALECIDO. ILEGITIMIDADE DE PARTE.INVENTÁRIOCONCLUÍDO.   RESPONSABILIDADE  SUBSIDIÁRIA  DOS  HERDEIROS.  RECURSO
ESPECIAL PARCIALMENTE CONHECIDO E, NESTA PARTE, NÃO PROVIDO.
1.  Não  se  conhece do Recurso Especial em relação à ofensa ao art.
1.022  do  CPC quando a parte não aponta, de forma clara, o vício em
que teria incorrido o acórdão impugnado. Aplicação, por analogia, da
Súmula 284/STF.
2.   Aforada  demanda  executiva  contra  devedor  já  falecido,  há
ilegitimidade ad causam passiva.
3.  Encerrado  oinventáriodebens  com  que faleceu o de cujus,
remanesce  a  responsabilidade  tributária  pessoal  dos  herdeiros,
segundo o quinhão herdado (CTN, art. 131, II).
4.  Não  se  podendo  demandar o de cujus e nem o espólio, porque já
efetuada  a  partilha  de  bens,  a  demanda fiscal deve ser aforada
contra os herdeiros.
5.  Recurso  Especial  parcialmente  conhecido  e,  nessa parte, não
provido.
Decisão
Vistos,  relatados  e discutidos os autos em que são partes as acima
indicadas,  acordam  os  Ministros  da  Segunda  Turma  do  Superior
Tribunal  de  Justiça: ""A Turma, por unanimidade, conheceu em parte
do  recurso e, nessa parte, negou-lhe provimento, nos termos do voto
do(a) Sr(a). Ministro(a)-Relator(a)."
Os  Srs.  Ministros  Og  Fernandes, Mauro Campbell Marques, Assusete
Magalhães (Presidente) e Francisco Falcão votaram com o Sr. Ministro
Relator." | Assuntos: Aplica-se a Súmula 83 do STJ aos recursos especiais interpostos
pela   alínea  "a"  do  permissivo  constitucional,  de  acordo  com
entendimento desta Corte Superior.
     "Colho  várias  consequências  dessas  observações  da Corte de
origem,  a saber: (a) a notória ilegitimidade ''ad causam'' passiva do
''de  cujus''  e  do espólio; (b) a inidoneidade da certidão de dívida
ativa  que lastreou a execução fiscal contra pessoa já falecida; (c)
a  necessidadedeemissãode nova CDA, a qual deve ser precedida da
prática  de  atos administrativos no seio da Procuradoria da Fazenda
Nacional,  com  vista  a  subsidiar  o  aforamento  de  nova demanda
executiva, nos termos do art. 2º, § § 5º e 6º, da Lei n. 6.830/1980;
(d)  a  impossibilidade  de  substituição da CDA no seio da execução
fiscal, em face do óbice previsto na Súmula 392/STJ".
     "Clara,  portanto,  a  individualização  das  responsabilidades
tributárias  no  tempo.  Remanesce a obrigatoriedade de os herdeiros
arcarem com a paga da exação, limitada ao quinhão de cada qual".', '', 'Superior Tribunal de Justiça. 2ª Turma', 'Federal', 'Tribunal', '{"search_term": "", "urn_type": "other", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br;justica.trabalho;regiao.8:tribunal.regional.trabalho;turma.4:acordao:2019-04-30;0111200-25.2001.5.08.0003', 'ACÓRDÃO TRT 8ª / 4ª T / AP 0111200-25.2001.5.08.0003', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.8:tribunal.regional.trabalho;turma.4:acordao:2019-04-30;0111200-25.2001.5.08.0003', '2019-04-30', '', '8ª Região - Pará e Amapá', 'jurisprudencia', 'POSSIBILIDADE DE PENHORA. FRAUDE À EXECUÇÃO. Preservado o privilégio do crédito trabalhista, não há que se falar em prejuízo quando da determinaçãodeemissãodecertidãodecrédito ao exequente para opor contra oinventáriodo de cujus, visto se tratar de procedimento necessário à preservação dos direitos do exequente, enquanto ocorrer a regularização da representatividade do espólio. Agravo não provido.', '', 'LexML', 'transport_energy', 'Acórdão', '', 'POSSIBILIDADE DE PENHORA. FRAUDE À EXECUÇÃO. Preservado o privilégio do crédito trabalhista, não há que se falar em prejuízo quando da determinaçãodeemissãodecertidãodecrédito ao exequente para opor contra oinventáriodo de cujus, visto se tratar de procedimento necessário à preservação dos direitos do exequente, enquanto ocorrer a regularização da representatividade do espólio. Agravo não provido.', '', 'Tribunal Regional do Trabalho. 4ª Turma', '', 'Tribunal', '{"search_term": "", "urn_type": "jurisprudence", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
