INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:tribunal.contas.uniao;plenario:acordao:2004-06-16;736', 'ACÓRDÃO%20TCU%20736/2004', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.contas.uniao;plenario:acordao:2004-06-16;736', '2004-06-16', '', '', 'jurisprudencia', 'Denúncia. Possíveis irregularidades praticadas pelo Conselho Regional de Medicina Veterinária do Maranhão. Pedidos de reexame de acórdão que aplicou multa aos responsáveis, em razão da retenção de ISS dos prestadores de serviços; impropriedades em suprimento de fundos; divergência entre o valor contábil e oinventáriodos bens patrimoniais; pagamento indevido de diárias; reajuste antecipado de contrato; contratação informal de prestação de serviços;emissãode notas fiscais sem o nome do Conselho; dispensa de licitação; ausência de comprovantes de despesa; e pagamento superfaturado a empresa prestadora de serviços. Elementos apresentados insuficientes para elidir as irregularidades. Conhecimento. Negado provimento.', '', 'LexML', 'transport_energy', 'Acórdão', '', 'Denúncia. Possíveis irregularidades praticadas pelo Conselho Regional de Medicina Veterinária do Maranhão. Pedidos de reexame de acórdão que aplicou multa aos responsáveis, em razão da retenção de ISS dos prestadores de serviços; impropriedades em suprimento de fundos; divergência entre o valor contábil e oinventáriodos bens patrimoniais; pagamento indevido de diárias; reajuste antecipado de contrato; contratação informal de prestação de serviços;emissãode notas fiscais sem o nome do Conselho; dispensa de licitação; ausência de comprovantes de despesa; e pagamento superfaturado a empresa prestadora de serviços. Elementos apresentados insuficientes para elidir as irregularidades. Conhecimento. Negado provimento.', '', 'Tribunal de Contas da União. Plenário', 'Federal', 'Tribunal', '{"search_term": "", "urn_type": "jurisprudence", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Segurançaviáriasob influência da Curva de Kuznets', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2017;1001100948', NULL, '', '', 'doutrina', 'Assuntos: Crescimento econômico, Brasil. Direitos econômicos e sociais, Brasil. {Direitos econômicos e sociais; Direitos econômicos; Direitos econômicos, sociais e culturais; Direitos sociais}Segurançano trânsito, Brasil. {Segurançano trânsito;Segurançade tráfego; Tráfego,segurança; Trânsito,segurança} Acidente de trânsito, Brasil. {Acidente de trânsito; Acidente de automóvel; Acidente de tráfego; Automóvel, acidente; Tráfego, acidente; Trânsito, acidente}', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO - 340', 'Assuntos: Crescimento econômico, Brasil. Direitos econômicos e sociais, Brasil. {Direitos econômicos e sociais; Direitos econômicos; Direitos econômicos, sociais e culturais; Direitos sociais}Segurançano trânsito, Brasil. {Segurançano trânsito;Segurançade tráfego; Tráfego,segurança; Trânsito,segurança} Acidente de trânsito, Brasil. {Acidente de trânsito; Acidente de automóvel; Acidente de tráfego; Automóvel, acidente; Tráfego, acidente; Trânsito, acidente}', '', 'Honorato, Cássio Mattos', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
