INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Políticas públicas para o uso da bicicleta como meio de transporte para o trabalho', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2014;1001033403', NULL, '', '', 'doutrina', 'Sumário:O uso da bicicleta pelo trabalhador em grandes cidades : a indissociabilidade da sustentabilidade ambiental, qualidade de vida esegurançaindividual -- Aspectos jurídicos envolvendo o uso de bicicletas em grandes cidades por trabalhadores: A legislação de trânsito. Política nacional de mobilidade urbana. O atual panorama de seguridade social envolvendo o trabalhador/ciclista vítima de acidentes "In Itinere" -- Propostas de políticas públicas que promovam o uso de bicicleta por trabalhadores em grandes cidades: Reestruturaçãoviária: a engenharia das vias públicas para o uso seguro da bicicleta em dias úteis. A adoção de políticas públicas que incentivem o trabalhador a fazer uso da bicicleta. A adoção de políticas públicas de desoneração tributária de modo a incentivar o empregador a promover o uso de bicicletas entre os seus empregados. | Assuntos: Ciclovia, Brasil. Política de transportes, Brasil.Segurançano trânsito, Brasil. {Segurançano trânsito;Segurançade tráfego; Tráfego,segurança; Trânsito,segurança} Tráfego urbano, Brasil. Políticas públicas, Brasil.', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PÚBLICO - 341::DIREITO ADMINISTRATIVO - 341.3::Atos administrativos - 341.35::Atos administrativos unilaterais - 341.351::Controle judicial dos atos administrativos - 341.3517', 'Sumário:O uso da bicicleta pelo trabalhador em grandes cidades : a indissociabilidade da sustentabilidade ambiental, qualidade de vida esegurançaindividual -- Aspectos jurídicos envolvendo o uso de bicicletas em grandes cidades por trabalhadores: A legislação de trânsito. Política nacional de mobilidade urbana. O atual panorama de seguridade social envolvendo o trabalhador/ciclista vítima de acidentes "In Itinere" -- Propostas de políticas públicas que promovam o uso de bicicleta por trabalhadores em grandes cidades: Reestruturaçãoviária: a engenharia das vias públicas para o uso seguro da bicicleta em dias úteis. A adoção de políticas públicas que incentivem o trabalhador a fazer uso da bicicleta. A adoção de políticas públicas de desoneração tributária de modo a incentivar o empregador a promover o uso de bicicletas entre os seus empregados. | Assuntos: Ciclovia, Brasil. Política de transportes, Brasil.Segurançano trânsito, Brasil. {Segurançano trânsito;Segurançade tráfego; Tráfego,segurança; Trânsito,segurança} Tráfego urbano, Brasil. Políticas públicas, Brasil.', '', 'Genchini, Marco Aurélio Barberato', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
