INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br;distrito.federal:tribunal.justica.distrito.federal.territorios;turma.criminal.2:acordao:2011-07-07;519829', 'Acórdão nº 519829 do Processo nº20110020089479hbc', 'https://www.lexml.gov.br/urn/urn:lex:br;distrito.federal:tribunal.justica.distrito.federal.territorios;turma.criminal.2:acordao:2011-07-07;519829', '2011-07-07', 'DF', '', 'jurisprudencia', 'HABEAS CORPUS. CRIME CONTRA A ORDEM TRIBUTÁRIA. VENDA DECOMBUSTÍVELADULTERADO. ARTIGO 1º, INCISO I, DA LEI N.º 8.176/1991. ALEGAÇÕES DE INÉPCIA DA DENÚNCIA E ILEGITIMIDADE PASSIVA. NÃO ACOLHIMENTO. RESPONSABILIDADE DO REVENDEDOR PELAQUALIDADEDOCOMBUSTÍVEL. CONCENTRAÇÃO DE ÁLCOOL NA GASOLINA. ALEGAÇÃO DE QUE O PERCENTUAL ENCONTRADO É AUTORIZADO E QUE EVENTUAL EXCESSO É MÍNIMO. NECESSIDADE DE DILAÇÃO PROBATÓRIA. VEDAÇÃO. PENDÊNCIA DE PROCESSO ADMINISTRATIVO. IRRELEVÂNCIA PARA O AJUIZAMENTO DE AÇÃO PENAL. ORDEM DENEGADA.
1. O PACIENTE, NAQUALIDADEDE EMPRESÁRIO INDIVIDUAL REVENDEDOR DECOMBUSTÍVEIS, SE TORNA RESPONSÁVEL PELOS ATOS PRATICADOS NO EXERCÍCIO DA EMPRESA, POSSUINDO O DEVER DE FISCALIZAR AQUALIDADEDOSCOMBUSTÍVEISADQUIRIDOS E COMERCIALIZADOS, DE MODO QUE NÃO É INEPTA A DENÚNCIA QUE DESCREVE O FATO TÍPICO CONSISTENTE NA REVENDA DECOMBUSTÍVELFORA DAS ESPECIFICAÇÕES EXIGIDAS PELA LEGISLAÇÃO PELO ESTABELECIMENTO DO PACIENTE. IGUALMENTE, O PACIENTE É PARTE LEGÍTIMA PARA FIGURAR NO PÓLO PASSIVO DA AÇÃO PENAL, POIS É RESPONSÁVEL PELAS CARACTERÍSTICASDOCOMBUSTÍVELREVENDIDO.
2. VERIFICAR SE, NA ESPÉCIE, A CONCENTRAÇÃO DE ÁLCOOL ETÍLICO NA GASOLINA ESTAVA DENTRO DOS LIMITES AUTORIZADOS OU QUE EVENTUAL EXCESSO ERA MÍNIMO DEMANDA DILAÇÃO PROBATÓRIA, INVIÁVEL EM SEDE DE HABEAS CORPUS E QUE COMPETE AO JUÍZO DA CAUSA EM GRAU DE AMPLA COGNIÇÃO. DE FATO, IN CASU, O TESTE LABORATORIAL CONCLUIU QUE A CONCENTRAÇÃO DE ÁLCOOL ETÍLICO NA GASOLINA ESTAVA EM 28%, SENDO QUE O LIMITE PERMITIDO É DE 25%, DE MODO QUE O FATO PRATICADO SE AMOLDA, AO MENOS EM PRINCÍPIO E EM TESE, AO CRIME PREVISTO NO ARTIGO 1º, INCISO I, DA LEI N.º 8.176/1991, NÃO HAVENDO, PORTANTO, NENHUMA ILEGALIDADE MANIFESTA.
3. A EXISTÊNCIA DE PROCESSO ADMINISTRATIVO EM CURSO NÃO IMPEDE O AJUIZAMENTO DE AÇÃO PENAL PARA APURAR CRIME CONTRA A ORDEM ECONÔMICA, MAS APENAS CRIMES CONTRA A ORDEM TRIBUTÁRIA.
4. ORDEM DENEGADA. | Assuntos: ', '', 'LexML', 'transport_energy', 'Acórdão', '', 'HABEAS CORPUS. CRIME CONTRA A ORDEM TRIBUTÁRIA. VENDA DECOMBUSTÍVELADULTERADO. ARTIGO 1º, INCISO I, DA LEI N.º 8.176/1991. ALEGAÇÕES DE INÉPCIA DA DENÚNCIA E ILEGITIMIDADE PASSIVA. NÃO ACOLHIMENTO. RESPONSABILIDADE DO REVENDEDOR PELAQUALIDADEDOCOMBUSTÍVEL. CONCENTRAÇÃO DE ÁLCOOL NA GASOLINA. ALEGAÇÃO DE QUE O PERCENTUAL ENCONTRADO É AUTORIZADO E QUE EVENTUAL EXCESSO É MÍNIMO. NECESSIDADE DE DILAÇÃO PROBATÓRIA. VEDAÇÃO. PENDÊNCIA DE PROCESSO ADMINISTRATIVO. IRRELEVÂNCIA PARA O AJUIZAMENTO DE AÇÃO PENAL. ORDEM DENEGADA.
1. O PACIENTE, NAQUALIDADEDE EMPRESÁRIO INDIVIDUAL REVENDEDOR DECOMBUSTÍVEIS, SE TORNA RESPONSÁVEL PELOS ATOS PRATICADOS NO EXERCÍCIO DA EMPRESA, POSSUINDO O DEVER DE FISCALIZAR AQUALIDADEDOSCOMBUSTÍVEISADQUIRIDOS E COMERCIALIZADOS, DE MODO QUE NÃO É INEPTA A DENÚNCIA QUE DESCREVE O FATO TÍPICO CONSISTENTE NA REVENDA DECOMBUSTÍVELFORA DAS ESPECIFICAÇÕES EXIGIDAS PELA LEGISLAÇÃO PELO ESTABELECIMENTO DO PACIENTE. IGUALMENTE, O PACIENTE É PARTE LEGÍTIMA PARA FIGURAR NO PÓLO PASSIVO DA AÇÃO PENAL, POIS É RESPONSÁVEL PELAS CARACTERÍSTICASDOCOMBUSTÍVELREVENDIDO.
2. VERIFICAR SE, NA ESPÉCIE, A CONCENTRAÇÃO DE ÁLCOOL ETÍLICO NA GASOLINA ESTAVA DENTRO DOS LIMITES AUTORIZADOS OU QUE EVENTUAL EXCESSO ERA MÍNIMO DEMANDA DILAÇÃO PROBATÓRIA, INVIÁVEL EM SEDE DE HABEAS CORPUS E QUE COMPETE AO JUÍZO DA CAUSA EM GRAU DE AMPLA COGNIÇÃO. DE FATO, IN CASU, O TESTE LABORATORIAL CONCLUIU QUE A CONCENTRAÇÃO DE ÁLCOOL ETÍLICO NA GASOLINA ESTAVA EM 28%, SENDO QUE O LIMITE PERMITIDO É DE 25%, DE MODO QUE O FATO PRATICADO SE AMOLDA, AO MENOS EM PRINCÍPIO E EM TESE, AO CRIME PREVISTO NO ARTIGO 1º, INCISO I, DA LEI N.º 8.176/1991, NÃO HAVENDO, PORTANTO, NENHUMA ILEGALIDADE MANIFESTA.
3. A EXISTÊNCIA DE PROCESSO ADMINISTRATIVO EM CURSO NÃO IMPEDE O AJUIZAMENTO DE AÇÃO PENAL PARA APURAR CRIME CONTRA A ORDEM ECONÔMICA, MAS APENAS CRIMES CONTRA A ORDEM TRIBUTÁRIA.
4. ORDEM DENEGADA. | Assuntos: ', '', 'Tribunal de Justiça do Distrito Federal e dos Territórios. 2ª Turma Criminal', 'Distrital', 'Tribunal', '{"search_term": "", "urn_type": "jurisprudence", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
