INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br;distrito.federal:tribunal.justica.distrito.federal.territorios;turma.criminal.2:acordao:2007-08-30;286438', 'Acórdão nº 286438 do Processo nº20050910115805apr', 'https://www.lexml.gov.br/urn/urn:lex:br;distrito.federal:tribunal.justica.distrito.federal.territorios;turma.criminal.2:acordao:2007-08-30;286438', '2007-08-30', 'DF', '', 'jurisprudencia', 'PENAL E PROCESSO PENAL. FURTO QUALIFICADO TENTADO (ARTIGO 155, § 4º, INCISOS I E IV, C/C O ARTIGO 14, INCISO II, AMBOS DO CÓDIGO PENAL).ADULTERAÇÃODE SINAL IDENTIFICADOR DE VEÍCULO AUTOMOTOR (ARTIGO 311 DO CÓDIGO PENAL). FURTO. ABSOLVIÇÃO. PROVAS. DEPOIMENTOS. INVIABILIDADE. DELITO PREVISTO NO ARTIGO 311 DO CÓDIGO PENAL. ABSOLVIÇÃO. POSSIBILIDADE. 1. NOS CRIMES CONTRA O PATRIMÔNIO, A PALAVRA DA VÍTIMA REVESTE-SE DE ESPECIAL IMPORTÂNCIA, PRINCIPALMENTE QUANDO EM CONSONÂNCIA COM AS DEMAIS PROVAS DOS AUTOS. 2. MALGRADO DETENHA A MÁQUINA ESTATAL TODO UM APARATO A SEU FAVOR, NO INTUITO DE FAZER PRESENTE O IUS PUNIENDI, SE NÃO O FEZ DE FORMA ADEQUADA, PORQUANTO TROUXE SOMENTE INDÍCIOS DE SER O RECORRENTE O AUTOR DO CRIME DEADULTERAÇÃODE SINAL IDENTIFICADOR DE VEÍCULO AUTOMOTOR, NÃO SE FAZ POSSÍVEL CONDENÁ-LO POR PRESUNÇÃO, SENDO A ABSOLVIÇÃO MEDIDA IMPERIOSA. DEU-SE PARCIAL PROVIMENTO. POR MAIORIA, VENCIDO O REVISOR. | Assuntos: PROCEDÊNCIA, ABSOLVIÇÃO,ADULTERAÇÃO, IDENTIFICAÇÃO, SINAL, VEÍCULO AUTOMOTOR, INSUFICIÊNCIA, COMPROVAÇÃO, AUTORIA DO CRIME, IMPOSSIBILIDADE, CONDENAÇÃO, PRESUNÇÃO, INDÍCIO. CONFIRMAÇÃO, CONDENAÇÃO, TENTATIVA, FURTO QUALIFICADO, DESTRUIÇÃO, CONCURSO DE PESSOAS, PALAVRA, VÍTIMA, COMPROVAÇÃO, MATERIALIDADE, AUTORIA DO CRIME.

VOTO VENCIDO: IMPROCEDÊNCIA, ABSOLVIÇÃO,ADULTERAÇÃO, IDENTIFICAÇÃO, SINAL, VEÍCULO AUTOMOTOR, CONFISSÃO, DEPOIMENTO, TESTEMUNHA, LAUDO PERICIAL, COMPROVAÇÃO, MATERIALIDADE, AUTORIA DO CRIME.', '', 'LexML', 'transport_energy', 'Acórdão', '', 'PENAL E PROCESSO PENAL. FURTO QUALIFICADO TENTADO (ARTIGO 155, § 4º, INCISOS I E IV, C/C O ARTIGO 14, INCISO II, AMBOS DO CÓDIGO PENAL).ADULTERAÇÃODE SINAL IDENTIFICADOR DE VEÍCULO AUTOMOTOR (ARTIGO 311 DO CÓDIGO PENAL). FURTO. ABSOLVIÇÃO. PROVAS. DEPOIMENTOS. INVIABILIDADE. DELITO PREVISTO NO ARTIGO 311 DO CÓDIGO PENAL. ABSOLVIÇÃO. POSSIBILIDADE. 1. NOS CRIMES CONTRA O PATRIMÔNIO, A PALAVRA DA VÍTIMA REVESTE-SE DE ESPECIAL IMPORTÂNCIA, PRINCIPALMENTE QUANDO EM CONSONÂNCIA COM AS DEMAIS PROVAS DOS AUTOS. 2. MALGRADO DETENHA A MÁQUINA ESTATAL TODO UM APARATO A SEU FAVOR, NO INTUITO DE FAZER PRESENTE O IUS PUNIENDI, SE NÃO O FEZ DE FORMA ADEQUADA, PORQUANTO TROUXE SOMENTE INDÍCIOS DE SER O RECORRENTE O AUTOR DO CRIME DEADULTERAÇÃODE SINAL IDENTIFICADOR DE VEÍCULO AUTOMOTOR, NÃO SE FAZ POSSÍVEL CONDENÁ-LO POR PRESUNÇÃO, SENDO A ABSOLVIÇÃO MEDIDA IMPERIOSA. DEU-SE PARCIAL PROVIMENTO. POR MAIORIA, VENCIDO O REVISOR. | Assuntos: PROCEDÊNCIA, ABSOLVIÇÃO,ADULTERAÇÃO, IDENTIFICAÇÃO, SINAL, VEÍCULO AUTOMOTOR, INSUFICIÊNCIA, COMPROVAÇÃO, AUTORIA DO CRIME, IMPOSSIBILIDADE, CONDENAÇÃO, PRESUNÇÃO, INDÍCIO. CONFIRMAÇÃO, CONDENAÇÃO, TENTATIVA, FURTO QUALIFICADO, DESTRUIÇÃO, CONCURSO DE PESSOAS, PALAVRA, VÍTIMA, COMPROVAÇÃO, MATERIALIDADE, AUTORIA DO CRIME.

