INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br;distrito.federal:tribunal.justica.distrito.federal.territorios;turma.criminal.2:acordao:2012-05-24;590325', 'Acórdão nº 590325 do Processo nº20090710002892apr', 'https://www.lexml.gov.br/urn/urn:lex:br;distrito.federal:tribunal.justica.distrito.federal.territorios;turma.criminal.2:acordao:2012-05-24;590325', '2012-05-24', 'DF', '', 'jurisprudencia', 'APELAÇÃO CRIMINAL. RECEPTAÇÃO. ABSOLVIÇÃO. ELEMENTO SUBJETIVO. CIRCUNSTÂNCIAS DO FATO. INVERSÃO DO ÔNUS. DEPOIMENTO POLICIAL. PROVA IDÔNEA.ADULTERAÇÃODE SINAL IDENTIFICADOR DE VEÍCULO AUTOMOTOR. AUTORIA E MATERIALIDADE. PROVA SATISFATÓRIA. DOSIMETRIA DA PENA. ANTECEDENTES.
MANTÉM-SE A CONDENAÇÃO PELO CRIME DE RECEPTAÇÃO, QUANDO AS CIRCUNSTÂNCIAS EM QUE O DELITO FOI PRATICADO DEMONSTRAM O ELEMENTO SUBJETIVO DO TIPO, SENDO ÔNUS DO AGENTE COMPROVAR A ORIGEM LÍCITA DO BEM.
DEPOIMENTOS PRESTADOS POR POLICIAIS SÃO MERECEDORES DE FÉ, NA MEDIDA EM QUE PROVÊM DE AGENTES PÚBLICOS NO EXERCÍCIO DE SUAS ATRIBUIÇÕES, ESPECIALMENTE QUANDO ESTÃO EM CONSONÂNCIA COM AS DEMAIS PROVAS. 
A SIMPLES ALEGAÇÃO DO RÉU DE QUE DESCONHECE A AUTORIA DAADULTERAÇÃODE SINAL IDENTIFICADOR DE VEÍCULO AUTOMOTOR NÃO É CAPAZ DE AFASTAR, POR SI SÓ, A CONDENAÇÃO, MORMENTE QUANDO O ACERVO PROBATÓRIO, CONSTITUÍDO DE PROVA ORAL E PERICIAL, EVIDENCIA A PRÁTICA DO CRIME A ELE IMPOSTO.
POSSUINDO O RÉU MAIS DE UMA CONDENAÇÃO COM TRÂNSITO EM JULGADO, POR FATOS ANTERIORES AO QUE SE EXAMINA, É LÍCITO AO JUIZ CONSIDERAR UMA DELAS COMO ANTECEDENTE DESABONADOR E OUTRA COMO REINCIDÊNCIA, SEM QUE SE CONFIGURE BIS IN IDEM. 
APELAÇÕES NÃO PROVIDAS. | Assuntos: IMPROCEDÊNCIA, ABSOLVIÇÃO, RECEPTAÇÃO,ADULTERAÇÃODE SINAL IDENTIFICADOR DE VEÍCULO AUTOMOTOR, DEPOIMENTO, TESTEMUNHA, VÍTIMA, CONFISSÃO, CO-RÉU, CREDIBILIDADE, DECLARAÇÃO, POLICIAL MILITAR, PARTICIPAÇÃO, INVESTIGAÇÃO POLICIAL, INTERCEPTAÇÃO TELEFÔNICA, VALOR, AQUISIÇÃO, MOTOCICLETA, INFERIORIDADE, VALOR DE MERCADO, LAUDO PERICIAL, COMPROVAÇÃO, ANUÊNCIA, ACUSADO, ORIGEM ILÍCITA, BEM,ADULTERAÇÃO, SINAL IDENTIFICADOR DE VEÍCULO, CARACTERIZAÇÃO, MATERIALIDADE, AUTORIA DO CRIME.', '', 'LexML', 'transport_energy', 'Acórdão', '', 'APELAÇÃO CRIMINAL. RECEPTAÇÃO. ABSOLVIÇÃO. ELEMENTO SUBJETIVO. CIRCUNSTÂNCIAS DO FATO. INVERSÃO DO ÔNUS. DEPOIMENTO POLICIAL. PROVA IDÔNEA.ADULTERAÇÃODE SINAL IDENTIFICADOR DE VEÍCULO AUTOMOTOR. AUTORIA E MATERIALIDADE. PROVA SATISFATÓRIA. DOSIMETRIA DA PENA. ANTECEDENTES.
MANTÉM-SE A CONDENAÇÃO PELO CRIME DE RECEPTAÇÃO, QUANDO AS CIRCUNSTÂNCIAS EM QUE O DELITO FOI PRATICADO DEMONSTRAM O ELEMENTO SUBJETIVO DO TIPO, SENDO ÔNUS DO AGENTE COMPROVAR A ORIGEM LÍCITA DO BEM.
DEPOIMENTOS PRESTADOS POR POLICIAIS SÃO MERECEDORES DE FÉ, NA MEDIDA EM QUE PROVÊM DE AGENTES PÚBLICOS NO EXERCÍCIO DE SUAS ATRIBUIÇÕES, ESPECIALMENTE QUANDO ESTÃO EM CONSONÂNCIA COM AS DEMAIS PROVAS. 
