INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:federal:lei:2013-12-17;12894', 'Lei nº 12.894, de 17 de Dezembro de 2013', 'https://www.lexml.gov.br/urn/urn:lex:br:federal:lei:2013-12-17;12894', '2013-12-17', '', '', 'lei', 'Acrescenta inciso V ao art. 1º da Lei nº 10.446, de 8 de maio de 2002, para prever a atribuição da Polícia Federal para apurar os crimes de falsificação, corrupção eadulteraçãode medicamentos, assim como sua venda, inclusive pela internet, quando houver repercussão interestadual ou internacional. | Assuntos: ACRESCIMO ,  DEPOSITO ,  NORMAS ,  CORRELAÇÃO ,  PREVENÇÃO ,  COMPETENCIA ,  POLICIA FEDERAL ,  OBJETIVO ,  PROCEDIMENTO ,  APURAÇÃO ,  INFRAÇÃO PENAL ,  CRIME ,  FALSIFICAÇÃO ,  CORRUPÇÃO ,ADULTERAÇÃO,  VENDA ,  MEDICAMENTOS .', '', 'LexML', 'transport_energy', 'Lei', '', 'Acrescenta inciso V ao art. 1º da Lei nº 10.446, de 8 de maio de 2002, para prever a atribuição da Polícia Federal para apurar os crimes de falsificação, corrupção eadulteraçãode medicamentos, assim como sua venda, inclusive pela internet, quando houver repercussão interestadual ou internacional. | Assuntos: ACRESCIMO ,  DEPOSITO ,  NORMAS ,  CORRELAÇÃO ,  PREVENÇÃO ,  COMPETENCIA ,  POLICIA FEDERAL ,  OBJETIVO ,  PROCEDIMENTO ,  APURAÇÃO ,  INFRAÇÃO PENAL ,  CRIME ,  FALSIFICAÇÃO ,  CORRUPÇÃO ,ADULTERAÇÃO,  VENDA ,  MEDICAMENTOS .', '', 'Federal', 'Federal', 'Outros', '{"search_term": "", "urn_type": "legislation", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Natureza jurídica financeira da distribuição dos royalties de petróleo e gás daANPe liminar ou tutela de urgência em processos judiciais', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2021;1001208660', NULL, '', '', 'doutrina', 'Sumário:Da natureza jurídica da distribuição dos royalties -- características elementares e legais do fundo especial gerido pelaANP-- da delimitação da discussão a respeito do direito ao recebimento de honorários advocatícios a partir de decisão judicial e a necessidade de se conferir segurança jurídica a esta situação -- ilegitimidade passiva daANPpara cobrar eventual restituição de royalties em decorrência de decisão judicial -- do direito fundamental ao cumprimento equânime pelaANPe endividamento de todosos esforços legais dos municípios e dos Tribunais de contas no sentido de recuperação de receitas originárias -- da distinção fundamental entre as categorias de tutela de urgência : análise da questão no tema repetitivo nº 692 do STJ -- da distinção fundamental entre verbas tributárias e as verbas dos royalties distribuídas pelaANP-- da distinção fundamental entre verbas do Fndef/Fundeb e os royalties daANP-- das receitas originárias: como se dá a busca dessas receitas no judiciário e a celebração dos contratos de prestação de serviços jurídicos -- da necessidade de se assegurar o adimplemento da verba de caráter alimentar diante da necessidade diária do município de promover gastos. | Assuntos: Royalties do petróleo, natureza jurídica, Brasil. Tutela de urgência, Brasil. Biocombustível, Brasil. Fundo especial, Brasil. Legitimidade passiva, Brasil. Prestação de serviços, Brasil.', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PÚBLICO - 341::DIREITO ADMINISTRATIVO - 341.3::Domínio Público. Conceito. Domínio Eminente. Domínio Patrimonial - 341.34::Jazidas. Código de Minas - 341.344::Petróleo. Monopólio - 341.3442', 'Sumário:Da natureza jurídica da distribuição dos royalties -- características elementares e legais do fundo especial gerido pelaANP-- da delimitação da discussão a respeito do direito ao recebimento de honorários advocatícios a partir de decisão judicial e a necessidade de se conferir segurança jurídica a esta situação -- ilegitimidade passiva daANPpara cobrar eventual restituição de royalties em decorrência de decisão judicial -- do direito fundamental ao cumprimento equânime pelaANPe endividamento de todosos esforços legais dos municípios e dos Tribunais de contas no sentido de recuperação de receitas originárias -- da distinção fundamental entre as categorias de tutela de urgência : análise da questão no tema repetitivo nº 692 do STJ -- da distinção fundamental entre verbas tributárias e as verbas dos royalties distribuídas pelaANP-- da distinção fundamental entre verbas do Fndef/Fundeb e os royalties daANP-- das receitas originárias: como se dá a busca dessas receitas no judiciário e a celebração dos contratos de prestação de serviços jurídicos -- da necessidade de se assegurar o adimplemento da verba de caráter alimentar diante da necessidade diária do município de promover gastos. | Assuntos: Royalties do petróleo, natureza jurídica, Brasil. Tutela de urgência, Brasil. Biocombustível, Brasil. Fundo especial, Brasil. Legitimidade passiva, Brasil. Prestação de serviços, Brasil.', '', 'Nilo, Edvaldo', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
