INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'A arbitragem como meio de solução de litígios comerciais internacionais envolvendo o petróleo e uma breve análise da cláusula arbitral da sétima rodada de licitações daANP', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2006;1000765424', NULL, '', '', 'doutrina', 'Sumário:Vantagens da arbitragem no direito do comércio internacional: a arbitragem possibilita uma solução mais rápida do que a via tradicional, de recurso ao judiciário. Os árbitros são indicados pelas partes, resultado da confiança neles depositada. A arbitragem possibilita um julgamento mais especializado, por árbitros que se dedicam ao caso com mais atenção. Confidencialidade/procedimento mais amigável. Flexibilidade quanto à escolha/aplicação de lei estrangeira ou princípios gerais de direito para reger o mérito da controvérsia. Flexibilidade quanto à escolha/aplicação de lei estrangeira ou regras de câmaras arbitrais para reger o processo arbitral. A cláusula de arbitragem nos contratos de concessão da sétima rodada de licitação daANP. | Assuntos: Arbitragem comercial internacional, Brasil. Indústria petrolífera, Brasil. {Indústria petrolífera; Petróleo, indústria} Cláusula compromissória, Brasil. Administração da justiça, Brasil. {Administração da justiça; Administração judiciária; Gestão da justiça; Morosidade da justiça} Árbitro direito, Brasil. {Árbitro (direito); Juiz arbitral} Juízo arbitral, Brasil. Autonomia da vontade, Brasil. Ordem jurídica interna, Brasil. Ordem jurídica internacional.', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PÚBLICO - 341::DIREITO INTERNACIONAL PÚBLICO - 341.1::Arbitragem e jurisdição internacional - 341.16::Arbitragem internacional. Justiça arbitral - 341.163', 'Sumário:Vantagens da arbitragem no direito do comércio internacional: a arbitragem possibilita uma solução mais rápida do que a via tradicional, de recurso ao judiciário. Os árbitros são indicados pelas partes, resultado da confiança neles depositada. A arbitragem possibilita um julgamento mais especializado, por árbitros que se dedicam ao caso com mais atenção. Confidencialidade/procedimento mais amigável. Flexibilidade quanto à escolha/aplicação de lei estrangeira ou princípios gerais de direito para reger o mérito da controvérsia. Flexibilidade quanto à escolha/aplicação de lei estrangeira ou regras de câmaras arbitrais para reger o processo arbitral. A cláusula de arbitragem nos contratos de concessão da sétima rodada de licitação daANP. | Assuntos: Arbitragem comercial internacional, Brasil. Indústria petrolífera, Brasil. {Indústria petrolífera; Petróleo, indústria} Cláusula compromissória, Brasil. Administração da justiça, Brasil. {Administração da justiça; Administração judiciária; Gestão da justiça; Morosidade da justiça} Árbitro direito, Brasil. {Árbitro (direito); Juiz arbitral} Juízo arbitral, Brasil. Autonomia da vontade, Brasil. Ordem jurídica interna, Brasil. Ordem jurídica internacional.', '', 'Tiburcio, Carmen', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
