INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Acertificaçãocoletiva', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:livro:2020;001166327', NULL, '', '', 'doutrina', 'Sumário:Processos coletivos : conceitos fundamentais: Conceito de processo coletivo. Grupo e membros do grupo. As tipologias de lítigios coletivos no Brasil e suas repercussões práticas. Instrumentos para a tutela das situações jurídicas coletivas no direito brasileiro -- A importância da "certificação"coletiva na experiência norte-americana: A class action como instrumento de tutela coletiva dos direitos. Os fundamentos da class certification no direito norte-americano. Os requisitos de admissibilidade analisados na class certification. A recorribilidade imediata da decisão de "certificação". A notificação adequada do grupo (notice) -- Da decisão de saneamento e organização dos processos coletivos : em defesa de uma "certificação": A class certification como uma decisão de saneamento e organização do processo. Saneamento processual e a organização do julgamento de casos repetitivos : importância e o papel do regimento interno dos tribunais como fontes suplementares. Conteúdo da decisão: a notificação adequada do grupo e dos seus membros. Conteúdo da decisão : a representatividade adequada nos processos coletivos. Conteúdo da decisão : a participação nos processos coletivos. | Assuntos: Processo civil, Brasil, Estados Unidos. {Processo civil; Direito judiciário civil; Direito processual civil; Justiça civil} Interesse coletivo. {Interesse coletivo; Direito coletivo; Interesse coletivo stricto sensu; Interesse geral; Interesse social} Incidente de resolução de demandas repetitivas. Recurso processo civil. Tutela jurisdicional. {Tutela jurisdicional; Prestação jurisdicional; Tutela jurídica} Ação coletiva. Juízo de admissibilidade. Legitimidade ativa.', '', 'LexML', 'transport_energy', 'Livro', 'Classificação: DIREITO PÚBLICO - 341::DIREITO PROCESSUAL - 341.4::Direito Processual Civil - 341.46', 'Sumário:Processos coletivos : conceitos fundamentais: Conceito de processo coletivo. Grupo e membros do grupo. As tipologias de lítigios coletivos no Brasil e suas repercussões práticas. Instrumentos para a tutela das situações jurídicas coletivas no direito brasileiro -- A importância da "certificação"coletiva na experiência norte-americana: A class action como instrumento de tutela coletiva dos direitos. Os fundamentos da class certification no direito norte-americano. Os requisitos de admissibilidade analisados na class certification. A recorribilidade imediata da decisão de "certificação". A notificação adequada do grupo (notice) -- Da decisão de saneamento e organização dos processos coletivos : em defesa de uma "certificação": A class certification como uma decisão de saneamento e organização do processo. Saneamento processual e a organização do julgamento de casos repetitivos : importância e o papel do regimento interno dos tribunais como fontes suplementares. Conteúdo da decisão: a notificação adequada do grupo e dos seus membros. Conteúdo da decisão : a representatividade adequada nos processos coletivos. Conteúdo da decisão : a participação nos processos coletivos. | Assuntos: Processo civil, Brasil, Estados Unidos. {Processo civil; Direito judiciário civil; Direito processual civil; Justiça civil} Interesse coletivo. {Interesse coletivo; Direito coletivo; Interesse coletivo stricto sensu; Interesse geral; Interesse social} Incidente de resolução de demandas repetitivas. Recurso processo civil. Tutela jurisdicional. {Tutela jurisdicional; Prestação jurisdicional; Tutela jurídica} Ação coletiva. Juízo de admissibilidade. Legitimidade ativa.', '', 'Tavares, João Paulo Lordelo Guimarães', '', '', '{"search_term": "", 