INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Considerações sobre ahomologaçãode sentença arbitral estrangeira após a emenda constitucional 45/04', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:capitulo.livro:2007;1000851181', NULL, '', '', 'doutrina', 'Sumário:O procedimento parahomologaçãode sentença arbitral estrangeira -- Os requisitos parahomologaçãode sentenças arbitrais estrangeiras -- A jurisprudência do Superior Tribunal de Justiça em matéria dehomologaçãode sentença arbitral estrangeira : da vinculação à arbitragem em contrato não assinado pela parte - comparecimento espontâneo da parte ao procedimento arbitral; da limitação das hipóteses de nãohomologação- delibação; ônus da prova no procedimento dehomologação; da citação na arbitragem; da sentença desprovida de requisitos válidos; legitimidade de parte - da cessão de direitos sobre a sentença arbitral estrangeira; da transferência da cláusula compromissória e da aplicação da Lei de arbitragem no tempo; da desnecessidade de caução parahomologaçãode sentença arbitral estrangeira e da validade da cláusula compromissória em contrato de adesão; da ação de anulação de sentença arbitral concomitantemente com pedido dehomologação; da alegação de inexistência de compromisso arbitral; da sentença rasurada, remendo feito à mão. | Assuntos: Homologaçãode sentença estrangeira, Brasil. {Homologaçãode sentença estrangeira; Valor de sentença estrangeira}Homologaçãode sentença estrangeira, jurisprudência, Brasil. {Homologaçãode sentença estrangeira; Valor de sentença estrangeira} Sentença arbitral, Brasil. {Sentença arbitral; Laudo arbitral} Sentença estrangeira, Brasil. {Sentença estrangeira; Sentença judicial estrangeira; Sentença judiciaria estrangeira} Procedimento, B