INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Homologaçãode sentença arbitral estrangeira', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2005;1000756979', NULL, '', '', 'doutrina', 'Resumo:Trata-se do primeiro caso dehomologaçãode sentença estrangeira pelo Superior Tribunal de Justiça depois da reforma do Poder Judiciário, conforme Emenda Constitucional 45/2004. O pedido originário foi ajuizado no Supremo Tribunal Federal em 2003, onde recebeu parecer contrário do Ministério Público. | Assuntos: Homologaçãode sentença estrangeira, direito comparado, Brasil, França. {Homologaçãode sentença estrangeira; Valor de sentença estrangeira} Sentença arbitral, Brasil. {Sentença arbitral; Laudo arbitral} Ordem pública, Brasil. Cláusula compromissória, Brasil. Arbitragem, Brasil. Arbitragem comercial internacional.Homologaçãode sentença estrangeira, Brasil. {Homologaçãode sentença estrangeira; Valor de sentença estrangeira} Cláusula compromissória, Brasil. Boa-fé, Brasil.', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PÚBLICO - 341::DIREITO INTERNACIONAL PÚBLICO - 341.1::Arbitragem e jurisdição internacional - 341.16::Arbitragem internacional. Justiça arbitral - 341.163 | Classificação: DIREITO PRIVADO - 342::DIREITO INTERNACIONAL PRIVADO - 342.3::Homologaçãode sentença estrangeira - 342.36', 'Resumo:Trata-se do primeiro caso dehomologaçãode sentença estrangeira pelo Superior Tribunal de Justiça depois da reforma do Poder Judiciário, conforme Emenda Constitucional 45/2004. O pedido originário foi ajuizado no Supremo Tribunal Federal em 2003, onde recebeu parecer contrário do Ministério Público. | Assuntos: Homologaçãode sentença estrangeira, direito comparado, Brasil, França. {Hom