INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'A ordem pública nahomologaçãode sentenças arbitrais estrangeiras', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2021;1001187893', NULL, '', '', 'doutrina', 'Sumário:A ordem pública interna, a ordem pública internacional e a ordem pública transnacional -- Panorama sobre tratados internacionais anteriores e posteriores à Convenção de Nova Iorque atinentes àhomologaçãode sentenças arbitrais estrangeiras -- A Convenção de Nova Iorque : panorama e análise específica do artigo V, 2, “b” -- A ofensa à ordem pública como causa de denegação dahomologaçãode sentenças arbitrais estrangeiras -- A análise de ofício dos motivos elencados no artigo V(2) da Convenção de Nova Iorque -- Significado da expressão “ordem pública daquele país” do artigo V, 2, “b”, da Convenção de Nova Iorque. | Assuntos: Homologaçãode sentença estrangeira. {Homologaçãode sentença estrangeira; Valor de sentença estrangeira} Sentença arbitral. {Sentença arbitral; Laudo arbitral} Ordem pública. Arbitragem comercial internacional. Cooperação jurídica internacional.', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PRIVADO - 342::DIREITO INTERNACIONAL PRIVADO - 342.3::Homologaçãode sentença estrangeira - 342.36', 'Sumário:A ordem pública interna, a ordem pública internacional e a ordem pública transnacional -- Panorama sobre tratados internacionais anteriores e posteriores à Convenção de Nova Iorque atinentes àhomologaçãode sentenças arbitrais estrangeiras -- A Convenção de Nova Iorque : panorama e análise específica do artigo V, 2, “b” -- A ofensa à ordem pública como causa de denegação dahomologaçãode sentenças arbitrais estrangeiras -- A análise de ofício dos motivos elencados no artigo V(2) da Convenção de Nova Iorque -- Significado da expressão “ordem pública daquele país” do artigo V, 2, “b”, da Convenção de Nova Iorque. | Assuntos: Homologaçãode sentença estrangeira. {Homologaçãode sentença estrangeira; Valor de sentença estrangeira} Sentença arbitral. {Sentença arbitral; Laudo arbitral} Ordem pública. Arbitragem comercial internacional. Cooperação jurídica internacional.', '', 'Fornasar, María Laura', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'A jurisprudência do Superior Tribunal de Justiça nahomologaçãode sentenças arbitrais estrangeiras', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2020;1001188276', NULL, '', '', 'doutrina', 'Sumário:Ahomologaçãode sentenças arbitrais estrangeiras no Superior Tribunal de Justiça: o juízo de delibação adotado pelo Superior Tribunal de Justiça e a legislação aplicável ao procedimento homologatório; parâmetros para a concretização do conceito de ofensa à ordem pública -- Análise de casos: Sentença Estrangeira Contestada 854/US e Sentença Estrangeira Contestada 853/US: competência concorrente, princípio constitucional do acesso à justiça e ordem pública; breve síntese do caso, os fundamentos para ahomologaçãoparcial da sentença estrangeira e o indeferimento dahomologaçãoda sentença arbitral estrangeira. Sentença Estrangeira Contestada 9.412/US: dever de revelação dos árbitros, imparcialidade e a exceção à ordem pública; o caso e o indeferimento dehomologação. | Assuntos: Homologaçãode sentença estrangeira, jurisprudência, Brasil. {Homologaçãode sentença estrangeira; Valor de sentença estrangeira} Sentença arbitral, jurisprudência, Brasil. {Sentença arbitral; Laudo arbitral} Ordem pública, jurisprudência, Brasil.', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PRIVADO - 342::DIREITO INTERNACIONAL PRIVADO - 342.3::Homologaçãode sentença estrangeira - 342.36', 'Sumário:Ahomologaçãode sentenças arbitrais estrangeiras no Superior Tribunal de Justiça: o juízo de delibação adotado pelo Superior Tribunal de Justiça e a legislação aplicável ao procedimento homologatório; parâmetros para a concretização do conceito de ofensa à ordem pública -- Análise de casos: Sentença Estrangeira Contestada 854/US e Sentença Estrangeira Contestada 853/US: competência concorrente, princípio constitucional do acesso à justiça e ordem pública; breve síntese do caso, os fundamentos para ahomologaçãoparcial da sentença estrangeira e o indeferimento dahomologaçãoda sentença arbitral estrangeira. Sentença Estrangeira Contestada 9.412/US: dever de revelação dos árbitros, imparcialidade e a exceção à ordem pública; o caso e o indeferimento dehomologação. | Assuntos: Homologaçãode sentença estrangeira, jurisprudência, Brasil. {Homologaçãode sentença estrangeira; Valor de sentença estrangeira} Sentença arbitral, jurisprudência, Brasil. {Sentença arbitral; Laudo arbitral} Ordem pública, jurisprudência, Brasil.', '', 'Estill, Beatriz Rieche', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Homologaçãode decisões estrangeiras no Brasil', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:livro:2021;001191295', NULL, '', '', 'doutrina', 'Resumo:Trata da Convenção, de 2 de julho de 2019, sobre o reconhecimento e execução de sentenças estrangeiras em matérias civis ou comerciais (Convenção de Sentenças HCCH 2019), que facilita a circulação internacional efetiva de sentenças em matéria civil ou comercial. Ao estabelecer as condições comumente aceitas para o reconhecimento e execução - e os fundamentos acordados para a recusa - a Convenção fornece segurança jurídica e previsibilidade às partes envolvidas em transações internacionais, fornecendo clareza sobre se, e em que medida, uma decisão será reconhecida e executada em outra jurisdição. Ao assegurar o reconhecimento e a execução de sentenças estrangeiras, a Convenção aumenta o acesso à justiça ao reduzir prazos legais, custos e riscos em circunstâncias transfronteiriças. A Convenção favorece um ambiente nacional e internacional positivo para o comércio multilateral, investimento e mobilidade.Sumário:Fundamentos teóricos para o reconhecimento e execução de decisões provenientes de outros Estados -- A Convenção de Senteças da Conferência da Haia (2019) -- As bases indiretas de jurisdição na Convenção de Sentenças -- O sistema dehomologaçãode decisões estrangeiras no Brasil -- Tratamento legal do controle indireto da jurisdição estrangeira no Brasil -- Tratamento jurisprudencial do controle indireto da jurisdição estrangeira no Brasil -- Necessidade do controle indireto da jurisdição estrangeira na ação dehomologação-- Viabilidade de especificação de bases indiretas de jurisdição no Brasil. | Assuntos: Homologaçãode sentença estrangeira, Brasil. {Homologaçãode sentença estrangeira; Valor de sentença estrangeira} Cooperação jurídica internacional, Brasil. Execução de sentença estrangeira, Brasil.', '', 'LexML', 'transport_energy', 'Livro', 'Classificação: DIREITO PRIVADO - 342::DIREITO INTERNACIONAL PRIVADO - 342.3::Homologaçãode sentença estrangeira - 342.36', 'Resumo:Trata da Convenção, de 2 de julho de 2019, sobre o reconhecimento e execução de sentenças estrangeiras em matérias civis ou comerciais (Convenção de Sentenças HCCH 2019), que facilita a circulação internacional efetiva de sentenças em matéria civil ou comercial. Ao estabelecer as condições comumente aceitas para o reconhecimento e execução - e os fundamentos acordados para a recusa - a Convenção fornece segurança jurídica e previsibilidade às partes envolvidas em transações internacionais, fornecendo clareza sobre se, e em que medida, uma decisão será reconhecida e executada em outra jurisdição. Ao assegurar o reconhecimento e a execução de sentenças estrangeiras, a Convenção aumenta o acesso à justiça ao reduzir prazos legais, custos e riscos em circunstâncias transfronteiriças. A Convenção favorece um ambiente nacional e internacional positivo para o comércio multilateral, investimento e mobilidade.Sumário:Fundamentos teóricos para o reconhecimento e execução de decisões provenientes de outros Estados -- A Convenção de Senteças da Conferência da Haia (2019) -- As bases indiretas de jurisdição na Convenção de Sentenças -- O sistema dehomologaçãode decisões estrangeiras no Brasil -- Tratamento legal do controle indireto da jurisdição estrangeira no Brasil -- Tratamento jurisprudencial do controle indireto da jurisdição estrangeira no Brasil -- Necessidade do controle indireto da jurisdição estrangeira na ação dehomologação-- Viabilidade de especificação de bases indiretas de jurisdição no Brasil. | Assuntos: Homologaçãode sentença estrangeira, Brasil. {Homologaçãode sentença estrangeira; Valor de sentença estrangeira} Cooperação jurídica internacional, Brasil. Execução de sentença estrangeira, Brasil.', '', 'Spitz, Lidia', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
