INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Recallno judiciário e a composição do STF', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:livro:2019;001145823', NULL, '', '', 'doutrina', 'Resumo:"A presente obra traz o ineditismo do tema, por sua adaptação ao constitucionalismo brasileiro e com a criação de duas novas subespécies dessa forma de exercício da democracia semidireta (recallrevocatório de decisões judiciais do STF erecalljudicial-político, consistente na revogação popular das nomeações de integrantes do STF). O tema tem sido constantemente ventilado no período constitucional pelo qual atravessa o país (STF, revogação das nomeações e manifestações populares). A obra aborda, ainda, exposição crítica acerca dos aspectos principiológico e doutrinário da separação de poderes e da democracia, coadunando, assim, com o direito de revogação pelo povo."--Sumário:Separação de poderes: situações que justificam orecallnos poderes : Separação dos poderes e aspectos doutrinários. A separação de poderes conformada normativamente. Poder Legislativo: esvaziamento das funções. Poder Executivo: atos de governo sem justiça social. Poder Judiciário: a exacerbação de seus poderes --Recall: o constitucionalismo brasileiro e orecall-- A proposta dorecallno judiciário brasileiro : Ao Supremo Tribunal Federal como limite, o controle de convencionalidade de suas decisões: o "limite do limite".Recallcomo direito fundamental. Definição e proposição de modalidades dorecall.Recallem face das decisões de controle concentrado de constitucionalidade.Recallsobre a nomeação dos membros do Supremo Tribunal Federal. | Assuntos: Controle de convencionalidade, Brasil. Relação executivo-judiciário, Brasil. Relação legislativo-judiciário, Brasil. Tribunal supremo, Brasil. Separação de poderes, Brasil. {Separação de poderes; Equilíbrio dos poderes}', '', 'LexML', 'transport_energy', 'Livro', 'Classificação: DIREITO PÚBLICO - 341::DIREITO CONSTITUCIONAL - 341.2::Soberania. Estado e Governo - 341.23::Separação dos poderes. Equilíbrio dos poderes. Sistema de Governo. Parlamentarismo. Presidencialismo - 341.233', 'Resumo:"A presente obra traz o ineditismo do tema, por sua adaptação ao constitucionalismo brasileiro e com a criação de duas novas subespécies dessa forma de exercício da democracia semidireta (recallrevocatório de decisões judiciais do STF erecalljudicial-político, consistente na revogação popular das nomeações de integrantes do STF). O tema tem sido constantemente ventilado no período constitucional pelo qual atravessa o país (STF, revogação das nomeações e manifestações populares). A obra aborda, ainda, exposição crítica acerca dos aspectos principiológico e doutrinário da separação de poderes e da democracia, coadunando, assim, com o direito de revogação pelo povo."--Sumário:Separação de poderes: situações que justificam orecallnos poderes : Separação dos poderes e aspectos doutrinários. A separação de poderes conformada normativamente. Poder Legislativo: esvaziamento das funções. Poder Executivo: atos de governo sem justiça social. Poder Judiciário: a exacerbação de seus poderes --Recall: o constitucionalismo brasileiro e orecall-- A proposta dorecallno judiciário brasileiro : Ao Supremo Tribunal Federal como limite, o controle de convencionalidade de suas decisões: o "limite do limite".Recallcomo direito fundamental. Definição e proposição de modalidades dorecall.Recallem face das decisões de controle concentrado de constitucionalidade.Recallsobre a nomeação dos membros do Supremo Tribunal Federal. | Assuntos: Controle de convencionalidade, Brasil. Relação executivo-judiciário, Brasil. Relação legislativo-judiciário, Brasil. Tribunal supremo, Brasil. Separação de poderes, Brasil. {Separação de poderes; Equilíbrio dos poderes}', '', 'Braga, Rogério Piccino', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
