INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Contratos de distribuição e revenda decombustíveis', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:livro:2006;000768576', NULL, '', '', 'doutrina', 'Sumário:Do sistema de abastecimento - abordagem panorâmica -- Da flexibilização do monopólio estatal e seus reflexos na indústria do petróleo -- Dos agentes econômicos e da estruturação do mercado decombustíveis-- Comentários específicos à legislação do setor de distribuição e revenda decombustíveis: Da legislação geral do petroléo - Lei 9.478, de 6 de agosto de 1997. Da legislação da distribuidora - Portaria ANP n. 202, de 30 de dezembro de 1999. Da legislação do revendedor - Portaria ANP n. 116, de 5 de setembro de 2000 00-- Da relação comercial entre distribuidora e revendor -- Das condições comerciais, cláusulas abusivas e dos litígios entre distribuidor e revendor -- Outros temas conexos e importantes para o setor: Da adulteração decombustíveisem uma visão ampla. Dopreçodocombustíveis- O revendedor é o "Bode expiatório" do mercado. Da denúncia de cartel dospreçosdoscombustíveis- O papel da SDE -- Da revenda de gás natural veicular. Do posto bandeira branca - uma boa opção. Da tributaçãodoscombustíveis. Do meio ambiente e a obtenção das licenças - Danos ao meio ambiente - riscos. Dos postos em hipermercados - Impedimento ao funcionamento - Inconstitucionalidade - Lei distrital impeditiva - Ação direta de inconstitucionalidade no TJDFT. A arbitragem nos contratos de petróleo - as vantagens da cláusula cheia. | Assuntos: Contrato comercial, Brasil. {Contrato comercial; Contrato (direito comercial)} Franquia comercial, Brasil. {Franquia comercial; Franchising}Combustível, distribuição, Brasil. {Combustível; Carburante} Posto de gasolina, Brasil. Revenda, Brasil.', '', 'LexML', 'transport_energy', 'Livro', 'Classificação: DIREITO PRIVADO - 342::DIREITO COMERCIAL - 342.2::Contratos comerciais - 342.24', 'Sumário:Do sistema de abastecimento - abordagem panorâmica -- Da flexibilização do monopólio estatal e seus reflexos na indústria do petróleo -- Dos agentes econômicos e da estruturação do mercado decombustíveis-- Comentários específicos à legislação do setor de distribuição e revenda decombustíveis: Da legislação geral do petroléo - Lei 9.478, de 6 de agosto de 1997. Da legislação da distribuidora - Portaria ANP n. 202, de 30 de dezembro de 1999. Da legislação do revendedor - Portaria ANP n. 116, de 5 de setembro de 2000 00-- Da relação comercial entre distribuidora e revendor -- Das condições comerciais, cláusulas abusivas e dos litígios entre distribuidor e revendor -- Outros temas conexos e importantes para o setor: Da adulteração decombustíveisem uma visão ampla. Dopreçodocombustíveis- O revendedor é o "Bode expiatório" do mercado. Da denúncia de cartel dospreçosdoscombustíveis- O papel da SDE -- Da revenda de gás natural veicular. Do posto bandeira branca - uma boa opção. Da tributaçãodoscombustíveis. Do meio ambiente e a obtenção das licenças - Danos ao meio ambiente - riscos. Dos postos em hipermercados - Impedimento ao funcionamento - Inconstitucionalidade - Lei distrital impeditiva - Ação direta de inconstitucionalidade no TJDFT. A arbitragem nos contratos de petróleo - as vantagens da cláusula cheia. | Assuntos: Contrato comercial, Brasil. {Contrato comercial; Contrato (direito comercial)} Franquia comercial, Brasil. {Franquia comercial; Franchising}Combustível, distribuição, Brasil. {Combustível; Carburante} Posto de gasolina, Brasil. Revenda, Brasil.', '', 'Silva, Luiz Antonio Guerra da', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
