INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:congresso.nacional:medida.provisoria;mpv:2024;1226', '[ Medida Provisória nº 1226/2024 ]', 'https://www.lexml.gov.br/urn/urn:lex:br:congresso.nacional:medida.provisoria;mpv:2024;1226', NULL, '', '', 'lei', 'Altera a Lei nº 12.351, de 22 de dezembro de 2010, para autorizar a utilização do superávit financeiro do Fundo Social como fonte de recursos para a disponibilização de linhas definanciamentoa pessoas jurídicas e físicas localizadas em ente federativo em estado de calamidade pública, nos termos do art. 65 da Lei Complementar nº 101, de 4 de maio de 2000, autoriza a União a aumentar a sua participação no Fundo Garantidor de Operações para a cobertura das operações contratadas no âmbito do Programa Nacional de Fortalecimento da Agricultura Familiar e do Programa Nacional de Apoio ao Médio Produtor Rural com beneficiários que tiveram perdas materiais nas áreas afetadas pelos eventos climáticos extremos ocorridos nos meses de abril e maio de 2024, e dispõe sobre a subvenção de que trata o art. 2º da Medida Provisória nº 1.216, de 9 de maio de 2024.', '', 'LexML', 'transport_energy', 'Medida Provisória', '', 'Altera a Lei nº 12.351, de 22 de dezembro de 2010, para autorizar a utilização do superávit financeiro do Fundo Social como fonte de recursos para a disponibilização de linhas definanciamentoa pessoas jurídicas e físicas localizadas em ente federativo em estado de calamidade pública, nos termos do art. 65 da Lei Complementar nº 101, de 4 de maio de 2000, autoriza a União a aumentar a sua participação no Fundo Garantidor de Operações para a cobertura das operações contratadas no âmbito do Programa Nacional de Fortalecimento da Agricultura Familiar e do Programa Nacional de Apoio ao Médio Produtor Rural com beneficiários que tiveram perdas materiais nas áreas afetadas pelos eventos climáticos extremos ocorridos nos meses de abril e maio de 2024, e dispõe sobre a subvenção de que trata o art. 2º da Medida Provisória nº 1.216, de 9 de maio de 2024.', '', 'Congresso Nacional', 'Federal', 'Legislativo Federal', '{"search_term": "", "urn_type": "legislation", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:congresso.nacional:medida.provisoria;mpv:2023-09-27;1190', 'MPV 1190/2023', 'https://www.lexml.gov.br/urn/urn:lex:br:congresso.nacional:medida.provisoria;mpv:2023-09-27;1190', '2023-09-27', '', '', 'lei', 'Abre crédito extraordinário, em favor de Encargos Financeiros da União e de Operações Oficiais de Crédito, no valor de R$ 400.000.000,00, para os fins que especifica.', '', 'LexML', 'transport_energy', 'Medida Provisória', '', 'Abre crédito extraordinário, em favor de Encargos Financeiros da União e de Operações Oficiais de Crédito, no valor de R$ 400.000.000,00, para os fins que especifica.', '', 'Congresso Nacional', 'Federal', 'Legislativo Federal', '{"search_term": "", "urn_type": "legislation", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Financiamentos', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2017;1001115902', NULL, '', '', 'doutrina', 'Resumo:"O presente trabalho desenvolver-se-á pautado na premissa de que as instituições financeiras devem implementar de forma substancial suas Políticas de Responsabilidade Socioambiental, devendo, por ocasião da análise dos projetos de concessão definanciamento, bem como durante a execução dos contratos definanciamentosjá firmados, não se limitar à análise contábil e formal, mas sim realizar uma análise substancial das variáveis econômica, social e ambiental envolvidas, de forma a determinar, dentro de uma faixa estreita de riscos aceitáveis pelo poder público e pela coletividade, quais riscos ambientais serão tolerados durante o desenvolvimento do empreendimento objeto dofinanciamento, como forma de cumprir com o dever constitucional de proteção do equilíbrio ambiental e, assim, evitar sua responsabilização civil pelos eventuais danos ambientais causados pelo empreendimento financiado". | Assuntos: Responsabilidade socioambiental, Brasil.Financiamento, Brasil.', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PRIVADO - 342::DIREITO COMERCIAL - 342.2::Instituições comerciais. Mercado de capitais - 342.23::Direito bancário - 342.234', 'Resumo:"O presente trabalho desenvolver-se-á pautado na premissa de que as instituições financeiras devem implementar de forma substancial suas Políticas de Responsabilidade Socioambiental, devendo, por ocasião da análise dos projetos de concessão definanciamento, bem como durante a execução dos contratos definanciamentosjá firmados, não se limitar à análise contábil e formal, mas sim realizar uma análise substancial das variáveis econômica, social e ambiental envolvidas, de forma a determinar, dentro de uma faixa estreita de riscos aceitáveis pelo poder público e pela coletividade, quais riscos ambientais serão tolerados durante o desenvolvimento do empreendimento objeto dofinanciamento, como forma de cumprir com o dever constitucional de proteção do equilíbrio ambiental e, assim, evitar sua responsabilização civil pelos eventuais danos ambientais causados pelo empreendimento financiado". | Assuntos: Responsabilidade socioambiental, Brasil.Financiamento, Brasil.', '', 'Messias, Ewerton Ricardo', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Anais do Seminário aspectos jurídicos e econômicos do sistema definanciamentoimobiliário', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:livro:1999;000582051', NULL, '', '', 'doutrina', 'Sumário:Atividade imobiliária / Arthur Parkinson -- Elementos fundamentais da alienação fiduciária do bem imóvel / Mehlim Namem Chalub-- A Lei 9514 como instrumento de direito econômico e do direito do desenvolvimento / Arnoldo Wald, Enrique Ricardo Lewandowski -- Aplicação de recursos no mercado imobiliário: a experiência européia / Diogo Leite de Campos. A experiência americana / Peter Messitte, Robert F. Mc.Donough -- A importância do equilíbrio econômico-financeiro nos contratos definanciamentoimobiliário / Sérgio Cutolo dos Santos, Sérgio Darcy da Silva Alves -- Alienação fiduciária de bens imóveis - aspectos de direito material / José Carlos Moreira Alves -- Sistema definanciamentoimobiliário - aspectos processuais e constitucionais / Ilmar do Nascimento Galvão -- Sistema definanciamentoimobiliário - interpretação sistemática da Lei 9514/97 com o Código de Defesa do Consumidor / Alvaro Villaça de Azevedo -- Rescisão na promessa da compra e venda imobiliária / Mailson da Nóbrega -- A dimensão do desafio da habitação e o SFI / Emílio H. Carazzai Sobrinho -- Mercado americano de Mortgages / Raul Leite Luna -- O judiciário e o social / Marcio Fernandes. | Assuntos: Compra e venda, Brasil. {Compra e venda; Compra e venda (direito civil); Venda (direito civil)} Direito imobiliário, Brasil. {Direito imobiliário; Direito predial; Direito sobre bens imóveis}Financiamentohabitacional, Brasil. {Financiamentohabitacional; Casa própria,financiamento; Habitação,financiamento; Imóvel residencial,financiamento} Mercado imobiliário, Brasil. Alienação fiduciária, Brasil. {Alienação fiduciária; Alienação fiduciária em garantia}', '', 'LexML', 'transport_energy', 'Livro', 'Classificação: DIREITO PRIVADO - 342::DIREITO CIVIL - 342.1::Direitos reais. Coisas ou bens - 342.12::Coisas ou bens. Suas divisões - 342.121::Coisas ou bens móveis e imóveis - 342.1214::Imóveis - 342.12142', 'Sumário:Atividade imobiliária / Arthur Parkinson -- Elementos fundamentais da alienação fiduciária do bem imóvel / Mehlim Namem Chalub-- A Lei 9514 como instrumento de direito econômico e do direito do desenvolvimento / Arnoldo Wald, Enrique Ricardo Lewandowski -- Aplicação de recursos no mercado imobiliário: a experiência européia / Diogo Leite de Campos. A experiência americana / Peter Messitte, Robert F. Mc.Donough -- A importância do equilíbrio econômico-financeiro nos contratos definanciamentoimobiliário / Sérgio Cutolo dos Santos, Sérgio Darcy da Silva Alves -- Alienação fiduciária de bens imóveis - aspectos de direito material / José Carlos Moreira Alves -- Sistema definanciamentoimobiliário - aspectos processuais e constitucionais / Ilmar do Nascimento Galvão -- Sistema definanciamentoimobiliário - interpretação sistemática da Lei 9514/97 com o Código de Defesa do Consumidor / Alvaro Villaça de Azevedo -- Rescisão na promessa da compra e venda imobiliária / Mailson da Nóbrega -- A dimensão do desafio da habitação e o SFI / Emílio H. Carazzai Sobrinho -- Mercado americano de Mortgages / Raul Leite Luna -- O judiciário e o social / Marcio Fernandes. | Assuntos: Compra e venda, Brasil. {Compra e venda; Compra e venda (direito civil); Venda (direito civil)} Direito imobiliário, Brasil. {Direito imobiliário; Direito predial; Direito sobre bens imóveis}Financiamentohabitacional, Brasil. {Financiamentohabitacional; Casa própria,financiamento; Habitação,financiamento; Imóvel residencial,financiamento} Mercado imobiliário, Brasil. Alienação fiduciária, Brasil. {Alienação fiduciária; Alienação fiduciária em garantia}', '', 'Seminário Aspectos Jurídicos e Econômicos do Sistema deFinanciamentoImobiliário (1999', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Ofinanciamentoda política', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:livro:2014;001008289', NULL, '', '', 'doutrina', 'Resumo:Estudo comparado sobre o tratamento dado aofinanciamentodos partidos políticos no direito da Alemanha, Espanha, Estados Unidos e Itália.Sumário:Relação entre democracia e o direito de partidos nas sociedades modernas -- Ofinanciamentode partidos políticos dentro do direito dos partidos -- A difícil decisão de fixar um ponto de equilibrio - ofinanciamentocomo tendência: Os modelos paradigmáticos. Estados Unidos da América. Alemanha. Itália. Espanha -- O desequilíbrio entre ofinanciamentopúblico e o privado e as suas consequências. | Assuntos: Campanha eleitoral,financiamento, direito comparado. {Campanha eleitoral; Campanha política} Corrupção na política. Partido político,financiamento, direito comparado. {Partido político; Sociedade política} Partido político,financiamento. {Partido político; Sociedade política} Campanha eleitoral,financiamento. {Campanha eleitoral; Campanha política} Campanha eleitoral,financiamento, direito comparado. {Campanha eleitoral; Campanha política} Corrupção na política. Partido político,financiamento, direito comparado. {Partido político; Sociedade política} Partido político,financiamento. {Partido político; Sociedade política} Campanha eleitoral,financiamento. {Campanha eleitoral; Campanha política}', '', 'LexML', 'transport_energy', 'Livro', 'Classificação: DIREITO PÚBLICO - 341::DIREITO CONSTITUCIONAL - 341.2::Partidos políticos - 341.29', 'Resumo:Estudo comparado sobre o tratamento dado aofinanciamentodos partidos políticos no direito da Alemanha, Espanha, Estados Unidos e Itália.Sumário:Relação entre democracia e o direito de partidos nas sociedades modernas -- Ofinanciamentode partidos políticos dentro do direito dos partidos -- A difícil decisão de fixar um ponto de equilibrio - ofinanciamentocomo tendência: Os modelos paradigmáticos. Estados Unidos da América. Alemanha. Itália. Espanha -- O desequilíbrio entre ofinanciamentopúblico e o privado e as suas consequências. | Assuntos: Campanha eleitoral,financiamento, direito comparado. {Campanha eleitoral; Campanha política} Corrupção na política. Partido político,financiamento, direito comparado. {Partido político; Sociedade política} Partido político,financiamento. {Partido político; Sociedade política} Campanha eleitoral,financiamento. {Campanha eleitoral; Campanha política} Campanha eleitoral,financiamento, direito comparado. {Campanha eleitoral; Campanha política} Corrupção na política. Partido político,financiamento, direito comparado. {Partido político; Sociedade política} Partido político,financiamento. {Partido político; Sociedade política} Campanha eleitoral,financiamento. {Campanha eleitoral; Campanha política}', '', 'Santano, Ana Claudia', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
