INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'As finanças doBNDES', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2009;1000895053', NULL, '', '', 'doutrina', 'Resumo:"Este artigo analisa a evolução das finanças doBNDESna atual década e discute suas perspectivas ao longo dos próximos anos. Mostra-se que os resultados doBNDEStêm sido associados ao retorno da renda variável e que os recursos líquidos do FAT estão escasseando. O artigo discute as incertezas associadas à continuidade do financiamento por parte do Tesouro na próxima década e conclui que, se oBNDESquiser continuar sua expansão, terá de se engajar em um intenso programa de novas captações, na década de 2010." | Assuntos: Desenvolvimento econômico, Brasil. Financiamento, Brasil. Banco nacional, finanças, Brasil.', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PÚBLICO - 341::DIREITO ADMINISTRATIVO - 341.3::Direito Financeiro - 341.38', 'Resumo:"Este artigo analisa a evolução das finanças doBNDESna atual década e discute suas perspectivas ao longo dos próximos anos. Mostra-se que os resultados doBNDEStêm sido associados ao retorno da renda variável e que os recursos líquidos do FAT estão escasseando. O artigo discute as incertezas associadas à continuidade do financiamento por parte do Tesouro na próxima década e conclui que, se oBNDESquiser continuar sua expansão, terá de se engajar em um intenso programa de novas captações, na década de 2010." | Assuntos: Desenvolvimento econômico, Brasil. Financiamento, Brasil. Banco nacional, finanças, Brasil.', '', 'Giambiagi, Fabio', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Contratos de financiamento do sistemaBNDES', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2018;1001132489', NULL, '', '', 'doutrina', 'Sumário:O financiamento do SistemaBNDES: Financiamento com apoio indireto. Financiamento com apoio direto -- As posições jurídicas subjetivas ativas de titularidade doBNDESenquanto credor e os impactos sobre o controle societário e o controle empresarial da beneficiária. | Assuntos: Controle acionário, Brasil. Credor, direitos e deveres, Brasil. {Credor; Devedores e credores} Financiamento bancário, Brasil. Sociedade anônima, financiamento, Brasil. {Sociedade anônima; Companhias; Sociedade por ações} Contrato de financiamento, Brasil.', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PRIVADO - 342::DIREITO COMERCIAL - 342.2', 'Sumário:O financiamento do SistemaBNDES: Financiamento com apoio indireto. Financiamento com apoio direto -- As posições jurídicas subjetivas ativas de titularidade doBNDESenquanto credor e os impactos sobre o controle societário e o controle empresarial da beneficiária. | Assuntos: Controle acionário, Brasil. Credor, direitos e deveres, Brasil. {Credor; Devedores e credores} Financiamento bancário, Brasil. Sociedade anônima, financiamento, Brasil. {Sociedade anônima; Companhias; Sociedade por ações} Contrato de financiamento, Brasil.', '', 'Ramunno, Pedro A. L', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'O papel doBNDESna economia brasileira', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2008;1000832616', NULL, '', '', 'doutrina', 'Resumo:Apresenta tabelas e gráficos :BNDESem perspectiva com bancos de desenvolvimento internacionais; crescimento do PIB e da FBCF (var. % (trim./trim. - 2004-2008); taxa de crescimento real do crédito ao setor privado, por atividade econômica (jan/04-jan/08); emissões primárias de debêntures e ações; emissões primárias - destinação dos recursos; desembolsos e aprovações doBNDES- R$ Bilhões (dados acumulados em 12 meses).Sumário:Transformações recentes da economia brasileira e o financiamento de longo prazo --BNDESe o financiamento de longo prazo ante as tranformações recentes nos mercados de crédito e de capitais. | Assuntos: Banco de desenvolvimento, história, Brasil. Crescimento econômico, Brasil. Desenvolvimento econômico, Brasil. Estabilização econômica, Brasil. Investimento público, Brasil. Macroeconomia, Brasil. Mercado de capitais, Brasil. {Mercado de capitais; Mercado de ações; Mercado de títulos; Mercado de valores} Crédito bancário, Brasil. {Crédito bancário; Crédito (direito bancário)}', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PRIVADO - 342::DIREITO COMERCIAL - 342.2::Instituições comerciais. Mercado de capitais - 342.23::Direito bancário - 342.234::Bancos de desenvolvimento - 342.2346', 'Resumo:Apresenta tabelas e gráficos :BNDESem perspectiva com bancos de desenvolvimento internacionais; crescimento do PIB e da FBCF (var. % (trim./trim. - 2004-2008); taxa de crescimento real do crédito ao setor privado, por atividade econômica (jan/04-jan/08); emissões primárias de debêntures e ações; emissões primárias - destinação dos recursos; desembolsos e aprovações doBNDES- R$ Bilhões (dados acumulados em 12 meses).Sumário:Transformações recentes da economia brasileira e o financiamento de longo prazo --BNDESe o financiamento de longo prazo ante as tranformações recentes nos mercados de crédito e de capitais. | Assuntos: Banco de desenvolvimento, história, Brasil. Crescimento econômico, Brasil. Desenvolvimento econômico, Brasil. Estabilização econômica, Brasil. Investimento público, Brasil. Macroeconomia, Brasil. Mercado de capitais, Brasil. {Mercado de capitais; Mercado de ações; Mercado de títulos; Mercado de valores} Crédito bancário, Brasil. {Crédito bancário; Crédito (direito bancário)}', '', 'Coutinho, Luciano, 1946', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
