INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Avaliação de impacto do uso do cartãoBNDESsobre o emprego nas empresas de menor porte', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2011;1000928055', NULL, '', '', 'doutrina', 'Resumo:"Este estudo avalia o impacto do uso do CartãoBNDESsobre o crescimento do emprego nas empresas que utilizaram esse instrumento de crédito para a realização de aquisições durante o ano de 2008. O cartão consiste num limite de crédito concedido para as empresas de menor porte, que visa atuar nos problemas de financiamento enfrentados por esse grupo de firmas. Foram utilizados dados doBNDESrelativos às firmas que utilizaram o cartão e àquelas que tiveram o cartão emitido e não o utilizaram (grupo de comparação para as firmas apoiadas) e da Relação Anual de Informações Sociais do MTE, que forneceu os dados do estoque de empregados das firmas ao longo do período 2007-2009. O método de diferença-em-diferenças foi empregado para a estimação do impacto do cartão sobre a evolução do emprego das firmas durante esse período. Em sua aplicação, foram considerados os impactos por porte e para dois períodos de observação dos efeitos: 2007-2008 e 2007-2009. Os resultados obtidos contribuem para a discussão da importância do crédito público para as empresas de menor porte e para o entendimento de como o acesso ao crédito pode permitir o crescimento dessas firmas". | Assuntos: Emprego teoria econômica, análise comparativa, Brasil. Pequena empresa, política, Brasil. {Pequena empresa; Empresa de pequeno porte; Empresa pequena; EPP} Crédito público, aspectos econômicos, Brasil.', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PÚBLICO - 341::DIREITO ADMINISTRATIVO - 341.3::Direito Financeiro - 341.38::Crédito Público - 341.386', 'Resumo:"Este estudo avalia o impacto do uso do CartãoBNDESsobre o crescimento do emprego nas empresas que utilizaram esse instrumento de crédito para a realização de aquisições durante o ano de 2008. O cartão consiste num limite de crédito concedido para as empresas de menor porte, que visa atuar nos problemas de financiamento enfrentados por esse grupo de firmas. Foram utilizados dados doBNDESrelativos às firmas que utilizaram o cartão e àquelas que tiveram o cartão emitido e não o utilizaram (grupo de comparação para as firmas apoiadas) e da Relação Anual de Informações Sociais do MTE, que forneceu os dados do estoque de empregados das firmas ao longo do período 2007-2009. O método de diferença-em-diferenças foi empregado para a estimação do impacto do cartão sobre a evolução do emprego das firmas durante esse período. Em sua aplicação, foram considerados os impactos por porte e para dois períodos de observação dos efeitos: 2007-2008 e 2007-2009. Os resultados obtidos contribuem para a discussão da importância do crédito público para as empresas de menor porte e para o entendimento de como o acesso ao crédito pode permitir o crescimento dessas firmas". | Assuntos: Emprego teoria econômica, análise comparativa, Brasil. Pequena empresa, política, Brasil. {Pequena empresa; Empresa de pequeno porte; Empresa pequena; EPP} Crédito público, aspectos econômicos, Brasil.', '', 'Machado, Luciano', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Efeitos doBNDESFiname nas firmas brasileiras', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2021;1001201022', NULL, '', '', 'doutrina', 'Assuntos: Crédito industrial, Brasil, 2002-2016.', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PRIVADO - 342::DIREITO COMERCIAL - 342.2::Contratos comerciais - 342.24::Títulos de crédito - 342.245::Títulos de crédito industrial - 342.2459', 'Assuntos: Crédito industrial, Brasil, 2002-2016.', '', 'Silva, Napoleão', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
