INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'A concorrência pública na parceria público-privada (PPP)', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:livro:2006;000764639', NULL, '', '', 'doutrina', 'Sumário:A parceria público-privada: O contrato da parceria público-privada. APPPe a união federal: O fundo garantidor de parcerias público-privadas- FGP -- A licitação e os princípios jurídicos: Os princípios relevantes a licitação. Os princípios jurídicos caros à administração pública. Os princípios relevantes especificamente para o processo licitatório -- A concorrência pública: Os parceiros naPPP. A comissão de licitação. O processo licitatório - fases -- A fase precedente ao processo licitatório em sentido estrito -- As fases do processo licitatório, em sentido estrito: O edital. O aviso. A entrega de documentos e propostas. Habilitação. As propostas. O julgamento das propostas. A homologação. A adjudicação. A anulação e revogação -- O processo administrativo-licitatório e os recursos administrativos. | Assuntos: Concorrência pública, Brasil. Parceria público-privadaPPP, legislação, Brasil. {Parceria público-privada (PPP); Parceria público-privada;PPP} Licitação, Brasil. Recurso administrativo, Brasil. {Recurso administrativo; Recurso (direito administrativo); Recurso (processo administrativo)} Princípio jurídico, Brasil. {Princípio jurídico; Princípios jurídicos} Concessão de serviços públicos, Brasil. {Concessão de serviços públicos; Concessão (direito administrativo); Concessão administrativa; Concessão de serviço público; Serviços públicos concedidos}', '', 'LexML', 'transport_energy', 'Livro', 'Classificação: DIREITO PÚBLICO - 341::DIREITO ADMINISTRATIVO - 341.3::Atos administrativos - 341.35::Concessão, permissão, autorização de serviço público - 341.353', 'Sumário:A parceria público-privada: O contrato da parceria público-privada. APPPe a união federal: O fundo garantidor de parcerias público-privadas- FGP -- A licitação e os princípios jurídicos: Os princípios relevantes a licitação. Os princípios jurídicos caros à administração pública. Os princípios relevantes especificamente para o processo licitatório -- A concorrência pública: Os parceiros naPPP. A comissão de licitação. O processo licitatório - fases -- A fase precedente ao processo licitatório em sentido estrito -- As fases do processo licitatório, em sentido estrito: O edital. O aviso. A entrega de documentos e propostas. Habilitação. As propostas. O julgamento das propostas. A homologação. A adjudicação. A anulação e revogação -- O processo administrativo-licitatório e os recursos administrativos. | Assuntos: Concorrência pública, Brasil. Parceria público-privadaPPP, legislação, Brasil. {Parceria público-privada (PPP); Parceria público-privada;PPP} Licitação, Brasil. Recurso administrativo, Brasil. {Recurso administrativo; Recurso (direito administrativo); Recurso (processo administrativo)} Princípio jurídico, Brasil. {Princípio jurídico; Princípios jurídicos} Concessão de serviços públicos, Brasil. {Concessão de serviços públicos; Concessão (direito administrativo); Concessão administrativa; Concessão de serviço público; Serviços públicos concedidos}', '', 'Pestana, Márcio', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
