INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Propostas legislativas de novomarcoregulatóriodo pré-sal', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2010;1000888537', NULL, '', '', 'doutrina', 'Resumo:Analisa a constitucionalidade dos projetos de lei de iniciativa do Presidente da República, que pretendem instituir ummarcoregulatóriopara contratos de exploração do monopólio do petróleo. | Assuntos: Petróleo submarino, exploração, aspectos constitucionais, Brasil. Petróleo submarino, exploração, projeto de lei, Brasil.', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PÚBLICO - 341::DIREITO CONSTITUCIONAL - 341.2', 'Resumo:Analisa a constitucionalidade dos projetos de lei de iniciativa do Presidente da República, que pretendem instituir ummarcoregulatóriopara contratos de exploração do monopólio do petróleo. | Assuntos: Petróleo submarino, exploração, aspectos constitucionais, Brasil. Petróleo submarino, exploração, projeto de lei, Brasil.', '', 'Souto,MarcosJuruena Villela, 1963', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'A Pré-Sal Petróleo S.A. e o novomarcoregulatóriobrasileiro', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2013;1001067735', NULL, '', '', 'doutrina', 'Resumo:Estuda a empresa estatal Pré-Sal Petróleo S.A. (PPSA) no contexto do pré-sal a fim de compreender as funções regulatórias desempenhadas pela empresa na exploração e produção de petróleo e gás natural, assim como estabelecer o ambiente de atuação da PPSA dentro do novomarcoregulatório. São examinadas as características gerais do novomarcoregulatórioelaborado para a região do pré-sal e realiza estudo em específico sobre o papel a ser desempenhado pela PPSA no âmbito do pré-sal. Conclui com críticas e sugestões sobre a atuação da nova empresa estatal no contexto domarcoregulatórioestabelecido em face do pré-sal, de modo a garantir maior eficiência regulatória ao setor.Sumário:O pré-sal -- Breves considerações sobre o novomarcoregulatório: A cessão onerosa e capitalização da Petrobrás. Contratos de partilha de produção. Fundo social -- A criação da nova empresa estatal - a PPSA. | Assuntos: Empresa de petróleo, criação, Brasil. Petróleo submarino, exploração, Brasil. Petróleo, regulação, Brasil. {Petróleo; Óleo cru}', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PÚBLICO - 341::DIREITO ADMINISTRATIVO - 341.3::Domínio Público. Conceito. Domínio Eminente. Domínio Patrimonial - 341.34::Jazidas. Código de Minas - 341.344::Petróleo. Monopólio - 341.3442', 'Resumo:Estuda a empresa estatal Pré-Sal Petróleo S.A. (PPSA) no contexto do pré-sal a fim de compreender as funções regulatórias desempenhadas pela empresa na exploração e produção de petróleo e gás natural, assim como estabelecer o ambiente de atuação da PPSA dentro do novomarcoregulatório. São examinadas as características gerais do novomarcoregulatórioelaborado para a região do pré-sal e realiza estudo em específico sobre o papel a ser desempenhado pela PPSA no âmbito do pré-sal. Conclui com críticas e sugestões sobre a atuação da nova empresa estatal no contexto domarcoregulatórioestabelecido em face do pré-sal, de modo a garantir maior eficiência regulatória ao setor.Sumário:O pré-sal -- Breves considerações sobre o novomarcoregulatório: A cessão onerosa e capitalização da Petrobrás. Contratos de partilha de produção. Fundo social -- A criação da nova empresa estatal - a PPSA. | Assuntos: Empresa de petróleo, criação, Brasil. Petróleo submarino, exploração, Brasil. Petróleo, regulação, Brasil. {Petróleo; Óleo cru}', '', 'Bulhões, Daniel Bruno Damasceno', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'As mudanças que omarcoregulatóriotrouxe para as organizações alternativas', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2020;1001179711', NULL, '', '', 'doutrina', 'Assuntos: Organizações da sociedade civil, Brasil.Marcoregulatório, Brasil. Parceria público-privada PPP, Brasil. {Parceria público-privada (PPP); Parceria público-privada; PPP} Organização da sociedade civil OSC, Brasil.', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PÚBLICO - 341::DIREITO ADMINISTRATIVO - 341.3::Atos administrativos - 341.35::Concessão, permissão, autorização de serviço público - 341.353', 'Assuntos: Organizações da sociedade civil, Brasil.Marcoregulatório, Brasil. Parceria público-privada PPP, Brasil. {Parceria público-privada (PPP); Parceria público-privada; PPP} Organização da sociedade civil OSC, Brasil.', '', 'Starosky Filho, Loriberto', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Omarcoregulatóriodos serviços públicos', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2004;2000775116', NULL, '', '', 'doutrina', 'Sumário:Conceito demarcoregulatório-- Normas voltadas à realização de objetivos concretos (instrumentalidade) -- Abertura à consensualidade (acordos regulatórios) -- Normas que dialogam com os subsistemas regulados (intersistematicidade) -- Organização em redes normativas (reticularidade). | Assuntos: Serviços públicos, regulação, Brasil. {Serviços públicos; Atividade essencial; Serviço de infraestrutura; Serviço público prestado; Serviços essenciais; Serviços públicos essenciais} Agência reguladora, Brasil. Concessão de serviços públicos, Brasil. {Concessão de serviços públicos; Concessão (direito administrativo); Concessão administrativa; Concessão de serviço público; Serviços públicos concedidos} Serviços públicos, regulação, Brasil. {Serviços públicos; Atividade essencial; Serviço de infraestrutura; Serviço público prestado; Serviços essenciais; Serviços públicos essenciais} Agência reguladora, Brasil. Concessão de serviços públicos, Brasil. {Concessão de serviços públicos; Concessão (direito administrativo); Concessão administrativa; Concessão de serviço público; Serviços públicos concedidos}', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PÚBLICO - 341::DIREITO ADMINISTRATIVO - 341.3', 'Sumário:Conceito demarcoregulatório-- Normas voltadas à realização de objetivos concretos (instrumentalidade) -- Abertura à consensualidade (acordos regulatórios) -- Normas que dialogam com os subsistemas regulados (intersistematicidade) -- Organização em redes normativas (reticularidade). | Assuntos: Serviços públicos, regulação, Brasil. {Serviços públicos; Atividade essencial; Serviço de infraestrutura; Serviço público prestado; Serviços essenciais; Serviços públicos essenciais} Agência reguladora, Brasil. Concessão de serviços públicos, Brasil. {Concessão de serviços públicos; Concessão (direito administrativo); Concessão administrativa; Concessão de serviço público; Serviços públicos concedidos} Serviços públicos, regulação, Brasil. {Serviços públicos; Atividade essencial; Serviço de infraestrutura; Serviço público prestado; Serviços essenciais; Serviços públicos essenciais} Agência reguladora, Brasil. Concessão de serviços públicos, Brasil. {Concessão de serviços públicos; Concessão (direito administrativo); Concessão administrativa; Concessão de serviço público; Serviços públicos concedidos}', '', 'Aragão, Alexandre Santos de, 1969', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Terceirização, trabalho temporário & o novomarcoregulatório', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:livro:2017;001110200', NULL, '', '', 'doutrina', 'Sumário:Terceirização e trabalho temporário: o novomarcoregulatório: Uma breve contextualização histórico-social. A terceirização : A trajetória da terceirização. A conformação do processo de terceirização. A "nova teoria contratual". A conexidade contratual. As várias facetas da terceirização. Igualdade de direito entre trabalhadores permanentes e terceirizados. Da responsabilidade na terceirização. A "terceirização em geral" sob o viés da lei 13.429/2017 (com as alterações da lei 13.467/2017). O contrato de trabalho temporário. Considerações finais. Referências. Índice alfabético. | Assuntos: Contrato de trabalho, Brasil. {Contrato de trabalho; Contrato (direito do trabalho); Contrato cogente} Terceirização, jurisprudência, Brasil. Terceirização, legislação, Brasil. Trabalho temporário, Brasil. Terceirização, Brasil.', '', 'LexML', 'transport_energy', 'Livro', 'Classificação: DIREITO PRIVADO - 342::DIREITO DO TRABALHO - 342.6::Contrato individual de Trabalho - 342.65::Modalidades de contrato de trabalho - 342.651::Contrato coletivo ou de equipe - 342.6516', 'Sumário:Terceirização e trabalho temporário: o novomarcoregulatório: Uma breve contextualização histórico-social. A terceirização : A trajetória da terceirização. A conformação do processo de terceirização. A "nova teoria contratual". A conexidade contratual. As várias facetas da terceirização. Igualdade de direito entre trabalhadores permanentes e terceirizados. Da responsabilidade na terceirização. A "terceirização em geral" sob o viés da lei 13.429/2017 (com as alterações da lei 13.467/2017). O contrato de trabalho temporário. Considerações finais. Referências. Índice alfabético. | Assuntos: Contrato de trabalho, Brasil. {Contrato de trabalho; Contrato (direito do trabalho); Contrato cogente} Terceirização, jurisprudência, Brasil. Terceirização, legislação, Brasil. Trabalho temporário, Brasil. Terceirização, Brasil.', '', 'Vecchi, Ipojucan Demétrius', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'O setor portuário e o novomarcoregulatório', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2013;1000994451', NULL, '', '', 'doutrina', 'Sumário:Considerações gerais sobre portos -- Visão panorâmica sobre a estruturação jurídica do setor portuário antes da constituição de 1988 -- O setor portuário na constituição de 1988 -- Visão panorâmica sobre a estruturação jurídica do setor portuário sob a vigência da Lei Federal nº 8.630/93 -- O setor portuário brasileiro a partir da Lei nº 12.815/13. | Assuntos: Administração portuária, legislação, Brasil. {Administração portuária; Porto, administração} Porto, arrendamento, Brasil. {Porto; Terminal portuário} Porto, regulação, Brasil. {Porto; Terminal portuário} Porto, exploração, Brasil. {Porto; Terminal portuário}', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PÚBLICO - 341', 'Sumário:Considerações gerais sobre portos -- Visão panorâmica sobre a estruturação jurídica do setor portuário antes da constituição de 1988 -- O setor portuário na constituição de 1988 -- Visão panorâmica sobre a estruturação jurídica do setor portuário sob a vigência da Lei Federal nº 8.630/93 -- O setor portuário brasileiro a partir da Lei nº 12.815/13. | Assuntos: Administração portuária, legislação, Brasil. {Administração portuária; Porto, administração} Porto, arrendamento, Brasil. {Porto; Terminal portuário} Porto, regulação, Brasil. {Porto; Terminal portuário} Porto, exploração, Brasil. {Porto; Terminal portuário}', '', 'Gomes,MarcosPinto Correia', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
