INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'O direito dasagênciasreguladorasindependentes', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:livro:2002;000627998', NULL, '', '', 'doutrina', 'Resumo:Análise comparativa deagênciareguladoranos seguintes países: Estados Unidos, França, Itália, Inglaterra e União Européia.Resumo:Investiga os modelos adotados no exterior, na implantação deagênciasreguladorasindependentes. Discute essa implantação no Brasil enfocando o sistema constitucional nacional, sem deixar de reconhecer a necessidade de modernização das estruturas governamentais.Sumário:A concepção de um Estado "Regulador": A aplicação da "Teoria dos Jogos". Os "Tipos Regulatórios" de Vital Moreira -- Asagênciasreguladorasindependentes -- AsAgênciasno direito brasileiro -- O controle da atuação dasagências. | Assuntos: Agênciareguladora, análise comparativa.Agênciareguladora, competência, Brasil.Agênciareguladora, controle, Brasil.Agênciareguladora, Brasil.', '', 'LexML', 'transport_energy', 'Livro', 'Classificação: DIREITO PÚBLICO - 341::DIREITO ADMINISTRATIVO - 341.3::Serviços Públicos - 341.32::Execução Indireta. Órgãos da Administração indireta - 341.322::AgênciasReguladoras- 341.3221', 'Resumo:Análise comparativa deagênciareguladoranos seguintes países: Estados Unidos, França, Itália, Inglaterra e União Européia.Resumo:Investiga os modelos adotados no exterior, na implantação deagênciasreguladorasindependentes. Discute essa implantação no Brasil enfocando o sistema constitucional nacional, sem deixar de reconhecer a necessidade de modernização das estruturas governamentais.Sumário:A concepção de um Estado "Regulador": A aplicação da "Teoria dos Jogos". Os "Tipos Regulatórios" de Vital Moreira -- Asagênciasreguladorasindependentes -- AsAgênciasno direito brasileiro -- O controle da atuação dasagências. | Assuntos: Agênciareguladora, análise comparativa.Agênciareguladora, competência, Brasil.Agênciareguladora, controle, Brasil.Agênciareguladora, Brasil.', '', 'Justen Filho, Marçal, 1955', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
