INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Os incentivos fiscais da Lei nº 11.196/2005 e o caso da subcontratação das atividades depesquisaedesenvolvimento', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2013;1000988203', NULL, '', '', 'doutrina', 'Sumário:O incentivo aodesenvolvimentonacional como princípio constitucional matriz do princípio dodesenvolvimentocientífico e tecnológico : a autonomia tecnológica do país como finalidade do regime de benefícios e a territorialidade da inovação incentivada -- O regime de incentivos à inovação da lei nª 11.196/2005, Art. 19 : a regra de apropriação do benefício fiscal de exclusão de 60% das despesas dedutíveis compesquisaedesenvolvimento. Os requisitos para a apropriação de benefícios na hipótese de subcontratação de serviços de P&D: regime da Lei vs. IN nº 1.187/2011. A aplicação da IN nº 1.187/2011 sob o influxo dos princípios constitucionais que pautam a inventividade -- A aplicação da In nº 1.187/2011 e o Princípio da Segurança Jurídica no Direito Tributário. A aplicação da IN nº 1.187/2011 no tempo e a proteção da confiança legítima em face das práticas reiteradas da Administração Tributária : a suppressio em matéria fiscal. | Assuntos: Desenvolvimentotecnológico, Brasil.Pesquisatecnológica, Brasil. {Pesquisatecnológica; Tecnologia,pesquisa} Incentivo fiscal, Brasil.', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PÚBLICO - 341::DIREITO ADMINISTRATIVO - 341.3::Direito Tributário - 341.39::Teoria. Fundamentos - 341.391::Incentivos fiscais - 341.39104', 'Sumário:O incentivo aodesenvolvimentonacional como princípio constitucional matriz do princípio dodesenvolvimentocientífico e tecnológico : a autonomia tecnológica do país como finalidade do regime de benefícios e a territorialidade da inovação incentivada -- O regime de incentivos à inovação da lei nª 11.196/2005, Art. 19 : a regra de apropriação do benefício fiscal de exclusão de 60% das despesas dedutíveis compesquisaedesenvolvimento. Os requisitos para a apropriação de benefícios na hipótese de subcontratação de serviços de P&D: regime da Lei vs. IN nº 1.187/2011. A aplicação da IN nº 1.187/2011 sob o influxo dos princípios constitucionais que pautam a inventividade -- A aplicação da In nº 1.187/2011 e o Princípio da Segurança Jurídica no Direito Tributário. A aplicação da IN nº 1.187/2011 no tempo e a proteção da confiança legítima em face das práticas reiteradas da Administração Tributária : a suppressio em matéria fiscal. | Assuntos: Desenvolvimentotecnológico, Brasil.Pesquisatecnológica, Brasil. {Pesquisatecnológica; Tecnologia,pesquisa} Incentivo fiscal, Brasil.', '', 'Moreira Filho, Aristóteles', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
