INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Ambiente do trabalhoedesenvolvimentosustentável', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2019;1001207671', NULL, '', '', 'doutrina', 'Resumo:"As transformações econômicas, sociais e políticas desencadeadas pelas Revoluções Industrial e Tecnológica levaram à evolução do conceito dedesenvolvimento, que evoluiu do conceito baseado meramente no crescimento econômico para o conceito baseado nodesenvolvimentosustentável, exigindo, por imposição do mercado, uma mudança de comportamento das empresas. O presente trabalho tem por objetivo verificar, diante do princípio ambiental dodesenvolvimentosustentável e do dever constitucional de proteção do equilíbrio ambiental, se as empresas devem inserir a análise da variável socioambiental nos seus processos decisórios, principalmente nos processos relacionados ao ambiente do trabalho e aos processos produtivos, não devendo limitar-se à simples análise da variável econômica, isso para que consigam desenvolver suas atividades de forma sustentável, atrelando ganho econômico à garantia de fruição dos direitos sociais e do direito ao meio ambiente ecologicamente equilibrado para as presentes e futuras gerações. Apesquisajustifica-se na necessidade das empresas terem que cumprir com sua função social, de forma a garantir a existência de vida digna no ambiente laboral e fora dele. Para a obtenção dos resultados almejados pelapesquisa, o método de abordagem a ser seguido será o empírico-dialético, utilizando-se daspesquisasbibliográfica e legislativa. Em conclusão, aponta-se que, para cumprir com sua função social, as empresas devem inserir a análise da variável socioambiental nos seus processos decisórios, visando garantir a existência de vida digna no ambiente laboral e fora dele, por meio da manutenção do equilíbrio entre as vertentes dodesenvolvimentosustentável, qual seja, o equilíbrio entre os ganhos econômicos e sociais e a proteção do meio ambiente."Sumário:Meio ambiente do trabalho e o direito fundamental ao meio ambiente ecologicamente equilibrado. O direito ao meio ambiente ecologicamente equilibrado como informador das relações de trabalho -- O risco ambiental e a necessidade de uma nova postura das empresas na pós-modernidade -- O ambiente do trabalho na pós-modernidade e o risco ambiental. Risco ambiental. O risco ambiental e seus reflexos no ambiente do trabalho. | Assuntos: Desenvolvimentosustentável, Brasil. {Desenvolvimentosustentável;Desenvolvimentoauto-sustentado;Desenvolvimentosustentado} Empresa, aspectos ambientais. Responsabilidade socioambiental, aspectos econômicos, Brasil. Sustentabilidade ambiental, aspectos socioeconômicos.', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PÚBLICO - 341::DIREITO ADMINISTRATIVO - 341.3::Domínio Público. Conceito. Domínio Eminente. Domínio Patrimonial - 341.34::Direito Ambiental - 341.347', 'Resumo:"As transformações econômicas, sociais e políticas desencadeadas pelas Revoluções Industrial e Tecnológica levaram à evolução do conceito dedesenvolvimento, que evoluiu do conceito baseado meramente no crescimento econômico para o conceito baseado nodesenvolvimentosustentável, exigindo, por imposição do mercado, uma mudança de comportamento das empresas. O presente trabalho tem por objetivo verificar, diante do princípio ambiental dodesenvolvimentosustentável e do dever constitucional de proteção do equilíbrio ambiental, se as empresas devem inserir a análise da variável socioambiental nos seus processos decisórios, principalmente nos processos relacionados ao ambiente do trabalho e aos processos produtivos, não devendo limitar-se à simples análise da variável econômica, isso para que consigam desenvolver suas atividades de forma sustentável, atrelando ganho econômico à garantia de fruição dos direitos sociais e do direito ao meio ambiente ecologicamente equilibrado para as presentes e futuras gerações. Apesquisajustifica-se na necessidade das empresas terem que cumprir com sua função social, de forma a garantir a existência de vida digna no ambiente laboral e fora dele. Para a obtenção dos resultados almejados pelapesquisa, o método de abordagem a ser seguido será o empírico-dialético, utilizando-se daspesquisasbibliográfica e legislativa. Em conclusão, aponta-se que, para cumprir com sua função social, as empresas devem inserir a análise da variável socioambiental nos seus processos decisórios, visando garantir a existência de vida digna no ambiente laboral e fora dele, por meio da manutenção do equilíbrio entre as vertentes dodesenvolvimentosustentável, qual seja, o equilíbrio entre os ganhos econômicos e sociais e a proteção do meio ambiente."Sumário:Meio ambiente do trabalho e o direito fundamental ao meio ambiente ecologicamente equilibrado. O direito ao meio ambiente ecologicamente equilibrado como informador das relações de trabalho -- O risco ambiental e a necessidade de uma nova postura das empresas na pós-modernidade -- O ambiente do trabalho na pós-modernidade e o risco ambiental. Risco ambiental. O risco ambiental e seus reflexos no ambiente do trabalho. | Assuntos: Desenvolvimentosustentável, Brasil. {Desenvolvimentosustentável;Desenvolvimentoauto-sustentado;Desenvolvimentosustentado} Empresa, aspectos ambientais. Responsabilidade socioambiental, aspectos econômicos, Brasil. Sustentabilidade ambiental, aspectos socioeconômicos.', '', 'Messias, Ewerton Ricardo', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
