INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Contradições na agenda brasileira dainovação', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2008;1000855621', NULL, '', '', 'doutrina', 'Resumo:Analisa algumas medidas de incentivo àinovação, entre elas a Lei daInovação, A Lei do Bem, ambas aprovadas no Congresso no final de 2005 e a Política Industrial, Tecnológica e de Comércio Exterior (PITCE), lançada em 2004 e que engloba mais de 50 medidas de incentivo àinovação. | Assuntos: Política industrial,inovação, Brasil. {Política industrial; Promoção industrial} Propriedade industrial,inovação, Brasil. {Propriedade industrial; Marca de fábrica, registro; Registro da marca} Propriedade intelectual,inovação, Brasil. {Propriedade intelectual; Propriedade imaterial}', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PRIVADO - 342::DIREITO COMERCIAL - 342.2::Direitos Intelectuais. Propriedade industrial, comercial, científica e de programas de computador - 342.27', 'Resumo:Analisa algumas medidas de incentivo àinovação, entre elas a Lei daInovação, A Lei do Bem, ambas aprovadas no Congresso no final de 2005 e a Política Industrial, Tecnológica e de Comércio Exterior (PITCE), lançada em 2004 e que engloba mais de 50 medidas de incentivo àinovação. | Assuntos: Política industrial,inovação, Brasil. {Política industrial; Promoção industrial} Propriedade industrial,inovação, Brasil. {Propriedade industrial; Marca de fábrica, registro; Registro da marca} Propriedade intelectual,inovação, Brasil. {Propriedade intelectual; Propriedade imaterial}', '', 'Mendes, Ricardo Camargo', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:0