INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Direito administrativo einovação', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2017;1001115216', NULL, '', '', 'doutrina', 'Sumário:O que pode ser ainovaçãono direito administrativo brasileiro. Três requisitos de cautela -- A Lei de direito administrativo: ponte experimental imperfeita -- A doutrina de direito administrativo : entre o centralismo e a proposta -- A jurisprudência de direito administrativo : laboratório ou museu?. | Assuntos: Direito administrativo,inovação, Brasil.', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PÚBLICO - 341::DIREITO ADMINISTRATIVO - 341.3', 'Sumário:O que pode ser ainovaçãono direito administrativo brasileiro. Três requisitos de cautela -- A Lei de direito administrativo: ponte experimental imperfeita -- A doutrina de direito administrativo : entre o centralismo e a proposta -- A jurisprudência de direito administrativo : laboratório ou museu?. | Assuntos: Direito administrativo,inovação, Brasil.', '', 'Mendonça, José Vicente Santos de', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Sustentabilidade de iniciativas premiadas no ConcursoInovação', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2010;1000899214', NULL, '', '', 'doutrina', 'Resumo:Apresenta tabelas com resultados da pesquisa sobre a sustentabilidade dasinovaçõespremiadas no ConcursoInovaçãona Gestão Pública Federal 1996-2006, incluindo: situação das iniciativas pesquisadas, áreas temáticas, tempo de existência das iniciativas em cada um dos Ministérios, dados do responsável pela iniciativa, mudanças ocorridas na instituição desde a criação da iniciativa, práticas gerenciais mais utilizadas e anexo com a relação das iniciativas premiadas por ano de premiação, por ministério, por órgão responsável, por área temática e por local de premiação. | Assuntos: Serviço público,inovação, pesquisa, Brasil. {Serviço público; Emprego público} Setor público,inovação, pesquisa, Brasil. Administração pública,inovação, pesquisa, Brasil.', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PÚBLICO - 341::DIREITO ADMINISTRATIVO - 341.3', 'Resumo:Apresenta tabelas com resultados da pesquisa sobre a sustentabilidade dasinovaçõespremiadas no ConcursoInovaçãona Gestão Pública Federal 1996-2006, incluindo: situação das iniciativas pesquisadas, áreas temáticas, tempo de existência das iniciativas em cada um dos Ministérios, dados do responsável pela iniciativa, mudanças ocorridas na instituição desde a criação da iniciativa, práticas gerenciais mais utilizadas e anexo com a relação das iniciativas premiadas por ano de premiação, por ministério, por órgão responsável, por área temática e por local de premiação. | Assuntos: Serviço público,inovação, pesquisa, Brasil. {Serviço público; Emprego público} Setor público,inovação, pesquisa, Brasil. Administração pública,inovação, pesquisa, Brasil.', '', 'Ferrarezi, Elizabete', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
