INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:congresso.nacional:projeto.lei;pln:2017;31', '[ Projeto de Lei do Congresso Nacional nº 31/2017 : Lei nº 13.553 de 20/12/2017 ]', 'https://www.lexml.gov.br/urn/urn:lex:br:congresso.nacional:projeto.lei;pln:2017;31', NULL, '', '', 'outro', 'Abre ao Orçamento de Investimento para 2017 crédito suplementar no valor total de R$ 8.480.320.523,00 em favor de diversas empresas estatais e reduz o Orçamento de Investimento de diversas empresas no valor global de R$ 15.278.975.941,00, para os fins que especifica.', '', 'LexML', 'transport_energy', '', '', 'Abre ao Orçamento de Investimento para 2017 crédito suplementar no valor total de R$ 8.480.320.523,00 em favor de diversas empresas estatais e reduz o Orçamento de Investimento de diversas empresas no valor global de R$ 15.278.975.941,00, para os fins que especifica.', '', 'Congresso Nacional', 'Federal', 'Legislativo Federal', '{"search_term": "", "urn_type": "other", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
