INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Gestão de ciência etecnologiapara a força terrestre', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:artigo.revista:2003;1000703574', NULL, '', '', 'doutrina', 'Resumo:Analisa a demanda da Força Terrestre por ciência etecnologia(C&T) e, para atender à gestão setorial, apresenta uma proposta de inclusão do tema na formação do oficial, particularmente nos cursos de Altos Estudos Militares. Destaca a importância de assuntos como a Gerência de Projetos, a Gestão de C&T propriamente dita, a Engenharia de Sistemas militares aplicada ao Projeto e ao preparo da Força Terrestre, e aborda aspectos da aquisição e do desenvolvimento de materiais de emprego militar - MEM, da transferência detecnologias, da gestão detecnologiada informação e da pesquisa operacional.Sumário:A demanda da força terrestre por ciência etecnologia-- Projeto sistemático de força terrestre -- Alguns temas centrais para a gestão da ciência etecnologiada força terrestre -- Gestão do processo de engenharia de sistemas -- Gestão da aquisição e desenvolvimento de material de emprego militar -- Gestão de transferência detecnologia-- Gestao datecnologiada informação -- Pesquisa operacional aplicada aos assuntos de defesa -- Inserção da ciência etecnologiana capacitação do oficial de estado-maior. | Assuntos: Estratégia militar, Brasil. Exército, Brasil. Engenharia militar, Brasil.Tecnologiamilitar, Brasil. Forças armadas, Brasil. Transferência detecnologia, Brasil. {Transferência detecnologia;Tecnologia, transferência}', '', 'LexML', 'transport_energy', 'Artigo de revista', 'Classificação: DIREITO PÚBLICO - 341::DIREITO CONSTITUCIONAL - 341.2::Segurança nacional - 341.26', 'Resumo:Analisa a demanda da Força Terrestre 