INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br;distrito.federal:distrital:decreto.legislativo:2021-11-16;2336', 'Decreto Legislativo nº 2336, de 16 de novembro de 2021', 'https://www.lexml.gov.br/urn/urn:lex:br;distrito.federal:distrital:decreto.legislativo:2021-11-16;2336', '2021-11-16', 'DF', '', 'outro', 'Homologa o Convênio ICMS 66/19, de 5 de julho de 2019, que concede isenção do ICMS às operações comaceleradoreslineares destinados à prestação de serviços de saúde, e o Convênio ICMS 51/21, de 8 de abril de 2021, que o altera. | Assuntos: IMPOSTO SOBRE OPERAÇÕES RELATIVAS À CIRCULAÇÃO DE MERCADORIAS E SOBRE PRESTAÇÕES DE SERVIÇOS DE TRANSPORTE INTERESTADUAL E INTERMUNICIPAL E DE COMUNICAÇÃO (ICMS). CONVÊNIO, homologação. SERVIÇO DE SAÚDE.', '', 'LexML', 'transport_energy', '', '', 'Homologa o Convênio ICMS 66/19, de 5 de julho de 2019, que concede isenção do ICMS às operações comaceleradoreslineares destinados à prestação de serviços de saúde, e o Convênio ICMS 51/21, de 8 de abril de 2021, que o altera. | Assuntos: IMPOSTO SOBRE OPERAÇÕES RELATIVAS À CIRCULAÇÃO DE MERCADORIAS E SOBRE PRESTAÇÕES DE SERVIÇOS DE TRANSPORTE INTERESTADUAL E INTERMUNICIPAL E DE COMUNICAÇÃO (ICMS). CONVÊNIO, homologação. SERVIÇO DE SAÚDE.', '', 'Distrital', 'Distrital', 'Outros', '{"search_term": "", "urn_type": "other", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
