INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:terceiro.conselho.contribuintes;camara.1;turma.ordinaria:acordao:2003-11-05;301-30798,4699323', 'Acórdão nº 301-30798 do Processo 11128.002028/99-10', 'https://www.lexml.gov.br/urn/urn:lex:br:terceiro.conselho.contribuintes;camara.1;turma.ordinaria:acordao:2003-11-05;301-30798,4699323', '2003-11-05', '', '', 'jurisprudencia', 'CLASSIFICAÇÃO FISCAL  II
