INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('', 'Propriedadeintelectuale desenvolvimento', 'https://www.lexml.gov.br/urn/urn:lex:br:rede.virtual.bibliotecas:livro:2005;000746897', NULL, '', '', 'doutrina', 'Resumo:Discute apropriedadeintelectual. Analisa possibilidades de políticas públicas pelos países adaptadores de tecnologia ou excluídos da produção tecnológica, tendo em vista os tratados em vigor, tais como Trips, PCT(Tratado de Cooperação em Matéria de Patentes) e as normas nacionais.Sumário:O divisor global de inovação / Jeffrey Sachs -- Aperfeiçoando a eficiência econômica e a eqüidade pela criação de leis depropriedadeintelectual/ Carlos M. Correa -- Revolução tecnológica, globalização e Direito das patentes / Bernard Remiche -- Trips e a experiência brasileira / Denis Borges Barbosa -- Políticas públicas parapropriedadeintelectualno Brasil / Marcelo Dias Varella -- O parágrafo 6 da Declaração de Doha, o Acordo Trips e os Países em desenvolvimento / Daya Shanker -- O impacto das patentes farmacêuticas em países em desenvolvimento e as perspectivas para o Brasil / Maria Fernanda Gonçalves Macedo e Eloan dos Santos Pinheiro -- Política de patentes em biotecnologia: posicionamento brasileiro / Maria Edelvacy Pinto Marinho -- Desenvolvimento tecnológico, pesquisa pública epropriedadeintelectual. Análise da miríade de normas institucionais / Marcelo Dias Varella; Ana Flávia Barros Plaatiau e Rafael T. Schleicher -- Indicações geográficas e arranjos produtivos locais / Marcelo Dias Varella e Ana Flávia Granja e Barros. | Assuntos: Propriedadeintelectual. {Propriedadeintelectual;Propriedadeimaterial}Propriedadeintelectual, coletânea, Brasil. {Propriedadeintelectual;Propriedadeimaterial} Patente, Brasil. Biotecnologia, Brasil. {Biotecnologia; Tecnologia biológica}', '', 'LexML', 'transport_energy', 'Livro', 'Classificação: DIREITO PRIVADO - 342::DIREITO COMERCIAL - 342.2::DireitosIntelectuais.Propriedadeindustrial, comercial, científica e de programas de computador - 342.27', 'Resumo:Discute apropriedadeintelectual. Analisa possibilidades de políticas públicas pelos países adaptadores de tecnologia ou excluídos da produção tecnológica, tendo em vista os tratados em vigor, tais como Trips, PCT(Tratado de Cooperação em Matéria de Patentes) e as normas nacionais.Sumário:O divisor global de inovação / Jeffrey Sachs -- Aperfeiçoando a eficiência econômica e a eqüidade pela criação de leis depropriedadeintelectual/ Carlos M. Correa -- Revolução tecnológica, globalização e Direito das patentes / Bernard Remiche -- Trips e a experiência brasileira / Denis Borges Barbosa -- Políticas públicas parapropriedadeintelectualno Brasil / Marcelo Dias Varella -- O parágrafo 6 da Declaração de Doha, o Acordo Trips e os Países em desenvolvimento / Daya Shanker -- O impacto das patentes farmacêuticas em países em desenvolvimento e as perspectivas para o Brasil / Maria Fernanda Gonçalves Macedo e Eloan dos Santos Pinheiro -- Política de patentes em biotecnologia: posicionamento brasileiro / Maria Edelvacy Pinto Marinho -- Desenvolvimento tecnológico, pesquisa pública epropriedadeintelectual. Análise da miríade de normas institucionais / Marcelo Dias Varella; Ana Flávia Barros Plaatiau e Rafael T. Schleicher -- Indicações geográficas e arranjos produtivos locais / Marcelo Dias Varella e Ana Flávia Granja e Barros. | Assuntos: Propriedadeintelectual. {Propriedadeintelectual;Propriedadeimaterial}Propriedadeintelectual, coletânea, Brasil. {Propriedadeintelectual;Propriedadeimaterial} Patente, Brasil. Biotecnologia, Brasil. {Biotecnologia; Tecnologia biológica}', '', '', '', '', '{"search_term": "", "urn_type": "doutrina", "country": "br", "source_file": "Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
