INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br;distrito.federal:tribunal.justica.distrito.federal.territorios;turma.civel.1:acordao:2012-05-30;593552', 'Acórdão nº 593552 do Processo nº20060110941726apc', 'https://www.lexml.gov.br/urn/urn:lex:br;distrito.federal:tribunal.justica.distrito.federal.territorios;turma.civel.1:acordao:2012-05-30;593552', '2012-05-30', 'DF', '', 'jurisprudencia', 'MATERIAIS. VEÍCULO. FIAT MAREA. FORMAÇÃO DE BORRA NO ÓLEO DO MOTOR. DANIFICAÇÃO DOS COMPONENTES INTERNOS DO MOTOR. LAUDO PERICIAL. INEXISTÊNCIA DE DEFEITO OU VÍCIO NO MOTOR. SUBSTITUIÇÃO DO ÓLEO A CADA 10.000 KM. ALTERAÇÃO SISTEMÁTICA DE ÓLEO LUBRIFICANTE DE MARCAS E BASES DIFERENTES. DANO MATERIAL. CULPA DO CONSUMIDOR/TERCEIRO. COMPROVAÇÃO. PRETENSÃO INDENIZATÓRIA. REJEIÇÃO. 
1. EMERGINDO DO ACERVO PROBATÓRIO QUE O CONSUMIDOR NÃO EVIDENCIARA QUE A FORMAÇÃO EXAGERADA DE BORRA NO ÓLEO LUBRIFICANTE DO MOTOR FORA ORIGINADA DE DEFEITO OU VÍCIO INERENTE AO MESMO E RESTANDO PROVADA A ALTERAÇÃO SISTEMÁTICA DE ÓLEOS LUBRIFICANTES DE MARCAS E BASES (SINTÉTICOE SEMISSINTÉTICO) DIFERENTES, O QUE, SEGUNDO LAUDO PERICIAL, PODE SE CARACTERIZAR COMO CIRCUNSTÂNCIA DECISIVA PARA A FORMAÇÃO ACELERADA DE BORRA DE ÓLEO, O DIREITO QUE INVOCARA FICARA CARENTE DE ESTOFO MATERIAL ANTE A NÃO COMPROVAÇÃO DE QUALQUER FALHA DE PRODUÇÃO DO BEM PASSÍVEL DE ENSEJAR A CARACTERIZAÇÃO DO DANO QUE O VITIMARA E A SUBSEQÜENTE COMPOSIÇÃO DO PREJUÍZO MATERIAL QUE EXPERIMENTARA. 
2. AFERIDO QUE A FORMAÇÃO EXAGERADA DE BORRA DE ÓLEO NO MOTOR DO VEÍCULO DERIVARA, NA REALIDADE, DA IMPRUDÊNCIA DO PRÓPRIO CONSUMIDOR EM ALTERAR SISTEMATICAMENTE O ÓLEO LUBRIFICANTE DO SEU AUTOMÓVEL OU DE UM EVENTUAL ABASTECIMENTO DO VEÍCULO COM GASOLINA ADULTERADA, E NÃO DE DEFEITO INTRÍNSECO OU EXTRÍNSECO NA FABRICAÇÃO OU COMERCIALIZAÇÃO DO PRODUTO, ESSA APREENSÃO, AFASTANDO O NEXO DE CAUSALIDADE ENLAÇANDO O OCORRIDO A QUALQUER ATO PASSÍVEL DE IMPUTAÇÃO À FABRICANTE, EXAURE UM DOS ELOS INDISPENSÁVEIS À GERMINAÇÃO DA RESPONSABILIDADE CIVIL, OBSTANDO O APERFEIÇOAMENTO DO SILOGISMO DELINEADO PELO ARTIGO 186 DO CÓDIGO CIVIL E ENSEJANDO SUA ALFORRIA DA OBRIGAÇÃO DE COMPOR OS DANOS DERIVADOS DO EVENTO. 
3. A AUSÊNCIA DE INFORMAÇÃO EXPLÍCITA NO SENTIDO DE NÃO SER RECOMENDÁVEL A ALTERAÇÃO DE ÓLEO LUBRIFICANTE NÃO CONSUBSTANCIA DEFEITO DE INFORMAÇÃO QUANTO À ADEQUADA MANUTENÇÃO DO VEÍCULO, QUANDO O MANUAL DO AUTOMÓVEL EXPRESSAMENTE ADVERTE QUE O SERVIÇO DE MANUTENÇÃO DEVE SER CONFIADO, COMO REGRA, À CONCESSIONÁRIA DA FIAT, ADMITINDO-SE, EXCEPCIONALMENTE, PEQUENAS INTERVENÇÕES DE MANUTENÇÃO E REPARAÇÃO EXECUTADAS PELO PRÓPRIO CLIENTE, DESDE QUE O CONSUMIDOR TENHA EXPERIÊNCIA ACERCA DO PROCEDIMENTO A SER REALIZADO E CERTIFIQUE-SE SOBRE A UTILIZAÇÃO DAS FERRAMENTAS NECESSÁRIAS, DAS PEÇAS ORIGINAIS DA FIAT E DOS LÍQUIDOS DE CONSUMO. 
4. APELAÇÃO CONHECIDA E DESPROVIDA. MAIORIA. | Assuntos: IMPROCEDÊCIA, CONDENAÇÃO, PAGAMENTO, VALOR, INDENIZAÇÃO, DANO MATERIAL, DANO, PARTE, VEÍCULO AUTOMOTOR, IMPOSSIBILIDADE, RESPONSABILIDADE, FABRICANTE, VENCIMENTO, PERÍODO, GARANTIA, BEM, VERIFICAÇÃO, PERÍCIA, TROCA, DIVERSIDADE, UTILIZAÇÃO, PRODUTO,COMBUSTÍVEL.

VOTO VENCIDO: PROCEDÊNCIA, CONDENAÇÃO, PAGAMENTO, VALOR, INDENIZAÇÃO, DANO MATERIAL, IMPOSSIBILIDADE, COBRANÇA, CONHECIMENTO, TÉCNICO, CONSUMIDOR, UTILIZAÇÃO, MARCA,COMBUSTÍVEL, PRODUTO, USO, CARRO, RESPONSABILIDADE, INFORMAÇÃO, FABRICANTE.', '', 'LexML', 'transport_energy', 'Acórdão', '', 'MATERIAIS. VEÍCULO. FIAT MAREA. FORMAÇÃO DE BORRA NO ÓLEO DO MOTOR. DANIFICAÇÃO DOS COMPONENTES INTERNOS DO MOTOR. LAUDO PERICIAL. INEXISTÊNCIA DE DEFEITO OU VÍCIO NO MOTOR. SUBSTITUIÇÃO DO ÓLEO A CADA 10.000 KM. ALTERAÇÃO SISTEMÁTICA DE ÓLEO LUBRIFICANTE DE MARCAS E BASES DIFERENTES. DANO MATERIAL. CULPA DO CONSUMIDOR/TERCEIRO. COMPROVAÇÃO. PRETENSÃO INDENIZATÓRIA. REJEIÇÃO. 
1. EMERGINDO DO ACERVO PROBATÓRIO QUE O CONSUMIDOR NÃO EVIDENCIARA QUE A FORMAÇÃO EXAGERADA DE BORRA NO ÓLEO LUBRIFICANTE DO MOTOR FORA ORIGINADA DE DEFEITO OU VÍCIO INERENTE AO MESMO E RESTANDO PROVADA A ALTERAÇÃO SISTEMÁTICA DE ÓLEOS LUBRIFICANTES DE MARCAS E BASES (SINTÉTICOE SEMISSINTÉTICO) DIFERENTES, O QUE, SEGUNDO LAUDO PERICIAL, PODE SE CARACTERIZAR COMO CIRCUNSTÂNCIA DECISIVA PARA A FORMAÇÃO ACELERADA DE BORRA DE ÓLEO, O DIREITO QUE INVOCARA FICARA CARENTE DE ESTOFO MATERIAL ANTE A NÃO COMPROVAÇÃO DE QUALQUER FALHA DE PRODUÇÃO DO BEM PASSÍVEL DE ENSEJAR A CARACTERIZAÇÃO DO DANO QUE O VITIMARA E A SUBSEQÜENTE COMPOSIÇÃO DO PREJUÍZO MATERIAL QUE EXPERIMENTARA. 
2. AFERIDO QUE A FORMAÇÃO EXAGERADA DE BORRA DE ÓLEO NO MOTOR DO VEÍCULO DERIVARA, NA REALIDADE, DA IMPRUDÊNCIA DO PRÓPRIO CONSUMIDOR EM ALTERAR SISTEMATICAMENTE O ÓLEO LUBRIFICANTE DO SEU AUTOMÓVEL OU DE UM EVENTUAL ABASTECIMENTO DO VEÍCULO COM GASOLINA ADULTERADA, E NÃO DE DEFEITO INTRÍNSECO OU EXTRÍNSECO NA FABRICAÇÃO OU COMERCIALIZAÇÃO DO PRODUTO, ESSA APREENSÃO, AFASTANDO O NEXO DE CAUSALIDADE ENLAÇANDO O OCORRIDO A QUALQUER ATO PASSÍVEL DE IMPUTAÇÃO À FABRICANTE, EXAURE UM DOS ELOS INDISPENSÁVEIS À GERMINAÇÃO DA RESPONSABILIDADE CIVIL, OBSTANDO O APERFEIÇOAMENTO DO SILOGISMO DELINEADO PELO ARTIGO 186 DO CÓDIGO CIVIL E ENSEJANDO SUA ALFORRIA DA OBRIGAÇÃO DE COMPOR OS DANOS DERIVADOS DO EVENTO. 
3. A AUSÊNCIA DE INFORMAÇÃO EXPLÍCITA NO SENTIDO DE NÃO SER RECOMENDÁVEL A ALTERAÇÃO DE ÓLEO LUBRIFICANTE NÃO CONSUBSTANCIA DEFEITO DE INFORMAÇÃO QUANTO À ADEQUADA MANUTENÇÃO DO VEÍCULO, QUANDO O MANUAL DO AUTOMÓVEL EXPRESSAMENTE ADVERTE QUE O SERVIÇO DE MANUTENÇÃO DEVE SER CONFIADO, COMO REGRA, À CONCESSIONÁRIA DA FIAT, ADMITINDO-SE, EXCEPCIONALMENTE, PEQUENAS INTERVENÇÕES DE MANUTENÇÃO E REPARAÇÃO EXECUTADAS PELO PRÓPRIO CLIENTE, DESDE QUE O CONSUMIDOR TENHA EXPERIÊNCIA ACERCA DO PROCEDIMENTO A SER REALIZADO E CERTIFIQUE-SE SOBRE A UTILIZAÇÃO DAS FERRAMENTAS NECESSÁRIAS, DAS PEÇAS ORIGINAIS DA FIAT E DOS LÍQUIDOS DE CONSUMO. 
4. APELAÇÃO CONHECIDA E DESPROVIDA. MAIORIA. | Assuntos: IMPROCEDÊCIA, CONDENAÇÃO, PAGAMENTO, VALOR, INDENIZAÇÃO, DANO MATERIAL, DANO, PARTE, VEÍCULO AUTOMOTOR, IMPOSSIBILIDADE, RESPONSABILIDADE, FABRICANTE, VENCIMENTO, PERÍODO, GARANTIA, BEM, VERIFICAÇÃO, PERÍCIA, TROCA, DIVERSIDADE, UTILIZAÇÃO, PRODUTO,COMBUSTÍVEL.

VOTO VENCIDO: PROCEDÊNCIA, CONDENAÇÃO, PAGAMENTO, VALOR, INDENIZAÇÃO, DANO MATERIAL, IMPOSSIBILIDADE, COBRANÇA, CONHECIMENTO, TÉCNICO, CONSUMIDOR, UTILIZAÇÃO, MARCA,COMBUSTÍVEL, PRODUTO, USO, CARRO, RESPONSABILIDADE, INFORMAÇÃO, FABRICANTE.', '', 'Tribunal de Justiça do Distrito Federal e dos Territórios. 1ª Turma Cível', 'Distrital', 'Tribunal', '{"search_term": "", "urn_type": "jurisprudence", "country": "br", "source_file": "Jurisprud\u00eancia___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
