INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br;distrito.federal:tribunal.justica.distrito.federal.territorios;turma.civel.2:acordao:2012-03-14;572877', 'Acórdão nº 572877 do Processo nº20050110255336apc', 'https://www.lexml.gov.br/urn/urn:lex:br;distrito.federal:tribunal.justica.distrito.federal.territorios;turma.civel.2:acordao:2012-03-14;572877', '2012-03-14', 'DF', '', 'jurisprudencia', 'APELAÇÃO CÍVEL. SENTENÇA ULTRA PETITA. NÃO OCORRÊNCIA. CERCEAMENTO DO DIREITO DE DEFESA NÃO CONFIGURADO. PRELIMINARES DE ILEGITIMIDADE PASSIVA AD CAUSAM E FALTA DE INTERESSE DE AGIR AFASTADAS. PRESCRIÇÃO. INOCORRÊNCIA. APLICAÇÃO DO ART. 27 DO CDC. RESPONSABILIDADE CIVIL. RELAÇÃO DE CONSUMO POR EQUIPARAÇÃO. VAZAMENTO DECOMBUSTÍVEL. RESPONSABILIDADE OBJETIVA. DANO MORAL CONFIGURADO. OBRIGAÇÃO DE FAZER. LIMITAÇÃO.
APESAR DE O JULGAMENTO ULTRA PETITA NÃO DAR ENSEJO À NULIDADE, CABENDO TÃO SOMENTE À INSTÂNCIA REVISORA DECOTAR O QUE EXCEDEU DO PEDIDO, NÃO SE VISLUMBRA SUA OCORRÊNCIA, IN CASU.
TRATANDO-SE DE RELAÇÃO DE CONSUMO POR EQUIPARAÇÃO, SENDO A HIPÓTESE REGIDA PELO CÓDIGO DE DEFESA DO CONSUMIDOR, APLICA-SE A TEORIA DA APARÊNCIA A FIM DE RESPONSABILIZAR, DE MODO SOLIDÁRIO, TODAS AS EMPRESAS ENVOLVIDAS, PODENDO, O CONSUMIDOR, DEMANDAR EM FACE DE QUALQUER UMA DELAS OU AMBAS.
IRREFUTÁVEL O INTERESSE PROCESSUAL, ESTE APOIADO NA NECESSIDADE DA INTERVENÇÃO JUDICIAL E NA UTILIDADE DO PROCESSO PARA A OBTENÇÃO DO DIREITO QUE SE ALEGA POSSUIR.
ÀS PRETENSÕES RELATIVAS À RESPONSABILIDADE PELO FATO DO PRODUTO OU SERVIÇO, ISTO É, PELOS VÍCIOS OU DEFEITOS DE SEGURANÇA NELE HAVIDOS, APLICA-SE O PRAZO PRESCRICIONAL PREVISTO NO ART. 27 DO CDC.
PARA ELIDIR A RESPONSABILIDADE OBJETIVA DAS RÉS SOBRE O DEFEITO NA PRESTAÇÃO DO SERVIÇO, O QUAL OCASIONOU VAZAMENTO DECOMBUSTÍVELE, CONSEQUENTEMENTE, DANOS À POPULAÇÃO QUE VIVIA AO REDOR DO POSTO DE GASOLINA, O FORNECEDOR DO PRODUTO OU SERVIÇO DEVE COMPROVAR A AUSÊNCIA DE DEFEITO OU A CULPA EXCLUSIVA DA VÍTIMA OU DE TERCEIRO, NOS TERMOS DO §3.º DO ART. 14 DO CDC, O QUE NÃO OCORREU.
