INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:tribunal.contas.uniao;plenario:acordao:2005-08-31;1316', 'ACÓRDÃO TCU 1316/2005', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.contas.uniao;plenario:acordao:2005-08-31;1316', '2005-08-31', '', '', 'jurisprudencia', 'Auditoria constante do plano TCU 2° semestre de 2002 (5° Estágio) para verificar a pertinência dos valores do pedágio na citada rodovia federal bem como a correção da execução contratual e manutenção do equilíbrio econômico-financeiro, ante as revisões e reajustes tarifários. Achados de auditoria envolvendo impropriedades na execução do contrato. Diligência junto aANTT. Envio de cópia do Relatório à CONCER e àANTT. Apresentação de alegações e envio de documentos. Determinações e recomendações àANTT. Ciência do Acórdão bem como do Relatório e Voto que o fundamentam ao Ministério dos Transportes, àANTTe à Concer. Arquivamento. O cumprimento das determinações será acompanhado mediante monitoramento (art. 243 do RI/TCU).', '', 'LexML', 'transport_energy', 'Acórdão', '', 'Auditoria constante do plano TCU 2° semestre de 2002 (5° Estágio) para verificar a pertinência dos valores do pedágio na citada rodovia federal bem como a correção da execução contratual e manutenção do equilíbrio econômico-financeiro, ante as revisões e reajustes tarifários. Achados de auditoria envolvendo impropriedades na execução do contrato. Diligência junto aANTT. Envio de cópia do Relatório à CONCER e àANTT. Apresentação de alegações e envio de documentos. Determinações e recomendações àANTT. Ciência do Acórdão bem como do Relatório e Voto que o fundamentam ao Ministério dos Transportes, àANTTe à Concer. Arquivamento. O cumprimento das determinações será acompanhado mediante monitoramento (art. 243 do RI/TCU).', '', 'Tribunal de Contas da União. Plenário', 'Federal', 'Tribunal', '{"search_term": "", "urn_type": "jurisprudence", "country": "br", "source_file": "Jurisprud\u00eancia___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
