INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br;justica.trabalho;regiao.8:tribunal.regional.trabalho;turma.4:acordao:2019-04-30;0111200-25.2001.5.08.0003', 'ACÓRDÃO TRT 8ª / 4ª T / AP 0111200-25.2001.5.08.0003', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.8:tribunal.regional.trabalho;turma.4:acordao:2019-04-30;0111200-25.2001.5.08.0003', '2019-04-30', '', '8ª Região - Pará e Amapá', 'jurisprudencia', 'POSSIBILIDADE DE PENHORA. FRAUDE À EXECUÇÃO. Preservado o privilégio do crédito trabalhista, não há que se falar em prejuízo quando da determinaçãodeemissãodecertidãodecrédito ao exequente para opor contra oinventáriodo de cujus, visto se tratar de procedimento necessário à preservação dos direitos do exequente, enquanto ocorrer a regularização da representatividade do espólio. Agravo não provido.', '', 'LexML', 'transport_energy', 'Acórdão', '', 'POSSIBILIDADE DE PENHORA. FRAUDE À EXECUÇÃO. Preservado o privilégio do crédito trabalhista, não há que se falar em prejuízo quando da determinaçãodeemissãodecertidãodecrédito ao exequente para opor contra oinventáriodo de cujus, visto se tratar de procedimento necessário à preservação dos direitos do exequente, enquanto ocorrer a regularização da representatividade do espólio. Agravo não provido.', '', 'Tribunal Regional do Trabalho. 4ª Turma', '', 'Tribunal', '{"search_term": "", "urn_type": "jurisprudence", "country": "br", "source_file": "Jurisprud\u00eancia___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
