INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:segundo.conselho.contribuintes;camara.2;turma.ordinaria:acordao:1997-08-26;202-09416,4823394', 'Acórdão nº 202-09416 do Processo 10830.001301/95-11', 'https://www.lexml.gov.br/urn/urn:lex:br:segundo.conselho.contribuintes;camara.2;turma.ordinaria:acordao:1997-08-26;202-09416,4823394', '1997-08-26', '', '', 'jurisprudencia', 'IPI - CLASSIFICAÇÃO FISCAL - Por aplicação das RGI/SH e Notas do Capítulo, osaceleradoresde reação e preparações catalíticas que não sejam compostos de constituição química definida e que contenham outra substância deliberadamente adicionada durante a fabricação, merecem ser classificados na posição 3815, da TIPI/88. PENALIDADE. Por aplicação do princípio da retroatividade benigna disposta no art. 106, II, "a"e "b"do CTN ( art. 45 da Lei nr. 9.430/96 e Ato Declaratório/CST nr. 9, de 16.01.97). ENCARGOS DA TRD. Inaplicabilidade. A título de juros de mora no período anterior a 01.08.91. Princípio da irretroatividade da lei tributária. Recurso parcialmente provido.', '', 'LexML', 'transport_energy', 'Acórdão', '', 'IPI - CLASSIFICAÇÃO FISCAL - Por aplicação das RGI/SH e Notas do Capítulo, osaceleradoresde reação e preparações catalíticas que não sejam compostos de constituição química definida e que contenham outra substância deliberadamente adicionada durante a fabricação, merecem ser classificados na posição 3815, da TIPI/88. PENALIDADE. Por aplicação do princípio da retroatividade benigna disposta no art. 106, II, "a"e "b"do CTN ( art. 45 da Lei nr. 9.430/96 e Ato Declaratório/CST nr. 9, de 16.01.97). ENCARGOS DA TRD. Inaplicabilidade. A título de juros de mora no período anterior a 01.08.91. Princípio da irretroatividade da lei tributária. Recurso parcialmente provido.', '', 'Segundo Conselho de Contribuintes. 2ª Câmara. Turma Ordinária', 'Federal', 'Outros', '{"search_term": "", "urn_type": "jurisprudence", "country": "br", "source_file": "Jurisprud\u00eancia___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
