INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:federal:decreto:2019-08-08;9964', 'Decreto nº 9.964, de 8 de Agosto de 2019', 'https://www.lexml.gov.br/urn/urn:lex:br:federal:decreto:2019-08-08;9964', '2019-08-08', '', '', 'lei', 'Altera o Decreto nº 9.888, de 27 de junho de 2019, para dispor sobre critérios, procedimentos e responsabilidades para regulação e fiscalização da Certificação de Biocombustíveis e do lastro do Crédito deDescarbonizaçãoda Política Nacional de Biocombustíveis - RenovaBio. | Assuntos: ALTERAÇÃO ,  CRITERIOS ,  PROCEDIMENTO ,  RESPONSABILIDADE ,  FISCALIZAÇÃO ,  CERTIFICADO ,  Biocombustível ,  POLITICA NACIONAL ,  REDUÇÃO ,  GAS ,  EFEITO ESTUFA .', '', 'LexML', 'transport_energy', 'Decreto', '', 'Altera o Decreto nº 9.888, de 27 de junho de 2019, para dispor sobre critérios, procedimentos e responsabilidades para regulação e fiscalização da Certificação de Biocombustíveis e do lastro do Crédito deDescarbonizaçãoda Política Nacional de Biocombustíveis - RenovaBio. | Assuntos: ALTERAÇÃO ,  CRITERIOS ,  PROCEDIMENTO ,  RESPONSABILIDADE ,  FISCALIZAÇÃO ,  CERTIFICADO ,  Biocombustível ,  POLITICA NACIONAL ,  REDUÇÃO ,  GAS ,  EFEITO ESTUFA .', '', 'Federal', 'Federal', 'Outros', '{"search_term": "", "urn_type": "legislation", "country": "br", "source_file": "Legisla\u00e7\u00e3o___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br;minas.gerais:estadual:lei:2024-12-20;25073', 'Lei nº 25073, de 20 de dezembro de 2024', 'https://www.lexml.gov.br/urn/urn:lex:br;minas.gerais:estadual:lei:2024-12-20;25073', '2024-12-20', 'Minas Gerais', '', 'lei', 'Autoriza o Poder Executivo a prestar contragarantia à União em face das garantias por ela oferecidas nas operações de crédito externo a serem celebradas pelo Banco de Desenvolvimento de Minas Gerais S.A. junto ao Banco Interamericano de Desenvolvimento. | Assuntos: Autoriza o Poder Executivo a prestar contragarantia à União em 
face das garantias por ela oferecidas nas operações de crédito 
externo a serem celebradas pelo Banco de Desenvolvimento de 
Minas Gerais – BDMG – junto ao Banco Interamericano de 
Desenvolvimento – BID –, em moeda estrangeira, até o valor 
equivalente a cem milhões de dólares americanos, destinadas ao 
financiamento do Programa Minas para Resultados:Descarbonizaçãoe Resiliência Climática da carteira de crédito 
do BDMG. Por fim, a título de contragarantia às operações de 
crédito, o Poder Executivo pode oferecer à União suas cotas da 
repartição constitucional das receitas tributárias.', '', 'LexML', 'transport_energy', 'Lei', '', 'Autoriza o Poder Executivo a prestar contragarantia à União em face das garantias por ela oferecidas nas operações de crédito externo a serem celebradas pelo Banco de Desenvolvimento de Minas Gerais S.A. junto ao Banco Interamericano de Desenvolvimento. | Assuntos: Autoriza o Poder Executivo a prestar contragarantia à União em 
face das garantias por ela oferecidas nas operações de crédito 
externo a serem celebradas pelo Banco de Desenvolvimento de 
Minas Gerais – BDMG – junto ao Banco Interamericano de 
Desenvolvimento – BID –, em moeda estrangeira, até o valor 
equivalente a cem milhões de dólares americanos, destinadas ao 
financiamento do Programa Minas para Resultados:Descarbonizaçãoe Resiliência Climática da carteira de crédito 
do BDMG. Por fim, a título de contragarantia às operações de 
crédito, o Poder Executivo pode oferecer à União suas cotas da 
repartição constitucional das receitas tributárias.', '', 'Estadual', '', 'Outros', '{"search_term": "", "urn_type": "legislation", "country": "br", "source_file": "Legisla\u00e7\u00e3o___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
