INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:congresso.nacional:medida.provisoria;mpv:2001;2217', '[ Medida Provisória nº 2217-3/2001 ]', 'https://www.lexml.gov.br/urn/urn:lex:br:congresso.nacional:medida.provisoria;mpv:2001;2217', NULL, '', '', 'lei', 'Altera a Lei nº 10233, de 5 de junho de 2001, que dispõe sobre a reestruturação dostransportesaquaviárioe terrestre, cria o Conselho Nacional de Integração de Políticas deTransporte, a Agência Nacional deTransportesTerrestres, a Agência Nacional deTransportesAquaviáriose o Departamento Nacional de Infra-Estrutura deTransportes, e dá outras providências.', '', 'LexML', 'transport_energy', 'Medida Provisória', '', 'Altera a Lei nº 10233, de 5 de junho de 2001, que dispõe sobre a reestruturação dostransportesaquaviárioe terrestre, cria o Conselho Nacional de Integração de Políticas deTransporte, a Agência Nacional deTransportesTerrestres, a Agência Nacional deTransportesAquaviáriose o Departamento Nacional de Infra-Estrutura deTransportes, e dá outras providências.', '', 'Congresso Nacional', 'Federal', 'Legislativo Federal', '{"search_term": "", "urn_type": "legislation", "country": "br", "source_file": "Legisla\u00e7\u00e3o___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
