INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:congresso.nacional:medida.provisoria;mpv:2016-12-23;762', 'MPV 762/2016', 'https://www.lexml.gov.br/urn/urn:lex:br:congresso.nacional:medida.provisoria;mpv:2016-12-23;762', '2016-12-23', '', '', 'lei', 'Altera a Lei nº 11.482, de 31 de maio de 2007, para prorrogar o prazo de vigência da não incidência do Adicional aoFretepara Renovação da Marinha Mercante - AFRMM previsto no art. 17 da Lei nº 9.432, de 8 de janeiro de 1997. 

NOVA EMENTA: Altera a Lei nº 11.482, de 31 de maio de 2007, para prorrogar o prazo de vigência da não incidência do Adicional aoFretepara Renovação da Marinha Mercante (AFRMM) previsto no art. 17 da Lei nº 9.432, de 8 de janeiro de 1997; a Lei nº 9.432, de 8 de janeiro de 1997; e a Lei nº 10.893, de 13 de julho de 2004.', '', 'LexML', 'transport_energy', 'Medida Provisória', '', 'Altera a Lei nº 11.482, de 31 de maio de 2007, para prorrogar o prazo de vigência da não incidência do Adicional aoFretepara Renovação da Marinha Mercante - AFRMM previsto no art. 17 da Lei nº 9.432, de 8 de janeiro de 1997. 

NOVA EMENTA: Altera a Lei nº 11.482, de 31 de maio de 2007, para prorrogar o prazo de vigência da não incidência do Adicional aoFretepara Renovação da Marinha Mercante (AFRMM) previsto no art. 17 da Lei nº 9.432, de 8 de janeiro de 1997; a Lei nº 9.432, de 8 de janeiro de 1997; e a Lei nº 10.893, de 13 de julho de 2004.', '', 'Congresso Nacional', 'Federal', 'Legislativo Federal', '{"search_term": "", "urn_type": "legislation", "country": "br", "source_file": "Legisla\u00e7\u00e3o___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:congresso.nacional:medida.provisoria;mpv:2018-05-27;831', 'MPV 831/2018', 'https://www.lexml.gov.br/urn/urn:lex:br:congresso.nacional:medida.provisoria;mpv:2018-05-27;831', '2018-05-27', '', '', 'lei', 'Altera a Lei nº 8.029, de 12 de abril de 1990, que dispõe sobre a extinção e dissolução de entidades da administração pública federal.

NOVA EMENTA: Altera a Lei nº 8.029, de 12 de abril de 1990, para prever a contratação direta pela Companhia Nacional de Abastecimento (Conab) de cooperativas e associações de transportadores autônomos de cargas de, no mínimo, 30% (trinta por cento) da demanda anual defreteda Companhia.', '', 'LexML', 'transport_energy', 'Medida Provisória', '', 'Altera a Lei nº 8.029, de 12 de abril de 1990, que dispõe sobre a extinção e dissolução de entidades da administração pública federal.

