INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br;santa.catarina:estadual:lei:2011-11-21;15622', 'LEI Nº 15.622, de 21 de novembro de 2011', 'https://www.lexml.gov.br/urn/urn:lex:br;santa.catarina:estadual:lei:2011-11-21;15622', '2011-11-21', 'Santa Catarina', '', 'lei', 'Art. 1º Fica o Poder Executivo autorizado a ceder à Agência Nacional do Petróleo, Gás Natural e Biocombustíveis -ANP, pelo prazo de 5 (cinco) anos, o uso gratuito de parte do imóvel com área de 11,14 m² (onze metros e quatorze decímetros quadrados), no Município de Florianópolis, onde funciona o Comando do Corpo de Bombeiros Militar de Santa Catarina, escriturado no livro de notas sob o nº 114, fls. 26 verso a 28 e cadastrado sob o nº 01576 no Sistema de Gestão Patrimonial da Secretaria de Estado da Administração. | Assuntos: ANP', '', 'LexML', 'transport_energy', 'Lei', '', 'Art. 1º Fica o Poder Executivo autorizado a ceder à Agência Nacional do Petróleo, Gás Natural e Biocombustíveis -ANP, pelo prazo de 5 (cinco) anos, o uso gratuito de parte do imóvel com área de 11,14 m² (onze metros e quatorze decímetros quadrados), no Município de Florianópolis, onde funciona o Comando do Corpo de Bombeiros Militar de Santa Catarina, escriturado no livro de notas sob o nº 114, fls. 26 verso a 28 e cadastrado sob o nº 01576 no Sistema de Gestão Patrimonial da Secretaria de Estado da Administração. | Assuntos: ANP', '', 'Estadual', '', 'Outros', '{"search_term": "", "urn_type": "legislation", "country": "br", "source_file": "Legisla\u00e7\u00e3o___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
