INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:federal:decreto:1982-06-07;87253', 'Decreto nº 87.253, de 7 de Junho de 1982', 'https://www.lexml.gov.br/urn/urn:lex:br:federal:decreto:1982-06-07;87253', '1982-06-07', '', '', 'lei', 'Atribui competência ao Conselho Nacional do Petróleo, para atestar aqualidadede aditivos ou de produtos a serem introduzidos noscombustíveisderivados de petróleo e em álcool etílico hidratadocombustível, e dá outras providências. | Assuntos: COMPETENCIA ,  CONSELHO NACIONAL DO PETROLEO (CNP) ,  ATESTADO ,QUALIDADE,  ADITIVO ,  PRODUTO ,COMBUSTIVEL,  DERIVADOS DE PETROLEO ,  ALCOOL HIDRATADO .', '', 'LexML', 'transport_energy', 'Decreto', '', 'Atribui competência ao Conselho Nacional do Petróleo, para atestar aqualidadede aditivos ou de produtos a serem introduzidos noscombustíveisderivados de petróleo e em álcool etílico hidratadocombustível, e dá outras providências. | Assuntos: COMPETENCIA ,  CONSELHO NACIONAL DO PETROLEO (CNP) ,  ATESTADO ,QUALIDADE,  ADITIVO ,  PRODUTO ,COMBUSTIVEL,  DERIVADOS DE PETROLEO ,  ALCOOL HIDRATADO .', '', 'Federal', 'Federal', 'Outros', '{"search_term": "", "urn_type": "legislation", "country": "br", "source_file": "Legisla\u00e7\u00e3o___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br;santa.catarina:estadual:lei:2014-11-27;16492', 'LEI Nº 16.492, DE 27 DE NOVEMBRO DE 2014', 'https://www.lexml.gov.br/urn/urn:lex:br;santa.catarina:estadual:lei:2014-11-27;16492', '2014-11-27', 'Santa Catarina', '', 'lei', 'Art. 1º O art. 3º da Lei nº 13.325, de 20 de janeiro de 2005, passa a vigorar com a seguinte redação: “Art. 3º Os postos revendedores ficam obrigados a exibir, de maneira correta e clara, o nome da empresa distribuidora fornecedoradoscombustíveis, de modo a assegurar ao consumidor o prévio conhecimento sobre a origem e aqualidadedoproduto adquirido, inclusive com a exposição obrigatória em local de ampla visualização dos consumidores dos telefones do Procon, da Secretaria de Estado da Fazenda, da Polícia Civil do Estado de Santa Catarina e do Comitê Sul Brasileiro deQualidadedosCombustíveis, participantes do programa de defesa do consumidor denominado Pró-Combustíveis.” (NR) | Assuntos: dispõe sobre a comercialização de produtoscombustíveisao consumidor final', '', 'LexML', 'transport_energy', 'Lei', '', 'Art. 1º O art. 3º da Lei nº 13.325, de 20 de janeiro de 2005, passa a vigorar com a seguinte redação: “Art. 3º Os postos revendedores ficam obrigados a exibir, de maneira correta e clara, o nome da empresa distribuidora fornecedoradoscombustíveis, de modo a assegurar ao consumidor o prévio conhecimento sobre a origem e aqualidadedoproduto adquirido, inclusive com a exposição obrigatória em local de ampla visualização dos consumidores dos telefones do Procon, da Secretaria de Estado da Fazenda, da Polícia Civil do Estado de Santa Catarina e do Comitê Sul Brasileiro deQualidadedosCombustíveis, participantes do programa de defesa do consumidor denominado Pró-Combustíveis.” (NR) | Assuntos: dispõe sobre a comercialização de produtoscombustíveisao consumidor final', '', 'Estadual', '', 'Outros', '{"search_term": "", "urn_type": "legislation", "country": "br", "source_file": "Legisla\u00e7\u00e3o___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
