INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:congresso.nacional:medida.provisoria;mpv:2020-07-16;992', 'MPV 992/2020', 'https://www.lexml.gov.br/urn/urn:lex:br:congresso.nacional:medida.provisoria;mpv:2020-07-16;992', '2020-07-16', '', '', 'lei', 'Dispõe sobre ofinanciamentoa microempresa e empresa de pequeno e médio porte, sobre o crédito presumido apurado com base em créditos decorrentes de diferenças temporárias, sobre o compartilhamento de alienação fiduciária e sobre a dispensa do cumprimento de exigências de demonstração de regularidade fiscal nas operações praticadas pelo Banco Central do Brasil em decorrência do disposto no art. 7º da Emenda Constitucional nº 106, de 7 de maio de 2020, e altera a Lei nº 13.476, de 28 de agosto de 2017, a Lei nº 13.097, de 19 de janeiro de 2015, e a Lei nº 6.015, de 31 de dezembro de 1973.', '', 'LexML', 'transport_energy', 'Medida Provisória', '', 'Dispõe sobre ofinanciamentoa microempresa e empresa de pequeno e médio porte, sobre o crédito presumido apurado com base em créditos decorrentes de diferenças temporárias, sobre o compartilhamento de alienação fiduciária e sobre a dispensa do cumprimento de exigências de demonstração de regularidade fiscal nas operações praticadas pelo Banco Central do Brasil em decorrência do disposto no art. 7º da Emenda Constitucional nº 106, de 7 de maio de 2020, e altera a Lei nº 13.476, de 28 de agosto de 2017, a Lei nº 13.097, de 19 de janeiro de 2015, e a Lei nº 6.015, de 31 de dezembro de 1973.', '', 'Congresso Nacional', 'Federal', 'Legislativo Federal', '{"search_term": "", "urn_type": "legislation", "country": "br", "source_file": "Legisla\u00e7\u00e3o___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
