INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:congresso.nacional:medida.provisoria;mpv:2024;1226', '[ Medida Provisória nº 1226/2024 ]', 'https://www.lexml.gov.br/urn/urn:lex:br:congresso.nacional:medida.provisoria;mpv:2024;1226', NULL, '', '', 'lei', 'Altera a Lei nº 12.351, de 22 de dezembro de 2010, para autorizar a utilização do superávit financeiro do Fundo Social como fonte de recursos para a disponibilização de linhas definanciamentoa pessoas jurídicas e físicas localizadas em ente federativo em estado de calamidade pública, nos termos do art. 65 da Lei Complementar nº 101, de 4 de maio de 2000, autoriza a União a aumentar a sua participação no Fundo Garantidor de Operações para a cobertura das operações contratadas no âmbito do Programa Nacional de Fortalecimento da Agricultura Familiar e do Programa Nacional de Apoio ao Médio Produtor Rural com beneficiários que tiveram perdas materiais nas áreas afetadas pelos eventos climáticos extremos ocorridos nos meses de abril e maio de 2024, e dispõe sobre a subvenção de que trata o art. 2º da Medida Provisória nº 1.216, de 9 de maio de 2024.', '', 'LexML', 'transport_energy', 'Medida Provisória', '', 'Altera a Lei nº 12.351, de 22 de dezembro de 2010, para autorizar a utilização do superávit financeiro do Fundo Social como fonte de recursos para a disponibilização de linhas definanciamentoa pessoas jurídicas e físicas localizadas em ente federativo em estado de calamidade pública, nos termos do art. 65 da Lei Complementar nº 101, de 4 de maio de 2000, autoriza a União a aumentar a sua participação no Fundo Garantidor de Operações para a cobertura das operações contratadas no âmbito do Programa Nacional de Fortalecimento da Agricultura Familiar e do Programa Nacional de Apoio ao Médio Produtor Rural com beneficiários que tiveram perdas materiais nas áreas afetadas pelos eventos climáticos extremos ocorridos nos meses de abril e maio de 2024, e dispõe sobre a subvenção de que trata o art. 2º da Medida Provisória nº 1.216, de 9 de maio de 2024.', '', 'Congresso Nacional', 'Federal', 'Legislativo Federal', '{"search_term": "", "urn_type": "legislation", "country": "br", "source_file": "Legisla\u00e7\u00e3o___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
