INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:federal:lei:2014-07-31;13019', 'Lei nº 13.019, de 31 de Julho de 2014', 'https://www.lexml.gov.br/urn/urn:lex:br:federal:lei:2014-07-31;13019', '2014-07-31', '', '', 'lei', 'Estabelece o regime jurídico das parcerias voluntárias, envolvendo ou não transferências de recursos financeiros, entre a administração pública e as organizações da sociedade civil, em regime de mútua cooperação, para a consecução de finalidades de interesse público; define diretrizes para a política de fomento e de colaboração com organizações da sociedade civil; institui o termo de colaboração e o termo de fomento; e altera as Leis nºs 8.429, de 2 de junho de 1992, e 9.790, de 23 demarçode 1999. | Assuntos: DEFINIÇÃO ,  DIRETRIZES GERAIS ,  POLITICA ,  FOMENTO ,  COLABORAÇÃO ,  ORGANIZAÇÃO ,  SOCIEDADE CIVIL . CRIAÇÃO ,  NORMAS GERAIS ,  REGIME JURIDICO ,  PARCERIA ,  CARACTERISTICA ,  VOLUNTARIO ,  ADMINISTRAÇÃO PUBLICA ,  COOPERAÇÃO ,  FOMENTO ,  ORGANIZAÇÃO ,  SOCIEDADE CIVIL ,  TRANSFERENCIA ,  RECURSOS FINANCEIROS ,  OBJETIVO ,  INTERESSE PUBLICO ,  INTERESSE SOCIAL . CRIAÇÃO ,  TERMO ,  COLABORAÇÃO ,  FOMENTO ,  CHAMADA ,  CELEBRAÇÃO ,  REQUISITOS ,  PROIBIÇÃO ,  FORMALIZAÇÃO ,  EXECUÇÃO ,  DESPESA ,  RECURSOS ,  LIBERAÇÃO ,  MOVIMENTAÇÃO ,  APLICAÇÃO FINANCEIRA ,  ALTERAÇÃO ,  PLANO DE TRABALHO ,  AVALIAÇÃO ,  TRANSPARENCIA ADMINISTRATIVA ,  CONTROLE ,  GESTÃO ,  PRESTAÇÃO DE CONTAS ,  PRAZO ,  RESPONSABILIDADE ,  SANÇÃO ,  PUNIÇÃO ADMINISTRATIVA ,  ATO ,  IMPROBIDADE ADMINISTRATIVA .', '', 'LexML', 'transport_energy', 'Lei', '', 'Estabelece o regime jurídico das parcerias voluntárias, envolvendo ou não transferências de recursos financeiros, entre a administração pública e as organizações da sociedade civil, em regime de mútua cooperação, para a consecução de finalidades de interesse público; define diretrizes para a política de fomento e de colaboração com organizações da sociedade civil; institui o termo de colaboração e o termo de fomento; e altera as Leis nºs 8.429, de 2 de junho de 1992, e 9.790, de 23 demarçode 1999. | Assuntos: DEFINIÇÃO ,  DIRETRIZES GERAIS ,  POLITICA ,  FOMENTO ,  COLABORAÇÃO ,  ORGANIZAÇÃO ,  SOCIEDADE CIVIL . CRIAÇÃO ,  NORMAS GERAIS ,  REGIME JURIDICO ,  PARCERIA ,  CARACTERISTICA ,  VOLUNTARIO ,  ADMINISTRAÇÃO PUBLICA ,  COOPERAÇÃO ,  FOMENTO ,  ORGANIZAÇÃO ,  SOCIEDADE CIVIL ,  TRANSFERENCIA ,  RECURSOS FINANCEIROS ,  OBJETIVO ,  INTERESSE PUBLICO ,  INTERESSE SOCIAL . CRIAÇÃO ,  TERMO ,  COLABORAÇÃO ,  FOMENTO ,  CHAMADA ,  CELEBRAÇÃO ,  REQUISITOS ,  PROIBIÇÃO ,  FORMALIZAÇÃO ,  EXECUÇÃO ,  DESPESA ,  RECURSOS ,  LIBERAÇÃO ,  MOVIMENTAÇÃO ,  APLICAÇÃO FINANCEIRA ,  ALTERAÇÃO ,  PLANO DE TRABALHO ,  AVALIAÇÃO ,  TRANSPARENCIA ADMINISTRATIVA ,  CONTROLE ,  GESTÃO ,  PRESTAÇÃO DE CONTAS ,  PRAZO ,  RESPONSABILIDADE ,  SANÇÃO ,  PUNIÇÃO ADMINISTRATIVA ,  ATO ,  IMPROBIDADE ADMINISTRATIVA .', '', 'Federal', 'Federal', 'Outros', '{"search_term": "", "urn_type": "legislation", "country": "br", "source_file": "Legisla\u00e7\u00e3o___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
