INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:tribunal.superior.trabalho;turma.5:acordao;rr:2007-09-26;14700-2003-103-3-0', 'Acórdão do processo Nº RR - 14700-52.2003.5.03.0103', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.5:acordao;rr:2007-09-26;14700-2003-103-3-0', '2007-09-26', '', '', 'outro', 'ADICIONAL DE PERICULOSIDADE. SISTEMAELÉTRICODE POTÊNCIA.CAMINHÃO¿MUCK¿. EXPOSIÇÃO A RISCO PRÓXIMO A TENSÃO DE 3.800V. Empregado que operacaminhãomuck equipado com cesto aéreo expõe-se a eletricidade ante o risco de queda de cabo eletrificado sobre ocaminhãoenquanto opera o braço levantador por ocasião de substituição de lâmpadas de iluminação pública. Acórdão regional em harmonia com a jurisprudência desta Corte concentrada na Orientação Jurisprudencial 324 da SBDI-1. Recurso de Revista de que não se conhece.', '', 'LexML', 'transport_energy', '', '', 'ADICIONAL DE PERICULOSIDADE. SISTEMAELÉTRICODE POTÊNCIA.CAMINHÃO¿MUCK¿. EXPOSIÇÃO A RISCO PRÓXIMO A TENSÃO DE 3.800V. Empregado que operacaminhãomuck equipado com cesto aéreo expõe-se a eletricidade ante o risco de queda de cabo eletrificado sobre ocaminhãoenquanto opera o braço levantador por ocasião de substituição de lâmpadas de iluminação pública. Acórdão regional em harmonia com a jurisprudência desta Corte concentrada na Orientação Jurisprudencial 324 da SBDI-1. Recurso de Revista de que não se conhece.', '', 'Tribunal Superior do Trabalho. 5ª Turma', 'Federal', 'Tribunal', '{"search_term": "", "urn_type": "other", "country": "br", "source_file": "Outros___A\u00e9reo.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:tribunal.superior.trabalho;turma.2:acordao;ag:2023-10-04;588-2017-15-5-0', 'Acórdão do processo Nº Ag-RRAg - 588-06.2017.5.05.0015', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.2:acordao;ag:2023-10-04;588-2017-15-5-0', '2023-10-04', '', '', 'outro', 'I -  AGRAVO DA RECLAMADA. AGRAVO DE INSTRUMENTO. RECURSO DE REVISTA. ADICIONAL DE PERICULOSIDADE. Constam do acórdão regional as seguintes atividades exercidas pelo reclamante: a) acompanhar "implantação, construção e manutenção das usinas de geração de energiaelétricaem operações"; b) acompanhar "tarefas de descarregamento doscaminhõescom óleo diesel nos locais indicados (tanques aéreos), usado durante as operações das usinas, bem como o abastecimento doscaminhõesque circulavam pelo interior da Empresa (média de 4 por mês cerca de uma hora por vez)"; c) verificar "se os funcionários utilizavam os EPIs corretamente"; d) "verificar vazamentos"; e e) "acompanhar e prestar auxílio a problemas operacionais que porventura ocorriam". O TRT, com fundamento no laudo pericial, manteve a sentença na qual deferido o adicional de periculosidade, tendo em vista que o reclamante ficava exposto a condições de risco de forma intermitente. Consignou, ademais, que a prova técnica não foi infirmada por prova em contrário. Para reverter esse entendimento, conforme pretendido, seria necessário revolver o conjunto fático-probatório dos autos, o que é vedado pela Súmula 126/TST. Agravo não provido. II -  RECURSO DE REVISTA DO RECLAMANTE. SOBREAVISO. O TRT concluiu que, no caso, "não se verifica a presença dos elementos caracterizadores do sobreaviso". Registrou que, do depoimento do reclamante, não se extrai que havia restrição à sua liberdade de locomoção. Para reverter esse entendimento, conforme pretendido, seria necessário revolver o conjunto fático-probatório dos autos, o que é vedado pela Súmula 126/TST. Recurso de revista não conhecido.', '', 'LexML', 'transport_energy', '', '', 'I -  AGRAVO DA RECLAMADA. AGRAVO DE INSTRUMENTO. RECURSO DE REVISTA. ADICIONAL DE PERICULOSIDADE. Constam do acórdão regional as seguintes atividades exercidas pelo reclamante: a) acompanhar "implantação, construção e manutenção das usinas de geração de energiaelétricaem operações"; b) acompanhar "tarefas de descarregamento doscaminhõescom óleo diesel nos locais indicados (tanques aéreos), usado durante as operações das usinas, bem como o abastecimento doscaminhõesque circulavam pelo interior da Empresa (média de 4 por mês cerca de uma hora por vez)"; c) verificar "se os funcionários utilizavam os EPIs corretamente"; d) "verificar vazamentos"; e e) "acompanhar e prestar auxílio a problemas operacionais que porventura ocorriam". O TRT, com fundamento no laudo pericial, manteve a sentença na qual deferido o adicional de periculosidade, tendo em vista que o reclamante ficava exposto a condições de risco de forma intermitente. Consignou, ademais, que a prova técnica não foi infirmada por prova em contrário. Para reverter esse entendimento, conforme pretendido, seria necessário revolver o conjunto fático-probatório dos autos, o que é vedado pela Súmula 126/TST. Agravo não provido. II -  RECURSO DE REVISTA DO RECLAMANTE. SOBREAVISO. O TRT concluiu que, no caso, "não se verifica a presença dos elementos caracterizadores do sobreaviso". Registrou que, do depoimento do reclamante, não se extrai que havia restrição à sua liberdade de locomoção. Para reverter esse entendimento, conforme pretendido, seria necessário revolver o conjunto fático-probatório dos autos, o que é vedado pela Súmula 126/TST. Recurso de revista não conhecido.', '', 'Tribunal Superior do Trabalho. 2ª Turma', 'Federal', 'Tribunal', '{"search_term": "", "urn_type": "other", "country": "br", "source_file": "Outros___A\u00e9reo.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:congresso.nacional:projeto.lei.conversao;plv:2023-04-25;9', 'PLV 9/2023', 'https://www.lexml.gov.br/urn/urn:lex:br:congresso.nacional:projeto.lei.conversao;plv:2023-04-25;9', '2023-04-25', '', '', 'outro', 'Altera a Lei nº 14.148, de 3 de maio de 2021, que instituiu o Programa Emergencial de Retomada do Setor de Eventos – Perse; reduz a zero por cento as alíquotas da Contribuição para o Programa de Integração Social e o Programa de Formação do Patrimônio do Servidor Público - PIS/Pasep e da Contribuição para o Financiamento da Seguridade Social - Cofins incidentes sobre as receitas decorrentes da atividade de transporte aéreo regular de passageiros; reduz as alíquotas da Contribuição para o Programa de Integração Social e o Programa de Formação do Patrimônio do Servidor Público - PIS/Pasep e da Contribuição para o Financiamento da Seguridade Social - Cofins incidentes sobre operações realizadas com óleo diesel, biodiesel, gás liquefeito de petróleo, álcool, querosene de aviação, gás naturalveiculare gasolina; altera a Lei nº 10.637, de 30 de dezembro de 2002, e a Lei nº 10.833, de 29 de dezembro de 2003, para excluir o Imposto sobre Operações relativas à Circulação de Mercadorias e sobre Prestações de Serviços de Transporte Interestadual e Intermunicipal e de Comunicação - ICMS da incidência e da base de cálculo dos créditos da Contribuição para o Programa de Integração Social e o Programa de Formação do Patrimônio do Servidor Público - PIS/Pasep e da Contribuição para o Financiamento da Seguridade Social – Cofins; e dá outras providências.', '', 'LexML', 'transport_energy', '', '', 'Altera a Lei nº 14.148, de 3 de maio de 2021, que instituiu o Programa Emergencial de Retomada do Setor de Eventos – Perse; reduz a zero por cento as alíquotas da Contribuição para o Programa de Integração Social e o Programa de Formação do Patrimônio do Servidor Público - PIS/Pasep e da Contribuição para o Financiamento da Seguridade Social - Cofins incidentes sobre as receitas decorrentes da atividade de transporte aéreo regular de passageiros; reduz as alíquotas da Contribuição para o Programa de Integração Social e o Programa de Formação do Patrimônio do Servidor Público - PIS/Pasep e da Contribuição para o Financiamento da Seguridade Social - Cofins incidentes sobre operações realizadas com óleo diesel, biodiesel, gás liquefeito de petróleo, álcool, querosene de aviação, gás naturalveiculare gasolina; altera a Lei nº 10.637, de 30 de dezembro de 2002, e a Lei nº 10.833, de 29 de dezembro de 2003, para excluir o Imposto sobre Operações relativas à Circulação de Mercadorias e sobre Prestações de Serviços de Transporte Interestadual e Intermunicipal e de Comunicação - ICMS da incidência e da base de cálculo dos créditos da Contribuição para o Programa de Integração Social e o Programa de Formação do Patrimônio do Servidor Público - PIS/Pasep e da Contribuição para o Financiamento da Seguridade Social – Cofins; e dá outras providências.', '', 'Congresso Nacional', 'Federal', 'Legislativo Federal', '{"search_term": "", "urn_type": "other", "country": "br", "source_file": "Outros___A\u00e9reo.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
