INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:agencia.nacional.energia.eletrica:resolucao.autorizativa:2008-07-29;1460', 'RESOLUÇÃO AUTORIZATIVA nº 1460, de 29/07/2008', 'https://www.lexml.gov.br/urn/urn:lex:br:agencia.nacional.energia.eletrica:resolucao.autorizativa:2008-07-29;1460', '2008-07-29', '', '', 'outro', 'Transfere da RovemaVeículose Máquinas Ltda para a Propower Geradora de Energia Ltda, as autorizações para implantação e exploração das Pequenas Centrais Hidrelétricas Cachoeira Formosa e Machadinho I, respectivamente nos rios Candeias e Machadinho, municípios de Buritis e Machadinho D''Oeste, (RO), bem como autoriza a modificação das características técnicas das instalações de transmissão da PCH Machadino I, e revoga o parág. 1º do art. 4º da Resolução ANEEL 166 de 26.04.2001 e o parág. 1º do art. 3º da Resolução ANEEL 250 de 07.05.2002. | Assuntos: Autorização. RovemaVeículose Máquinas Ltda. Transferência. Propower Geradora de Energia Ltda. Implantação. Exploração. Potencial Hidráulico. PCH Cachoeira Formosa. Rio Candeias. PCH Machadinho 1. Rio Machadinho. Buritis e Machadinho D''oeste (Ro). {Alteração, Modificação}. Característica Técnica. Instalação. {Transmissão, TransmissãoElétrica}. Revogação. Parágrafo. {Artigo, Artigos}. Resolução | RovemaVeículose Máquinas Ltda. Propower Geradora de Energia Ltda. Autorização. Transferência. Implantação. Exploração. Potencial hidráulico. PCH Cachoeira Formosa. PCH Machadinho 1. Alteração. Característica técnica. Instalação. {Transmissão, TransmissãoElétrica}. Revogação. Parágrafo. {Artigo, Artigos}. Resolução. Rio Candeias. Rio Machadinho. Buritis (RO). Machadinho D''Oeste (RO)', '', 'LexML', 'transport_energy', '', '', 'Transfere da RovemaVeículose Máquinas Ltda para a Propow