INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:federal:decreto.lei:1943-03-19;5332', 'Decreto-Lei nº 5.332, de 19 de Março de 1943', 'https://www.lexml.gov.br/urn/urn:lex:br:federal:decreto.lei:1943-03-19;5332', '1943-03-19', '', '', 'outro', 'Extingue a 1ªBateriaIndependente de Metralhadoras Anti-Aéreas, da 7ª Região Militar. | Assuntos: EXTINÇÃO ,  ORGANIZAÇÃO MILITAR (OM) ,BATERIA,  METRALHADORA .', '', 'LexML', 'transport_energy', '', '', 'Extingue a 1ªBateriaIndependente de Metralhadoras Anti-Aéreas, da 7ª Região Militar. | Assuntos: EXTINÇÃO ,  ORGANIZAÇÃO MILITAR (OM) ,BATERIA,  METRALHADORA .', '', 'Federal', 'Federal', 'Outros', '{"search_term": "", "urn_type": "other", "country": "br", "source_file": "Outros___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
