INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br;minas.gerais;divinopolis:municipal:lei.complementar:2022-07-05;226', 'Lei Complementar n° 226, de 05 de Julho de 2022', 'https://www.lexml.gov.br/urn/urn:lex:br;minas.gerais;divinopolis:municipal:lei.complementar:2022-07-05;226', '2022-07-05', 'MG', 'Divinópolis', 'outro', 'Altera dispositivos relativos ao Imposto Sobre Serviços de Qualquer Natureza - ISSQN - contidos na Lei Complementar nº 007, de 28 de dezembro de 1991 - Serviços de guarda, estacionamento, armazenamento, vigilância e congêneres - 11.05 - Serviços relacionados ao monitoramento erastreamentoa distância, em qualquer via ou local, de veículos, cargas, pessoas e semoventes em circulação ou movimento, realizados por meio de telefonia móvel, transmissão de satélites, rádio ou qualquer outro meio, inclusive pelas empresas de Tecnologia da Informação Veicular, independentemente de o prestador de serviços ser proprietário ou não da infraestrutura de telecomunicações que utiliza. | Assuntos: Altera dispositivos relativos ao Imposto Sobre Serviços de Qualquer Natureza - ISSQN - contidos na Lei Complementar nº 007, de 28 de dezembro de 1991 - Serviços de guarda, estacionamento, armazenamento, vigilância e congêneres - 11.05 - Serviços relacionados ao monitoramento erastreamentoa distância, em qualquer via ou local, de veículos, cargas, pessoas e semoventes em circulação ou movimento, realizados por meio de telefonia móvel, transmissão de satélites, rádio ou qualquer outro meio, inclusive pelas empresas de Tecnologia da Informação Veicular, independentemente de o prestador de serviços ser proprietário ou não da infraestrutura de telecomunicações que utiliza.', '', 'LexML', 'transport_energy', '', '', 'Altera dispositivos relativos ao Imposto Sobre Serviços de Qualquer Natureza - ISSQN - contidos na Lei Complementar nº 007, de 28 de dezembro de 1991 - Serviços de guarda, estacionamento, armazenamento, vigilância e congêneres - 11.05 - Serviços relacionados ao monitoramento erastreamentoa distância, em qualquer via ou local, de veículos, cargas, pessoas e semoventes em circulação ou movimento, realizados por meio de telefonia móvel, transmissão de satélites, rádio ou qualquer outro meio, inclusive pelas empresas de Tecnologia da Informação Veicular, independentemente de o prestador de serviços ser proprietário ou não da infraestrutura de telecomunicações que utiliza. | Assuntos: Altera dispositivos relativos ao Imposto Sobre Serviços de Qualquer Natureza - ISSQN - contidos na Lei Complementar nº 007, de 28 de dezembro de 1991 - Serviços de guarda, estacionamento, armazenamento, vigilância e congêneres - 11.05 - Serviços relacionados ao monitoramento erastreamentoa distância, em qualquer via ou local, de veículos, cargas, pessoas e semoventes em circulação ou movimento, realizados por meio de telefonia móvel, transmissão de satélites, rádio ou qualquer outro meio, inclusive pelas empresas de Tecnologia da Informação Veicular, independentemente de o prestador de serviços ser proprietário ou não da infraestrutura de telecomunicações que utiliza.', '', 'Municipal', '', 'Outros', '{"search_term": "", "urn_type": "other", "country": "br", "source_file": "Outros___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:tribunal.superior.trabalho;turma.2:acordao;rr:2018-03-20;190-2014-222-5-0', 'Acórdão do processo Nº RR - 190-25.2014.5.05.0222', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.2:acordao;rr:2018-03-20;190-2014-222-5-0', '2018-03-20', '', '', 'outro', 'I - AGRAVO. AGRAVO DE INSTRUMENTO. RECURSO DE REVISTA. HORAS EXTRAS. TRABALHO EXTERNO. EXISTÊNCIA DE TACÓGRAFO ERASTREAMENTO. Observo possível violação ao art. 62, I, da CLT. Dou provimento para analisar o agravo de instrumento. II - AGRAVO DE INSTRUMENTO. HORAS EXTRAS. TRABALHO EXTERNO. EXISTÊNCIA DE TACÓGRAFO ERASTREAMENTO. Observo possível violação ao art. 62, I, da CLT. Agravo de instrumento conhecido e provido. III - RECURSO DE REVISTA. HORAS EXTRAS. TRABALHO EXTERNO. EXISTÊNCIA DE TACÓGRAFO ERASTREAMENTO. Na hipótese, o TRT esclarece que havia tacógrafo erastreamentopor satélite. Para configuração da hipótese do art. 62, I, da CLT não se exige a simples constatação de exercício de atividade externa, mas, sim, daquela que, por sua natureza, seja incompatível com a fixação ou possibilidade de controle direto ou indireto da jornada de trabalho. Do exame do acórdão regional, infere-se a possibilidade de controle da jornada do empregado, pois o veículo utilizado pelo autor era equipado com dispositivo derastreamentovia satélite. A jurisprudência desta Corte Superior firmou entendimento de que o sistema de monitoramento erastreamentoviabiliza o controle de jornada do empregado. Precedentes. Recurso de revista conhecido e provido.', '', 'LexML', 'transport_energy', '', '', 'I - AGRAVO. AGRAVO DE INSTRUMENTO. RECURSO DE REVISTA. HORAS EXTRAS. TRABALHO EXTERNO. EXISTÊNCIA DE TACÓGRAFO ERASTREAMENTO. Observo possível violação ao art. 62, I, da CLT. Dou provimento para analisar o agravo de instrumento. II - AGRAVO DE INSTRUMENTO. HORAS EXTRAS. TRABALHO EXTERNO. EXISTÊNCIA DE TACÓGRAFO ERASTREAMENTO. Observo possível violação ao art. 62, I, da CLT. Agravo de instrumento conhecido e provido. III - RECURSO DE REVISTA. HORAS EXTRAS. TRABALHO EXTERNO. EXISTÊNCIA DE TACÓGRAFO ERASTREAMENTO. Na hipótese, o TRT esclarece que havia tacógrafo erastreamentopor satélite. Para configuração da hipótese do art. 62, I, da CLT não se exige a simples constatação de exercício de atividade externa, mas, sim, daquela que, por sua natureza, seja incompatível com a fixação ou possibilidade de controle direto ou indireto da jornada de trabalho. Do exame do acórdão regional, infere-se a possibilidade de controle da jornada do empregado, pois o veículo utilizado pelo autor era equipado com dispositivo derastreamentovia satélite. A jurisprudência desta Corte Superior firmou entendimento de que o sistema de monitoramento erastreamentoviabiliza o controle de jornada do empregado. Precedentes. Recurso de revista conhecido e provido.', '', 'Tribunal Superior do Trabalho. 2ª Turma', 'Federal', 'Tribunal', '{"search_term": "", "urn_type": "other", "country": "br", "source_file": "Outros___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:tribunal.superior.trabalho;turma.2:acordao;rr:2018-11-27;2128-2012-242-9-0', 'Acórdão do processo Nº RR - 2128-52.2012.5.09.0242', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.2:acordao;rr:2018-11-27;2128-2012-242-9-0', '2018-11-27', '', '', 'outro', 'I - AGRAVO DE INSTRUMENTO. RECURSO DE REVISTA. HORAS EXTRAS. TRABALHO EXTERNO. EXISTÊNCIA DERASTREAMENTO. Observa-se possível violação ao art. 62, I, da CLT. Agravo de instrumento conhecido e provido. II - RECURSO DE REVISTA. HORAS EXTRAS. TRABALHO EXTERNO. EXISTÊNCIA DERASTREAMENTO. Na hipótese, o TRT esclarece que haviarastreamentodos veículos. Para configuração da hipótese do art. 62, I, da CLT não se exige a simples constatação de exercício de atividade externa, mas, sim, daquela que, por sua natureza, seja incompatível com a fixação ou possibilidade de controle direto ou indireto da jornada de trabalho. Do exame do acórdão regional, infere-se a possibilidade de controle da jornada do empregado, pois o veículo utilizado pelo autor era equipado com dispositivo derastreamentovia satélite. A jurisprudência desta Corte Superior firmou entendimento de que o sistema de monitoramento erastreamentoviabiliza o controle de jornada do empregado. Precedentes. Recurso de revista conhecido e provido.', '', 'LexML', 'transport_energy', '', '', 'I - AGRAVO DE INSTRUMENTO. RECURSO DE REVISTA. HORAS EXTRAS. TRABALHO EXTERNO. EXISTÊNCIA DERASTREAMENTO. Observa-se possível violação ao art. 62, I, da CLT. Agravo de instrumento conhecido e provido. II - RECURSO DE REVISTA. HORAS EXTRAS. TRABALHO EXTERNO. EXISTÊNCIA DERASTREAMENTO. Na hipótese, o TRT esclarece que haviarastreamentodos veículos. Para configuração da hipótese do art. 62, I, da CLT não se exige a simples constatação de exercício de atividade externa, mas, sim, daquela que, por sua natureza, seja incompatível com a fixação ou possibilidade de controle direto ou indireto da jornada de trabalho. Do exame do acórdão regional, infere-se a possibilidade de controle da jornada do empregado, pois o veículo utilizado pelo autor era equipado com dispositivo derastreamentovia satélite. A jurisprudência desta Corte Superior firmou entendimento de que o sistema de monitoramento erastreamentoviabiliza o controle de jornada do empregado. Precedentes. Recurso de revista conhecido e provido.', '', 'Tribunal Superior do Trabalho. 2ª Turma', 'Federal', 'Tribunal', '{"search_term": "", "urn_type": "other", "country": "br", "source_file": "Outros___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:tribunal.superior.trabalho;turma.4:acordao;rr:2021-06-08;10890-2016-18-18-0', 'Acórdão do processo Nº RR - 10890-59.2016.5.18.0018', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.4:acordao;rr:2021-06-08;10890-2016-18-18-0', '2021-06-08', '', '', 'outro', 'A) AGRAVO DE INSTRUMENTO EM RECURSO DE REVISTA INTERPOSTO PELA RECLAMADA (APPLE BENEFICIAMENTO E LOGISTICA LTDA-EPP). ACÓRDÃO REGIONAL PUBLICADO NA VIGÊNCIA DA LEI Nº 13.015/2014 E ANTES DA VIGÊNCIA DA LEI 13.467/2017.  1. JORNADA DE TRABALHO. MOTORISTA. CONTROLE POR SISTEMA DERASTREAMENTOVIA SATÉLITE. CONHECIMENTO E PROVIMENTO. I. Hipótese em que o Tribunal Regional entendeu que orastreamentode veículo via satélite não serve como efetiva prova de controle de jornada do empregado motorista. II. Demonstrada divergência jurisprudencial quanto ao tema. III. Agravo de instrumento de que se conhece e a que se dá provimento, para determinar o processamento do recurso de revista, observando-se o disposto no ATO SEGJUD.GP Nº 202/2019 do TST.  B) RECURSO DE REVISTA INTERPOSTO PELA RECLAMADA (APPLE BENEFICIAMENTO E LOGISTICA LTDA-EPP). ACÓRDÃO REGIONAL PUBLICADO NA VIGÊNCIA DA LEI Nº 13.015/2014 E ANTES DA VIGÊNCIA DA LEI 13.467/2017.  1. JORNADA DE TRABALHO. MOTORISTA. CONTROLE POR SISTEMA DERASTREAMENTOVIA SATÉLITE. CONHECIMENTO E PROVIMENTO. I. A jurisprudência desta Corte Superior é no sentido de que orastreamentovia satélite viabiliza o controle da jornada de trabalho do empregado motorista, porquanto se realiza por meio de aparelho que capta sinais de GPS e permite a transmissão de dados como a localização exata do veículo, tempo no qual ficou parado, bem como a velocidade em que trafega. II. No caso dos autos, consta do acórdão regional que a Reclamada apresentou relatórios, oriundos de sistema derastreamentode veículo via satélite, para controle de jornada do Reclamante. III.  Logo, conforme entendimento desta Corte Superior, os relatórios obtidos por sistema derastreamentovia satélite são viáveis para o efetivo controle de jornada de empregado motorista. Recurso de revista de que se conhece, por divergência jurisprudencial, e a que se dá provimento.', '', 'LexML', 'transport_energy', '', '', 'A) AGRAVO DE INSTRUMENTO EM RECURSO DE REVISTA INTERPOSTO PELA RECLAMADA (APPLE BENEFICIAMENTO E LOGISTICA LTDA-EPP). ACÓRDÃO REGIONAL PUBLICADO NA VIGÊNCIA DA LEI Nº 13.015/2014 E ANTES DA VIGÊNCIA DA LEI 13.467/2017.  1. JORNADA DE TRABALHO. MOTORISTA. CONTROLE POR SISTEMA DERASTREAMENTOVIA SATÉLITE. CONHECIMENTO E PROVIMENTO. I. Hipótese em que o Tribunal Regional entendeu que orastreamentode veículo via satélite não serve como efetiva prova de controle de jornada do empregado motorista. II. Demonstrada divergência jurisprudencial quanto ao tema. III. Agravo de instrumento de que se conhece e a que se dá provimento, para determinar o processamento do recurso de revista, observando-se o disposto no ATO SEGJUD.GP Nº 202/2019 do TST.  B) RECURSO DE REVISTA INTERPOSTO PELA RECLAMADA (APPLE BENEFICIAMENTO E LOGISTICA LTDA-EPP). ACÓRDÃO REGIONAL PUBLICADO NA VIGÊNCIA DA LEI Nº 13.015/2014 E ANTES DA VIGÊNCIA DA LEI 13.467/2017.  1. JORNADA DE TRABALHO. MOTORISTA. CONTROLE POR SISTEMA DERASTREAMENTOVIA SATÉLITE. CONHECIMENTO E PROVIMENTO. I. A jurisprudência desta Corte Superior é no sentido de que orastreamentovia satélite viabiliza o controle da jornada de trabalho do empregado motorista, porquanto se realiza por meio de aparelho que capta sinais de GPS e permite a transmissão de dados como a localização exata do veículo, tempo no qual ficou parado, bem como a velocidade em que trafega. II. No caso dos autos, consta do acórdão regional que a Reclamada apresentou relatórios, oriundos de sistema derastreamentode veículo via satélite, para controle de jornada do Reclamante. III.  Logo, conforme entendimento desta Corte Superior, os relatórios obtidos por sistema derastreamentovia satélite são viáveis para o efetivo controle de jornada de empregado motorista. Recurso de revista de que se conhece, por divergência jurisprudencial, e a que se dá provimento.', '', 'Tribunal Superior do Trabalho. 4ª Turma', 'Federal', 'Tribunal', '{"search_term": "", "urn_type": "other", "country": "br", "source_file": "Outros___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:tribunal.superior.trabalho;turma.3:acordao;ed:2020-10-20;107100-1998-16-2-0', 'Acórdão do processo Nº ED-AIRR - 107100-58.1998.5.02.0016', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.3:acordao;ed:2020-10-20;107100-1998-16-2-0', '2020-10-20', '', '', 'outro', 'EMBARGOS DE DECLARAÇÃO EM AGRAVO DE INSTRUMENTO EM RECURSO DE REVISTA. CERCEAMENTO DO DIREITO DE DEFESA - NULIDADE DA ARREMATAÇÃO DE BEM IMÓVEL POR VÍCIO DE NOTIFICAÇÃO POSTAL DO LEILÃO JUDICIAL - AUSÊNCIA DE JUNTADA DO AVISO DE RECEBIMENTO OU COMPROVANTE DERASTREAMENTO-  NÚMEROS DERASTREAMENTOEMITIDOS PELOS CORREIOS -  PREQUESTIONAMENTO - APLICAÇÃO DO ARTIGO 896, §1º-A, I, DA CLT. A 3ª Turma do TST afastou a transcendência do recurso de revista de ROSEMEIRE ARANIBAR LOPEZ SOARES DA SILVA E OUTRO, notadamente em razão de o acórdão de agravo de petição estar em sintonia com a Súmula/TST nº 16, sendo irrelevante a ausência de juntada de aviso de recebimento para se ter presumida a notificação quarenta e oito horas depois de sua postagem. Este Colegiado acrescentou que a questão concernente aos números derastreamentoemitidos pelos Correios não se encontra prequestionada na decisão recorrida, razão pela qual incide o artigo 896, §1º-A, da CLT, no particular. Os embargantes sustentam que "o acórdão embargado foi omisso quanto à análise das provas relativas ao prequestionamento relacionado à ausência de números derastreamentoemitidos pelos Correios". Argumentam que "a discussão sobre a absoluta impossibilidade de os Recorrentes produzirem a prova que deles é exigida, ante a falta de informações básicas de materialidade da postagem, foi expressamente prequestionada junto ao Tribunal de origem, não havendo margem para dúvidas de que os recorrentes trataram expressamente da ausência de números derastreamentodas postagens". Afirmam que "os argumentos relacionados à falta de código derastreamentodas correspondências" foram expostos nos embargos de declaração opostos contra o acórdão de agravo de petição. Asseveram que "o Tribunal a quo simplesmente desconsiderou os argumentos acima reproduzidos, rejeitando os embargos sem enfrentar a discussão jurídica apresentada". Alegam que "não se trata, portanto, de falta de prequestionamento, mas sim de verdadeira recusa à prestação jurisdicional por parte do Tribunal Regional do Trabalho da 2ª Região". Aduzem que "esta C. Turma foi absolutamente omissa quanto à comprovação de que os embargantes não dispunham de meios possíveis para a comprovação da não-entrega das cartas de intimação". Destacam que "os recorrentes não têm meios de provar que a correspondência não foi entregue em suas residências, uma vez que não há nos autos elementos para a rastreabilidade das cartas de intimação". Insistem que "não há nos autos o aviso de recebimento das correspondências e não há o código derastreamentodessas cartas". Colacionam decisão da 5ª Turma do TST. Defendem a transcendência política e jurídica do recurso de revista e invocam os princípios constitucionais do contraditório e da ampla defesa. Equivoca-se o polo embargante ao sugerir que as razões de recurso de natureza ordinária dirigido ao Tribunal Regional configurariam o prequestionamento exigido pelo artigo 896, §1º-A, I, da CLT. Na verdade, considera-se prequestionada a tese jurídica, ou a questão fática a ela imprescindível, quando a decisão impugnada adotar entendimento explícito a respeito. Esse, aliás, é o teor do item I da Súmula/TST nº 297. E nem se insista no argumento de que a circunstância relativa aos números derastreamentoemitidos pelos Correios estaria prequestionada pela mera oposição de embargos declaratórios acerca dessa temática contra o acórdão de agravo de petição. É que o prequestionamento ficto abraçado pelo item III da Súmula/TST nº 297 é restrito à matéria de direito, não alcançando os fatos que instruem o processo. Os recorrentes deveriam ter suscitado a alegada omissão do Tribunal Regional em preliminar de nulidade por negativa de prestação jurisdicional; não o fazendo, assumiram as consequências de sua inércia, haja vista a impossibilidade de trânsito do recurso de revista no aspecto, em virtude do obstáculo de natureza instrumental do artigo 896, §1º-A, I, da CLT. Embargos de declaração conhecidos e providos, apenas para prestar esclarecimentos, sem conferir efeito modificativo ao julgado. PENALIDADES PROCESSUAIS REQUERIDAS EM CONTRARRAZÕES. SUELI FLORENTINO alega que a irresignação dos embargantes quanto ao prequestionamento do número derastreamentodos Correios não passa de expediente dissimulatório e procrastinatório, que enseja a aplicação da penalidade prevista no artigo 81 do CPC. Sustenta que a utilização dos declaratórios como sucedâneo recursal também dá azo à multa do artigo 1.026, §2º, do CPC. Ao contrário do que sugere a embargada, os presentes embargos de declaração não denotam intuito protelatório, apenas desconhecimento a respeito do que seria prequestionamento. Note-se que os embargantes chegam a expor que "o Tribunal a quo simplesmente desconsiderou os argumentos acima reproduzidos, rejeitando os embargos sem enfrentar a discussão jurídica apresentada", argumento que contradiz suas próprias razões de declaratórios e que ratifica tanto a ausência de tese do Tribunal Regional acerca do número derastreamentodos Correios quanto a aplicação do artigo 896, §1º-A, I, da CLT neste particular. Pedidos formulados em contrarrazões indeferidos.', '', 'LexML', 'transport_energy', '', '', 'EMBARGOS DE DECLARAÇÃO EM AGRAVO DE INSTRUMENTO EM RECURSO DE REVISTA. CERCEAMENTO DO DIREITO DE DEFESA - NULIDADE DA ARREMATAÇÃO DE BEM IMÓVEL POR VÍCIO DE NOTIFICAÇÃO POSTAL DO LEILÃO JUDICIAL - AUSÊNCIA DE JUNTADA DO AVISO DE RECEBIMENTO OU COMPROVANTE DERASTREAMENTO-  NÚMEROS DERASTREAMENTOEMITIDOS PELOS CORREIOS -  PREQUESTIONAMENTO - APLICAÇÃO DO ARTIGO 896, §1º-A, I, DA CLT. A 3ª Turma do TST afastou a transcendência do recurso de revista de ROSEMEIRE ARANIBAR LOPEZ SOARES DA SILVA E OUTRO, notadamente em razão de o acórdão de agravo de petição estar em sintonia com a Súmula/TST nº 16, sendo irrelevante a ausência de juntada de aviso de recebimento para se ter presumida a notificação quarenta e oito horas depois de sua postagem. Este Colegiado acrescentou que a questão concernente aos números derastreamentoemitidos pelos Correios não se encontra prequestionada na decisão recorrida, razão pela qual incide o artigo 896, §1º-A, da CLT, no particular. Os embargantes sustentam que "o acórdão embargado foi omisso quanto à análise das provas relativas ao prequestionamento relacionado à ausência de números derastreamentoemitidos pelos Correios". Argumentam que "a discussão sobre a absoluta impossibilidade de os Recorrentes produzirem a prova que deles é exigida, ante a falta de informações básicas de materialidade da postagem, foi expressamente prequestionada junto ao Tribunal de origem, não havendo margem para dúvidas de que os recorrentes trataram expressamente da ausência de números derastreamentodas postagens". Afirmam que "os argumentos relacionados à falta de código derastreamentodas correspondências" foram expostos nos embargos de declaração opostos contra o acórdão de agravo de petição. Asseveram que "o Tribunal a quo simplesmente desconsiderou os argumentos acima reproduzidos, rejeitando os embargos sem enfrentar a discussão jurídica apresentada". Alegam que "não se trata, portanto, de falta de prequestionamento, mas sim de verdadeira recusa à prestação jurisdicional por parte do Tribunal Regional do Trabalho da 2ª Região". Aduzem que "esta C. Turma foi absolutamente omissa quanto à comprovação de que os embargantes não dispunham de meios possíveis para a comprovação da não-entrega das cartas de intimação". Destacam que "os recorrentes não têm meios de provar que a correspondência não foi entregue em suas residências, uma vez que não há nos autos elementos para a rastreabilidade das cartas de intimação". Insistem que "não há nos autos o aviso de recebimento das correspondências e não há o código derastreamentodessas cartas". Colacionam decisão da 5ª Turma do TST. Defendem a transcendência política e jurídica do recurso de revista e invocam os princípios constitucionais do contraditório e da ampla defesa. Equivoca-se o polo embargante ao sugerir que as razões de recurso de natureza ordinária dirigido ao Tribunal Regional configurariam o prequestionamento exigido pelo artigo 896, §1º-A, I, da CLT. Na verdade, considera-se prequestionada a tese jurídica, ou a questão fática a ela imprescindível, quando a decisão impugnada adotar entendimento explícito a respeito. Esse, aliás, é o teor do item I da Súmula/TST nº 297. E nem se insista no argumento de que a circunstância relativa aos números derastreamentoemitidos pelos Correios estaria prequestionada pela mera oposição de embargos declaratórios acerca dessa temática contra o acórdão de agravo de petição. É que o prequestionamento ficto abraçado pelo item III da Súmula/TST nº 297 é restrito à matéria de direito, não alcançando os fatos que instruem o processo. Os recorrentes deveriam ter suscitado a alegada omissão do Tribunal Regional em preliminar de nulidade por negativa de prestação jurisdicional; não o fazendo, assumiram as consequências de sua inércia, haja vista a impossibilidade de trânsito do recurso de revista no aspecto, em virtude do obstáculo de natureza instrumental do artigo 896, §1º-A, I, da CLT. Embargos de declaração conhecidos e providos, apenas para prestar esclarecimentos, sem conferir efeito modificativo ao julgado. PENALIDADES PROCESSUAIS REQUERIDAS EM CONTRARRAZÕES. SUELI FLORENTINO alega que a irresignação dos embargantes quanto ao prequestionamento do número derastreamentodos Correios não passa de expediente dissimulatório e procrastinatório, que enseja a aplicação da penalidade prevista no artigo 81 do CPC. Sustenta que a utilização dos declaratórios como sucedâneo recursal também dá azo à multa do artigo 1.026, §2º, do CPC. Ao contrário do que sugere a embargada, os presentes embargos de declaração não denotam intuito protelatório, apenas desconhecimento a respeito do que seria prequestionamento. Note-se que os embargantes chegam a expor que "o Tribunal a quo simplesmente desconsiderou os argumentos acima reproduzidos, rejeitando os embargos sem enfrentar a discussão jurídica apresentada", argumento que contradiz suas próprias razões de declaratórios e que ratifica tanto a ausência de tese do Tribunal Regional acerca do número derastreamentodos Correios quanto a aplicação do artigo 896, §1º-A, I, da CLT neste particular. Pedidos formulados em contrarrazões indeferidos.', '', 'Tribunal Superior do Trabalho. 3ª Turma', 'Federal', 'Tribunal', '{"search_term": "", "urn_type": "other", "country": "br", "source_file": "Outros___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:superior.tribunal.justica;turma.2:acordao;aresp:2022-09-27;2076095-2212753', 'AREsp 2076095 / RS', 'https://www.lexml.gov.br/urn/urn:lex:br:superior.tribunal.justica;turma.2:acordao;aresp:2022-09-27;2076095-2212753', '2022-09-27', '', '', 'outro', 'ADMINISTRATIVO. PESCA DE PARELHA. SISTEMA PREPS DERASTREAMENTOINOPERANTE. INFRAÇÃO AMBIENTAL. MULTA E APREENSÃO DO PESCADO. AÇÃO
ANULATÓRIA DOS AUTOS DE INFRAÇÃO. ALEGAÇÃO DE PESCA NA MODALIDADE
PARELHA. EMBARCAÇÕES QUE NAVEGAM LADO-A-LADO. SISTEMA DERASTREAMENTODE UMA EMBARCAÇÃO EM OPERAÇÃO. PELO QUE COMPROVARIA A
PRESENÇA DA OUTRA FORA DO ZONA DE EXCLUSÃO. SENTENÇA DE PROCEDÊNCIA
DA AÇÃO ANULATÓRIA. ACÓRDÃO CONFIRMANDO A SENTENÇA. RECURSO ESPECIAL
DO IBAMA. PEDIDO DE MANUTENÇÃO DOS AUTOS DE INFRAÇÃO. ALEGAÇÃO DA
HIGIDEZ DA AUTUAÇÃO. NAVEGAÇÃO SEMRASTREAMENTOOBRIGATÓRIO EM
DESACORDO COM A AUTORIZAÇÃO EMITIDA. RECURSO ESPECIAL PROVIDO.
INFRAÇÃO ADMINISTRATIVA FORMAL CONSTATADA. INDEPENDENDO DA
OCORRÊNCIA DE INFRAÇÃO ADMINISTRATIVA MATERIAL. MANUTENÇÃO DOS AUTOS
DE INFRAÇÃO.
I. Na origem, trata-se de ação anulatória de auto de infração
decorrente de atividade pesqueira com embarcação sem orastreamentoobrigatório (Sistema PREPS).
II. Sentença dando provimento à pretensão autoral de anulação dos
autos de infração, entendendo que, por se tratar de pesca na
modalidade parelha, o funcionamento do sistema derastreamentode
uma das embarcações comprovaria a presença da outra no mesmo local,
ou seja, fora da zona de exclusão.
III. Apelação da autarquia ambiental, entendimento de que o cruzeiro
de pesca não atendeu à autorização emitida pelo órgão competente,
que previarastreamentoobrigatório nas embarcações.
IV. Acórdão confirmando a sentença de primeiro grau, entendendo que,
por se tratar de pesca na modalidade parelha, o sinal emitido por
uma das embarcações comprovaria a presença da outra no mesmo local.
V. Recurso especial do IBAMA a regularidade e legalidade da
autuação, tendo em vista o não atendimento, pelos recorridos, das
exigências previstas na autorização de pesca emitida, além de que
não seria possível assegurar que a embarcação semrastreamentotenha, de fato, se limitado fora da zona de exclusão.
VI. Recurso especial provido. Constatação que de fato houve infração
administrativa formal, consistente em navegação pesqueira com o
Sistema PREPS inoperante/desativado, não sendo o caso de se
rediscutir eventuais justificativas da inocorrência de infração
administrativa material, ou seja, de não ter havido a efetiva pesca
de arrasto dentro da área de exclusão.
VII. Agravo conhecido para dar provimento ao recurso especial do
IBAMA e restabelecer a higidez dos autos de infração.
Decis?o
Vistos, relatados e discutidos os autos em que são partes as acima
indicadas, acordam os Ministros da Segunda Turma do Superior
Tribunal de Justiça,  por unanimidade, conhecer do agravo para dar
provimento ao recurso especial, nos termos do voto do Sr.
Ministro-Relator." Os Srs. Ministros Herman Benjamin, Mauro Campbell
Marques e Assusete Magalhães votaram com o Sr. Ministro Relator.
Ausente, justificadamente, o Sr. Ministro Humberto Martins. | Assuntos: "[...] a mera conduta que implique em riscos de dano ao meio
ambiente, ainda que materialmente não concretizados, já é suficiente
para configurar uma infração administrativa passível de autuação e
de sanção pecuniária [...]".', '', 'LexML', 'transport_energy', '', '', 'ADMINISTRATIVO. PESCA DE PARELHA. SISTEMA PREPS DERASTREAMENTOINOPERANTE. INFRAÇÃO AMBIENTAL. MULTA E APREENSÃO DO PESCADO. AÇÃO
ANULATÓRIA DOS AUTOS DE INFRAÇÃO. ALEGAÇÃO DE PESCA NA MODALIDADE
PARELHA. EMBARCAÇÕES QUE NAVEGAM LADO-A-LADO. SISTEMA DERASTREAMENTODE UMA EMBARCAÇÃO EM OPERAÇÃO. PELO QUE COMPROVARIA A
PRESENÇA DA OUTRA FORA DO ZONA DE EXCLUSÃO. SENTENÇA DE PROCEDÊNCIA
DA AÇÃO ANULATÓRIA. ACÓRDÃO CONFIRMANDO A SENTENÇA. RECURSO ESPECIAL
DO IBAMA. PEDIDO DE MANUTENÇÃO DOS AUTOS DE INFRAÇÃO. ALEGAÇÃO DA
HIGIDEZ DA AUTUAÇÃO. NAVEGAÇÃO SEMRASTREAMENTOOBRIGATÓRIO EM
DESACORDO COM A AUTORIZAÇÃO EMITIDA. RECURSO ESPECIAL PROVIDO.
INFRAÇÃO ADMINISTRATIVA FORMAL CONSTATADA. INDEPENDENDO DA
OCORRÊNCIA DE INFRAÇÃO ADMINISTRATIVA MATERIAL. MANUTENÇÃO DOS AUTOS
DE INFRAÇÃO.
