INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:federal:decreto.legislativo:2024-02-29;1', 'Decreto Legislativo nº 1 de 29/02/2024', 'https://www.lexml.gov.br/urn/urn:lex:br:federal:decreto.legislativo:2024-02-29;1', '2024-02-29', '', '', 'outro', 'Fica desbloqueada a execução física, orçamentária e financeira do objeto listado neste decreto vinculado ao Programa de Trabalho 26.846.2126.00P5.0043/2016 - Recomposição do Equilíbrio Econômico - Financeiro do Contrato de Concessão da BR-290/RS - Osório Porto Alegre - Entroncamento BR-116/RS (entrada p/ Guaíba) - No Estado do Rio Grande do Sul, constante da Lei nº 14.535, de 17 de janeiro de 2023 (LOA 2023), vinculados à Unidade Orçamentária 39250 Agência Nacional de Transportes Terrestres -ANTT. | Assuntos: DESBLOQUEIO ,  EXECUÇÃO FISICA ,  EXECUÇÃO FINANCEIRA ,  EXECUÇÃO ORÇAMENTARIA ,  OBJETO ,  COMPOSIÇÃO ,  RELAÇÃO ,  FINANÇAS ,  CONTRATO ,  CONCESSÃO ,  RODOVIA ,  ESTADO DO RIO GRANDE DO SUL (RS) ,  OSORIO (RS) ,  PORTO ALEGRE (RS) ,  VINCULAÇÃO ,  AGENCIA NACIONAL DE TRANSPORTES TERRESTRES (ANTT) .', '', 'LexML', 'transport_energy', '', '', 'Fica desbloqueada a execução física, orçamentária e financeira do objeto listado neste decreto vinculado ao Programa de Trabalho 26.846.2126.00P5.0043/2016 - Recomposição do Equilíbrio Econômico - Financeiro do Contrato de Concessão da BR-290/RS - Osório Porto Alegre - Entroncamento BR-116/RS (entrada p/ Guaíba) - No Estado do Rio Grande do Sul, constante da Lei nº 14.535, de 17 de janeiro de 2023 (LOA 2023), vinculados à Unidade Orçamentária 39250 Agência Nacional de Transportes Terrestres -ANTT. | Assuntos: DESBLOQUEIO ,  EXECUÇÃO FISICA ,  EXECUÇÃO FINANCEIRA ,  EXECUÇÃO ORÇAMENTARIA ,  OBJETO ,  COMPOSIÇÃO ,  RELAÇÃO ,  FINANÇAS ,  CONTRA