INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:agencia.nacional.energia.eletrica:resolucao.normativa:2004-05-13;064', 'RESOLUÇÃO NORMATIVA nº 064, de 13/05/2004', 'https://www.lexml.gov.br/urn/urn:lex:br:agencia.nacional.energia.eletrica:resolucao.normativa:2004-05-13;064', '2004-05-13', '', '', 'outro', 'Altera a redação do parág. 4º do art. 41, do Anexo I, da ResoluçãoANEEL233 de 14.07.1998, acrescentado pela ResoluçãoANEEL081 de 18.02.2003, referente à Norma de OrganizaçãoANEEL001. | Assuntos: {Alteração, Modificação}. Redação. Parágrafo. {Artigo, Artigos}. Anexo. {Resolução Normativa, Ren}. Aprovação. {Norma Organizacional, Norma de Organização}. Procedimento Administrativo. {(ANEEL), Agência Nacional de Energia Elétrica}. Legislação Básica | {ANEEL, Agência Nacional da Energia Elétrica}. Alteração. Redação. Parágrafo. {Artigo, Artigos}. Anexo. {Resolução Normativa, Ren}. Aprovação. {Norma organizacional, Norma de organização}. Procedimento administrativo. Legislação básica', '', 'LexML', 'transport_energy', '', '', 'Altera a redação do parág. 4º do art. 41, do Anexo I, da ResoluçãoANEEL233 de 14.07.1998, acrescentado pela ResoluçãoANEEL081 de 18.02.2003, referente à Norma de OrganizaçãoANEEL001. | Assuntos: {Alteração, Modificação}. Redação. Parágrafo. {Artigo, Artigos}. Anexo. {Resolução Normativa, Ren}. Aprovação. {Norma Organizacional, Norma de Organização}. Procedimento Administrativo. {(ANEEL), Agência Nacional de Energia Elétrica}. Legislação Básica | {ANEEL, Agência Nacional da Energia Elétrica}. Alteração. Redação. Parágrafo. {Artigo, Artigos}. Anexo. {Resolução Normativa, Ren}. Aprovação. {Norma organizacional, Norma de organização}. Procedimento administrativo. Legislação básica', '', 'Agência Nacional de Energia El