INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:federal:decreto.lei:1988-08-25;2459', 'Decreto-Lei nº 2.459, de 25 de Agosto de 1988', 'https://www.lexml.gov.br/urn/urn:lex:br:federal:decreto.lei:1988-08-25;2459', '1988-08-25', '', '', 'outro', 'Concede isenção do IPI para a aguardente de cana e de melaço, destinada à fabricação de álcool etílico para fins combustíveis, e dá outras providências. | Assuntos: CONCESSÃO ,  ISENÇÃO ,  IMPOSTO SOBRE PRODUTOS INDUSTRIALIZADOS (IPI) ,  AGUARDENTE ,  PROGRAMA NACIONAL DO ALCOOL (PROALCOOL) ,  DESTINAÇÃO ,  FABRICAÇÃO ,  ALCOOL HIDRATADO ,  OBJETIVO ,  COMBUSTIVEL .', '', 'LexML', 'transport_energy', '', '', 'Concede isenção do IPI para a aguardente de cana e de melaço, destinada à fabricação de álcool etílico para fins combustíveis, e dá outras providências. | Assuntos: CONCESSÃO ,  ISENÇÃO ,  IMPOSTO SOBRE PRODUTOS INDUSTRIALIZADOS (IPI) ,  AGUARDENTE ,  PROGRAMA NACIONAL DO ALCOOL (PROALCOOL) ,  DESTINAÇÃO ,  FABRICAÇÃO ,  ALCOOL HIDRATADO ,  OBJETIVO ,  COMBUSTIVEL .', '', 'Federal', 'Federal', 'Outros', '{"search_term": "", "urn_type": "other", "country": "br", "source_file": "Outros___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:tribunal.superior.eleitoral;plenario:acordao;ro:1982-09-28;ro-5309', 'Acórdão RO de 28/09/1982 (Processo RO nº 5309)', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.eleitoral;plenario:acordao;ro:1982-09-28;ro-5309', '1982-09-28', '', '', 'outro', 'RECURSO ORDINARIO. DIRIGENTES DE EMPRESAS BENEFICIADAS PELOPROALCOOL. INELEGIBILIDADE DA LETRA "H" NAO CONFIGURADA. PRECLUSAO. 1) SE O FATO ALEGADO PELO RECORRENTE PREEXISTIA AO PEDIDO DE REGISTRO DO CANDIDATO, NAO HA MOTIVO SUPERVENIENTE QUE JUSTIFIQUE O RECURSO POR PARTE DE QUEM NAO IMPUGNOU O REGISTRO. A ALEGACAO DE CONHECIMENTO SUPERVENIENTE DO IMPEDIMENTO NAO AFASTA A PRECLUSAO. 2) OS INCENTIVOS DOPROALCOOLQUE BENEFICIAM, COM CARATER DE GENERALIDADE, TODAS AS EMPRESAS DO RAMO, COMO RECONHECE O PROPRIO RECORRENTE, NAO JUSTIFICAM A INELEGIBILIDADE DA LETRA "H", COMO O TSE JA RECONHECEU NO CASO ANALOGO DA SUDENE.', '', 'LexML', 'transport_energy', '', '', 'RECURSO ORDINARIO. DIRIGENTES DE EMPRESAS BENEFICIADAS PELOPROALCOOL. INELEGIBILIDADE DA LETRA "H" NAO CONFIGURADA. PRECLUSAO. 1) SE O FATO ALEGADO PELO RECORRENTE PREEXISTIA AO PEDIDO DE REGISTRO DO CANDIDATO, NAO HA MOTIVO SUPERVENIENTE QUE JUSTIFIQUE O RECURSO POR PARTE DE QUEM NAO IMPUGNOU O REGISTRO. A ALEGACAO DE CONHECIMENTO SUPERVENIENTE DO IMPEDIMENTO NAO AFASTA A PRECLUSAO. 2) OS INCENTIVOS DOPROALCOOLQUE BENEFICIAM, COM CARATER DE GENERALIDADE, TODAS AS EMPRESAS DO RAMO, COMO RECONHECE O PROPRIO RECORRENTE, NAO JUSTIFICAM A INELEGIBILIDADE DA LETRA "H", COMO O TSE JA RECONHECEU NO CASO ANALOGO DA SUDENE.', '', 'Tribunal Superior Eleitoral. Plenário', 'Federal', 'Tribunal', '{"search_term": "", "urn_type": "other", "country": "br", "source_file": "Outros___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:camara.deputados:projeto.lei;pl:2015-12-15;3982', 'PL 3982/2015', 'https://www.lexml.gov.br/urn/urn:lex:br:camara.deputados:projeto.lei;pl:2015-12-15;3982', '2015-12-15', '', '', 'outro', 'Autoriza a renegociação de dívidas oriundas de operações de crédito rural ou agroindustrial contratadas por produtores rurais e suas cooperativas ao amparo do Programa Nacional do Álcool -Proálcool.', '', 'LexML', 'transport_energy', '', '', 'Autoriza a renegociação de dívidas oriundas de operações de crédito rural ou agroindustrial contratadas por produtores rurais e suas cooperativas ao amparo do Programa Nacional do Álcool -Proálcool.', '', 'Câmara dos Deputados', 'Federal', 'Outros', '{"search_term": "", "urn_type": "other", "country": "br", "source_file": "Outros___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:federal:emenda.constitucional:2015-04-16;87', 'Emenda Constitucional nº 87, de 2015', 'https://www.lexml.gov.br/urn/urn:lex:br:federal:emenda.constitucional:2015-04-16;87', '2015-04-16', '', '', 'outro', 'Altera o § 2º do art. 155 da Constituição Federal e inclui o art. 99 no Ato das Disposições Constitucionais Transitórias, para tratar da sistemática de cobrança do imposto sobre operações relativas à circulação de mercadorias e sobre prestações de serviços de transporte interestadual e intermunicipal e de comunicação incidente sobre as operações e prestações que destinem bens e serviços a consumidor final, contribuinte ou não do imposto, localizado em outro Estado. | Assuntos: ALTERAÇÃO ,  CONSTITUIÇÃO FEDERAL ,  SISTEMA TRIBUTARIO NACIONAL ,  IMPOSTO SOBRE CIRCULAÇÃO DE MERCADORIAS E SERVIÇOS (ICMS) ,  OPERAÇÃO INTERESTADUAL .', '', 'LexML', 'transport_energy', '', '', 'Altera o § 2º do art. 155 da Constituição Federal e inclui o art. 99 no Ato das Disposições Constitucionais Transitórias, para tratar da sistemática de cobrança do imposto sobre operações relativas à circulação de mercadorias e sobre prestações de serviços de transporte interestadual e intermunicipal e de comunicação incidente sobre as operações e prestações que destinem bens e serviços a consumidor final, contribuinte ou não do imposto, localizado em outro Estado. | Assuntos: ALTERAÇÃO ,  CONSTITUIÇÃO FEDERAL ,  SISTEMA TRIBUTARIO NACIONAL ,  IMPOSTO SOBRE CIRCULAÇÃO DE MERCADORIAS E SERVIÇOS (ICMS) ,  OPERAÇÃO INTERESTADUAL .', '', 'Federal', 'Federal', 'Outros', '{"search_term": "", "urn_type": "other", "country": "br", "source_file": "Outros___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
