INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br;distrito.federal:distrital:decreto.legislativo:2021-11-16;2336', 'Decreto Legislativo nº 2336, de 16 de novembro de 2021', 'https://www.lexml.gov.br/urn/urn:lex:br;distrito.federal:distrital:decreto.legislativo:2021-11-16;2336', '2021-11-16', 'DF', '', 'outro', 'Homologa o Convênio ICMS 66/19, de 5 de julho de 2019, que concede isenção do ICMS às operações comaceleradoreslineares destinados à prestação de serviços de saúde, e o Convênio ICMS 51/21, de 8 de abril de 2021, que o altera. | Assuntos: IMPOSTO SOBRE OPERAÇÕES RELATIVAS À CIRCULAÇÃO DE MERCADORIAS E SOBRE PRESTAÇÕES DE SERVIÇOS DE TRANSPORTE INTERESTADUAL E INTERMUNICIPAL E DE COMUNICAÇÃO (ICMS). CONVÊNIO, homologação. SERVIÇO DE SAÚDE.', '', 'LexML', 'transport_energy', '', '', 'Homologa o Convênio ICMS 66/19, de 5 de julho de 2019, que concede isenção do ICMS às operações comaceleradoreslineares destinados à prestação de serviços de saúde, e o Convênio ICMS 51/21, de 8 de abril de 2021, que o altera. | Assuntos: IMPOSTO SOBRE OPERAÇÕES RELATIVAS À CIRCULAÇÃO DE MERCADORIAS E SOBRE PRESTAÇÕES DE SERVIÇOS DE TRANSPORTE INTERESTADUAL E INTERMUNICIPAL E DE COMUNICAÇÃO (ICMS). CONVÊNIO, homologação. SERVIÇO DE SAÚDE.', '', 'Distrital', 'Distrital', 'Outros', '{"search_term": "", "urn_type": "other", "country": "br", "source_file": "Outros___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:camara.deputados:projeto.lei;pl:2017-11-28;9203', 'PL 9203/2017', 'https://www.lexml.gov.br/urn/urn:lex:br:camara.deputados:projeto.lei;pl:2017-11-28;9203', '2017-11-28', '', '', 'outro', 'Insere um art. 19-A na Lei nº 10.826, de 22 de dezembro de 2003, que "dispõe sobre registro, posse e comercialização de armas de fogo e munição, sobre o Sistema Nacional de Armas - Sinarm, define crimes e dá outras providências", para aumentar a pena dos crimes definidos nos art. 12, 14, 16, 17 e 18, quando o acessório referido em seus tipos penais se constituir emaceleradorde disparos.', '', 'LexML', 'transport_energy', '', '', 'Insere um art. 19-A na Lei nº 10.826, de 22 de dezembro de 2003, que "dispõe sobre registro, posse e comercialização de armas de fogo e munição, sobre o Sistema Nacional de Armas - Sinarm, define crimes e dá outras providências", para aumentar a pena dos crimes definidos nos art. 12, 14, 16, 17 e 18, quando o acessório referido em seus tipos penais se constituir emaceleradorde disparos.', '', 'Câmara dos Deputados', 'Federal', 'Outros', '{"search_term": "", "urn_type": "other", "country": "br", "source_file": "Outros___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:senado.federal:projeto.lei;pl:2019;4396', '[ Projeto de Lei nº 4396/2019 - Iniciadora ]', 'https://www.lexml.gov.br/urn/urn:lex:br:senado.federal:projeto.lei;pl:2019;4396', NULL, '', '', 'outro', 'Altera o parágrafo único do art. 52 da Lei nº 13.146, de 6 de julho de 2015, que institui a Lei Brasileira de Inclusão da Pessoa com Deficiência (Estatuto da Pessoa com deficiência), para determinar que os comandos manuais obrigatórios nos veículos adaptados oferecidos pelas locadoras de veículos sejam de freio e deacelerador, e não de freio e de embreagem.', '', 'LexML', 'transport_energy', '', '', 'Altera o parágrafo único do art. 52 da Lei nº 13.146, de 6 de julho de 2015, que institui a Lei Brasileira de Inclusão da Pessoa com Deficiência (Estatuto da Pessoa com deficiência), para determinar que os comandos manuais obrigatórios nos veículos adaptados oferecidos pelas locadoras de veículos sejam de freio e deacelerador, e não de freio e de embreagem.', '', 'Senado Federal', 'Federal', 'Outros', '{"search_term": "", "urn_type": "other", "country": "br", "source_file": "Outros___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:senado.federal:projeto.lei;pl:2023;4396', '[ Projeto de Lei nº 4396/2023 ]', 'https://www.lexml.gov.br/urn/urn:lex:br:camara.deputados:projeto.lei;pl:2023-04-20;4396', '2023-04-20', '', '', 'outro', 'Altera a Lei nº 14.583, de 16 de maio de 2023, para incluir as pessoas com deficiência nas políticas de difusão dos direitos fundamentais e dos direitos humanos.', '', 'LexML', 'transport_energy', '', '', 'Altera a Lei nº 14.583, de 16 de maio de 2023, para incluir as pessoas com deficiência nas políticas de difusão dos direitos fundamentais e dos direitos humanos.', '', 'Senado Federal', 'Federal', 'Outros', '{"search_term": "", "urn_type": "other", "country": "br", "source_file": "Outros___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
INSERT INTO documents (urn, titulo, url, data_publicacao, estado, municipality, tipo, conteudo, autor, fonte, transport_category, document_type_full, document_description, document_summary, search_term, justice, region, court_class, metadata, created_at, updated_at) VALUES ('urn:lex:br:tribunal.superior.trabalho;turma.8:acordao;ag:2018-10-10;695-2014-1-2-0', 'Acórdão do processo Nº Ag-AIRR - 695-81.2014.5.02.0001', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.8:acordao;ag:2018-10-10;695-2014-1-2-0', '2018-10-10', '', '', 'outro', 'AGRAVO EM AGRAVO DE INSTRUMENTO EM RECURSO DE REVISTA INTERPOSTO SOB A ÉGIDE DA LEI Nº 13.015/2014 -  ENQUADRAMENTO SINDICAL. PROGRAMA DE PARTICIPAÇÃO NOS RESULTADOS (PPR).ACELERADORDO PPR. HORAS EXTRAS. EXPEDIÇÃO DE OFÍCIOS. NÃO ATENDIMENTO DO PRESSUPOSTO DO ART. 896, § 1º-A, I, DA CLT - MULTA PREVISTA NO ART. 477, § 8º, DA CLT. TRCT COMPLEMENTAR. SÚMULA 126 DO TST. ART. 896, "A" E "C", DA CLT. Os argumentos lançados no apelo não viabilizam o processamento do recurso de revista. Agravo a que se nega provimento.', '', 'LexML', 'transport_energy', '', '', 'AGRAVO EM AGRAVO DE INSTRUMENTO EM RECURSO DE REVISTA INTERPOSTO SOB A ÉGIDE DA LEI Nº 13.015/2014 -  ENQUADRAMENTO SINDICAL. PROGRAMA DE PARTICIPAÇÃO NOS RESULTADOS (PPR).ACELERADORDO PPR. HORAS EXTRAS. EXPEDIÇÃO DE OFÍCIOS. NÃO ATENDIMENTO DO PRESSUPOSTO DO ART. 896, § 1º-A, I, DA CLT - MULTA PREVISTA NO ART. 477, § 8º, DA CLT. TRCT COMPLEMENTAR. SÚMULA 126 DO TST. ART. 896, "A" E "C", DA CLT. Os argumentos lançados no apelo não viabilizam o processamento do recurso de revista. Agravo a que se nega provimento.', '', 'Tribunal Superior do Trabalho. 8ª Turma', 'Federal', 'Tribunal', '{"search_term": "", "urn_type": "other", "country": "br", "source_file": "Outros___Geral.csv"}', '2025-07-18 13:09:17', '2025-07-18 13:09:17');
